        'Cada campo vale para o ponto da árvore escolhido e tudo abaixo dele (os de cada nível somam) e aparece no cadastro desses relógios. O identificador é o nome do campo nas fórmulas. Marcado "só nos desejados", o campo aparece só nos relógios da lista de desejos.' => '每个字段适用于所选的树节点及其下的所有节点（各层的字段会叠加），并显示在这些手表的档案中。标识符是该字段在公式中的名称。勾选“仅心愿单”后，该字段只出现在心愿单中的手表上。',
