        'Criar' => '创建',
        'O que se registra num relógio: instantâneo (corda), com valor (leitura de carga) ou sessão com início e fim (pulso, winder, sol). O identificador é o nome nas funções das fórmulas: HORAS("pulso"; 30). Sessão exclusiva: o relógio fica num lugar só. Mede o gasto: cada leitura desse tipo mede quanto caiu por dia de uso ou guardado (a função MEDIDO das fórmulas). Vale quando: uma fórmula que diz para quais relógios o tipo vale (ex.: corda_manual, só para quem aceita corda); vazia, vale para todos do grupo.' => '手表上记录的内容：瞬时（上弦）、带数值（电量读数）或有开始和结束的时段（手腕、摇表器、晒太阳）。标识符是公式函数中使用的名称：HORAS("pulso"; 30)。独占时段：手表同一时间只在一个地方。测量消耗：这种类型的每次读数都会测量每天佩戴或存放时下降了多少（公式函数 MEDIDO）。适用条件：一个说明该类型适用于哪些手表的公式（例如 corda_manual，只适用于可以上弦的手表）；为空则适用于该组的所有手表。',
