        'Uma fórmula pode ter uma versão em cada ponto da árvore: vale para o relógio a do ponto mais perto dele. Números com vírgula ou ponto, argumentos separados por ponto e vírgula, textos entre aspas. Variáveis: os identificadores dos campos e das fórmulas.' => '一个公式可以在树的每个节点各有一个版本：手表使用离它最近的节点的版本。数字可用逗号或点，参数用分号分隔，文本放在引号中。变量：字段和公式的标识符。',
