        '— sorteia —' => '— 抽选 —',
        'Cada modo tem blocos de dias da semana. O sorteio segue os critérios, recalculados a cada dia com o uso dos dias anteriores do plano (a carga não é simulada: não se sabe se você vai carregar). Com o ciclo (opcional), um relógio só volta depois que todos os disponíveis do bloco passaram; dentro do ciclo, a forma de escolha decide a ordem. Um bloco sorteia entre os relógios disponíveis de um ponto da árvore — um relógio para o bloco inteiro na semana, ou um por dia — ou usa um relógio fixo. A forma de escolha vale para o modo; a garantia de rodízio ({1} dias), para todos. Na escala inteligente, o modo monta o período inteiro de uma vez (de 7 dias a 2 anos), simulando as fórmulas dia a dia: escolhe sempre pela maior nota no dia simulado, e o relógio escolhido fica os dias da fórmula dias_seguidos (vazio: 1); os blocos dizem de onde escolher em cada dia da semana (ou o relógio fixo), e o "um por" não conta. A escala é refeita toda manhã a partir do estado real.' => '每种模式由一周中若干天组成的区块构成。抽选遵循规则，并且每天都根据计划中前几天的佩戴情况重新计算（电量不做模拟：无法知道你是否会充电）。启用循环（可选）时，一块表要等区块中所有可用的表都轮过一次后才会再次出现；在循环内，选择方式决定顺序。一个区块会在树的某个节点下的可用手表中抽选——整周的区块用一块表，或每天一块——或者使用固定的手表。选择方式适用于该模式；轮换保证（{1} 天）适用于所有模式。在智能排程中，模式会一次性生成整个时段（7 天到 2 年），逐日模拟公式：总是选择模拟当天评分最高的手表，被选中的手表会连续佩戴公式 dias_seguidos 给出的天数（为空：1）；区块说明一周中每天从哪里选择（或固定的手表），“每…一块”不起作用。排程每天早上根据实际情况重新生成。',
