        'Salvar o modo' => '保存模式',
        'Criar o modo' => '创建模式',
        'Os documentos de cada relógio (a página Documentos, aberta pela ficha) ficam numa categoria. "Aceita" limita os arquivos da categoria; nada marcado, ela aceita qualquer arquivo. O jeito de abrir cada arquivo vem do tipo dele, não da categoria: as fotos na galeria, os vídeos no player, o PDF no visualizador, o XML da nota com o resumo, o resto para baixar. Uma categoria com documentos não se exclui: passe os documentos para outra antes.' => '每块手表的文档（“文档”页面，从手表档案打开）都属于一个类别。“接受”限制该类别的文件；什么都不勾选则接受任何文件。每个文件的打开方式取决于文件类型，而不是类别：照片在图库中、视频在播放器中、PDF 在查看器中、发票 XML 带摘要，其余的供下载。有文档的类别不能删除：请先把文档移到其他类别。',
