        'Nova categoria' => '新类别',
        'Ordem {1}' => '顺序 {1}',
        'vazio: no fim' => '为空：排在最后',
        'Aceita (nada marcado: qualquer arquivo)' => '接受（不勾选：任何文件）',
        'Não consegui ler os cadastros: {1}' => '无法读取定义：{1}',
        'Inserir âncora' => '插入占位符',
        'Atualização do banco' => '数据库更新',
        'O banco está desatualizado' => '数据库已过期',
        'Esta versão do sistema precisa de migrações que ainda não foram aplicadas no banco. Até lá, as páginas, a API e o cron ficam parados, para não gravar nada pela metade.' => '这个版本的系统需要尚未应用到数据库的迁移。在此之前，页面、API 和 cron 都会暂停，以免只写入一半的数据。',
        'Aplicar agora' => '立即应用',
        'Aplica na ordem e para na primeira que falhar. Se o usuário do banco do sistema não tiver permissão de alterar tabelas, rode na mão, na ordem: {1}' => '按顺序应用，遇到第一个失败就停止。如果系统的数据库用户没有修改表的权限，请按顺序手动执行：{1}',
        'Continuar para a Configuração' => '继续前往设置',
        'O cron está com erro' => 'cron 出错了',
        'Some sozinho na primeira execução sem erro.' => '在第一次无错误运行后会自动消失。',
        '{1}, com filtro de datas e busca.' => '{1}，可按日期筛选和搜索。',
        'Ver todas as execuções do cron' => '查看所有 cron 运行记录',
        'Registro da última rodada' => '上一次运行的日志',
        'Rotina do dia' => '每日例程',
        'Manhã: relógio do dia e avisos' => '早上：当天的手表和提醒',
        'Noite: preparar o de amanhã' => '晚上：准备明天的手表',
        'No pulso a partir de' => '开始佩戴于',
        'Pôr no pulso sozinho' => '自动戴上',
        'No pulso até' => '佩戴至',
        'Tirar do pulso sozinho' => '自动取下',
        'Sessão no sol esquecida fecha às' => '忘记结束的晒太阳时段在此时间结束',
        'Sem <strong>pôr sozinho</strong>, o relógio do dia só entra no pulso pelo <strong>Pôs no pulso</strong>; sem <strong>tirar sozinho</strong>, só sai pelo ' => '不勾选<strong>自动戴上</strong>时，当天的手表只能通过<strong>已戴上</strong>戴到手腕上；不勾选<strong>自动取下</strong>时，只能通过 ',
        '<strong>Tirou do pulso</strong> (esquecido, continua contando como no pulso). O horário de uso vale sempre para o plano e as previsões. Fora do pulso, o relógio conta como guardado.' => '<strong>已取下</strong>取下（如果忘了，会一直按戴在手腕上计算）。佩戴时间始终用于计划和预测。不在手腕上时，手表按存放计算。',
        'Limites e contas' => '限值与计算',
        'Carregar quando a carga chegar a (%)' => '电量降到此值时充电（%）',
        'Solar: pôr no sol quando chegar a (%)' => '太阳能：降到此值时晒太阳（%）',
        'Gasto medido: média dos últimos (dias)' => '实测消耗：最近多少天的平均值',
        'Aviso Encostado: dias sem ir ao pulso' => '“闲置”提醒：多少天没戴',
        'O limite de carga de um relógio (no cadastro dele) vale no lugar do geral. Medições do gasto mais velhas que a janela saem da média. ' => '手表自己的电量下限（在其档案中）优先于通用值。早于统计窗口的消耗测量不计入平均值。 ',
        'Um relógio da coleção que passa do limite de dias sem ir ao pulso ganha o aviso <strong>Encostado</strong> (desliga em Cadastros › Avisos).' => '收藏中的手表超过规定天数没戴时，会收到<strong>闲置</strong>提醒（可在 定义 › 提醒 中关闭）。',
        'Telas' => '界面',
        'Idioma padrão (quem não escolheu outro no menu)' => '默认语言（适用于未在菜单中选择其他语言的人）',
        'Abrir o relógio na página Hoje' => '在“今天”页面打开手表的方式',
        'Ao lado da lista' => '在列表旁边',
        'Numa janela flutuante, grande' => '在大的浮动窗口中',
        'Destaque no alto da página Hoje' => '“今天”页面顶部的焦点',
        'O relógio do dia' => '当天的手表',
        'O relógio no pulso agora' => '现在戴在手腕上的手表',
        'Próximos dias (página Hoje): mostrar até (dias por página)' => '未来几天（“今天”页面）：每页最多显示（天）',
        'Plano: mostrar até (dias por página)' => '计划：每页最多显示（天）',
        'Endereço do sistema (a âncora {link})' => '系统地址（占位符 {link}）',
        '<strong>Ao lado da lista:</strong> o relógio clicado abre num painel à direita, e a lista continua à vista. <strong>Numa janela flutuante:</strong> abre grande, ' => '<strong>在列表旁边：</strong>点击的手表在右侧面板中打开，列表仍然可见。<strong>在浮动窗口中：</strong>大窗口打开，',
        'no meio da tela, com os quadros lado a lado; fecha no ×, no Esc ou num clique fora. No celular, os dois cobrem a tela inteira.' => '位于屏幕中央，各个方框并排；点 ×、按 Esc 或点击窗口外部即可关闭。在手机上，两种方式都会占满整个屏幕。',
        '<strong>Destaque:</strong> o quadro grande no alto da página Hoje mostra o relógio do dia (o do plano) ou o que está no pulso agora, ' => '<strong>焦点：</strong>“今天”页面顶部的大方框显示当天的手表（计划中的）或现在戴在手腕上的手表，',
        'mesmo que seja outro (o do dia aparece embaixo do nome). Sem nenhum relógio no pulso, fica o do dia.' => '即使是另一块（当天的手表显示在名称下方）。手腕上没有手表时，显示当天的手表。',
        '<strong>Mostrar até:</strong> quantos dias os Próximos dias (página Hoje, padrão 7) e o dia a dia da página Plano (padrão 31) mostram de cada vez. ' => '<strong>最多显示：</strong>“未来几天”（“今天”页面，默认 7）和“计划”页面的逐日列表（默认 31）每次显示多少天。',
        'Passando disso, embaixo aparecem as páginas: &lt; (anterior), os números e &gt; (próxima).' => '超出时，底部会出现分页：&lt;（上一页）、页码和 &gt;（下一页）。',
        'Cron' => 'Cron',
        'Sorteios' => '抽选',
        'Os números vêm de' => '随机数来源',
        '1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP' => '1. RANDOM.ORG（大气噪声）· 2. 不可用时用 ANU QRNG（量子）· 3. 两者都不可用时用 PHP 的安全生成器',
        'Último lote' => '上一批',
        'nenhum ainda' => '还没有',
        'Serviços fora' => '不可用的服务',
        'os dois sem responder desde {1} {2}; o sistema tenta de novo depois de 10 minutos' => '两者自 {1} {2} 起都没有响应；系统会在 10 分钟后重试',
        'Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés.' => '系统中所有的抽选（完全随机轮换、按评分抽选以及排程中同分时的决胜）都使用这些数字。它们成批到达，每次抽选只取所需，没有偏差。',
        'Telegram (API de alerta)' => 'Telegram（提醒 API）',
        'Enviar alertas' => '发送提醒',
        'O endereço e o destinatário ficam no config.php. O texto de cada aviso vem da mensagem padrão do Telegram ou da personalizada dele, em "O que vai para onde".' => '地址和接收人在 config.php 中。每条提醒的文本来自 Telegram 的默认消息或它自己的自定义消息，在“各项发往何处”中设置。',
        'Google Agenda' => 'Google 日历',
        'Criar eventos na agenda' => '在日历中创建事件',
        'Antecedência dos eventos (dias)' => '事件提前创建（天）',
        'ID da agenda' => '日历 ID',
        'xxxx@group.calendar.google.com' => 'xxxx@group.calendar.google.com',
        'Caminho da chave JSON no servidor' => '服务器上 JSON 密钥的路径',
        'Chave encontrada. Compartilhe a agenda com {1}, com permissão para fazer alterações nos eventos.' => '已找到密钥。请将日历共享给 {1}，并授予更改事件的权限。',
        'Nenhuma chave válida nesse caminho. Confira o nome do arquivo e se o usuário do PHP-FPM (www-data) tem permissão de leitura.' => '该路径下没有有效的密钥。请检查文件名，以及 PHP-FPM 用户（www-data）是否有读取权限。',
        'O teste cria um evento daqui a 10 minutos, no formato dos modelos. Salve antes de testar.' => '测试会在 10 分钟后创建一个事件，格式与模板相同。请先保存再测试。',
        'Criar evento de teste' => '创建测试事件',
        'Remover evento de teste' => '删除测试事件',
        'Inserir âncora na mensagem padrão do {1}' => '在 {1} 的默认消息中插入占位符',
        'Mensagem padrão' => '默认消息',
        'Todo aviso usa a mensagem padrão do canal, a não ser que tenha a sua personalizada, marcada em "O que vai para onde". As âncoras entre chaves, como {relogio}, viram os valores na hora de enviar; "Inserir âncora" põe uma onde está o cursor.' => '每条提醒都使用该渠道的默认消息，除非它有自己的自定义消息（在“各项发往何处”中勾选）。花括号中的占位符（如 {relogio}）会在发送时替换为实际的值；“插入占位符”会在光标处插入一个。',
        'O que cada âncora vira' => '每个占位符代表什么',
        'Excluir o evento {1}?' => '删除事件 {1}？',
        '{1} no {2}' => '{2} 上的 {1}',
        '{1}, personalizado no {2}' => '{1}，在 {2} 上自定义',
        'Vazio usa a mensagem padrão do {1}' => '为空则使用 {1} 的默认消息',
        'O que vai para onde' => '各项发往何处',
        'Marque "Personalizar" num canal para aquele aviso ter uma mensagem só dele, no lugar da mensagem padrão do canal. Cada canal tem a sua.' => '在某个渠道上勾选“自定义”，该提醒就会使用自己的消息，而不是该渠道的默认消息。每个渠道各有一条。',
        'Quando' => '何时',
        'Personalizar' => '自定义',
        'As mudanças desta página valem depois de salvar.' => '本页的更改在保存后生效。',
        'Salvar configuração' => '保存设置',
        'Conferir a carga dos smartwatches' => '检查智能手表的电量',
        'Relógio (opcional: com relógio, as âncoras dele funcionam) {1}' => '手表（可选：选择手表后，它的占位符可用）{1}',
        'Nenhum, é um evento geral' => '无，这是一个通用事件',
        ' (indisponível)' => '（不可用）',
        'Quando dispara {1}' => '触发时间 {1}',
        'Data' => '日期',
        'A partir de' => '开始于',
        'Hora {1}' => '时间 {1}',
        'Dia do mês {1}' => '每月的第几天 {1}',
        'A cada quantos dias {1}' => '每隔多少天 {1}',
        'Dias da semana' => '星期',
        ' Ativo' => ' 启用',
        'Próximas vezes: {1}.' => '接下来的时间：{1}。',
        'nenhuma nos próximos 60 dias' => '未来 60 天内没有',
        'Depois de salvar, o evento aparece na tabela "O que vai para onde", onde se escolhem os canais e o texto de cada um. Evento novo já vem marcado para o Telegram.' => '保存后，事件会出现在“各项发往何处”表中，可在那里选择渠道和每个渠道的文本。新事件默认已勾选 Telegram。',
        'Salvar alterações' => '保存更改',
        'Criar evento' => '创建事件',
        'Eventos personalizados' => '自定义事件',
        'Um aviso seu, com horário e repetição próprios: todo dia, em dias da semana, todo mês, a cada N dias ou uma vez só. Os eventos já criados estão na tabela acima (editar e excluir ficam no nome deles).' => '你自己的提醒，有自己的时间和重复方式：每天、每周的某几天、每月、每隔 N 天或只一次。已创建的事件在上方的表中（编辑和删除在其名称上）。',
        'Editar o evento {1}' => '编辑事件 {1}',
        'Novo evento' => '新事件',
        'Como sai hoje' => '今天会发出什么',
        'Telegram de manhã' => '早上的 Telegram',
        '(nada a enviar)' => '（没有要发送的）',
        'Enviar agora' => '立即发送',
        'Telegram à noite' => '晚上的 Telegram',
        '(nada a enviar: amanhã continua o mesmo relógio)' => '（没有要发送的：明天仍是同一块表）',
        'Agenda' => '日历',
        'Nada previsto no período.' => '该时段内没有安排。',
        '{1} eventos criados pelo sistema estão na agenda. Mudou um modelo? Sincronize: os eventos já criados são atualizados.' => '系统创建的 {1} 个事件在日历中。改了模板？请同步：已创建的事件会被更新。',
        'Sincronizar agora' => '立即同步',
        'Cópia de segurança' => '备份',
        'Uma cópia do banco inteiro por dia, na rodada da noite, guardando as {1} mais novas, {2} o conteúdo dos documentos (os arquivos já ficam na pasta deles). A cópia volta em qualquer um dos três bancos, na mesma versão do sistema. {3}' => '每天在晚间运行时备份整个数据库一次，保留最新的 {1} 份，{2}文档的内容（文件本身已保存在各自的文件夹中）。备份可以在三种数据库中的任意一种恢复，但需要相同的系统版本。{3}',
        'Última: {1} {2}.' => '最近一次：{1} {2}。',
        'Nenhuma feita ainda.' => '还没有备份。',
        'A cópia automática está desligada: {1}. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada.' => '自动备份已关闭：{1}。请在 config.php 中设置 BACKUP_PASTA，即服务器上发布目录之外的一个文件夹。',
        'Cópia' => '备份',
        'Feita em' => '创建于',
        'Tamanho' => '大小',
        'Baixar' => '下载',
        'Voltar o banco para a cópia de {1}? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora.' => '把数据库恢复到 {1} 的备份？之后所做的一切都会丢失。恢复前，系统会先备份当前的状态。',
        'Restaurar' => '恢复',
        'Fazer uma cópia agora' => '立即备份',
        'Não consegui ler a configuração: {1}' => '无法读取设置：{1}',
        'Configuração' => '设置',
        'Inteligente' => '智能',
        'vai o relógio com a maior nota nos critérios' => '选规则评分最高的手表',
        'Inteligente com sorteio' => '智能抽选',
        'sorteio em que a nota de cada relógio é a chance dele: variedade sem perder o critério' => '每块手表的评分就是它的中签概率：既有变化又不失规则',
        'todos com a mesma chance, sem olhar os critérios (os números do RANDOM.ORG; fora do ar, do ANU QRNG; sem os dois, do gerador seguro do PHP)' => '所有手表机会均等，不看规则（数字来自 RANDOM.ORG；不可用时来自 ANU QRNG；两者都不可用时来自 PHP 的安全生成器）',
        'Fila (FIFO)' => '队列（FIFO）',
        'vai o que está há mais tempo sem uso: todos passam pelo pulso em rodízio' => '选闲置最久的：所有手表轮流戴',
        'Critérios de escolha do relógio' => '手表的选择规则',
        'Não foi salvo:' => '未保存：',
        'Como a nota funciona' => '评分是如何计算的',
        'Cada {1} — todos os relógios, um grupo em qualquer nível da árvore, ou um relógio — pode ter o seu {2}. O relógio usa o conjunto {3}, inteiro: o dele; senão o do grupo dele; senão o do grupo de cima; e assim até o de todos os relógios. Um lugar sem conjunto próprio herda o de cima.' => '每个{1}——所有手表、树中任意层级的分组，或一块手表——都可以有自己的{2}。手表整体使用{3}的那一组：它自己的；没有则用它所在分组的；再没有则用上一级分组的；依此类推，直到所有手表的那一组。没有自己规则组的位置继承上一级的。',
        'conjunto de critérios' => '规则组',
        'mais perto dele' => '离它最近',
        'Num conjunto, cada {1} tem um peso, e a soma fecha 100%. Cada parâmetro tem {2}, com peso dentro dele, que também fecha 100%. Cada subparâmetro mede uma coisa do relógio e usa {3} para transformar o valor medido numa nota de 0 a 100. {4} = peso do subparâmetro × peso do parâmetro; {5} = soma de nota × peso efetivo. Subparâmetro sem medida para o relógio (autonomia num relógio que não é smartwatch, por exemplo) sai da conta, e os pesos dos que ficam são reescalados.' => '在一个规则组中，每个{1}都有一个权重，总和为 100%。每个参数下有若干{2}，各自在参数内有权重，总和也为 100%。每个子参数衡量手表的一个方面，并用{3}把测量值转换成 0 到 100 的评分。{4} = 子参数权重 × 参数权重；{5} = 评分 × 有效权重之和。对手表没有测量值的子参数（例如非智能手表的续航）不参与计算，其余子参数的权重会重新按比例分配。',
        'parâmetro' => '参数',
        'subparâmetros' => '子参数',
        'Peso efetivo' => '有效权重',
        'nota final' => '最终评分',
        'Como a nota vira escolha' => '评分如何变成选择',
        'Cada modo de rodízio tem a sua forma de escolher o relógio, escolhida no quadro {1}, na página Hoje:' => '每种轮换模式都有自己的选表方式，在“今天”页面的 {1} 方框中选择：',
        'Modo de rodízio' => '轮换模式',
        '(o modo atual)' => '（当前模式）',
        'sempre pela maior nota, com as medidas de cada dia simulado' => '始终按最高评分，使用每个模拟日的测量值',
        'Garantia de rodízio: {1} (no mesmo quadro). Fora da nota também valem o grupo de cada bloco de dias, os relógios fixos e não repetir o de ontem.' => '轮换保证：{1}（在同一个方框中）。评分之外，每个区块的分组、固定手表以及不重复昨天的手表也同样适用。',
        'nenhum relógio fica mais de {1} dias sem uso' => '任何手表都不会超过 {1} 天不戴',
        'Onde há critérios' => '哪里有规则',
        'Lugar' => '位置',
        'Parâmetros' => '参数',
        'Usado por' => '使用者',
        'relógio' => '块手表',
        'relógios' => '块手表',
        'Nenhum lugar tem critérios: todos os relógios ficam com nota neutra, 50.' => '没有任何位置有规则：所有手表都得中性分 50。',
        'Há relógios sem conjunto nenhum (nota neutra, 50): {1}.' => '有手表没有任何规则组（中性分 50）：{1}。',
        'Editar os critérios de' => '编辑以下位置的规则',
        ' — com critérios próprios' => ' — 有自己的规则',
        'Abrir' => '打开',
        '{1} não tem critérios próprios{2}' => '{1} 没有自己的规则{2}',
        ': usa os de {1}.' => '：使用 {1} 的规则。',
        ', e nenhum lugar acima tem: nota neutra, 50.' => '，且上级位置都没有：中性分 50。',
        'Criar critérios próprios, copiando os de {1}' => '创建自己的规则，复制 {1} 的规则',
        'Criar vazio' => '创建空的',
        'Critérios de {1}' => '{1} 的规则',
        'Usado por {1} {2}{3}. Os lugares abaixo deste, sem critérios próprios, também usam estes.' => '使用者：{1} {2}{3}。此处以下没有自己规则的位置也使用这些规则。',
        'Parâmetro' => '参数',
        'Peso no conjunto' => '在规则组中的权重',
        'Subparâmetros' => '子参数',
        'subparâmetro' => '个子参数',
        '(fora da conta)' => '（不参与计算）',
        'Subir' => '上移',
        'Descer' => '下移',
        'Soma' => '合计',
        'Salvar parâmetros' => '保存参数',
        'Excluir o parâmetro {1} ({2}) e os subparâmetros dele?

{3}' => '删除参数 {1}（{2}）及其子参数？

{3}',
        'O peso dele é dividido na proporção dos que ficam:
