        'O parâmetro fica sem subparâmetros e sai da conta até ganhar um.' => '该参数将没有子参数，在获得一个之前不参与计算。',
        'Nota' => '评分',
        'De' => '从',
        'Até' => '到',
        'Faixas de {1} {2}' => '{1} 的区间 {2}',
        '{1} A linha em branco serve para incluir uma faixa; o "+ faixa" cria mais.' => '{1} 空白行用于添加一个区间；“+ 区间”可添加更多。',
        'Uma nota por categoria; categoria sem faixa: o subparâmetro não se aplica ao relógio daquela categoria.' => '每个类别一个评分；没有区间的类别：该子参数不适用于该类别的手表。',
        'Nota de 0 a 100. "De" entra na faixa, "até" não (a última inclui o seu "até"); "até" vazio = sem limite. A primeira começa em 0; cada uma começa onde a anterior terminou; a última vai até {1}.' => '评分为 0 到 100。“从”包含在区间内，“到”不包含（最后一个区间包含它的“到”）；“到”为空 = 没有上限。第一个区间从 0 开始；每个区间从上一个结束的地方开始；最后一个一直到 {1}。',
        '"sem limite" (até vazio)' => '“没有上限”（“到”为空）',
        '{1} (ou sem limite)' => '{1}（或没有上限）',
        '+ faixa' => '+ 区间',
        'Salvar faixas' => '保存区间',
        'Trocar o que {1} mede? As faixas atuais serão apagadas, e ele recomeça com nota 50 em tudo.' => '更改 {1} 测量的内容？当前的区间将被删除，并从全部 50 分重新开始。',
        'Trocar a medida para {1}' => '把测量改为 {1}',
        'Mover para o parâmetro {1}' => '移到参数 {1}',
        'Mover' => '移动',
        'Sem subparâmetros: este parâmetro não entra na conta até ganhar um.' => '没有子参数：在获得一个之前，此参数不参与计算。',
        'Novo subparâmetro {1}' => '新子参数 {1}',
        'Mede {1}' => '测量 {1}',
        'A nota de cada relógio agora' => '每块手表现在的评分',
        'Relógios disponíveis, da maior nota para a menor, cada um pelo conjunto de critérios que vale para ele. As regras que ficam fora da nota — o grupo de cada bloco de dias, os relógios fixos, não repetir o de ontem e a garantia de rodízio — valem na hora do sorteio.' => '可用的手表，按评分从高到低，每块都按适用于它的规则组计算。评分之外的规则——每个区块的分组、固定手表、不重复昨天的手表以及轮换保证——在抽选时生效。',
        '{1} · critérios de {2}' => '{1} · {2} 的规则',
        'Valor medido' => '测量值',
        'Faixa' => '区间',
        'Pontos' => '得分',
        'Nenhum critério com medida para este relógio: nota neutra, 50.' => '这块手表没有可测量的规则：中性分 50。',
        'Nota final (pesos efetivos somam {1})' => '最终评分（有效权重合计 {1}）',
        'editar os critérios de {1}' => '编辑 {1} 的规则',
        'critérios só deste relógio' => '仅这块手表的规则',
        'Restaurar os critérios iniciais' => '恢复初始规则',
        'Apagar todos os critérios de todos os lugares e voltar aos iniciais?' => '删除所有层级的全部标准并恢复为初始标准？',
        'Apaga os critérios de todos os lugares e volta aos que vieram com o sistema: um conjunto para todos os relógios e um para cada grupo principal. A forma de escolha e a garantia de rodízio não mudam.' => '删除所有位置的规则，恢复系统自带的规则：一组用于所有手表，每个主要分组各一组。选择方式和轮换保证不变。',
        'fecha 100%' => '合计 100%',
        'passa {1}%' => '超出 {1}%',
        'faltam {1}%' => '还差 {1}%',
        'Não consegui ler os critérios: {1}' => '无法读取规则：{1}',
        'Critérios de escolha' => '选择规则',
        'Lista de desejos' => '心愿单',
        'Novo desejo' => '新心愿',
        'Nenhum relógio na lista de desejos. Em "Novo desejo" (ou no cadastro de qualquer relógio, na "Situação na coleção"), um relógio desejado entra aqui: com a marca, a referência, o preço-alvo, a prioridade e o link. Ele não entra no rodízio nem nos avisos.' => '心愿单中没有手表。在“新心愿”中（或在任意手表档案的“在收藏中的状态”里），心愿手表会出现在这里：包括品牌、型号、目标价、优先级和链接。它不参与轮换，也没有提醒。',
        '{1}{2}, a prioridade mais alta primeiro. Somando os preços-alvo: R$ {3}{4}. Comprou? "Comprei" põe o relógio na coleção (disponível para o rodízio) e abre a ficha dele, para preencher a compra.' => '{1}{2}，优先级最高的在前。目标价合计：R$ {3}{4}。买到了？“我买了”会把手表放进收藏（可参与轮换）并打开它的档案，以便填写购买信息。',
        ' relógio desejado' => ' 块心愿手表',
        ' relógios desejados' => ' 块心愿手表',
        ' ({1} sem preço-alvo)' => '（{1} 块没有目标价）',
