        'Link' => '链接',
        'R$ ' => 'R$ ',
        'abrir a página' => '打开页面',
        'Comprei' => '我买了',
        'Comprou o {1}? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra.' => '你买了 {1} 吗？它会进入收藏，可参与轮换，并打开它的档案供你填写购买信息。',
        'Fora da coleção' => '收藏之外',
        'Nenhum relógio emprestado, vendido ou arquivado. No cadastro de um relógio, a "Situação na coleção" muda isso: fora dela, ele sai do rodízio, do plano e dos avisos; a ficha, os documentos e o histórico ficam.' => '没有借出、卖出或归档的手表。在手表档案中修改“在收藏中的状态”即可：离开收藏后，它会退出轮换、计划和提醒；档案、文档和历史记录都会保留。',
        'Emprestados, vendidos e arquivados: fora do rodízio, do plano e dos avisos (o emprestado continua na tabela da página Hoje e no valor da coleção). A ficha, os documentos e o histórico ficam.' => '借出、卖出和归档的手表：不参与轮换、计划和提醒（借出的手表仍在“今天”页面的表格中，并计入收藏价值）。档案、文档和历史记录都会保留。',
        'Situação' => '状态',
