        'Uma árvore sem limite de níveis. Cada relógio fica num grupo só. Cada grupo pode ter os seus próprios {1}; o relógio usa os do lugar mais perto dele (os dele, os do grupo dele, os do grupo de cima... ou os de todos). O mesmo nome pode se repetir em ramos diferentes. Os campos, os tipos de lançamento, as fórmulas e os avisos de cada grupo ficam em {2}.' => '一棵层级不限的树。每块手表只属于一个分组。每个分组可以有自己的{1}；手表使用离它最近的那一层（自己的、所在分组的、上级分组的……或全部的）。同一个名称可以在不同分支中重复。每个分组的字段、记录类型、公式和提醒在{2}中。',
        'critérios' => '标准',
        'a raiz' => '根目录',
        'Excluir o grupo {1}?

Vão para {2}: {3} subgrupo(s) e {4} relógio(s), com os campos, os tipos de lançamento e as fórmulas dele.{5}' => '删除分组 {1}？

将移到 {2}：{3} 个子分组和 {4} 块手表，连同它的字段、记录类型和公式。{5}',
        '
Os critérios próprios do grupo ({1} parâmetros) serão excluídos; os relógios passam a usar os de cima.' => '
该分组自己的标准（{1} 个参数）将被删除；手表改用上级的标准。',
