        'Nada lançado ainda.' => '还没有任何记录。',
        'Estado {1}' => '状态 {1}',
        '{1} {2} com esses filtros{3}. Os trechos são contínuos: em uso (rodízio), fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso; as marcações (corda, carga, pilha, revisão) não têm fim nem duração.' => '{1} {2}（按这些筛选条件）{3}。各时段是连续的：使用中（轮换）、不在轮换中、各种会话类型（在上链盒上、晒太阳……）以及休息中；标记（上链、充电、电池、保养）没有结束时间和时长。',
        'Fim' => '结束',
        'Estado' => '状态',
        'em andamento: o fim é o momento desta consulta' => '进行中：结束时间为本次查询的时刻',
