        'Vai o relógio com a maior nota nos critérios. Previsível: com os mesmos dados, a mesma escolha.' => '选择标准得分最高的手表。可预测：数据相同，选择也相同。',
        'Sorteio em que a nota de cada relógio é a chance dele: quem tem nota maior sai mais vezes, mas todos têm chance. Variedade sem perder o critério.' => '抽选时每块手表的得分就是它的机会：得分高的被选中更多，但每块都有机会。在保持标准的同时增加变化。',
        'Todos os relógios do tipo têm a mesma chance, sem olhar os critérios. Os números vêm do RANDOM.ORG (ruído atmosférico); fora do ar, do ANU QRNG (quântico); sem os dois, do gerador seguro do PHP.' => '该类型的所有手表机会均等，不考虑标准。随机数来自 RANDOM.ORG（大气噪声）；它不可用时来自 ANU QRNG（量子）；两者都不可用时，使用 PHP 的安全生成器。',
        'Vai o que está há mais tempo sem uso: todos passam pelo pulso, em fila. Não olha os critérios, e já garante o rodízio por natureza.' => '选择最久未用的那块：所有手表依次上腕。不考虑标准，本身就保证了轮换。',
        'Dia' => '日期',
        'Lembrete' => '提醒',
        'Neste modo o sorteio é feito dia a dia.' => '在此模式下，抽选按天进行。',
        'Página {1} de {2} · {3} dias no plano, {4} por página (o "Mostrar até" da {5}).' => '第 {1} 页，共 {2} 页 · 计划中 {3} 天，每页 {4} 天（{5} 中的“最多显示”）。',
        'Não consegui ler os próximos dias: {1}' => '无法读取接下来的日子：{1}',
        'sem modo' => '无模式',
        'no pulso agora' => '正在佩戴',
        'Relógio do dia: {1} ({2})' => '今日手表：{1}（{2}）',
        'Hoje não tem relógio do dia.' => '今天没有今日手表。',
        'Por que ele: ' => '为什么是它：',
        'Hoje sem relógio? O dia fica livre: o {1} sai do rodízio de hoje (se já está no pulso pelo rodízio, sai agora; o tempo que ficou conta). Os outros dias não mudam.' => '今天不戴表？这一天空出来：{1} 退出今天的轮换（如果已经因轮换戴在手腕上，现在取下；已佩戴的时间照常计入）。其他日子不变。',
        'Sem relógio hoje' => '今天不戴表',
        'Hoje sem relógio' => '今天不戴表',
        'dia livre' => '空闲日',
        'Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? Escolha abaixo, ou sorteie de novo (inclusive hoje) no quadro do modo de rodízio.' => '今天轮换中没有手表上腕。想戴一块吗？在下面选择，或在轮换模式面板中重新抽选（包括今天）。',
        'Nenhum relógio para hoje' => '今天没有手表',
        'Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível.' => '这一天的分组中没有可用的手表。请在轮换模式中更改分组，或将一块手表标记为可用。',
