        'ver o plano inteiro →' => '查看完整计划 →',
        'Sortear entre' => '抽选范围',
        ' (indisponível: o dia sorteia outro do mesmo grupo)' => '（不可用：当天从同一分组中另抽一块）',
        'Modo de rodízio {1}' => '轮换模式 {1}',
        'Rodízio manual' => '手动轮换',
        'Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre ({1}).' => '你为一段时间内的每一天选择手表。设置开始和结束日期并点击“确定”：日期每 7 天一组显示，每天都有手表列表、“替我决定”（由系统选择）和“不戴表（空闲日）”。在这段时间之外，仍按平常的轮换模式（{1}）。',
        'nenhum' => '无',
        'Monta o plano do período inteiro de uma vez, simulando a carga de cada relógio dia a dia, com os lembretes de carregar, dar corda e pôr no sol. É refeita toda manhã a partir do estado real.' => '一次性为整个期间制定计划，逐日模拟每块手表的电量，并提醒充电、上链和晒太阳。每天早上根据实际状态重新制定。',
        'Cada bloco de dias sorteia entre os relógios do grupo escolhido, ou usa o relógio fixo; marcando "sortear um por dia", cada dia do bloco tem o seu sorteio. O plano vem montado até domingo; a semana seguinte é sorteada quando começa.' => '每个日期块从所选分组的手表中抽选，或使用固定手表；勾选“每天抽一块”后，该块的每一天都单独抽选。计划制定到星期日；下一周在开始时抽选。',
        'Período {1}' => '期间 {1}',
        'Uma semana' => '一周',
        'Um mês' => '一个月',
        'Dois meses' => '两个月',
        'Meio ano' => '半年',
        'Um ano' => '一年',
        'Dois anos' => '两年',
        '{1} sortear um por dia' => '{1} 每天抽一块',
        'Como escolher o relógio {1}' => '如何选择手表 {1}',
        'Como escolher o relógio: {1}' => '如何选择手表：{1}',
        'pela maior nota' => '按最高分',
        'A escala escolhe sempre pela maior nota nos critérios, com as medidas de cada dia simulado.' => '排程总是按标准的最高分选择，并使用每个模拟日的测量值。',
        'Garantia de rodízio: dias sem uso, no máximo {1}' => '轮换保证：未使用天数，最多 {1}',
        'Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota.' => '超过上限的优先，闲置最久的排在最前。0 表示关闭。同一数值适用于所有使用分数的模式。',
        'A nota vem dos {1}, que você cadastra.' => '分数来自你定义的{1}。',
        'Trocar o modo refaz o plano a partir de amanhã; hoje continua o {1}. Continuar?' => '更改模式会从明天起重新制定计划；今天仍是 {1}。继续？',
        'Trocar o modo apaga o plano atual. Continuar?' => '更改模式会清除当前计划。继续？',
        'Aplicar modo' => '应用模式',
        'Trocar o modo apaga o plano atual e gera outro{1}. O histórico de uso, corda, sol e carga continua. Os modos e os blocos de dias se cadastram em {2}.' => '更改模式会清除当前计划并生成新计划{1}。使用、上链、晒太阳和充电的历史保留。模式和日期块在{2}中定义。',
        ' a partir de amanhã: hoje continua o {1}, que já está no pulso (para trocar hoje, use "Usando hoje")' => '（从明天起：今天仍是已经戴在手腕上的 {1}；要更改今天，请使用“今天佩戴”）',
        ' a partir de hoje' => '（从今天起）',
        'o fim da escala' => '排程结束',
        'domingo' => '星期日',
        'a partir de amanhã' => '从明天起',
        'Refaz o plano de amanhã até {1} pelo modo atual; hoje continua o {2}.' => '按当前模式重新制定从明天到 {1} 的计划；今天仍是 {2}。',
        'Sortear de novo a partir de amanhã? Hoje continua o {1}.' => '从明天起重新抽选？今天仍是 {1}。',
        'inclusive hoje' => '包括今天',
        'Refaz também hoje: se sair outro relógio, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => '今天也重做：如果抽到另一块手表，它从现在起成为佩戴的手表，{1} 取下。',
        'Sortear de novo inclusive hoje? Se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora, e o {1} sai.' => '重新抽选并包括今天？如果今天抽到另一块手表，它从现在起成为佩戴的手表，{1} 取下。',
