        'o banco recusou a gravação: ela quebraria uma regra dos dados (um registro que outro ainda usa, um valor repetido onde não pode, ou um valor fora das regras de validação do banco)' => '数据库拒绝了写入：它会违反数据规则（另一条记录仍在使用的记录、不允许重复的地方出现重复值，或超出数据库校验规则的值）',
