        'Relógio de amanhã' => '明天的手表',
        'alerta da noite enviado' => '晚间提醒已发送',
        'erro: a API de alerta não aceitou o alerta da noite' => '错误：提醒 API 没有接受晚间提醒',
        'noite: amanhã continua o mesmo relógio, nada a preparar' => '晚间：明天还是同一块手表，无需准备',
