    'ajuda' => [
        'api.php devolve tudo o que está guardado, sem filtro: arvore, campos, lancamento_tipos, formulas, avisos, relogios (com os valores dos campos, o resultado de cada fórmula, os avisos, os lançamentos, a previsão e a linha do tempo inteira com o resumo), modos, plano (inteiro), config (inteira), eventos (com os disparos), agenda, criterios (com a nota de cada relógio), cron (todas as execuções guardadas), usuarios (os logins), migracoes e motor, e as categorias dos documentos (documento_categorias). A senha dos usuários não existe no sistema: sai o hash dela (veja senhas). Os arquivos dos documentos não vêm (só os dados de cada um, em relogios[].documentos): eles saem pelo recurso=documento. Para pegar só uma parte, ou filtrar, ordenar e paginar: veja filtros.' => 'api.php 返回全部已保存的内容，无筛选：arvore、campos、lancamento_tipos、formulas、avisos、relogios（含各字段的值、每条公式的结果、提醒、记录、预测以及带摘要的完整时间线）、modos、plano（完整）、config（完整）、eventos（含触发记录）、agenda、criterios（含每块手表的分数）、cron（全部已保存的执行）、usuarios（登录名）、migracoes 和 motor，以及文档类别（documento_categorias）。用户密码在系统中不存在：输出的是其 hash（见 senhas）。文档文件本身不返回（只有各自的数据，位于 relogios[].documentos）：文件通过 recurso=documento 获取。若只要一部分，或要筛选、排序和分页：见 filtros。',
        'token (cabeçalho X-Api-Token ou parâmetro token; o API_TOKEN do config.php, obrigatório, com pelo menos 10 caracteres) ou o login do site (HTTP Basic), em todo pedido. Ex.: curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje; curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje' => 'token（请求头 X-Api-Token 或参数 token；config.php 中的 API_TOKEN，必填，至少 10 个字符）或网站登录（HTTP Basic），每个请求都要带。例：curl -H "X-Api-Token: segredo" http://servidor/relojoeiro/api.php?recurso=hoje; curl -u lucas:senha http://servidor/relojoeiro/api.php?recurso=hoje',
        'JSON (padrão) ou XML: formato=xml, ou o cabeçalho Accept com xml. Ex.: http://servidor/relojoeiro/api.php?recurso=plano&formato=xml' => 'JSON（默认）或 XML：formato=xml，或请求头 Accept 含 xml。例：http://servidor/relojoeiro/api.php?recurso=plano&formato=xml',
        'tudo o que está guardado, sem filtro (os relógios com os campos, as fórmulas, os avisos, os lançamentos, a previsão e a linha do tempo; modos, plano, configuração, eventos, agenda e o motor)' => '全部已保存的内容，无筛选（手表及其字段、公式、提醒、记录、预测和时间线；模式、计划、设置、事件、日历和引擎）',
        'nao: sem as fotos em base64 (a resposta fica bem menor)' => 'nao：不含 base64 照片（响应会小很多）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?foto=nao"',
        'tudo o que a página Hoje mostra: o dia e o relógio dele, os avisos de hoje (com o lançamento que resolve cada um), os próximos 62 dias do plano, os Próximos dias da página (uma página: proximos), os modos com os blocos, os grupos, a tabela dos relógios (os da coleção: na coleção e emprestados), os que estão fora dela (desejados, vendidos, arquivados: fora_da_colecao) e os totais da coleção (quantos, disponíveis, em uso, o valor pago, quantos desejados e quantos fora)' => '今天页面显示的全部内容：当天及其手表、今天的提醒（含解决每一条的记录）、计划中接下来的 62 天、页面上的接下来的日子（一页：proximos）、带区块的模式、分组、手表表（收藏中的：在收藏中和已借出）、收藏之外的（心愿中、已售出、已归档：fora_da_colecao）以及收藏合计（数量、可用、使用中、已付金额、心愿数量和之外的数量）',
        'a página dos Próximos dias (padrão 1)' => '接下来的日子的页码（默认 1）',
        'quantos dias por página nos Próximos dias (sem ele: o Mostrar até da Configuração, padrão 7)' => '接下来的日子中每页多少天（不传时：设置中的显示至，默认 7）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hoje"',
        'tudo o que o painel de um relógio mostra: agora, carga e de onde vem, situação, nota, quando entra no rodízio, compra, próximas manutenções, previsão, o gasto da bateria, quantos documentos o relógio tem em cada categoria, os tipos de lançamento dele (com a sessão aberta), as últimas leituras, as marcações dos últimos 14 dias, o resumo do histórico, a situação na coleção (com o desejo, no desejado) e o cadastro; sem relogio, só o cadastro de um relógio novo; relógio que não existe: 404' => '一块手表的面板所显示的全部内容：现在、电量及其来源、情况、分数、何时进入轮换、购买、各项下次保养、预测、电池消耗、该手表在每个类别中有多少文档、其记录类型（含已打开的时段）、最近的读数、最近 14 天的标记、历史摘要、在收藏中的情况（含心愿，处于心愿中时）以及档案；不传 relogio 时，只有新手表的档案；手表不存在：404',
        'o id do relógio (vazio: o cadastro de um relógio novo)' => '手表的 id（空：新手表的档案）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ficha&relogio=10"',
        'tudo o que a página Configuração mostra: os valores (inclusive o caminho da chave do Google), o Mostrar até de cada lista (mostrar_ate), de onde vêm os números dos sorteios (aleatorio: RANDOM.ORG, senão ANU QRNG, senão o gerador seguro do PHP; o último lote), os canais com a mensagem padrão e a personalizada de cada tipo de aviso, os eventos personalizados, a chave do Google lida ou não, como as mensagens e a agenda saem agora e a situação do cron (nunca rodou, parado ou rodando)' => '设置页面显示的全部内容：各值（包括 Google 密钥的路径）、每个列表的显示至（mostrar_ate）、抽签数字的来源（aleatorio：RANDOM.ORG，否则 ANU QRNG，否则 PHP 的安全随机生成器；最近一批）、各渠道及其每种提醒类型的默认消息和自定义消息、自定义事件、Google 密钥是否已读取、消息和日历当前如何发出，以及 cron 的情况（从未运行、已停止或运行中）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=config"',
        'as execuções do cron, com o resumo do período (total, com atividade, com erro, a mais lenta) e páginas; sem atividade elas ficam 7 dias, com atividade ou erro, 1 ano' => 'cron 的各次执行，含该时段摘要（总计、有活动、有错误、最慢的一次）和分页；无活动的保留 7 天，有活动或有错误的保留 1 年',
        'data (AAAA-MM-DD) ou data e hora (AAAA-MM-DD HH:MM[:SS], espaço ou T); cron_de e cron_ate também valem' => 'data（AAAA-MM-DD）或日期和时间（AAAA-MM-DD HH:MM[:SS]，空格或 T）；cron_de 和 cron_ate 同样有效',
        'atividade (padrão), erro, nada ou todas; cron_situacao também vale' => 'atividade（默认）、erro、nada 或 todas；cron_situacao 同样有效',
        'texto no registro; cron_busca também vale' => '记录中的文本；cron_busca 同样有效',
        'por página (padrão 100, máximo 1000)' => '每页数量（默认 100，最大 1000）',
        'a página (padrão 1)' => '页码（默认 1）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cron&situacao=erro&de=2026-09-01&busca=agenda"',
        'os grupos em ordem de árvore (com o caminho, os de cima, quantos subgrupos, os relógios direto neles e quantos parâmetros de critérios próprios) e o grupo de cada relógio' => '按树顺序排列的分组（含路径、上级、子分组数量、直接属于它们的手表，以及自有标准参数的数量）和每块手表的分组',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=arvore"',
        'tudo o que a página Cadastros mostra: campos, tipos de lançamento (com quantos lançamentos cada um tem), fórmulas e avisos (todas as versões), modos com os blocos, grupos, relógios e as funções do motor' => '定义页面显示的全部内容：字段、记录类型（含各自有多少条记录）、公式和提醒（全部版本）、带区块的模式、分组、手表以及引擎的函数',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=cadastros"',
        'calcula uma fórmula sem gravar, em cada relógio (ou nos pedidos), com as partes da conta (o testar da página Cadastros); fórmula com erro de escrita: 400 com os erros' => '在每块手表上（或在所请求的手表上）计算一条公式而不保存，并给出计算的各部分（定义页面的测试）；公式书写错误：400 并附带错误',
        'a fórmula' => '公式',
        'um id ou vários separados por vírgula (vazio: todos)' => '一个 id 或多个以逗号分隔（空：全部）',
        'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12' => 'curl -u lucas:senha -G "http://servidor/relojoeiro/api.php" --data-urlencode recurso=calcular --data-urlencode "expressao=energia * 2" -d relogio=10,12',
        'os avisos de todos os relógios da coleção agora (os desejados, vendidos e arquivados não têm aviso), do mais urgente ao mais distante, com a data prevista, quanto falta, o estado (atrasado, em_breve, ok) e o texto' => '收藏中全部手表当前的提醒（心愿中、已售出和已归档的没有提醒），从最紧急到最远，含预计日期、还差多少、状态（atrasado、em_breve、ok）和文本',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=avisos"',
        'os conjuntos de critérios por lugar (parâmetros, subparâmetros, faixas), as variáveis que podem medir (com o limite), os lugares (quem tem critérios próprios e de quem herda), os modos e a nota de cada relógio com a conta' => '按位置划分的标准集合（参数、子参数、区间）、可度量的变量（含上限）、各个位置（谁有自有标准、从谁继承）、模式，以及每块手表带计算过程的分数',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=criterios"',
        'a linha do tempo: trechos contínuos por estado (rodizio, pulso fora do rodízio, cada tipo de sessão, repouso) e as marcações, com o resumo do tempo em cada estado e os lançamentos crus do período' => '时间线：按状态划分的连续片段（rodizio、pulso 即轮换之外的手腕、每种时段类型、repouso）和标记，含每个状态的时间摘要以及该时段的原始记录',
        'um id ou vários (relogio_id também vale; vazio: todos)' => '一个 id 或多个（relogio_id 同样有效；空：全部）',
        'data ou data e hora; entra a linha que cruza o período' => '日期或日期和时间；与该时段相交的行会纳入',
        'rodizio, pulso, winder, sol, repouso, marca... (um ou vários; linha_estado também vale)' => 'rodizio、pulso、winder、sol、repouso、marca……（一个或多个；linha_estado 同样有效）',
        'a página' => '页码',
        'desc (padrão, mais recente primeiro) ou asc; dois no mesmo instante saem pela ordem em que foram lançados (o id)' => 'desc（默认，最近的在前）或 asc；同一时刻的两条按被记录的顺序输出（即 id）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=historico&relogio=3&de=2026-09-01&estado=marca"',
        'a previsão da energia dos relógios com leitura (o smartwatch): quanto dura usando, quando chega ao limite parado, com quanto entra no próximo rodízio e quanto precisa, e a confiança da conta' => '带读数的手表（智能手表）的能量预测：使用时能持续多久、静止时何时到达限值、以多少能量进入下一次轮换以及还需要多少，以及计算的置信度',
        'um id ou vários (vazio: todos)' => '一个 id 或多个（空：全部）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=previsao&relogio=10"',
        'o plano gravado (a escala de dois anos sai inteira), o dia a dia da página Plano uma página por vez (dia_a_dia, com os dias livres no meio), com o modo ativo, o fim da escala e o último dia gravado; cada dia com o relógio, o bloco, a origem (sorteio ou manual) e o lembrete; os dias livres do período (sem relógio e sem sorteio, para escolher à mão); e o resumo do período (de hoje em diante), como a página Plano mostra: quantos dias cada relógio tem, a porcentagem, o próximo dia, quantos à mão e os relógios sem nenhum dia' => '已保存的计划（两年排班表完整输出）、计划页面的逐日内容每次一页（dia_a_dia，中间含空闲日），含当前模式、排班表结束日和最后保存日；每一天含手表、区块、来源（抽签或手动）和备忘；该时段的空闲日（无手表且无抽签，供手动选择）；以及从今天起的时段摘要，与计划页面所显示的一致：每块手表有多少天、百分比、下一天、多少天为手动，以及没有任何一天的手表',
        'datas AAAA-MM-DD (vazio: o plano inteiro)' => '日期 AAAA-MM-DD（空：整个计划）',
        'a página do dia_a_dia (padrão 1)' => 'dia_a_dia 的页码（默认 1）',
        'quantos dias por página no dia_a_dia (sem ele: o Mostrar até da Configuração, padrão 31)' => 'dia_a_dia 中每页多少天（不传时：设置中的显示至，默认 31）',
        'o id: o dia_a_dia só com os dias desse relógio' => 'id：dia_a_dia 只含该手表的日子',
        'N: os próximos N dias, de hoje em diante (no lugar de de e ate); todos: de hoje até o fim do plano' => 'N：从今天起接下来的 N 天（用来代替 de 和 ate）；todos：从今天直到计划结束',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=plano&de=2026-10-01&ate=2026-10-31"',
        'a lista de desejos (a página Desejos): os relógios desejados, a prioridade mais alta primeiro, cada um com a marca, a referência, o preço-alvo, a prioridade e o link; a soma dos preços-alvo; e os que estão fora da coleção (emprestados, vendidos, arquivados). Pôr na coleção (o Comprei): recurso=relogio, acao=salvar, posse=colecao' => '心愿单（心愿单页面）：心愿中的手表，优先级最高的在前，每块含品牌、型号、目标价格、优先级和链接；目标价格合计；以及收藏之外的（已借出、已售出、已归档）。放入收藏（我买了）：recurso=relogio, acao=salvar, posse=colecao',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=desejos"',
        'o uso da coleção num período (a página Estatísticas): o resumo (dias com relógio, horas no pulso, relógios usados, o mais e o menos usado, o valor da coleção, o custo por uso médio), cada relógio (dias de uso, horas, a parte de cada um, o custo por uso, dias sem uso, a tendência), o uso por dia da semana e por mês, e a distribuição da coleção (por grupo, marca, ano da compra, situação e cada campo de lista); as porcentagens e as alturas das barras (0 a 100, comparadas com a maior) vêm prontas. Contam as sessões no pulso (partidas na meia-noite) e as marcações antigas no pulso (o dia, sem horas)' => '某一时段内收藏的使用情况（统计页面）：摘要（有手表的天数、在手腕上的小时数、使用过的手表、使用最多和最少的、收藏金额、平均每次使用成本）、每块手表（使用天数、小时数、各自占比、每次使用成本、未使用天数、趋势）、按星期几和按月的使用，以及收藏分布（按分组、品牌、购买年份、情况和每个列表字段）；百分比和柱高（0 到 100，与最大者比较）已算好。计入手腕上的时段（在午夜拆分）以及手腕上的旧标记（只计日，不计小时）',
        'datas AAAA-MM-DD (padrão: os últimos 90 dias, até hoje; ate depois de hoje vira hoje; até 3661 dias); de=tudo: desde o primeiro uso; inválidas: 400 com erro' => '日期 AAAA-MM-DD（默认：最近 90 天，直到今天；ate 晚于今天则变为今天；最多 3661 天）；de=tudo：从第一次使用起；无效：400 并附带错误',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=estatisticas&de=2026-01-01&ate=2026-06-30"',
        'a hora do servidor para acertar os relógios (a página Hora certa): a local com o fuso, a UTC (Zulu), a letra militar do fuso e o grupo data-hora, o calendário (dia do ano, semana ISO, trimestre, dia juliano) e a fase da lua (pelo ciclo médio, aproximada), e como acertar; agora_ms, em milissegundos, para a tela acertar o relógio dela. Não usa o banco' => '用于对表的服务器时间（准确时间页面）：本地时间及时区、UTC（Zulu）、时区的军用字母和日期时间组、日历（年中第几天、ISO 周、季度、儒略日）和月相（按平均周期，为近似值），以及如何对表；agora_ms，以毫秒计，供界面对其手表对时。不使用数据库',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=hora_certa"',
        'os acessórios (a página Acessórios): pulseiras, caixas, estojos, ferramentas, carregadores, peças e outros, cada um com o tipo, o relógio de que ele é (ou solto) e a observação, pelo tipo e pelo nome; os tipos, quantos de cada tipo, quantos soltos e os relógios (o menu). Gravar: escrita acessorios' => '配件（配件页面）：表带、表盒、收纳盒、工具、充电器、零件和其他，每项含类型、所属手表（或未绑定）和备注，按类型和名称排列；类型、每种数量、未绑定数量和手表（菜单）。保存：写入 acessorios',
        'o id: só os acessórios desse relógio; 0: só os soltos (sem ele: todos)' => 'id：只返回该手表的配件；0：只返回未绑定的（不传：全部）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=acessorios&relogio=3"',
        'o passaporte de um relógio (a página Passaporte, para imprimir ou guardar em PDF), tudo já em texto: quem ele é, o cadastro preenchido (cada valor formatado pelo tipo: data, sim/não, número com a unidade, R$), a compra, o uso (a primeira e a última vez no pulso, as horas no pulso, os dias de uso e o custo por uso), as manutenções (cada tipo de marcação, quantas vezes e a última; as revisões e trocas de pilha), os acessórios, os documentos e os próximos avisos; relógio que não existe: 404' => '一块手表的护照（护照页面，用于打印或保存为 PDF），全部已是文本：它是谁、已填写的档案（每个值按类型格式化：日期、是/否、带单位的数字、R$）、购买、使用（第一次和最后一次在手腕上、在手腕上的小时数、使用天数和每次使用成本）、保养（每种标记类型、次数和最近一次；检修和更换电池）、配件、文档和即将到来的提醒；手表不存在：404',
        'o id do relógio (obrigatório)' => '手表的 id（必填）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=passaporte&relogio=3"',
        'a coleção em fotos, por grupo (a página Galeria, para ver e imprimir): cada relógio com a foto, a marca, a referência, o ano e o valor da compra e os dias de uso, e os totais' => '按分组的收藏照片（图库页面，用于查看和打印）：每块手表含照片、品牌、型号、购买年份和购买金额以及使用天数，还有合计',
        'todos: também os desejados, vendidos e arquivados (sem ele: os da coleção, na coleção e emprestados)' => 'todos：也包括心愿中、已售出和已归档的（不传：收藏中的，即在收藏中和已借出）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=galeria&posse=todos"',
        'os textos das telas no idioma do pedido (o dicionário da função t() do api.js: o texto em português => a tradução), o idioma, o locale das datas e dos números, o padrão da instalação e os idiomas do sistema. Responde sem login (é só o texto da interface). O idioma de qualquer pedido: lingua=, senão o cookie lingua (o seletor do menu), senão o padrão da instalação (config.idioma), senão o Accept-Language, senão português; toda resposta da API sai nele' => '按请求语言返回的界面文本（api.js 中函数 t() 的词典：葡萄牙语文本 => 译文）、语言、日期和数字的 locale、安装默认值以及系统的语言。无需登录即可响应（只是界面文本）。任意请求的语言：lingua=，否则 cookie lingua（菜单中的选择器），否则安装默认值（config.idioma），否则 Accept-Language，否则葡萄牙语；API 的全部响应都用该语言输出',
        'js: um script (window.TEXTOS_API = {...}), que as páginas carregam antes dos outros' => 'js：一段脚本（window.TEXTOS_API = {...}），页面会在其他脚本之前加载它',
        'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"' => 'curl "http://servidor/relojoeiro/api.php?recurso=textos&lingua=en"',
        'os Próximos dias da página Hoje, uma página (de hoje até o fim do plano, com os dias livres no meio): a troca de página da tela lê só eles' => '今天页面的接下来的日子，一页（从今天直到计划结束，中间含空闲日）：界面翻页只读取这些',
        'quantos dias por página (sem ele: o Mostrar até da Configuração, padrão 7)' => '每页多少天（不传时：设置中的显示至，默认 7）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=proximos&pagina=2"',
        'o Rodízio manual (o quadro Modo de rodízio da página Hoje): os dias de um período, de 7 em 7, cada um com o que o plano tem agora e a escolha de partida do seletor (o relógio escolhido à mão, livre ou auto: Decida por mim), os relógios disponíveis e o critério do Decida por mim. Gravar: recurso=rodizio, acao=manual' => '手动轮换（今天页面的轮换模式框）：某一时段的日子，每 7 天一组，每一天含计划当前的内容以及选择器的初始选择（手动选择的手表、空闲或自动：帮我决定）、可用的手表以及“帮我决定”的标准。保存：recurso=rodizio, acao=manual',
        'datas AAAA-MM-DD, de hoje em diante, até 2 anos (obrigatórias; inválidas: 400 com erro)' => '日期 AAAA-MM-DD，从今天起，最多 2 年（必填；无效：400 并附带错误）',
        '1, 2...: a página de 7 dias (padrão 1)' => '1、2……：每 7 天一页的页码（默认 1）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=rodizio_manual&de=2026-12-20&ate=2027-01-05&pagina=2"',
        'os eventos personalizados, com quando disparam, se vão pelo Telegram e pela agenda, as 10 próximas ocorrências e os disparos' => '自定义事件，含何时触发、是否经 Telegram 和日历发出、接下来的 10 次发生以及触发记录',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=eventos"',
        'o Google Agenda: se está ativa, a chave lida, o que tem de estar na agenda agora (com o título e a descrição pelo modelo) e o que o sistema já criou' => 'Google 日历：是否已启用、密钥是否已读取、当前日历中应有的内容（标题和描述按模板）以及系统已经创建的内容',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agenda"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=agenda"',
        'a foto de um relógio (a imagem, não é JSON)' => '一块手表的照片（图像，不是 JSON）',
        'o id do relógio' => '手表的 id',
        'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"' => 'curl -u lucas:senha -o foto.jpg "http://servidor/relojoeiro/api.php?recurso=foto&relogio=10"',
        'os documentos de um relógio (ou de todos): o manual, a nota fiscal em PDF e em XML (com o resumo da NF-e), fotos, vídeos e o que mais for, com as categorias (e quantos documentos cada uma tem), os relógios (com quantos), se a pasta dos documentos está pronta, se a cópia de segurança no banco está ligada, onde está cada arquivo (na pasta, no banco) e o maior arquivo aceito' => '一块手表（或全部手表）的文档：说明书、PDF 和 XML 发票（含 NF-e 摘要）、照片、视频以及其他内容，含类别（以及每一类有多少文档）、手表（含数量）、文档文件夹是否就绪、数据库中的备份是否已开启、每个文件位于何处（在文件夹中、在数据库中）以及接受的最大文件',
        'o id do relógio (sem ele: de todos)' => '手表的 id（不传：全部手表的）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=documentos&relogio=10"',
        'o arquivo de um documento (não é JSON): imagens, vídeos, áudios, PDF e texto vêm para mostrar; o resto (inclusive XML, HTML e SVG), para baixar; aceita o pedido de um pedaço (Range), que o vídeo usa para avançar; se o arquivo sumiu da pasta, ele é recriado antes a partir da cópia no banco' => '一份文档的文件（不是 JSON）：图像、视频、音频、PDF 和文本用于显示；其余（包括 XML、HTML 和 SVG）用于下载；接受分段请求（Range），视频用它来快进；如果文件已从文件夹中消失，会先根据数据库中的副本重建',
        'o id do documento' => '文档的 id',
        '1: sempre para baixar' => '1：始终用于下载',
        '1: a miniatura da foto (sem ela, a foto)' => '1：照片的缩略图（没有缩略图则为照片）',
        'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"' => 'curl -u lucas:senha -o nota.pdf "http://servidor/relojoeiro/api.php?recurso=documento&id=7"',
        'os logins, cada um com o hash da senha (o algoritmo e o custo), para migrar os usuários com a mesma senha (veja senhas), e quem está pedindo (pelo login do site); a senha não existe no sistema' => '各登录名，每个带密码的 hash（算法和代价），用于以相同密码迁移用户（见 senhas），以及谁在请求（根据网站登录）；密码在系统中不存在',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=usuarios"',
        'as migrações que faltam aplicar no banco (lista vazia: está em dia); com o banco desatualizado, só ele (e o manual e o código, que não usam o banco) responde' => '数据库中尚未应用的迁移（空列表：已是最新）；数据库过期时，只有它（以及不使用数据库的手册和代码）会响应',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=migracoes"',
        'a situação da instalação: o banco, se está vazio, instalado e em dia, as migrações que faltam, quantos usuários há e o próximo passo (instalar, aplicar as migrações, criar o primeiro usuário ou nada); responde também com o banco vazio, pelo token' => '安装情况：数据库、是否为空、是否已安装且为最新、尚未应用的迁移、有多少用户以及下一步（安装、应用迁移、创建第一个用户或无）；数据库为空时也会响应，通过 token',
        'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"' => 'curl -H "X-Api-Token: segredo" "http://servidor/relojoeiro/api.php?recurso=instalacao"',
        'o que a importação do sistema anterior usa: o servidor do banco antigo (sem a senha) e de onde ele vem no config.php, se o PHP tem a extensão do MySQL, quantos relógios este banco já tem (com algum, a importação pede substituir=1) e o que ela traz' => '从旧系统导入时使用的信息：旧数据库的服务器（不含密码）及其在 config.php 中的来源、PHP 是否有 MySQL 扩展、此数据库已有多少块手表（若已有，导入要求 substituir=1）以及它会带入什么',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=importacao"',
        'a cópia de segurança do banco (uma por dia, na rodada da noite do cron, na BACKUP_PASTA do config.php): se a pasta serve, quantas cópias ficam, se levam o conteúdo dos documentos, a versão do banco, a última e as cópias da pasta (da mais nova para a mais velha); com arquivo=<nome>, baixa aquela cópia (JSON Lines comprimido, o mesmo nos quatro bancos). Fazer e restaurar: na escrita' => '数据库备份（每天一份，在 cron 的夜间轮次，位于 config.php 的 BACKUP_PASTA）：文件夹是否可用、保留多少份、是否包含文档内容、数据库版本、最近一次以及文件夹中的各份副本（从最新到最旧）；带 arquivo=<nome> 时，下载该副本（压缩的 JSON Lines，四种数据库相同）。执行和还原：在写入操作中',
        'o nome de uma cópia (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): baixa o arquivo' => '一份副本的名称（relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz）：下载该文件',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=backup"',
        'o login das páginas: sem login, 401 (o navegador pede o usuário e a senha); com login, vai para a página de volta (302) ou diz quem entrou (usuario, por, volta). É para onde o api.js manda quem abre uma página sem login' => '页面登录：未登录时为 401（浏览器要求输入用户和密码）；已登录时，转到返回页面（302）或说明谁已进入（usuario、por、volta）。api.js 会把未登录就打开页面的人送到这里',
        'uma página do sistema para onde ir depois de entrar (index.php, plano.php?..., ajuda.php#...); outra coisa não vale' => '登录后要前往的系统页面（index.php、plano.php?...、ajuda.php#...）；其他内容无效',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php' => '在浏览器中：http://servidor/relojoeiro/api.php?recurso=entrar&volta=index.php',
        'as autonomias de cada relógio, enxuto e rápido, para sistemas de fora, em segundos inteiros: prevista (cheio, pelo cadastro), atual (cheio, pela conta do sistema com o gasto medido), estimada (quanto ainda dura seguindo o plano), restante_em_uso (no pulso sem tirar), restante_guardado (parado) e quando acaba (acaba_em_unixtimestamp, acaba_em_segundos, acaba_em_datacomtz); null com o motivo em motivos' => '每块手表的续航，精简且快速，供外部系统使用，以整数秒计：prevista（满电，按档案）、atual（满电，按系统根据实测消耗的计算）、estimada（按计划还能持续多久）、restante_em_uso（戴在手腕上不摘下）、restante_guardado（静止）以及何时耗尽（acaba_em_unixtimestamp、acaba_em_segundos、acaba_em_datacomtz）；为 null 时原因在 motivos 中',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=autonomia&f[relogios][acaba_em_segundos][ate]=86400&mostrar[relogios]=nome,acaba_em_datacomtz"',
        'esta explicação: os recursos, os parâmetros, as ações de escrita com os campos, os exemplos, o dicionário de todos os campos (campos) e as funções do motor; com parte=manual, o manual (veja manual); com parte=reconstrucao, a reconstrução (veja reconstrucao); com parte=codigo, o código (veja codigo)' => '本说明：资源、参数、带字段的写入操作、示例、全部字段的词典（campos）以及引擎函数；parte=manual 时为手册（见 manual）；parte=reconstrucao 时为重建（见 reconstrucao）；parte=codigo 时为代码（见 codigo）',
        'manual: em vez desta explicação, o texto da página Ajuda (o mesmo que recurso=manual); reconstrucao: o roteiro para reescrever a aplicação do zero (o mesmo que recurso=reconstrucao); codigo: o código do sistema (o mesmo que recurso=codigo)' => 'manual：不返回本说明，而是帮助页面的文本（与 recurso=manual 相同）；reconstrucao：从零重写应用的路线（与 recurso=reconstrucao 相同）；codigo：系统代码（与 recurso=codigo 相同）',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=ajuda&parte=reconstrucao"',
        'o texto da página Ajuda: os trechos do README para quem usa (a ideia central, como funciona, o cadastro campo por campo, a Configuração, um dia com o sistema, as telas, as perguntas frequentes e como reescrever o sistema do zero), em markdown, inteiro e seção por seção (título, nível, âncora e texto), e já em HTML com o sumário, como a página Ajuda mostra; sem o README.md na pasta: 404; responde mesmo com o banco desatualizado. O mesmo que recurso=ajuda&parte=manual' => '帮助页面的文本：给使用者的 README 片段（核心理念、如何运作、逐字段的档案、设置、使用系统的一天、各界面、常见问题以及如何从零重写系统），为 markdown，有全文也有逐节（标题、级别、锚点和文本），并且已是带目录的 HTML，与帮助页面所显示的一致；文件夹中没有 README.md：404；即使数据库过期也会响应。与 recurso=ajuda&parte=manual 相同',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=manual&mostrar[secoes]=titulo,ancora"',
        'o roteiro para reescrever a aplicação inteira do zero, em qualquer linguagem e banco, chegando ao mesmo sistema: o que ele é, os princípios, a arquitetura, a ordem de construção e as regras de cada parte (árvore e campos, lançamentos, fórmulas, avisos, gasto medido, critérios, rodízio e escala, pulso sozinho, cron, mensagens e agenda, documentos, telas, segurança, testes), a especificação visual de cada tela (telas: o visual com os valores exatos, o menu e cada página com as tabelas, os campos, os botões e as mensagens), a lista do código do sistema (codigo: o mesmo do recurso=codigo, que traz cada arquivo como está agora), o modelo de dados lido do próprio banco (tabelas, colunas, chaves, índices e regras de validação) e as listas do código (funções das fórmulas, tipos de campo, formatos de lançamento, repetições, dias da semana, âncoras, canais, migrações e as constantes do config.php). O mesmo que recurso=ajuda&parte=reconstrucao' => '从零完整重写应用的路线，可用任何语言和数据库，得到同一个系统：它是什么、原则、架构、构建顺序以及每一部分的规则（树和字段、记录、公式、提醒、实测消耗、标准、轮换和排班表、独自上手腕、cron、消息和日历、文档、界面、安全、测试）、每个界面的视觉规格（telas：带确切值的外观、菜单以及每个页面的表格、字段、按钮和消息）、系统代码清单（codigo：与 recurso=codigo 相同，按现状给出每个文件）、从数据库本身读出的数据模型（表、列、键、索引和校验规则）以及代码中的清单（公式函数、字段类型、记录格式、重复方式、星期几、锚点、渠道、迁移和 config.php 的常量）。与 recurso=ajuda&parte=reconstrucao 相同',
        'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"' => 'curl -u lucas:senha "http://servidor/relojoeiro/api.php?recurso=reconstrucao"',
        'o código do sistema como está agora, lido do disco na hora do pedido, para a reescrita ler o original: cada arquivo (as páginas, o estilo, o JavaScript, a API, o núcleo, o banco, as migrações, o servidor, os testes, a documentação e as capturas das telas) com a camada, o que ele é, a linguagem, o tamanho, as linhas, o SHA-256 e a data; nas páginas, os arquivos que ela carrega e o HTML que o navegador recebe; e o que fica de fora de propósito (o config.php, a chave do Google, o banco, os documentos, as senhas), com o que ver no lugar. Só saem os arquivos do sistema (os do repositório); responde mesmo com o banco vazio ou desatualizado. O mesmo que recurso=ajuda&parte=codigo' => '系统当前的代码，在请求时从磁盘读取，供重写时阅读原文：每个文件（页面、样式、JavaScript、API、核心、数据库、迁移、服务器、测试、文档和界面截图）含层次、它是什么、语言、大小、行数、SHA-256 和日期；对于页面，含它加载的文件以及浏览器收到的 HTML；以及有意排除的内容（config.php、Google 密钥、数据库、文档、密码），并说明改看什么。只输出系统文件（仓库中的那些）；即使数据库为空或过期也会响应。与 recurso=ajuda&parte=codigo 相同',
        'um arquivo (o nome como está em arquivos, ex.: estilo.css, docs/telas/hoje.png): vem com o conteúdo como está (conteudo; a imagem em conteudo_base64) e, numa página, com o HTML que o navegador recebe (html)' => '一个文件（名称与 arquivos 中的一致，例：estilo.css、docs/telas/hoje.png）：按原样返回内容（conteudo；图像在 conteudo_base64 中），若是页面，还返回浏览器收到的 HTML（html）',
        '1, com arquivo: o arquivo puro, sem JSON (texto como text/plain, para ler no navegador; imagem como imagem)' => '1，且带 arquivo：纯文件，无 JSON（文本为 text/plain，供在浏览器中阅读；图像作为图像）',
        '1, com arquivo de uma página e cru=1: o HTML que o navegador recebe, puro' => '1，且带某个页面的 arquivo 以及 cru=1：浏览器收到的 HTML，纯文本',
        '1, sem arquivo: a lista com o conteúdo de todos (com f[arquivos][camada]=tela, só o das telas)' => '1，不带 arquivo：带全部内容的列表（带 f[arquivos][camada]=tela 时，只含界面的）',
        'no navegador: http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1' => '在浏览器中：http://servidor/relojoeiro/api.php?recurso=codigo&arquivo=estilo.css&cru=1',
        'POST, com os campos em formulário ou em JSON no corpo (Content-Type: application/json); recurso e acao nos campos ou na URL. Resposta: {ok, mensagem, erros, id}; 400 quando recusado (os erros dizem por quê). Ex. em JSON: curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php' => 'POST，字段以表单或正文中的 JSON 提交（Content-Type: application/json）；recurso 和 acao 可在字段中或 URL 中。响应：{ok, mensagem, erros, id}；被拒绝时为 400（erros 说明原因）。JSON 示例：curl -u lucas:senha -H "Content-Type: application/json" -d \'{"recurso":"lancamento","acao":"lancar","relogio_id":10,"tipo":"carga","valor":68}\' http://servidor/relojoeiro/api.php',
        'nome, pai_id (0 = na raiz)' => 'nome, pai_id（0 = 在根）',
        'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=novo -d "nome=Cronógrafos" -d pai_id=2 http://servidor/relojoeiro/api.php',
        'id, nome' => 'id, nome',
        'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=renomear -d id=5 -d "nome=Automáticos" http://servidor/relojoeiro/api.php',
        'id, pai_id (0 = na raiz; não pode ir para dentro dele mesmo)' => 'id, pai_id（0 = 在根；不能移入自身内部）',
        'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=mover -d id=5 -d pai_id=0 http://servidor/relojoeiro/api.php',
        'id, direcao (sobe ou desce)' => 'id, direcao（sobe 或 desce）',
        'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=ordem -d id=5 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'id; o que é dele (subgrupos, relógios, campos, tipos de lançamento, fórmulas, avisos) sobe para o de cima, menos as versões de fórmulas e avisos que o de cima já tem (essas saem); os blocos dos modos que sorteavam dele passam a sortear do de cima; os critérios próprios saem (os relógios usam os do lugar mais perto, acima)' => 'id；属于它的内容（子分组、手表、字段、记录类型、公式、提醒）上移到上级，但上级已有的公式和提醒版本除外（那些会被删除）；原本从它抽签的模式区块改为从上级抽签；自有标准被删除（手表改用上方最近位置的标准）',
        'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=excluir -d id=5 http://servidor/relojoeiro/api.php',
        'grupo[<id do relógio>] = o grupo (0 = na raiz), um ou vários' => 'grupo[<手表的 id>] = 分组（0 = 在根），一个或多个',
        'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=arvore -d acao=relogios -d "grupo[13]=1" -d "grupo[4]=8" http://servidor/relojoeiro/api.php',
        'identificador, nome, tipo (inteiro, decimal, sim_nao, data, lista, texto), unidade, opcoes (lista: uma por linha), padrao, no_id (0 = todos), so_desejado (1: o campo vale só nos relógios desejados, a lista de desejos; padrão 0)' => 'identificador, nome, tipo（inteiro、decimal、sim_nao、data、lista、texto）, unidade, opcoes（lista：每行一个）, padrao, no_id（0 = 全部）, so_desejado（1：该字段仅对心愿中的手表有效，即心愿单；默认 0）',
        'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=novo -d identificador=resistencia_agua -d "nome=Resistência à água" -d tipo=inteiro -d unidade=m -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (só o que vier muda)' => 'id 以及同样的字段（只改传来的）',
        'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=alterar -d id=21 -d "nome=Resistência (m)" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=ordem -d id=21 -d direcao=sobe http://servidor/relojoeiro/api.php',
        'id (os valores dele saem junto)' => 'id（它的值一并输出）',
        'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=campos -d acao=excluir -d id=21 http://servidor/relojoeiro/api.php',
        'identificador, nome, formato (instantaneo, valor, sessao), unidade (com valor), fecha_as (sessão: HH:MM; vazio: não fecha sozinha), exclusiva (1 ou 0, só sessão), mede_gasto (1 ou 0, só com valor: cada leitura mede o gasto, comparando com a anterior), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual), no_id' => 'identificador, nome, formato（instantaneo、valor、sessao）, unidade（带值时）, fecha_as（时段：HH:MM；空：不会自行结束）, exclusiva（1 或 0，仅时段）, mede_gasto（1 或 0，仅带值时：每次读数与上一次比较来测量消耗）, condicao（何时有效：一条公式，1 有效、0 无效；空则始终有效；例：corda_manual）, no_id',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=novo -d identificador=banho_ultrassom -d "nome=Banho ultrassônico" -d formato=instantaneo -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos' => 'id 以及同样的字段',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=alterar -d id=11 -d fecha_as=18:00 http://servidor/relojoeiro/api.php',
        'id (só sem lançamentos)' => 'id（仅当没有记录时）',
        'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento_tipos -d acao=excluir -d id=11 http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao, unidade, no_id: uma fórmula nova, ou mais uma versão de uma que existe, em outro ponto da árvore' => 'identificador, nome, expressao, unidade, no_id：一条新公式，或已有公式在树的另一处的又一个版本',
        'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=nova -d identificador=idade_dias -d "nome=Idade (dias)" --data-urlencode "expressao=AGORA() - data_compra" -d unidade=dias -d no_id=0 http://servidor/relojoeiro/api.php',
        'id: nome, expressao, unidade, no_id' => 'id：nome、expressao、unidade、no_id',
        'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=alterar -d id=17 --data-urlencode "expressao=ARREDONDA(AGORA() - data_compra)" http://servidor/relojoeiro/api.php',
        'id (a versão)' => 'id（该版本）',
        'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=formulas -d acao=excluir -d id=17 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome, no_id, disponivel (1 ou 0), copia_banco (1 ou 0: a cópia no banco de todos os documentos dele; o cron copia ou tira aos poucos), posse (a situação na coleção: colecao, o padrão; desejado, a lista de desejos; emprestado; vendido; arquivado. Fora da coleção o relógio fica indisponível (disponivel=1 é ignorado, com uma nota), e, saindo dela, as sessões abertas dele (no pulso, no sol...) fecham agora e os dias dele no plano de amanhã em diante saem e são sorteados de novo (hoje fica, mas ele não vai ao pulso sozinho); voltando para ela sem disponivel, fica disponível), valores[<identificador do campo>]: só muda o que vier; valor vazio apaga (os campos só nos desejados, como o preco_alvo, só gravam no desejado)' => 'id（0 或省略则创建）, nome, no_id, disponivel（1 或 0）, copia_banco（1 或 0：其全部文档在数据库中的副本；cron 会逐步复制或移除）, posse（在收藏中的情况：colecao，默认；desejado，心愿单；emprestado；vendido；arquivado。离开收藏后手表变为不可用（disponivel=1 被忽略，并附一条说明），并且在离开时，其已打开的时段（在手腕上、在晒太阳中……）立即结束，其计划中从明天起的日子被移除并重新抽签（今天保留，但它不会独自上手腕）；回到收藏时若不传 disponivel，则变为可用）, valores[<字段的标识符>]：只改传来的；空值会删除（仅用于心愿中的字段，如 preco_alvo，只在 desejado 时保存）',
        'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=salvar -d id=10 -d "valores[preferencia]=80" -d disponivel=1 http://servidor/relojoeiro/api.php',
        'id, foto_base64 (JPEG, PNG ou WebP, até 4 MB; data:image/...;base64,... ou só o base64)' => 'id, foto_base64（JPEG、PNG 或 WebP，最大 4 MB；data:image/...;base64,... 或仅 base64）',
        'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=foto -d id=10 --data-urlencode foto_base64@foto.b64 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=remover_foto -d id=10 http://servidor/relojoeiro/api.php',
        'id (com todo o histórico, a foto e os documentos, inclusive os arquivos deles; os acessórios dele ficam soltos)' => 'id（含全部历史、照片和文档，包括其文件；其配件变为未绑定）',
        'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=relogio -d acao=excluir -d id=15 http://servidor/relojoeiro/api.php',
        'relogio_id, categoria_id, titulo (vazio: o nome do arquivo), data (AAAA-MM-DD), descricao, copia_banco (1: pede a cópia destes arquivos no banco; o config.php e o relógio, se pedem, valem por cima) e o arquivo: arquivos[] (upload; vários de uma vez) ou arquivo_base64 com arquivo_nome; a miniatura de uma foto, opcional: miniatura (upload, JPEG, PNG ou WebP até 1 MB) ou miniatura_base64. Cada arquivo até o limite (recurso=documentos, limite) e do tipo que a categoria aceita. O arquivo vai para a pasta e, se a cópia é pedida (pelo config.php, pelo relógio ou pelo próprio arquivo), também para o banco, em pedaços de 4 MB (se a cópia falhar, o documento fica e a mensagem avisa; o cron tenta de novo). Responde ids: os documentos guardados' => 'relogio_id, categoria_id, titulo（空：文件名）, data（AAAA-MM-DD）, descricao, copia_banco（1：要求将这些文件复制到数据库；若 config.php 和手表也提出要求，则它们优先）以及文件：arquivos[]（上传；一次多个）或 arquivo_base64 配 arquivo_nome；照片缩略图，可选：miniatura（上传，JPEG、PNG 或 WebP，最大 1 MB）或 miniatura_base64。每个文件不超过上限（recurso=documentos，limite）且须为类别所接受的类型。文件进入文件夹，若要求副本（由 config.php、手表或文件本身提出），也以 4 MB 的分块写入数据库（若复制失败，文档仍保留并由消息告知；cron 会再试）。响应 ids：已保存的文档',
        'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -F recurso=documentos -F acao=enviar -F relogio_id=10 -F categoria_id=2 -F "arquivos[]=@nota.pdf" http://servidor/relojoeiro/api.php',
        'id, categoria_id, titulo, data, descricao, copia_banco (1 ou 0): só muda o que vier; a cópia entra ou sai do banco na hora (só sai se o arquivo da pasta confere com ela)' => 'id, categoria_id, titulo, data, descricao, copia_banco（1 或 0）：只改传来的；副本立即进入或离开数据库（仅当文件夹中的文件与它一致时才离开）',
        'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=alterar -d id=7 -d "titulo=No casamento" -d data=2026-09-20 http://servidor/relojoeiro/api.php',
        'id: o documento, o arquivo dele na pasta e a cópia no banco' => 'id：文档、其在文件夹中的文件以及数据库中的副本',
        'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documentos -d acao=excluir -d id=7 http://servidor/relojoeiro/api.php',
        'id (0 ou ausente cria), nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro; padrão pulseira), relogio_id (o relógio de que ele é; 0: solto, serve a vários), observacao (até 1000): só muda o que vier' => 'id（0 或省略则创建）, nome（最多 120）, tipo（pulseira、caixa、estojo、ferramenta、carregador、peca、outro；默认 pulseira）, relogio_id（它所属的手表；0：未绑定，可供多块使用）, observacao（最多 1000）：只改传来的',
        'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=salvar -d "nome=Pulseira NATO verde" -d tipo=pulseira -d relogio_id=3 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=acessorios -d acao=excluir -d id=4 http://servidor/relojoeiro/api.php',
        'identificador, nome, aceita[] (imagem, video, audio, pdf, xml; nenhum: qualquer arquivo), ordem (vazio: no fim)' => 'identificador, nome, aceita[]（imagem、video、audio、pdf、xml；一个都没有：任意文件）, ordem（空：放在末尾）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=nova -d identificador=garantia -d nome=Garantia -d "aceita[]=pdf" http://servidor/relojoeiro/api.php',
        'id, nome, aceita[], ordem (o identificador não muda)' => 'id, nome, aceita[], ordem（标识符不变）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=alterar -d id=7 -d nome=Garantias http://servidor/relojoeiro/api.php',
        'id (só uma categoria sem documentos)' => 'id（仅限没有文档的类别）',
        'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=documento_categorias -d acao=excluir -d id=7 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (instantâneo ou com valor), valor (com valor), quando (AAAA-MM-DD HH:MM; vazio: agora), medir (1, o padrão, ou 0: num tipo que mede o gasto, com 1 a medição entra na média; com 0 fica só no histórico)' => 'relogio_id, tipo（瞬时或带值）, valor（带值时）, quando（AAAA-MM-DD HH:MM；空：现在）, medir（1，默认，或 0：在测量消耗的类型中，1 会使该次测量计入平均值；0 则只留在历史中）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=lancar -d relogio_id=10 -d tipo=carga -d valor=68 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: abre a sessão; uma exclusiva fecha a outra exclusiva aberta' => 'relogio_id, tipo（时段）, quando：打开时段；独占的会结束另一个已打开的独占时段',
        'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=iniciar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, quando: fecha a sessão aberta' => 'relogio_id, tipo, quando：结束已打开的时段',
        'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=encerrar -d relogio_id=4 -d tipo=sol http://servidor/relojoeiro/api.php',
        'relogio_id, tipo, inicio (quando também vale), fim: uma sessão que já passou (espaço ou T entre data e hora)' => 'relogio_id, tipo, inicio（quando 同样有效）, fim：一段已经过去的时段（日期与时间之间为空格或 T）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=periodo -d relogio_id=3 -d tipo=winder -d "inicio=2026-09-26 20:00" -d "fim=2026-09-27 07:00" http://servidor/relojoeiro/api.php',
        'id: quando ou inicio e fim, valor (só o que vier)' => 'id：quando，或 inicio 和 fim，valor（只改传来的）',
        'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=alterar -d id=42 -d valor=70 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=lancamento -d acao=excluir -d id=42 http://servidor/relojoeiro/api.php',
        'relogio_id, tipo (sessão), quando: fecha a sessão se ela está aberta, abre se está fechada (um botão só num atalho de celular). Em todas as ações, relogio_id=hoje é o relógio do dia, pelo plano' => 'relogio_id, tipo（时段）, quando：若时段已打开则结束，若已关闭则打开（手机快捷方式上的单一按钮）。在所有操作中，relogio_id=hoje 是当天的手表，按计划确定',
        'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: ..." -d recurso=lancamento -d acao=alternar -d relogio_id=hoje -d tipo=pulso http://servidor/relojoeiro/api.php',
        'identificador, nome, expressao (a data prevista), condicao (vale quando: uma fórmula, 1 vale e 0 não; vazia, vale sempre; ex.: corda_manual = 0), antecedencia_dias, texto (o motivo, com {relogio}, {data}, {quando}, {limite}), resolve (o tipo de lançamento), ativo, no_id, escala (nao, uso, sempre), simula_valor, simula_horas, agenda (janela ou sempre), na_hora (1 ou 0: o Telegram recebe o aviso no minuto em que ele vence, uma vez)' => 'identificador, nome, expressao（预计日期）, condicao（何时有效：一条公式，1 有效、0 无效；空则始终有效；例：corda_manual = 0）, antecedencia_dias, texto（事由，含 {relogio}、{data}、{quando}、{limite}）, resolve（记录类型）, ativo, no_id, escala（nao、uso、sempre）, simula_valor, simula_horas, agenda（janela 或 sempre）, na_hora（1 或 0：Telegram 在提醒到期的那一分钟收到它，仅一次）',
        'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=novo -d identificador=pulseira -d "nome=Trocar a pulseira" --data-urlencode "expressao=data_compra + 365" -d antecedencia_dias=15 -d "texto=vence {quando}, {data}" -d no_id=0 http://servidor/relojoeiro/api.php',
        'id e os mesmos campos (menos o identificador)' => 'id 以及同样的字段（不含标识符）',
        'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=alterar -d id=9 -d antecedencia_dias=30 http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=avisos -d acao=excluir -d id=9 http://servidor/relojoeiro/api.php',
        'escopo ("" todos, g:<grupo>, r:<relógio>), origem (herdado: copia o que ele usa hoje; vazio)' => 'escopo（"" 全部，g:<分组>，r:<手表>）, origem（herdado：复制它今天所使用的；空）',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_criar -d escopo=r:10 -d origem=herdado http://servidor/relojoeiro/api.php',
        'escopo (volta a herdar o de cima)' => 'escopo（改回继承上级的）',
        'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=conjunto_excluir -d escopo=r:10 http://servidor/relojoeiro/api.php',
        'escopo, nome, peso (os outros abrem espaço na proporção)' => 'escopo, nome, peso（其余的按比例让出空间）',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_novo -d escopo=g:1 -d "nome=Estilo" -d peso=10 http://servidor/relojoeiro/api.php',
        'escopo, nome[<id>], peso[<id>]: todos os do conjunto, somando 100' => 'escopo, nome[<id>], peso[<id>]：该集合的全部，合计为 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_pesos -d escopo=g:1 -d "peso[5]=35" -d "peso[6]=10" http://servidor/relojoeiro/api.php',
        'id (o peso dele vai para os outros na proporção)' => 'id（它的权重按比例分给其余各项）',
        'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=param_excluir -d id=29 http://servidor/relojoeiro/api.php',
        'parametro_id, nome, variavel (o identificador de um campo ou fórmula; metrica também vale), peso' => 'parametro_id, nome, variavel（一个字段或公式的标识符；metrica 同样有效）, peso',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_novo -d parametro_id=5 -d "nome=Carga" -d variavel=energia -d peso=20 http://servidor/relojoeiro/api.php',
        'parametro_id, nome[<id>], peso[<id>]: somando 100' => 'parametro_id, nome[<id>], peso[<id>]：合计为 100',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_pesos -d parametro_id=5 -d "peso[6]=60" -d "peso[7]=40" http://servidor/relojoeiro/api.php',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_excluir -d id=7 http://servidor/relojoeiro/api.php',
        'id, variavel (metrica também vale; as faixas recomeçam)' => 'id, variavel（metrica 同样有效；区间重新开始）',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_medida -d id=7 -d variavel=dias_de_carga http://servidor/relojoeiro/api.php',
        'id, parametro_id (o de destino, de qualquer lugar)' => 'id, parametro_id（目标参数，可以是任意位置的）',
        'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=sub_mover -d id=7 -d parametro_id=8 http://servidor/relojoeiro/api.php',
        'tipo (parametro ou sub), id, direcao (sobe ou desce)' => 'tipo（parametro 或 sub）, id, direcao（sobe 或 desce）',
        'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=ordem -d tipo=parametro -d id=5 -d direcao=desce http://servidor/relojoeiro/api.php',
        'sub_id, de[], ate[], categoria[], nota[], apagar[] (todas as faixas do subparâmetro de uma vez; a última vai até o limite da medida ou sem limite)' => 'sub_id, de[], ate[], categoria[], nota[], apagar[]（一次提交该子参数的全部区间；最后一档直到度量上限，或没有上限）',
        'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=faixas -d sub_id=6 -d "de[0]=0" -d "ate[0]=50" -d "nota[0]=30" -d "de[1]=50" -d "ate[1]=100" -d "nota[1]=100" http://servidor/relojoeiro/api.php',
        '(nada): volta aos critérios iniciais' => '（无）：恢复为初始标准',
        'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=criterios -d acao=restaurar http://servidor/relojoeiro/api.php',
        'modo (o id), bloco_alvo[<bloco>] (0, o grupo, ou r:<id> para um relógio fixo), bloco_cada_dia[<bloco>] (presente: um por dia), selecao, escala_dias, max_sem_uso: grava e ativa o modo' => 'modo（其 id）, bloco_alvo[<区块>]（0、分组，或 r:<id> 表示固定的一块手表）, bloco_cada_dia[<区块>]（出现即表示每天一块）, selecao, escala_dias, max_sem_uso：保存并启用该模式',
        'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d "bloco_alvo[8]=1" -d "bloco_cada_dia[8]=1" -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=modo -d modo=2 -d "bloco_alvo[8]=1" -d "bloco_cada_dia[8]=1" -d selecao=ponderado -d max_sem_uso=21 http://servidor/relojoeiro/api.php',
        '(nada): refaz o plano de amanhã até domingo (ou até o fim da escala); se o dia ainda não começou no pulso, também hoje' => '（无）：重做从明天到星期日的计划（或直到排班表结束）；如果当天尚未在手腕上开始，也包括今天',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear http://servidor/relojoeiro/api.php',
        '(nada): inclusive hoje; se sair outro relógio, ele passa a ser o do pulso a partir de agora' => '（无）：包括今天；如果抽到另一块手表，从现在起它成为手腕上的那块',
        'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=resortear_hoje http://servidor/relojoeiro/api.php',
        '(nada): hoje sem relógio: o dia fica livre (sem relógio e sem sorteio) e a sessão do rodízio de hoje termina agora (o tempo que já ficou no pulso conta; a que nem começou sai); nenhum relógio vai ao pulso sozinho hoje; os outros dias não mudam. Desfaz: trocar_dia de hoje (ou usando) com um relógio, ou resortear_hoje' => '（无）：今天没有手表：该日变为空闲（无手表且无抽签），并且今天的轮换时段现在结束（已经在手腕上的时间计入；尚未开始的则删除）；今天没有任何手表会独自上手腕；其他日子不变。撤销：对今天执行 trocar_dia（或 usando）并指定一块手表，或 resortear_hoje',
        'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=sem_relogio http://servidor/relojoeiro/api.php',
        'relogio_id: o relógio de hoje, a partir de agora (na escala, fica os dias que faltavam do bloco de hoje)' => 'relogio_id：从现在起今天的手表（在排班表中，保留今天区块尚未用完的日子）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=usando -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'data (AAAA-MM-DD, de hoje em diante), relogio_id: o relógio daquele dia, escolhido à mão (hoje: como o usando; na escala, ela é refeita a partir do dia); relogio_id 0: o dia volta a ser sorteado' => 'data（AAAA-MM-DD，从今天起）, relogio_id：那一天的手表，手动选择（今天：与 usando 相同；在排班表中，从该日起重做）；relogio_id 为 0：该日恢复为抽签',
        'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=trocar_dia -d data=2026-10-09 -d relogio_id=12 http://servidor/relojoeiro/api.php',
        'de, ate (AAAA-MM-DD, de hoje até 2 anos), relogio_ids[] (um ou vários, na ordem), dias_cada (padrão 1): os dias do período ficam escolhidos à mão, cada relógio dias_cada dias seguidos, e depois do último volta ao primeiro (hoje: o primeiro passa a ser o do pulso a partir de agora; na escala, ela é refeita a partir do começo do período)' => 'de, ate（AAAA-MM-DD，从今天起最多 2 年）, relogio_ids[]（一个或多个，按顺序）, dias_cada（默认 1）：该时段的日子改为手动选择，每块手表连续 dias_cada 天，最后一块之后回到第一块（今天：第一块从现在起成为手腕上的那块；在排班表中，从该时段开始处重做）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo -d de=2026-12-20 -d ate=2027-01-05 -d "relogio_ids[]=12" -d "relogio_ids[]=7" -d dias_cada=2 http://servidor/relojoeiro/api.php',
        'de, ate: tudo o que o período tem, de amanhã em diante (à mão, sorteado ou livre), sai e ele é sorteado de novo (os dias escolhidos à mão e os livres ficam quando se sorteia de novo ou se monta a próxima semana)' => 'de, ate：该时段从明天起的全部内容（手动、已抽签或空闲）被移除并重新抽签（再次抽签或编排下一周时，手动选择的日子和空闲日会保留）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_sortear -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        'hoje (1: Excluindo hoje, de hoje em diante; sem ele, de amanhã em diante): toda a programação (os dias escolhidos à mão, os sorteados e os livres) sai e o modo ativo monta o plano de novo; hoje, se mudar, o novo vai para o pulso a partir de agora' => 'hoje（1：排除今天，从今天起；不传则从明天起）：全部安排（手动选择的日子、已抽签的和空闲的）被移除，由当前模式重新编排计划；今天若有变化，新的手表从现在起上手腕',
        'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=apagar_tudo -d hoje=1 http://servidor/relojoeiro/api.php',
        'de, ate; dias[AAAA-MM-DD]: o id do relógio, auto (Decida por mim: o sistema decide ao gravar, pelo critério do recurso=rodizio_manual) ou livre (hoje não). O dia que não vem fica com a escolha de partida (dias[].escolha do recurso=rodizio_manual). Tudo fica gravado à mão, com o motivo; hoje, com outro relógio, ele passa a ser o do pulso a partir de agora; hoje em auto continua o que está. Fora do período, vale o modo ativo' => 'de, ate；dias[AAAA-MM-DD]：手表的 id、auto（帮我决定：保存时由系统按 recurso=rodizio_manual 的标准决定）或 livre（今天不可以）。未传来的日子保持初始选择（recurso=rodizio_manual 的 dias[].escolha）。全部按手动保存，并带事由；今天若换成另一块手表，从现在起它成为手腕上的那块；今天为 auto 则保持现状。时段之外，以当前模式为准',
        'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=manual -d de=2026-12-20 -d ate=2027-01-05 -d "dias[2026-12-20]=12" -d "dias[2026-12-21]=auto" -d "dias[2026-12-25]=livre" http://servidor/relojoeiro/api.php',
        'de, ate: tudo o que o período tem, de amanhã em diante, sai e os dias ficam livres: sem relógio e sem sorteio (nem a escala), para escolher à mão (trocar_dia ou periodo num dia livre o tira de lá)' => 'de, ate：该时段从明天起的全部内容被移除，日子变为空闲：无手表且无抽签（排班表也不排），供手动选择（在空闲日上执行 trocar_dia 或 periodo 会把它从空闲中移出）',
        'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=periodo_livre -d de=2026-12-20 -d ate=2027-01-05 http://servidor/relojoeiro/api.php',
        '(nada): só no domingo, monta ou refaz a semana seguinte inteira; recusada na escala' => '（无）：仅在星期日，编排或重做整个下一周；在排班表模式下会被拒绝',
        'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=rodizio -d acao=proxima_semana http://servidor/relojoeiro/api.php',
        'id (0 cria), nome, selecao (inteligente, ponderado, aleatorio, fifo), escala_dias (vazio: sorteio pelos blocos; 7 a 730: escala), blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por] (dia ou bloco), blocos[n][relogio_id] (0: sorteia); substitui os blocos; ciclo (1 ou 0, o padrão: com o ciclo, um relógio só volta depois que todos os disponíveis do bloco passaram na semana; na escala, pelo período dela)' => 'id（0 则创建）, nome, selecao（inteligente、ponderado、aleatorio、fifo）, escala_dias（空：按区块抽签；7 到 730：排班表）, blocos[n][nome], blocos[n][dias][], blocos[n][no_id], blocos[n][um_por]（dia 或 bloco）, blocos[n][relogio_id]（0：抽签）；替换各区块；ciclo（1 或 0，默认：开启循环时，一块手表要等该区块中全部可用手表都在本周出现过才再次出现；在排班表中，按其时段计算）',
        'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=salvar -d id=0 -d "nome=Só smartwatch" -d selecao=inteligente -d "blocos[0][nome]=Todo dia" -d "blocos[0][dias][]=1" -d "blocos[0][dias][]=7" -d "blocos[0][no_id]=1" -d "blocos[0][um_por]=dia" http://servidor/relojoeiro/api.php',
        'id (o plano de amanhã em diante é refeito)' => 'id（从明天起的计划会被重做）',
        'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=ativar -d id=5 http://servidor/relojoeiro/api.php',
        'id (não o ativo)' => 'id（不能是当前启用的）',
        'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=modos -d acao=excluir -d id=6 http://servidor/relojoeiro/api.php',
        'horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim (HH:MM), pulso_auto_inicio e pulso_auto_fim (1 ou 0), carga_limiar (1 a 99), sol_limiar (1 a 99), url_sistema, painel_modo (lado: o relógio abre no painel ao lado da lista; flutuante: numa janela grande por cima da página), destaque_hoje (dia: o destaque no alto da página Hoje é o relógio do dia; pulso: o relógio no pulso agora), idioma (pt-BR, en, zh-CN, hi, es ou fr: o idioma padrão da instalação), proximos_por_pagina e plano_por_pagina (1 a 366: o Mostrar até dos Próximos dias da página Hoje e do dia a dia da página Plano; padrão 7 e 31), alerta_ativo e agenda_ativa (1 ou 0), agenda_id, agenda_chave, agenda_antecedencia (1 a 365), max_sem_uso, previsao_limite, medicao_janela_dias (1 a 3650: a janela da média do gasto medido), encostado_dias (1 a 3650: o aviso Encostado, dias sem ir ao pulso), alerta_tipos[] e agenda_tipos[] (os tipos de aviso de cada canal: dia, vespera, os identificadores dos avisos, ev<id>), tg_padrao e ag_padrao, tg_proprio_<tipo> e ag_proprio_<tipo> (1 ou 0), tg_corpo_<tipo> e ag_corpo_<tipo>; só o que vier muda' => 'horario_manha, horario_noite, uso_inicio, uso_fim, sol_fim（HH:MM）, pulso_auto_inicio 和 pulso_auto_fim（1 或 0）, carga_limiar（1 到 99）, sol_limiar（1 到 99）, url_sistema, painel_modo（lado：手表在列表旁边的面板中打开；flutuante：在页面上方的大窗口中）, destaque_hoje（dia：今天页面顶部的突出显示是当天的手表；pulso：现在在手腕上的手表）, idioma（pt-BR、en、zh-CN、hi、es 或 fr：安装的默认语言）, proximos_por_pagina 和 plano_por_pagina（1 到 366：今天页面接下来的日子以及计划页面逐日内容的显示至；默认 7 和 31）, alerta_ativo 和 agenda_ativa（1 或 0）, agenda_id, agenda_chave, agenda_antecedencia（1 到 365）, max_sem_uso, previsao_limite, medicao_janela_dias（1 到 3650：实测消耗平均值的窗口）, encostado_dias（1 到 3650：闲置提醒，多少天没上手腕）, alerta_tipos[] 和 agenda_tipos[]（每个渠道的提醒类型：dia、vespera、各提醒的标识符、ev<id>）, tg_padrao 和 ag_padrao, tg_proprio_<tipo> 和 ag_proprio_<tipo>（1 或 0）, tg_corpo_<tipo> 和 ag_corpo_<tipo>；只改传来的',
        'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d alerta_ativo=1 --data-urlencode "tg_padrao={acao}: {relogio}" -d tg_proprio_corda=1 --data-urlencode "tg_corpo_corda=Corda no {relogio}!" http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=salvar -d horario_manha=06:30 -d alerta_ativo=1 --data-urlencode "tg_padrao={acao}: {relogio}" -d tg_proprio_corda=1 --data-urlencode "tg_corpo_corda=Corda no {relogio}!" http://servidor/relojoeiro/api.php',
        '(nada): manda a mensagem da manhã agora' => '（无）：现在发送早晨消息',
        'curl -u lucas:senha -d recurso=config -d acao=testar_manha http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=testar_manha http://servidor/relojoeiro/api.php',
        '(nada): manda a mensagem da noite agora' => '（无）：现在发送夜晚消息',
        'curl -u lucas:senha -d recurso=config -d acao=testar_noite http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=testar_noite http://servidor/relojoeiro/api.php',
        'evento_id (ou id; 0 cria), nome, ativo, repeticao (uma, diaria, semanal, mensal, intervalo), hora (HH:MM), data_inicio, dias_semana (1 a 7), dia_mes, intervalo_dias, relogio_id; o evento novo já vai pelo Telegram' => 'evento_id（或 id；0 则创建）, nome, ativo, repeticao（uma、diaria、semanal、mensal、intervalo）, hora（HH:MM）, data_inicio, dias_semana（1 到 7）, dia_mes, intervalo_dias, relogio_id；新事件立即经 Telegram 发出',
        'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_salvar -d evento_id=0 -d "nome=Limpar as pulseiras" -d repeticao=semanal -d "dias_semana[]=1" -d "dias_semana[]=4" -d hora=20:00 http://servidor/relojoeiro/api.php',
        'evento_id (ou id)' => 'evento_id（或 id）',
        'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=evento_excluir -d evento_id=3 http://servidor/relojoeiro/api.php',
        '(nada): cria um evento de teste daqui a 10 minutos' => '（无）：创建一个 10 分钟后的测试事件',
        'curl -u lucas:senha -d recurso=config -d acao=teste_agenda_criar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=teste_agenda_criar http://servidor/relojoeiro/api.php',
        '(nada): remove o evento de teste' => '（无）：移除测试事件',
        'curl -u lucas:senha -d recurso=config -d acao=teste_agenda_remover http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=teste_agenda_remover http://servidor/relojoeiro/api.php',
        '(nada): sincroniza o Google Agenda agora' => '（无）：现在同步 Google 日历',
        'curl -u lucas:senha -d recurso=config -d acao=sincronizar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=config -d acao=sincronizar http://servidor/relojoeiro/api.php',
        'login, senha (6 caracteres ou mais; login que existe: troca a senha); ou login e senha_hash (o hash de outro sistema, bcrypt ou argon2: o usuário entra com a senha de lá; veja senhas); o primeiro usuário sai pelo token (sem usuários, o login não entra)' => 'login, senha（6 个字符或更多；登录名已存在：更换密码）；或 login 和 senha_hash（另一系统的 hash，bcrypt 或 argon2：用户用那边的密码进入；见 senhas）；第一个用户通过 token 创建（没有用户时，登录不会被接受）',
        'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=salvar -d login=visitante -d senha=segredo123 http://servidor/relojoeiro/api.php',
        'login (não o próprio)' => 'login（不能是自己的）',
        'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=usuarios -d acao=excluir -d login=visitante http://servidor/relojoeiro/api.php',
        '(nada): aplica as migrações pendentes, na ordem: o SQL de cada uma e, se ela tiver, o passo em PHP' => '（无）：按顺序应用待处理的迁移：每一条的 SQL，以及它若有的 PHP 步骤',
        'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=migracoes -d acao=aplicar http://servidor/relojoeiro/api.php',
        '(nada; lingua= escolhe o idioma, como em qualquer pedido: fora do português, o cadastro inicial sai nele e ele vira o idioma padrão, config.idioma): instala o banco do config.php, só num banco vazio (o schema.sql traduzido para o banco, com os passos em PHP das migrações), pelo token (antes da instalação não há usuários); a resposta traz comandos, tabelas e segundos. Depois: o primeiro usuário, em recurso=usuarios, acao=salvar' => '（无；lingua= 选择语言，与任意请求相同：若不是葡萄牙语，初始档案用该语言输出，并成为默认语言 config.idioma）：安装 config.php 中的数据库，仅限空数据库（翻译到该数据库的 schema.sql，含各迁移的 PHP 步骤），通过 token（安装之前没有用户）；响应包含 comandos、tabelas 和秒数。然后：第一个用户，在 recurso=usuarios, acao=salvar',
        'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php' => 'curl -H "X-Api-Token: segredo" -d recurso=instalacao -d acao=instalar http://servidor/relojoeiro/api.php',
        'banco (o nome do banco antigo, MySQL/MariaDB), substituir (1: apaga antes os relógios e o histórico deste banco; obrigatório quando ele já tem relógios): traz a árvore, os relógios, as fotos, os usuários, os valores dos campos e o histórico, tudo numa transação (parou no meio: nada fica gravado); a resposta traz contagem (quantos de cada)' => 'banco（旧数据库的名称，MySQL/MariaDB）, substituir（1：先删除此数据库中的手表和历史；当它已有手表时必填）：带入树、手表、照片、用户、字段的值以及历史，全部在一个事务中（中途停止：什么都不会保存）；响应包含 contagem（每一类有多少）',
        'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=importacao -d acao=importar -d banco=relogios -d substituir=1 http://servidor/relojoeiro/api.php',
        '(nada): faz uma cópia agora na BACKUP_PASTA (as mais velhas que passam do BACKUP_MANTER saem); a resposta traz arquivo' => '（无）：现在在 BACKUP_PASTA 做一份副本（超过 BACKUP_MANTER 的最旧副本会被删除）；响应包含 arquivo',
        'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=fazer http://servidor/relojoeiro/api.php',
        'arquivo (o nome de uma cópia da pasta): antes, guarda uma cópia do que está agora; depois, num passo só, troca todos os registros pelos da cópia (se algo falha, nada muda); só uma cópia da mesma versão do banco; sem o conteúdo dos documentos, eles voltam sem a cópia no banco e o cron refaz a pedida' => 'arquivo（文件夹中一份副本的名称）：先保存当前内容的一份副本；然后一步把全部记录换成该副本中的记录（若有失败，则什么都不改）；只能是同一数据库版本的副本；若不含文档内容，文档会回来但没有数据库中的副本，cron 会重新做被要求的复制',
        'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php' => 'curl -u lucas:senha -d recurso=backup -d acao=restaurar -d arquivo=relojoeiro-2026-10-12-200000.jsonl.gz http://servidor/relojoeiro/api.php',
        'a senha não fica guardada em lugar nenhum: fica só o hash dela, feito pelo password_hash do PHP com PASSWORD_DEFAULT (bcrypt). O hash tem 60 caracteres: $2y$, o custo com dois dígitos e $ (12 é 2^12 rodadas), o sal (22 caracteres, sorteado a cada senha) e o resultado (31). O sal e o custo vão dentro do próprio hash' => '密码不会保存在任何地方：只保存其 hash，由 PHP 的 password_hash 以 PASSWORD_DEFAULT（bcrypt）生成。hash 有 60 个字符：$2y$、两位数字的代价和 $（12 即 2^12 轮）、盐（22 个字符，每个密码随机抽取）以及结果（31）。盐和代价都在 hash 自身之内',
        'o hash não se desfaz em senha (é de mão única). Para conferir, calcula-se o bcrypt da senha digitada com o sal e o custo que estão no hash e compara-se com o resultado: é o que o password_verify do PHP faz no login. A mesma senha dá hashes diferentes a cada cálculo (o sal muda), e todos conferem' => 'hash 不能还原成密码（它是单向的）。校验时，用 hash 中的盐和代价计算所输入密码的 bcrypt，再与结果比较：这就是 PHP 的 password_verify 在登录时所做的。同一密码每次计算得到的 hash 都不同（盐会变），但都能对上',
        'leve o login e o senha_hash de cada um (recurso=usuarios, ou a resposta sem recurso) e, no outro sistema, confira a senha digitada contra o hash com o bcrypt dele: cada um entra lá com a mesma senha de sempre. $2y$ (PHP) e $2b$ (Python, Node, Java, C#...) são o mesmo cálculo; se a biblioteca recusar o $2y$, troque o começo por $2b$' => '带走每一个的 login 和 senha_hash（recurso=usuarios，或不带 recurso 的响应），在另一个系统里用它的 bcrypt 把输入的密码与 hash 核对：每个人在那边用一直以来的同一密码进入。$2y$（PHP）和 $2b$（Python、Node、Java、C#……）是同一种计算；若库拒绝 $2y$，把开头换成 $2b$',
        'POST recurso=usuarios, acao=salvar, login e senha_hash (um bcrypt $2y$, $2b$ ou $2a$, ou um argon2): o usuário entra aqui com a senha que tinha lá, sem ninguém saber qual é (o $2b$ é guardado como $2y$, o mesmo cálculo)' => 'POST recurso=usuarios, acao=salvar, login 和 senha_hash（bcrypt 的 $2y$、$2b$ 或 $2a$，或 argon2）：用户在这里用那边原有的密码进入，没有人知道密码是什么（$2b$ 会按 $2y$ 保存，计算相同）',
        'conferir: password_verify($senha, $hash); fazer: password_hash($senha, PASSWORD_DEFAULT)' => '校验：password_verify($senha, $hash)；生成：password_hash($senha, PASSWORD_DEFAULT)',
        'pip install bcrypt; conferir: bcrypt.checkpw(senha.encode(), hash.encode()); fazer: bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()' => 'pip install bcrypt；校验：bcrypt.checkpw(senha.encode(), hash.encode())；生成：bcrypt.hashpw(senha.encode(), bcrypt.gensalt()).decode()',
        'npm install bcryptjs; conferir: require("bcryptjs").compareSync(senha, hash); fazer: require("bcryptjs").hashSync(senha, 12)' => 'npm install bcryptjs；校验：require("bcryptjs").compareSync(senha, hash)；生成：require("bcryptjs").hashSync(senha, 12)',
        'Spring Security: new BCryptPasswordEncoder().matches(senha, hash) (com jBCrypt, BCrypt.checkpw(senha, hash) trocando $2y$ por $2a$)' => 'Spring Security：new BCryptPasswordEncoder().matches(senha, hash)（若用 jBCrypt，则 BCrypt.checkpw(senha, hash)，并把 $2y$ 换成 $2a$）',
        'BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)' => 'BCrypt.Net-Next: BCrypt.Net.BCrypt.Verify(senha, hash)',
        'em qualquer consulta: a resposta sem parâmetros e todos os recursos' => '在任意查询中：不带参数的响应以及全部资源',
        'incluir=relogios,plano: só essas partes da resposta' => 'incluir=relogios,plano：只返回响应中的这些部分',
        'excluir=motor,criterios: a resposta sem essas partes' => 'excluir=motor,criterios：响应中不含这些部分',
        'as regras valem para uma lista da resposta, pelo caminho dela entre os colchetes: relogios, plano, avisos, eventos, usuarios, cron.execucoes, criterios.notas, criterios.conjuntos, agenda.desejados, relogios.lancamentos, relogios.avisos, relogios.linha_do_tempo, relogio.leituras (na ficha)...; lista dentro de lista vale em cada item' => '这些规则适用于响应中的一个列表，按其在方括号中的路径：relogios、plano、avisos、eventos、usuarios、cron.execucoes、criterios.notas、criterios.conjuntos、agenda.desejados、relogios.lancamentos、relogios.avisos、relogios.linha_do_tempo、relogio.leituras（在详情中）……；列表之中的列表对每一项都有效',
        'qualquer campo do item; com ponto entra num objeto (compra.valor) ou, numa lista de itens com identificador, no item daquele identificador (formulas.energia.valor, campos.loja.valor)' => '条目的任意字段；用点进入一个对象（compra.valor），或者在带标识符的条目列表中，进入该标识符对应的条目（formulas.energia.valor、campos.loja.valor）',
        'igual a v (vários separados por vírgula: igual a um deles; numa lista de valores, se algum for)' => '等于 v（多个以逗号分隔：等于其中之一；在值列表中，若有任何一个等于）',
        'a partir de v (números como números; datas e textos como texto)' => '从 v 起（数字按数字；日期和文本按文本）',
        'até v (uma data sem hora vai até o fim daquele dia)' => '直到 v（不带时间的日期算到那天结束）',
        'o texto contém t' => '文本包含 t',
        'diferente de v (vários separados por vírgula: de todos)' => '不等于 v（多个以逗号分隔：全部都不等于）',
        'vazio (1) ou preenchido (0)' => '空（1）或已填写（0）',
        'o texto t em qualquer campo do item' => '文本 t 出现在条目的任意字段中',
        'ordena pelo campo; -campo: do maior para o menor; vários separados por vírgula' => '按该字段排序；-campo：从大到小；多个以逗号分隔',
        'N itens por página, a página P' => '每页 N 项，第 P 页',
        'só esses campos de cada item (com ponto também)' => '只返回每个条目的这些字段（也可以用点）',
        'textos sem diferença de maiúsculas e acentos; verdadeiro e falso valem 1 e 0; filtros juntos: o item tem de passar em todos' => '文本不区分大小写和重音；真和假相当于 1 和 0；多个筛选一起用：条目必须全部通过',
        'ganha _filtros: {listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [o caminho sem lista, a parte que não existe]}; com filtros, objetos vazios saem como listas vazias' => '会多出 _filtros：{listas: {caminho: {antes, passaram, devolvidos, pagina, limite}}, ignorados: [没有列表的路径, 不存在的部分]}；有筛选时，空对象输出为空列表',
        'limite, pagina, ordem e busca sem colchetes continuam sendo os do recurso (historico, cron)' => '不带方括号的 limite、pagina、ordem 和 busca 仍然属于该资源本身（historico、cron）',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][disponivel]=1&mostrar[relogios]=id,nome&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][formulas.energia.valor][ate]=20&ordem[relogios]=formulas.energia.valor&mostrar[relogios]=nome,formulas.energia.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][id]=10,12&f[relogios.lancamentos][tipo]=carga&f[relogios.lancamentos][inicio][de]=2026-09-01&mostrar[relogios]=nome,lancamentos&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=relogios&f[relogios][campos.loja.valor][contem]=aliexpress&mostrar[relogios]=nome,campos.valor_compra.valor&foto=nao"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=plano&f[plano][data][de]=2026-10-01&f[plano][data][ate]=2026-10-31&f[plano][relogio][contem]=xiaomi"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=cron&f[cron.execucoes][teve_erro]=1&limite[cron.execucoes]=20&pagina[cron.execucoes]=2"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?incluir=criterios&f[criterios.notas][nota][de]=50&ordem[criterios.notas]=-nota&mostrar[criterios.notas]=relogio,nota"',
        'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"' => 'curl -u lucas:senha -g "http://servidor/relojoeiro/api.php?recurso=hoje&f[relogios][com_aviso]=1&mostrar[relogios]=nome,manutencao.nome"',
        '[] no caminho: uma lista (o campo é de cada item); <...>: uma chave que varia (o identificador de um campo, um estado, uma função...). Datas e horas no fuso do sistema (o FUSO do config.php; sem ele, o do PHP, date.timezone); null: sem valor. Números de tempo em segundos são inteiros.' => '路径中的 []：一个列表（该字段属于每一项）；<...>：会变化的键（一个字段的标识符、一个状态、一个函数……）。日期和时间使用系统时区（config.php 的 FUSO；没有则用 PHP 的 date.timezone）；null：无值。以秒计的时间数字是整数。',
        'os eventos que o sistema criou no Google Agenda' => '系统在 Google 日历中创建的事件',
        'a marca do título e da descrição com que foi criado (mudou: o evento é atualizado na próxima sincronização)' => '创建时所用标题和描述的标记（若有变化：事件在下次同步时更新）',
        'a identificação do evento (a mesma dos desejados)' => '事件的标识（与 desejados 中的相同）',
        'quando foi criado (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '创建时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o dia do evento (texto AAAA-MM-DD)' => '事件的日期（文本 AAAA-MM-DD）',
        'o id do evento no Google' => '事件在 Google 中的 id',
        'o título com que foi criado' => '创建时所用的标题',
        'o que tem de estar no Google Agenda agora: os avisos marcados para a agenda, o relógio do dia, a véspera e os eventos' => '现在 Google 日历中应有的内容：标记到日历的提醒、当天的手表、前一天以及各事件',
        'a identificação do evento na agenda (a mesma enquanto nada mudar; é o que o sistema usa para atualizar ou remover)' => '日历中事件的标识（只要没有变化就保持不变；系统用它来更新或删除）',
        'o dia do evento na agenda (texto AAAA-MM-DD)' => '日历中事件的日期（文本 AAAA-MM-DD）',
        'a descrição do evento, montada pela mensagem do canal da agenda' => '事件的描述，由日历渠道的消息组装而成',
        'a ação ("Dar corda", "Usar hoje", o nome do evento) — a âncora {acao}' => '操作（“上链”、“今天使用”、事件名称）——锚点 {acao}',
        'a hora do evento na agenda (HH:MM)' => '日历中事件的时间（HH:MM）',
        'o instante previsto do que motivou o evento (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => '引发该事件之事的预计时刻（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'o porquê ("a reserva acaba em 3h, 28/09 10:53") — a âncora {motivo}' => '原因（“动力储存将在 3h 后耗尽，28/09 10:53”）——锚点 {motivo}',
        'o nome do relógio; vazio num evento geral' => '手表的名称；一般事件中为空',
        'o relógio do evento; null num evento geral' => '事件的手表；一般事件中为 null',
        'o tipo: dia, vespera, o identificador do aviso, ou ev<id> (evento personalizado)' => '类型：dia、vespera、提醒的标识符，或 ev<id>（自定义事件）',
        'o título do evento, montado pela mensagem do canal da agenda' => '事件的标题，由日历渠道的消息组装而成',
        'os grupos, em ordem de árvore' => '各分组，按树的顺序',
        'o caminho por extenso ("Tradicional › Quartzo › Solar")' => '完整路径（“Tradicional › Quartzo › Solar”）',
        'o número do grupo' => '分组的编号',
        'o nome do grupo' => '分组的名称',
        'a posição entre os irmãos' => '在同级中的位置',
        'o grupo de cima; null: na raiz' => '上级分组；null：在根',
        'o nível na árvore (0: na raiz)' => '在树中的层级（0：在根）',
        'os avisos cadastrados (cada identificador pode ter uma versão por grupo)' => '已登记的提醒（每个标识符可以按分组有一个版本）',
        'a data na agenda: janela (só dentro da antecedência da agenda) ou sempre' => '在日历中的日期：janela（仅在日历提前量之内）或 sempre',
        '1: o aviso vai pelo Telegram no minuto em que vence (uma vez, até ser resolvido); 0: só no alerta da manhã' => '1：提醒在到期的那一分钟经 Telegram 发出（一次，直到被解决）；0：只在早晨警报中',
        'com quantos dias antes ele entra "em breve" (número)' => '提前多少天进入“即将”（数字）',
        'o aviso vale' => '该提醒有效',
        'vale quando: uma fórmula que diz para quais relógios do grupo o aviso vale (1 vale, 0 não; ex.: corda_manual = 0, só o automático sem corda); null: vale para todos' => '何时有效：一条公式，说明该提醒对分组中的哪些手表有效（1 有效，0 无效；例：corda_manual = 0，仅没有上链的自动手表）；null：对全部有效',
        'na escala inteligente: nao, uso ou sempre' => '在智能排班表中：nao、uso 或 sempre',
        'a fórmula da data prevista' => '预计日期的公式',
        'o número da versão' => '版本号',
        'o aviso (o tipo dele nos canais)' => '该提醒（它在各渠道中的类型）',
        'esse grupo por extenso' => '该分组的完整名称',
        'o grupo desta versão; null: todos' => '此版本的分组；null：全部',
        'o nome do aviso — a âncora {acao}' => '提醒的名称——锚点 {acao}',
        'o tipo de lançamento que resolve (o botão na tela Hoje); null: nenhum' => '用来解决它的记录类型（今天界面上的按钮）；null：没有',
        'as horas da sessão que a escala simula para resolver (número; null)' => '排班表为解决它而模拟的时段小时数（数字；null）',
        'o valor do lançamento que a escala simula para resolver (número; null)' => '排班表为解决它而模拟的记录值（数字；null）',
        'o motivo, com {relogio}, {data}, {quando} e {limite} — a âncora {motivo}' => '事由，含 {relogio}、{data}、{quando} 和 {limite}——锚点 {motivo}',
        'os campos do cadastro dos relógios (cada um vale para o grupo dele e tudo abaixo)' => '手表档案的字段（每一个对其分组及其下全部有效）',
        'o número do campo' => '字段的编号',
        'o nome do campo nas fórmulas e nos critérios' => '字段在公式和标准中的名称',
        'o grupo em que o campo vale; null: todos os relógios' => '字段生效的分组；null：全部手表',
        'o nome do campo' => '字段的名称',
        'as opções de um campo de lista, uma por linha (texto; vazio nos outros)' => '列表字段的选项，每行一个（文本；其他类型为空）',
        'a posição do campo no cadastro' => '字段在档案中的位置',
        'o valor usado quando o relógio não tem o campo preenchido (texto; null: nenhum)' => '手表未填写该字段时使用的值（文本；null：没有）',
        'inteiro, decimal, sim_nao, data, lista ou texto' => 'inteiro、decimal、sim_nao、data、lista 或 texto',
        'a unidade (texto; vazio: nenhuma)' => '单位（文本；空：没有）',
        'a mensagem padrão da agenda: a primeira linha é o título do evento, o resto a descrição' => '日历的默认消息：第一行是事件标题，其余是描述',
        'com quantos dias de antecedência os eventos são criados na agenda' => '提前多少天在日历中创建事件',
        '1: cria os eventos no Google Agenda; 0: não' => '1：在 Google 日历中创建事件；0：不创建',
        'o caminho da chave JSON da conta de serviço do Google, no servidor' => '服务器上 Google 服务账号 JSON 密钥的路径',
        'o id da agenda do Google' => 'Google 日历的 id',
        'o id do evento de teste na agenda (vazio: nenhum)' => '日历中测试事件的 id（空：没有）',
        'o limite de carga geral (%): carregar quando a carga chega a ele (o campo carga_minima do relógio, se preenchido, vale no lugar)' => '总电量上限（%）：当电量到达该值时充电（若手表的 carga_minima 字段已填写，则改用它）',
        'o erro guardado da última execução com erro (texto; vazio: sem erro)' => '最近一次有错误的执行所保存的错误（文本；空：无错误）',
        'o registro da última rodada com atividade (texto)' => '最近一轮有活动的记录（文本）',
        'quando o cron rodou pela última vez (texto AAAA-MM-DD HH:MM:SS, no fuso do sistema)' => 'cron 最近一次运行的时间（文本 AAAA-MM-DD HH:MM:SS，系统时区）',
        'os avisos "na hora" que já foram pelo Telegram e ainda estão vencidos (relogio_id:identificador, separados por vírgula): o cron não manda de novo' => '已经经 Telegram 发出且仍处于到期状态的“到点”提醒（relogio_id:identificador，以逗号分隔）：cron 不会再次发送',
        'quando foi feita a última cópia de segurança (texto AAAA-MM-DD HH:MM:SS)' => '最近一次备份的时间（文本 AAAA-MM-DD HH:MM:SS）',
        'até que dia vai a escala inteligente gerada (texto AAAA-MM-DD; vazio fora da escala)' => '已生成的智能排班表延伸到哪一天（文本 AAAA-MM-DD；不在排班表中则为空）',
        'o dia em que a escala foi gerada pela última vez (texto AAAA-MM-DD)' => '排班表最近一次生成的日期（文本 AAAA-MM-DD）',
        'a hora da rodada da manhã do cron: o relógio do dia e os avisos (HH:MM)' => 'cron 早晨轮次的时间：当天的手表和提醒（HH:MM）',
        'a hora da rodada da noite: preparar o relógio de amanhã (HH:MM)' => '夜晚轮次的时间：准备明天的手表（HH:MM）',
        'a garantia de rodízio: nenhum relógio passa desses dias sem uso (0 desliga)' => '轮换保障：没有任何手表会超过这么多天不被使用（0 则关闭）',
        'a média do gasto medido pelas leituras usa as medições destes últimos dias (sem nenhuma na janela, a última)' => '由读数测得的消耗平均值使用最近这些天的测量（窗口内一次都没有，则用最近一次）',
        'o aviso Encostado: depois de quantos dias sem ir ao pulso um relógio da coleção é avisado (1 a 3650; padrão 30)' => '闲置提醒：收藏中的一块手表多少天没上手腕后会被告知（1 到 3650；默认 30）',
        'o idioma padrão da instalação (pt-BR, en, zh-CN, hi, es, fr; vazio: o do navegador, senão português)' => '安装的默认语言（pt-BR、en、zh-CN、hi、es、fr；空：浏览器的语言，否则为葡萄牙语）',
        '1: o Telegram (a API de alerta) envia; 0: não envia' => '1：Telegram（警报 API）会发送；0：不发送',
        'como o relógio abre na página Hoje: lado (no painel à direita da lista) ou flutuante (numa janela grande por cima da página); vazio: lado' => '手表在今天页面如何打开：lado（在列表右侧的面板中）或 flutuante（在页面上方的大窗口中）；空：lado',
        'o destaque no alto da página Hoje: dia (o relógio do dia, o do plano) ou pulso (o relógio no pulso agora; sem nenhum no pulso, o do dia); vazio: dia' => '今天页面顶部的突出显示：dia（当天的手表，即计划中的那块）或 pulso（现在在手腕上的手表；手腕上没有时，用当天的）；空：dia',
        'o "Mostrar até" dos Próximos dias da página Hoje: quantos dias por página (1 a 366; vazio: 7)' => '今天页面接下来的日子的“显示至”：每页多少天（1 到 366；空：7）',
        'o "Mostrar até" do dia a dia da página Plano: quantos dias por página (1 a 366; vazio: 31)' => '计划页面逐日内容的“显示至”：每页多少天（1 到 366；空：31）',
        'a fonte do último lote de números aleatórios e quando (o sistema grava; só leitura)' => '最近一批随机数的来源和时间（由系统写入；只读）',
        'quando os dois serviços de números aleatórios falharam (segundos desde 1970; vazio: no ar); o sistema grava; só leitura' => '两个随机数服务都失败的时间（自 1970 起的秒数；空：在线）；由系统写入；只读',
        'marca de que a migração v10 foi aplicada (1)' => '迁移 v10 已应用的标记（1）',
