        'os lugares que podem ter critérios: todos os relógios, cada grupo (em ordem de árvore) e cada relógio' => '可以有标准的位置：全部手表、每个分组（按树的顺序）和每块手表',
        'o lugar: "" (todos), g:<grupo> ou r:<relógio>' => '位置：""（全部）、g:<分组> 或 r:<手表>',
        'o lugar de quem ele herda os critérios quando não tem os seus; null: ninguém (nota neutra)' => '当它没有自有标准时，所继承标准的来源位置；null：没有（中性分数）',
        'esse lugar por extenso' => '该位置的完整名称',
