        'verdadeiro ou falso: o modo é escala inteligente (escolhe sempre pela maior nota)' => '真或假：该模式是智能排班表（始终按最高分数选择）',
        'o nome do modo' => '模式的名称',
        'a forma de escolha: inteligente (a maior nota), ponderado (sorteio pela nota), aleatorio ou fifo (o mais tempo sem uso)' => '选择方式：inteligente（最高分数）、ponderado（按分数抽签）、aleatorio 或 fifo（最久未使用）',
        'a nota de cada relógio agora, com a conta' => '每块手表现在的分数，含计算过程',
        'o lugar dos critérios usados: "" (todos), g:<grupo> ou r:<relógio>; null: nenhum (nota neutra, 50)' => '所用标准的位置：""（全部）、g:<分组> 或 r:<手表>；null：没有（中性分数，50）',
        'cada subparâmetro que entrou na conta' => '进入计算的每个子参数',
        'a faixa em que o valor caiu ("30 a 50", ou a categoria)' => '值落入的区间（“30 到 50”，或该类别）',
        'a nota da faixa, de 0 a 100 (número)' => '区间的分数，0 到 100（数字）',
        'o peso no conjunto: peso do subparâmetro × peso do parâmetro, reescalado sem os que não se aplicam, em % (número)' => '在集合中的权重：子参数权重 × 参数权重，去掉不适用的之后重新换算，以 % 计（数字）',
        'nota × peso efetivo ÷ 100 (número): quanto somou na nota' => '分数 × 有效权重 ÷ 100（数字）：对分数贡献了多少',
        'o valor medido (número, ou o texto de uma lista)' => '测得的值（数字，或列表的文本）',
        'o que o subparâmetro mede (o identificador do campo ou da fórmula)' => '子参数所度量的（字段或公式的标识符）',
        'verdadeiro ou falso: o relógio está disponível para o rodízio' => '真或假：手表可用于轮换',
        'o grupo do relógio (o caminho na árvore)' => '手表的分组（在树中的路径）',
        'a nota final, de 0 a 100 (número): a soma dos pontos' => '最终分数，0 到 100（数字）：各得分之和',
