        'a especificação visual que a reescrita tem de reproduzir, tela por tela: o que está lá existe, o que não está não existe' => '重写必须逐屏复现的视觉规格：存在的就存在，不存在的就不存在',
        'como ler a especificação (os textos entre aspas são os da tela, palavra por palavra; o estilo.css é a referência de cada medida)' => '如何阅读该规格（引号中的文本是界面上的，逐字相同；estilo.css 是每项尺寸的参考）',
        'o sistema visual, comum a todas as páginas, em partes: cores, letras, controles, componentes, layout (larguras e tamanhos de tela) e comportamento' => '视觉系统，所有页面共用，分部分：颜色、字体、控件、组件、布局（宽度和屏幕尺寸）和行为',
        'o nome curto da parte (cores, letras, controles, componentes, layout, comportamento)' => '部分的短名称（cores、letras、controles、componentes、layout、comportamento）',
        'uma regra do visual, com os valores exatos (cores em hexadecimal, tamanhos em px ou rem, os textos da tela)' => '一条视觉规则，带确切值（颜色为十六进制，尺寸为 px 或 rem，以及界面文本）',
        'o menu do topo' => '顶部菜单',
        'como o menu aparece no computador e no celular, e as páginas que não estão nele' => '在电脑和手机上菜单如何显示，以及不在菜单中的页面',
        'os itens do menu, na ordem da barra' => '菜单项，按栏中的顺序',
        'o arquivo da página (index.php, plano.php...)' => '页面文件（index.php、plano.php……）',
        'o texto do item no menu' => '菜单项的文本',
        'cada página do sistema, na ordem do menu e depois as que abrem do relógio' => '系统的每个页面，先按菜单顺序，然后是从手表打开的那些',
        'o nome curto da página (hoje, ficha, plano, configuracao, criterios, grupos, execucoes, historico, documentos, cadastros, usuarios, ajuda)' => '页面的短名称（hoje、ficha、plano、configuracao、criterios、grupos、execucoes、historico、documentos、cadastros、usuarios、ajuda）',
        'o arquivo da página' => '页面文件',
        'o título da página (o da aba do navegador)' => '页面标题（浏览器标签上的）',
        'o endereço, com os parâmetros que a página aceita' => '地址，含页面所接受的参数',
        'o que a página lê da API' => '页面从 API 读取什么',
        'o que a página grava pela API (o recurso e as ações); vazio: só lê' => '页面通过 API 写入什么（资源和操作）；空：只读',
        'as partes da página, de cima para baixo' => '页面的各部分，从上到下',
        'o nome da parte (e quando ela aparece)' => '部分的名称（以及它何时出现）',
        'o que a parte tem: cada tabela com as colunas, cada formulário com os campos (rótulo, tipo, padrão e limites), cada botão com o texto e o que ele manda para a API, e cada mensagem' => '该部分有什么：每个表格及其列、每个表单及其字段（标签、类型、默认值和限制）、每个按钮及其文本和它发给 API 的内容，以及每条消息',
        'os arquivos da página, lidos dela na hora (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega): o código de cada um em recurso=codigo&arquivo=<nome>' => '页面的文件，当场从它读取（pagina.php、estilo.css、页面本身以及它加载的脚本）：每一个的代码在 recurso=codigo&arquivo=<名称>',
        'as capturas de tela no repositório, para conferir o resultado' => '仓库中的界面截图，用于核对结果',
        'o caminho da imagem (docs/telas/...)' => '图像的路径（docs/telas/...）',
        'o que ela mostra' => '它显示什么',
        'a lista do código do sistema, como em recurso=codigo (sem o conteúdo: cada arquivo pelo recurso=codigo&arquivo=<nome>)' => '系统代码的清单，与 recurso=codigo 中相同（不含内容：每个文件通过 recurso=codigo&arquivo=<名称>）',
        'como pedir um arquivo, o arquivo puro, o HTML de uma página e todos de uma vez' => '如何请求一个文件、纯文件、一个页面的 HTML 以及一次全部',
        'as camadas do sistema' => '系统的各层次',
        'o nome curto da camada' => '层次的短名称',
        'o que está nela' => '其中有什么',
        'cada arquivo do sistema' => '系统的每个文件',
        'o nome do arquivo, com a pasta (estilo.css, testes/cenario.php, docs/telas/hoje.png): é o que se passa em arquivo=' => '文件的名称，含文件夹（estilo.css、testes/cenario.php、docs/telas/hoje.png）：这就是传给 arquivo= 的内容',
        'a camada (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem; veja camadas)' => '层次（tela、api、linha_de_comando、banco、servidor、testes、documentacao、repositorio、imagem；见 camadas）',
        'o que o arquivo é e o que ele faz' => '该文件是什么、做什么',
        'php, javascript, css, sql, markdown, apache, nginx, texto ou png' => 'php、javascript、css、sql、markdown、apache、nginx、texto 或 png',
        'o tamanho, em bytes' => '大小，以字节计',
        'quantas linhas (null na imagem)' => '有多少行（图像为 null）',
        'o SHA-256 do arquivo: para conferir a cópia, ou saber se mudou desde a última leitura' => '文件的 SHA-256：用于核对副本，或得知自上次读取以来是否改变',
        'a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => '文件在服务器上的最后修改日期（AAAA-MM-DD HH:MM:SS）',
        'o endereço deste arquivo na API, com o conteúdo, em JSON' => '此文件在 API 中的地址，含内容，JSON',
        'o endereço do arquivo puro, sem JSON (texto como text/plain; imagem como imagem)' => '纯文件的地址，无 JSON（文本为 text/plain；图像作为图像）',
        'só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => '仅页面：它使用的文件，按顺序（pagina.php、estilo.css、页面本身以及它加载的脚本）',
        'só nas páginas: o endereço do HTML que o navegador recebe, puro' => '仅页面：浏览器收到的 HTML 的地址，纯文本',
        'o que fica de fora de propósito' => '有意排除的内容',
        'o que é' => '它是什么',
        'por que não sai' => '为什么不输出',
        'onde está o que a reescrita precisa saber dele' => '重写需要知道的关于它的内容在哪里',
        'o modelo de dados, lido do próprio banco em uso (o que vale agora, depois de todas as migrações)' => '数据模型，从正在使用的数据库本身读出（现在有效的，在全部迁移之后）',
        'o banco de onde o modelo foi lido: mysql, pgsql, sqlite ou firebird (os tipos das colunas vêm no dialeto dele)' => '模型所读取的数据库：mysql、pgsql、sqlite 或 firebird（列类型用它的方言）',
        'como ler as tabelas, e as três referências que ficam pelo nome, de propósito' => '如何阅读各表，以及故意按名称保留的三处引用',
        'cada tabela, em ordem alfabética' => '每张表，按字母顺序',
        'o nome da tabela' => '表的名称',
        'o que a tabela guarda' => '该表保存什么',
        'as colunas, na ordem da tabela' => '各列，按表中的顺序',
        'o nome da coluna' => '列的名称',
        'o tipo, no dialeto do banco em uso' => '类型，用正在使用的数据库的方言',
        'verdadeiro: aceita vazio (NULL)' => '真：允许为空（NULL）',
        'o valor padrão, como o banco escreve (null: nenhum)' => '默认值，按数据库的写法（null：没有）',
        'as colunas da chave primária' => '主键的各列',
        'as ligações com outras tabelas' => '与其他表的关联',
        'a coluna desta tabela' => '本表的列',
        'a tabela.coluna para onde ela aponta' => '它指向的 表.列',
        'o que acontece ao apagar a linha de cima: CASCADE (some junto) ou SET NULL (a ligação se desfaz)' => '删除上面那一行时发生什么：CASCADE（一并消失）或 SET NULL（关联解除）',
        'cada chave única: a lista das colunas dela' => '每个唯一键：它的列的列表',
        'uma coluna da chave única, na ordem' => '唯一键的一列，按顺序',
        'cada índice que não é único: a lista das colunas dele' => '每个非唯一索引：它的列的列表',
        'uma coluna do índice, na ordem' => '索引的一列，按顺序',
        'as regras de validação (CHECK) da tabela, inclusive as das listas fechadas' => '表的校验规则（CHECK），包括封闭列表的那些',
        'o nome da regra (ck_<tabela>_<o quê>; null: a de uma lista fechada, sem nome)' => '规则的名称（ck_<表>_<是什么>；null：封闭列表的，没有名称）',
        'a condição que toda linha tem de cumprir, como o banco escreve' => '每一行都必须满足的条件，按数据库的写法',
        'as listas do código que a reescrita precisa ter iguais' => '重写必须保持一致的代码清单',
        'as funções do motor das fórmulas' => '公式引擎的函数',
        'o nome da função' => '函数的名称',
        'quantos argumentos ela aceita ("2", "1 a 2", "3 ou mais")' => '它接受多少个参数（“2”、“1 到 2”、“3 个或更多”）',
        'o que ela devolve' => '它返回什么',
        'verdadeiro: lê os lançamentos do relógio (o primeiro argumento é um tipo de lançamento, entre aspas)' => '真：读取手表的记录（第一个参数是一个记录类型，放在引号里）',
        'os tipos de campo do cadastro' => '档案的字段类型',
        'o tipo (inteiro, decimal, sim_nao, data, lista, texto)' => '类型（inteiro、decimal、sim_nao、data、lista、texto）',
        'o que ele é, e como entra nas contas' => '它是什么，以及如何进入计算',
        'os formatos dos tipos de lançamento' => '记录类型的格式',
        'o que ele é' => '它是什么',
        'as repetições dos eventos personalizados' => '自定义事件的重复方式',
        'a repetição (uma, diaria, semanal, mensal, intervalo)' => '重复（uma、diaria、semanal、mensal、intervalo）',
        'como ela aparece na tela' => '它在界面上如何显示',
        'os dias da semana como o sistema numera' => '系统如何给星期几编号',
        'o número (1 segunda a 7 domingo)' => '编号（1 周一到 7 周日）',
        'as âncoras das mensagens (entre chaves no texto)' => '消息的锚点（在文本中位于花括号之间）',
        'a âncora, sem as chaves' => '锚点，不含花括号',
        'o que ela vira' => '它会变成什么',
        'os canais das mensagens' => '消息的渠道',
        'o código do canal (tg: Telegram, ag: Google Agenda)' => '渠道的代码（tg：Telegram，ag：Google 日历）',
        'como a mensagem sai nele' => '消息在其中如何发出',
        'as migrações, na ordem' => '各迁移，按顺序',
        'o arquivo do SQL dela' => '它的 SQL 文件',
        'o que ela traz' => '它带入什么',
        'verdadeiro: ela tem também um passo em programa, depois do SQL' => '真：它在 SQL 之后还有一个程序步骤',
        'as constantes do config.php' => 'config.php 的常量',
        'o nome (ou os nomes) da constante' => '常量的名称（或各名称）',
        'para que ela serve' => '它用来做什么',
        'falso: a cópia de segurança está desligada no config.php (BACKUP_ATIVO = false): o cron não faz cópia, a escrita fazer é recusada e a Configuração não mostra o quadro Cópia de segurança' => 'false：备份已在 config.php 中关闭（BACKUP_ATIVO = false）：cron 不做备份，写入操作 fazer 被拒绝，设置中不显示备份框',
        'verdadeiro: a pasta das cópias (BACKUP_PASTA do config.php) existe, aceita gravar e fica fora da pasta publicada' => '真：副本文件夹（config.php 的 BACKUP_PASTA）存在、允许写入且位于已发布文件夹之外',
        'por que a pasta não serve (sem BACKUP_PASTA, não existe, sem permissão de escrita, ou dentro da pasta publicada); null: serve' => '文件夹不可用的原因（没有 BACKUP_PASTA、不存在、无写入权限，或位于已发布文件夹之内）；null：可用',
        'quantas cópias ficam na pasta (BACKUP_MANTER; padrão 7): a cada cópia nova, as mais velhas que passam disso saem' => '文件夹中保留多少份副本（BACKUP_MANTER；默认 7）：每做一份新副本，超出这个数量的最旧副本会被删除',
        'verdadeiro: as cópias levam o conteúdo dos documentos guardado no banco (BACKUP_DOCUMENTOS); falso: não levam (os arquivos já estão na pasta dos documentos)' => '真：副本包含保存在数据库中的文档内容（BACKUP_DOCUMENTOS）；假：不包含（文件已经在文档文件夹中）',
        'a versão do banco agora (a última migração): só uma cópia da mesma versão volta' => '数据库现在的版本（最近一次迁移）：只有同一版本的副本才能还原',
        'quando foi feita a última cópia (texto AAAA-MM-DD HH:MM:SS); null: nenhuma' => '最近一次副本的时间（文本 AAAA-MM-DD HH:MM:SS）；null：没有',
        'as cópias que estão na pasta, da mais nova para a mais velha' => '文件夹中的各份副本，从最新到最旧',
        'o nome do arquivo (relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz): é o que se passa em arquivo= para baixar ou restaurar' => '文件的名称（relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz）：这就是传给 arquivo= 用来下载或还原的内容',
        'o tamanho por extenso ("7 KB", "1,2 MB")' => '大小的文字形式（“7 KB”、“1,2 MB”）',
        'quando a cópia foi feita (texto AAAA-MM-DD HH:MM:SS)' => '副本制作的时间（文本 AAAA-MM-DD HH:MM:SS）',
        'verdadeiro: a cópia leva o conteúdo dos documentos' => '真：副本包含文档内容',
        'a versão do banco da cópia (a última migração dele)' => '副本的数据库版本（它的最近一次迁移）',
        'as camadas do sistema, na ordem' => '系统的各层次，按顺序',
        'cada arquivo do sistema (os do repositório), pela camada' => '系统的每个文件（仓库中的那些），按层次',
        'o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => '文件的内容，按原样（文本）；仅在带 arquivo= 或 conteudo=1 时',
        'o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => '图像的内容，base64；仅在带 arquivo= 或 conteudo=1 时',
        'só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => '仅页面，且带 arquivo= 或 conteudo=1：浏览器收到的 HTML，已经组装好（带菜单的顶部、页面骨架和脚本）',
        'o que fica de fora de propósito, e o que ver no lugar' => '有意排除的内容，以及改看什么',
        'o que é (o config.php, a chave do Google, o banco, a pasta dos documentos, as senhas)' => '它是什么（config.php、Google 密钥、数据库、文档文件夹、密码）',
        'com arquivo=: o nome do arquivo, com a pasta (estilo.css, testes/cenario.php, docs/telas/hoje.png): é o que se passa em arquivo=' => '带 arquivo=：文件的名称，含文件夹（estilo.css、testes/cenario.php、docs/telas/hoje.png）：这就是传给 arquivo= 的内容',
        'com arquivo=: a camada (tela, api, linha_de_comando, banco, servidor, testes, documentacao, repositorio, imagem; veja camadas)' => '带 arquivo=：层次（tela、api、linha_de_comando、banco、servidor、testes、documentacao、repositorio、imagem；见 camadas）',
        'com arquivo=: o que o arquivo é e o que ele faz' => '带 arquivo=：该文件是什么、做什么',
        'com arquivo=: php, javascript, css, sql, markdown, apache, nginx, texto ou png' => '带 arquivo=：php、javascript、css、sql、markdown、apache、nginx、texto 或 png',
        'com arquivo=: o tamanho, em bytes' => '带 arquivo=：大小，以字节计',
        'com arquivo=: quantas linhas (null na imagem)' => '带 arquivo=：有多少行（图像为 null）',
        'com arquivo=: o SHA-256 do arquivo: para conferir a cópia, ou saber se mudou desde a última leitura' => '带 arquivo=：文件的 SHA-256：用于核对副本，或得知自上次读取以来是否改变',
        'com arquivo=: a data da última alteração do arquivo no servidor (AAAA-MM-DD HH:MM:SS)' => '带 arquivo=：文件在服务器上的最后修改日期（AAAA-MM-DD HH:MM:SS）',
        'com arquivo=: o endereço deste arquivo na API, com o conteúdo, em JSON' => '带 arquivo=：此文件在 API 中的地址，含内容，JSON',
        'com arquivo=: o endereço do arquivo puro, sem JSON (texto como text/plain; imagem como imagem)' => '带 arquivo=：纯文件的地址，无 JSON（文本为 text/plain；图像作为图像）',
        'com arquivo=: só nas páginas: os arquivos que ela usa, na ordem (o pagina.php, o estilo.css, a própria página e os scripts que ela carrega)' => '带 arquivo=：仅页面：它使用的文件，按顺序（pagina.php、estilo.css、页面本身以及它加载的脚本）',
        'com arquivo=: só nas páginas: o endereço do HTML que o navegador recebe, puro' => '带 arquivo=：仅页面：浏览器收到的 HTML 的地址，纯文本',
        'com arquivo=: o conteúdo do arquivo, como está (texto); só com arquivo= ou conteudo=1' => '带 arquivo=：文件的内容，按原样（文本）；仅在带 arquivo= 或 conteudo=1 时',
        'com arquivo=: o conteúdo da imagem, em base64; só com arquivo= ou conteudo=1' => '带 arquivo=：图像的内容，base64；仅在带 arquivo= 或 conteudo=1 时',
        'com arquivo=: só nas páginas, com arquivo= ou conteudo=1: o HTML que o navegador recebe, já montado (o topo com o menu, o esqueleto da página e os scripts)' => '带 arquivo=：仅页面，且带 arquivo= 或 conteudo=1：浏览器收到的 HTML，已经组装好（带菜单的顶部、页面骨架和脚本）',
        'aparece quando a consulta usa filtros (incluir, excluir, f, busca, ordem, limite, pagina, mostrar)' => '当查询使用筛选时出现（incluir、excluir、f、busca、ordem、limite、pagina、mostrar）',
        'o que foi pedido e não existe (caminho sem lista, parte que não existe)' => '所请求但不存在的内容（没有列表的路径、不存在的部分）',
        'quantos itens a lista tinha' => '列表原来有多少项',
        'quantos vieram (a página)' => '返回了多少项（该页）',
        'o limite por página; null: sem' => '每页上限；null：没有',
        'quantos passaram nos filtros' => '有多少项通过了筛选',
        'o recurso (vazio: tudo)' => '资源（空：全部）',
        'a ação (escrita)' => '操作（写入）',
        'json (padrão) ou xml' => 'json（默认）或 xml',
        'o token da API; também no cabeçalho X-Api-Token, ou o login do site (HTTP Basic) no lugar dele' => 'API 的 token；也可以放在请求头 X-Api-Token 中，或改用网站登录（HTTP Basic）',
        'pedido recusado: uma escrita que não passou nas validações ({ok: false, mensagem, erros: [...]}, um erro por motivo) ou uma fórmula mal escrita no recurso=calcular ({erro, erros})' => '请求被拒绝：一次未通过校验的写入（{ok: false, mensagem, erros: [...]}，每个原因一条错误）或 recurso=calcular 中书写错误的公式（{erro, erros}）',
        'recurso=entrar com o login certo e volta=<página>: vai para a página' => 'recurso=entrar 且登录正确并带 volta=<页面>：前往该页面',
        'sem o token nem o login do site, ou com eles errados; sem nenhum usuário (ou com o banco vazio), também sem_usuarios: true e como (o que fazer: instalar, criar o primeiro usuário pelo token)' => '没有 token 也没有网站登录，或它们不正确；没有任何用户时（或数据库为空），还有 sem_usuarios: true 以及怎么做（要做什么：安装、通过 token 创建第一个用户）',
        'recurso desconhecido (com recursos, a lista deles), ou o relógio, a foto, o documento (ou o arquivo dele) ou o README.md (recurso=manual) que não existe, ou um arquivo que não sai pelo recurso=codigo ({erro, e o_que_ver no que fica de fora de propósito, como o config.php, ou arquivos, os que saem)' => '未知的 recurso（带 recursos，即它们的列表），或手表、照片、文档（或其文件）或 README.md（recurso=manual）不存在，或某个文件不通过 recurso=codigo 输出（{erro，以及有意排除内容中的 o_que_ver，如 config.php，或 arquivos，即会输出的那些）',
        'o banco recusou a gravação (um registro que outro ainda usa, um valor repetido, ou um valor fora das regras de validação do banco: o nome da regra, ck_<tabela>_<o quê>, vem no detalhe)' => '数据库拒绝了写入（一条仍被其他记录使用的记录、一个重复的值，或一个超出数据库校验规则的值：规则名称 ck_<表>_<是什么> 出现在 detalhe 中）',
        'o envio passou do limite do PHP do servidor (post_max_size): um arquivo grande demais' => '上传超过了服务器 PHP 的上限（post_max_size）：文件太大',
        'sistema parado (token ou fuso inválido no config.php) ou erro interno' => '系统停止（config.php 中的 token 或时区无效）或内部错误',
        'banco desatualizado (só recurso=migracoes responde, e o recurso=manual e o recurso=codigo, que não usam o banco), banco vazio (antes da instalação só recurso=instalacao responde, e o manual e o código) ou banco fora do ar' => '数据库过期（只有 recurso=migracoes 会响应，以及不使用数据库的 recurso=manual 和 recurso=codigo），数据库为空（安装之前只有 recurso=instalacao 会响应，以及手册和代码）或数据库离线',
        'números com vírgula ou ponto; textos entre aspas; argumentos separados por ponto e vírgula; operações + - * / ^; comparações = <> < <= > >= (dão 1 ou 0); variáveis: os identificadores dos campos e das fórmulas; vazio se propaga; divisão por zero: vazio' => '数字可用逗号或点；文本放在引号里；参数用分号分隔；运算 + - * / ^；比较 = <> < <= > >=（结果为 1 或 0）；变量：字段和公式的标识符；空值会传递；除以零：空值',
    ],
    'reconstrucao' => [
        'os eventos que o sistema criou no Google Agenda: a chave (o que o evento é: o tipo, o relógio e o dia), o id no Google, a data, o título e a assinatura (o resumo do conteúdo, para saber se mudou)' => '系统在 Google 日历中创建的事件：键（事件是什么：类型、手表和日期）、在 Google 中的 id、日期、标题和签名（内容摘要，用于判断是否改变）',
        'os avisos do cadastro: o identificador, o nome, a fórmula da data prevista (expressao), a condição (vale quando), a antecedência em dias, o texto, se está ativo, o grupo da versão (no_id; vazio: todos), o tipo de lançamento que resolve, como a escala simula a solução (escala, simula_valor, simula_horas) e se entra na agenda só dentro da janela ou sempre' => '档案中的提醒：标识符、名称、预计日期的公式（expressao）、条件（何时有效）、提前天数、文本、是否启用、版本的分组（no_id；空：全部）、用来解决它的记录类型、排班表如何模拟解决方案（escala、simula_valor、simula_horas）以及是只在窗口内进入日历还是始终进入',
        'os campos do cadastro dos relógios: o identificador (o nome nas fórmulas), o nome, o tipo, a unidade, o valor padrão, o grupo em que vale (vazio: todos) e a ordem' => '手表档案的字段：标识符（在公式中的名称）、名称、类型、单位、默认值、生效的分组（空：全部）和顺序',
        'as opções de um campo do tipo lista, em ordem (sem repetir, sem diferenciar maiúsculas e acentos)' => '列表类型字段的选项，按顺序（不重复，不区分大小写和重音）',
        'o valor de cada campo em cada relógio (texto normalizado pelo tipo do campo: número com ponto, data AAAA-MM-DD, sim/não 1 ou 0)' => '每块手表每个字段的值（按字段类型规范化的文本：数字用点，日期 AAAA-MM-DD，是/否为 1 或 0）',
        'para cada canal (tg: Telegram, ag: Google Agenda) e cada tipo de aviso (dia, vespera, o identificador de um aviso) ou evento personalizado: se ele vai pelo canal, se tem mensagem própria e o texto dela' => '对于每个渠道（tg：Telegram，ag：Google 日历）和每种提醒类型（dia、vespera、某个提醒的标识符）或自定义事件：它是否经该渠道发出、是否有自己的消息及其文本',
        'os valores soltos da Configuração (horários, limites, mensagens padrão, marcas do sistema), chave e valor' => '设置中的零散值（时间、限值、默认消息、系统标记），键和值',
        'as faixas de um subparâmetro: de um número até outro (ou sem limite) ou uma categoria, e a nota (0 a 100) que o valor ganha nela' => '一个子参数的区间：从一个数字到另一个（或无上限）或一个类别，以及值在其中得到的分数（0 到 100）',
        'os parâmetros de um conjunto de critérios: o lugar (todos, um grupo ou um relógio), o nome, o peso (%) e a ordem' => '一个标准集合的参数：位置（全部、一个分组或一块手表）、名称、权重（%）和顺序',
        'os subparâmetros de um parâmetro: o nome, a variável que mede (um campo ou uma fórmula), o peso dentro do parâmetro (%) e a ordem' => '一个参数的子参数：名称、所度量的变量（一个字段或一条公式）、在参数内的权重（%）和顺序',
        'cada execução do cron que registrou algo: início, fim, duração, o registro em texto, se teve erro e se teve atividade' => '每次记录了内容的 cron 执行：开始、结束、持续时间、文本记录、是否有错误以及是否有活动',
        'os documentos de cada relógio: a categoria, o título, a data, a descrição, o nome e o tipo do arquivo, o tamanho, o caminho na pasta (arquivo e miniatura), se a cópia no banco está completa (no_banco), se o próprio arquivo pede a cópia (copia_banco) e o SHA-256' => '每块手表的文档：类别、标题、日期、描述、文件的名称和类型、大小、在文件夹中的路径（文件和缩略图）、数据库中的副本是否完整（no_banco）、文件本身是否要求副本（copia_banco）以及 SHA-256',
        'as categorias dos documentos (Manual, Nota fiscal, Fotos...): identificador, nome e ordem' => '文档的类别（说明书、发票、照片……）：标识符、名称和顺序',
        'as famílias de arquivo que uma categoria aceita (imagem, video, audio, pdf, xml); nenhuma: qualquer arquivo' => '一个类别所接受的文件族（imagem、video、audio、pdf、xml）；一个都没有：任意文件',
        'a cópia de um documento dentro do banco, em pedaços de 4 MB (parte 0, 1, 2...; a parte -1 é a miniatura)' => '文档在数据库内的副本，以 4 MB 分块（部分 0、1、2……；部分 -1 是缩略图）',
        'os dias da semana de um evento personalizado semanal (1 segunda a 7 domingo)' => '每周自定义事件的星期几（1 周一到 7 周日）',
        'cada ocorrência de um evento personalizado que já disparou (para não disparar duas vezes)' => '已经触发过的自定义事件的每次发生（以免触发两次）',
        'os lembretes do usuário: nome, se está ativo, a repetição (uma vez, todo dia, em dias da semana, todo mês, a cada N dias), a data de início, a hora, o dia do mês, o intervalo e o relógio (opcional)' => '用户的备忘：名称、是否启用、重复（一次、每天、在星期几、每月、每 N 天）、开始日期、时间、月中的日期、间隔和手表（可选）',
        'as fórmulas do cadastro: o identificador (o nome nas outras fórmulas, nos avisos e nos critérios), o nome, a expressão, a unidade e o grupo da versão (no_id; vazio: todos). A mesma fórmula pode ter uma versão por grupo: vale a do grupo mais perto do relógio' => '档案中的公式：标识符（在其他公式、提醒和标准中的名称）、名称、表达式、单位和版本的分组（no_id；空：全部）。同一公式可以每个分组有一个版本：采用离手表最近的分组的那一版',
        'a foto de cada relógio (a imagem inteira, o tipo e quando foi trocada)' => '每块手表的照片（完整图像、类型以及更换时间）',
        'o histórico de cada relógio: o tipo, o início (o instante, num instantâneo), o fim (numa sessão; vazio: aberta), o valor (numa leitura) e a origem (manual, rodizio, importado)' => '每块手表的历史：类型、开始（瞬时记录中的时刻）、结束（时段中；空：已打开）、值（读数中）和来源（manual、rodizio、importado）',
        'os tipos de lançamento: identificador, nome, formato (instantâneo, com valor ou sessão), unidade, a hora em que a sessão esquecida fecha sozinha (fecha_as), o grupo, a ordem, se a sessão é exclusiva (o relógio fica num lugar só), se a leitura mede o gasto e a condição (vale quando)' => '记录类型：标识符、名称、格式（瞬时、带值或时段）、单位、忘记关闭的时段自行结束的时刻（fecha_as）、分组、顺序、时段是否独占（手表只处于一个地方）、读数是否测量消耗以及条件（何时有效）',
        'cada medição do gasto: o lançamento (a leitura) que a fechou, se mede o uso ou o repouso, o gasto achado (% por dia), as duas leituras, o intervalo, as horas no pulso e fora, o peso (horas) e se entra na média' => '每次消耗测量：结束它的记录（读数）、测量的是使用还是静止、得到的消耗（每天 %）、两次读数、间隔、在手腕上和离开手腕的小时数、权重（小时）以及是否计入平均值',
        'os modos de rodízio: nome, a forma de escolha, a ordem, o horizonte da escala inteligente (escala_dias; vazio: o modo sorteia pelos blocos), o ciclo e a marca do modo em uso (1 no ativo, vazio nos outros: no máximo um)' => '轮换模式：名称、选择方式、顺序、智能排班表的时间跨度（escala_dias；空：该模式按区块抽签）、循环以及当前使用模式的标记（启用的为 1，其他为空：最多一个）',
        'os blocos de um modo: nome, de onde sortear (um grupo; vazio: todos), um relógio por dia ou um para o bloco inteiro, o relógio fixo (opcional) e a ordem' => '一个模式的区块：名称、从何处抽签（一个分组；空：全部）、每天一块手表或整个区块一块、固定手表（可选）和顺序',
        'os dias da semana de um bloco (1 segunda a 7 domingo; um dia em um bloco só)' => '一个区块的星期几（1 周一到 7 周日；一天只属于一个区块）',
        'a árvore dos grupos: o nome, o grupo de cima (vazio: a raiz) e a ordem entre irmãos' => '分组的树：名称、上级分组（空：根）以及同级之间的顺序',
        'o relógio de cada dia: o relógio, o bloco do modo que o escolheu, a origem (sorteio ou manual), a ação do dia (o que fazer antes de usar), o motivo da escolha e quando foi gravado' => '每一天的手表：手表、选出它的模式区块、来源（抽签或手动）、当天的操作（使用前要做什么）、选择的事由以及保存时间',
        'os relógios: nome, grupo, se está disponível para o rodízio, se pede a cópia no banco de todos os documentos e quando foi cadastrado' => '各手表：名称、分组、是否可用于轮换、是否要求将其全部文档复制到数据库以及登记时间',
        'os dias livres do plano: sem relógio e sem sorteio (nem a escala), para escolher à mão' => '计划中的空闲日：无手表且无抽签（排班表也不排），供手动选择',
        'quem entra no site: o login e o hash da senha (password_hash)' => '进入网站的人：登录名和密码的 hash（password_hash）',
        'mysql (MySQL ou MariaDB, o padrão), pgsql (PostgreSQL), sqlite ou firebird (Firebird 3+)' => 'mysql（MySQL 或 MariaDB，默认）、pgsql（PostgreSQL）、sqlite 或 firebird（Firebird 3+）',
        'o servidor do banco (MySQL, PostgreSQL e Firebird; no Firebird, DB_NOME é o caminho do arquivo .fdb no servidor ou um apelido, e DB_HOST vazio abre o arquivo direto)' => '数据库服务器（MySQL、PostgreSQL 和 Firebird；在 Firebird 中，DB_NOME 是服务器上 .fdb 文件的路径或一个别名，DB_HOST 为空则直接打开文件）',
        'o arquivo do banco (SQLite), fora da pasta publicada' => '数据库文件（SQLite），位于已发布文件夹之外',
        'obrigatório, com pelo menos 10 caracteres: sem ele o sistema inteiro para (as páginas, a API e o cron dizem o motivo)' => '必填，至少 10 个字符：没有它整个系统停止（页面、API 和 cron 会说明原因）',
        'o fuso horário do sistema e das datas gravadas (vazio: o do PHP)' => '系统和所保存日期的时区（空：PHP 的时区）',
        'a API de mensagem (Telegram): um GET com destinatario, titulo e mensagem; resposta 2xx é sucesso; sem o endereço, nada é enviado' => '消息 API（Telegram）：一个带 destinatario、titulo 和 mensagem 的 GET；响应 2xx 为成功；没有地址则什么都不发送',
        'a pasta dos arquivos dos documentos, fora da pasta publicada, com escrita para o PHP' => '文档文件的文件夹，位于已发布文件夹之外，PHP 可写',
        'o maior documento aceito, em bytes (sem ele: 100 MB; 0 ou -1: sem limite do sistema)' => '接受的最大文档，以字节计（没有：100 MB；0 或 -1：系统无上限）',
        'a cópia dos documentos no banco para o sistema inteiro: true, todos; false, nenhum; ausente, o relógio e o arquivo decidem' => '整个系统的文档数据库副本：true，全部；false，一个都不；省略，由手表和文件决定',
        'opcional, para quem traduz: true faz a tradução que falta parar com erro (na API e no cron; nas telas, o texto aparece entre ⟦ ⟧ e o erro vai para o console)' => '可选，供翻译者使用：true 让缺少的翻译报错停止（在 API 和 cron 中；在界面上，文本显示在 ⟦ ⟧ 之间，错误写入控制台）',
        'opcional: false desliga a cópia de segurança (sem cópia automática, sem a escrita fazer e sem o quadro da Configuração); sem a linha, ligada' => '可选：false 关闭备份（没有自动备份、没有写入操作 fazer，设置中也没有该框）；没有这一行时为开启',
        'a cópia de segurança do banco: a pasta (fora da publicada; sem ela, não há cópia automática), quantas ficam (padrão 7) e se leva o conteúdo dos documentos (padrão: não)' => '数据库备份：文件夹（位于已发布文件夹之外；没有它就没有自动副本）、保留多少份（默认 7）以及是否包含文档内容（默认：否）',
        'só para importar o sistema anterior (importar.php)' => '仅用于导入旧系统（importar.php）',
        'só para testes: as fontes dos números aleatórios (RANDOM.ORG e ANU QRNG); trocadas, os sorteios pedem os números a um servidor de teste' => '仅用于测试：随机数来源（RANDOM.ORG 和 ANU QRNG）；换掉之后，抽签会向测试服务器请求数字',
        'só para testes: os endereços do Google que a agenda usa (o do token e o da API do Google Agenda); trocados, a sincronização conversa com um servidor de teste' => '仅用于测试：日历所用的 Google 地址（token 的地址和 Google 日历 API 的地址）；换掉之后，同步与测试服务器通信',
        'A interface que a reescrita tem de reproduzir, tela por tela: o visual (cores, letras, controles e componentes, com os valores exatos), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem, com cada tabela (as colunas), cada formulário (os campos com o rótulo, o tipo, o padrão e os limites), cada botão (o texto e o que ele manda para a API) e cada mensagem. Os textos entre aspas são os da tela, palavra por palavra. As capturas em docs/telas/ mostram o resultado; o estilo.css é a referência de cada medida. O código de cada página, como está agora, sai pelo recurso=codigo (os arquivos dela em codigo; o HTML que ela entrega ao navegador em recurso=codigo&arquivo=<página>&html=1&cru=1).' => '重写必须逐屏复现的界面：视觉（颜色、字体、控件和组件，带确切值）、菜单，以及每个页面的地址、它从 API 读取和写入什么、按顺序的各部分，含每个表格（列）、每个表单（字段及其标签、类型、默认值和限制）、每个按钮（文本以及它发给 API 的内容）和每条消息。引号中的文本是界面上的，逐字相同。docs/telas/ 中的截图显示结果；estilo.css 是每项尺寸的参考。每个页面现在的代码通过 recurso=codigo 输出（它的文件在 codigo 中；它交给浏览器的 HTML 在 recurso=codigo&arquivo=<页面>&html=1&cru=1）。',
        'Fundo da página: aço #e4e8ec. Bordas: aço escuro #c3cad2. Texto: tinta #1c2530 (também o fundo da barra do menu). Rótulos e notas: cinza #6b7684. Botões, links, aba ativa, barras de carga: safira #1f4f8f. O que fazer, recados e carga baixa: âmbar #a8661a. Fundo de cartões, quadros e tabelas: papel #fbfcfd.' => '页面背景：钢灰 #e4e8ec。边框：深钢灰 #c3cad2。文本：墨色 #1c2530（也是菜单栏的背景）。标签和说明：灰色 #6b7684。按钮、链接、活动标签、电量条：蓝宝石色 #1f4f8f。要做什么、提示和低电量：琥珀色 #a8661a。卡片、框和表格的背景：纸白 #fbfcfd。',
        'Etiquetas de estado (pílulas): em uso: fundo #e3f3e6, texto #1e6b2e, borda #a9d8b3. Em repouso e erro: fundo #fbe8e6, texto #9b2c22, borda #efb5ae. Indisponível e sem atividade: fundo #eef1f4, texto cinza, borda aço escuro. Atividade, "você" e "relógio de hoje": fundo #e6eef8, texto #1f4f8f, borda #b8cbe6. Numa sessão que não é o pulso (no sol, no winder, no carregador), outras sessões e carga: fundo #fff4e0, texto #8a5a00, borda #efd29a.' => '状态标签（胶囊）：使用中：背景 #e3f3e6，文本 #1e6b2e，边框 #a9d8b3。休息中和错误：背景 #fbe8e6，文本 #9b2c22，边框 #efb5ae。不可用和无活动：背景 #eef1f4，文本灰色，边框深钢灰。活动、“你”和“今天的手表”：背景 #e6eef8，文本 #1f4f8f，边框 #b8cbe6。非手腕的时段（在晒太阳、在上链盒、在充电器）、其他时段和电量：背景 #fff4e0，文本 #8a5a00，边框 #efd29a。',
        'Origem de um valor do cadastro: "informado" em azul (#e6eef8 / #1f4f8f / #b8cbe6), "padrão" em bege (#fbf1e3 / #8a5a00 / #ecd2a8), "vazio" sem etiqueta e com a linha em cinza.' => '档案中一个值的来源：“已填写”为蓝色（#e6eef8 / #1f4f8f / #b8cbe6），“默认”为米色（#fbf1e3 / #8a5a00 / #ecd2a8），“空”无标签且该行为灰色。',
        'Atrasado (um prazo vencido, "faltam" e "passa" das somas): texto #9b2c22 em negrito. Caixa de erros de gravação: fundo #fdf0ee, borda #e3b4ae, texto #7a2419, cantos 10px. Linha de execução com erro: fundo #fdf2f1.' => '逾期（一个已到期的期限，合计中的“还差”和“超过”）：文本 #9b2c22 粗体。保存错误框：背景 #fdf0ee，边框 #e3b4ae，文本 #7a2419，圆角 10px。有错误的执行行：背景 #fdf2f1。',
        'Letras e números' => '字体和数字',
        'Fonte: "Segoe UI", "Helvetica Neue", Arial, sans-serif, 16px, entrelinha 1,5.' => '字体："Segoe UI", "Helvetica Neue", Arial, sans-serif，16px，行高 1.5。',
        'Título da página (h1): grande, de 2rem a 3,4rem conforme a largura (clamp(2rem, 6vw, 3.4rem)), negrito 700, espaçamento -0,02em, entrelinha 1,05. Título de seção (h2): 1,1rem. Notas e explicações: 0,92rem, cinza. Título dos quadros do painel do relógio: 0,78rem, maiúsculas, negrito, espaçado 0,06em, cinza, com uma linha embaixo. Números em tabelas e valores com algarismos de largura igual (tabular).' => '页面标题（h1）：大，按宽度从 2rem 到 3.4rem（clamp(2rem, 6vw, 3.4rem)），粗体 700，字距 -0.02em，行高 1.05。节标题（h2）：1.1rem。说明和解释：0.92rem，灰色。手表面板各框的标题：0.78rem，大写，粗体，字距 0.06em，灰色，下方有一条线。表格中的数字和等宽数字的值（tabular）。',
        'Formatos: data DD/MM/AAAA (curta: DD/MM); hora HH:MM; números com vírgula e sem zeros sobrando (1 casa por padrão); dinheiro "R$ 1.234,56"; porcentagem "12,5%"; duração pelas duas maiores partes: "1a 5m", "5d 3h", "12h 22min", "40min", "menos de 1min"; dia da semana curto: seg, ter, qua, qui, sex, sáb, dom.' => '格式：日期 DD/MM/AAAA（短：DD/MM）；时间 HH:MM；数字用逗号且不保留多余的零（默认 1 位小数）；金额“R$ 1.234,56”；百分比“12,5%”；时长取最大的两部分：“1a 5m”、“5d 3h”、“12h 22min”、“40min”、“不足 1min”；星期几短写：seg、ter、qua、qui、sex、sáb、dom。',
        'Campos, listas e botões' => '字段、列表和按钮',
        'Uma altura só para campo, lista e botão: 2,4rem, para ficarem alinhados lado a lado. Cantos 8px; campo e lista com borda 1px aço escuro e fundo branco; textarea com a mesma borda. Foco visível: contorno 2px safira afastado 2px. Campo numérico curto: 5,5rem. Números digitados aceitam vírgula ou ponto (teclado decimal no celular). No celular, os campos têm letra de 16px (o iPhone não aproxima a tela).' => '字段、列表和按钮同一高度：2.4rem，以便并排对齐。圆角 8px；字段和列表边框 1px 深钢灰、背景白色；textarea 同样的边框。可见焦点：2px 蓝宝石色轮廓，偏移 2px。短数字字段：5.5rem。输入的数字接受逗号或点（手机上为小数键盘）。在手机上，字段字号为 16px（iPhone 不会放大页面）。',
        'Botão principal: fundo safira, texto branco, borda safira, preenchimento 0,3rem 1rem. Botão "leve": fundo transparente, texto e borda safira (as ações secundárias). Botão "discreto": sem borda, 0,85rem, preenchimento lateral 0,45rem (↑, ↓ e Excluir das linhas). O Excluir das ações de linha é vermelho: texto #9b2c22, borda #efb5ae, fundo #fbe8e6 ao passar o mouse.' => '主按钮：背景蓝宝石色，文本白色，边框蓝宝石色，内边距 0.3rem 1rem。“浅色”按钮：背景透明，文本和边框蓝宝石色（次要操作）。“低调”按钮：无边框，0.85rem，左右内边距 0.45rem（行内的 ↑、↓ 和删除）。行操作中的删除为红色：文本 #9b2c22，边框 #efb5ae，悬停时背景 #fbe8e6。',
        'Caixa de marcar (checkbox) sempre à esquerda do texto, na mesma linha. Rótulo de campo: acima do campo nas grades de formulário; à esquerda na Configuração (veja os componentes). Botões desativados durante o envio de um formulário.' => '复选框始终在文本左侧，同一行。字段标签：在表单网格中位于字段上方；在设置中位于左侧（见各组件）。表单发送期间按钮禁用。',
        'Barra do menu: fundo tinta, links #b9c3ce sem sublinhado; o da página atual em branco com uma linha branca de 2px embaixo.' => '菜单栏：背景墨色，链接 #b9c3ce 无下划线；当前页面的为白色，下方有 2px 白线。',
        'Cartão (as seções das páginas de cadastro): fundo papel, borda 1px aço escuro, cantos 12px, preenchimento 1rem, título h2 em cima.' => '卡片（档案页面的各节）：背景纸白，边框 1px 深钢灰，圆角 12px，内边距 1rem，上方为 h2 标题。',
        'Quadro (o painel do relógio): igual ao cartão (cantos 12px, preenchimento 0,85rem 1rem), com o título em maiúsculas pequenas, o corpo, e um rodapé opcional (linha em cima, botões à direita, alinhados no pé: os quadros da mesma linha da grade têm a mesma altura). Quadro "largo" ocupa a linha inteira da grade.' => '框（手表面板）：与卡片相同（圆角 12px，内边距 0.85rem 1rem），标题为小型大写，有正文，以及可选页脚（上方一条线，按钮在右侧，对齐到底部：网格同一行的框高度相同）。“宽”框占网格的整行。',
        'Pares (rótulo e valor): duas colunas, o rótulo em cinza 0,85rem à esquerda (até 55% da largura), o valor à direita; uma linha fina aço entre os pares (a última sem); um texto menor (0,78rem, cinza) embaixo do valor é a explicação dele; rótulo vazio continua a linha de cima.' => '成对（标签和值）：两列，标签在左侧为灰色 0.85rem（最多占宽度的 55%），值在右侧；成对之间有一条细钢灰线（最后一对没有）；值下方更小的文本（0.78rem，灰色）是它的说明；空标签延续上一行。',
        'Tabela: fundo papel, cantos 10px, cabeçalho em cinza 0,9rem negrito, células com preenchimento 0,55rem 0,75rem e uma linha aço embaixo. Linha clicável: o fundo muda para #f1f4f8 ao passar e fica #e3eaf5 quando selecionada; fim de semana em #f4f6f8; o relógio de hoje com uma faixa safira de 3px na borda esquerda, e um com aviso pendente com a faixa âmbar. Tabela compacta (dos cadastros): 0,88rem, sem fundo próprio.' => '表格：背景纸白，圆角 10px，表头灰色 0.9rem 粗体，单元格内边距 0.55rem 0.75rem，下方一条钢灰线。可点击的行：悬停时背景变为 #f1f4f8，选中时为 #e3eaf5；周末为 #f4f6f8；今天的手表在左边框有 3px 蓝宝石色条，有待处理提醒的为琥珀色条。紧凑表格（定义中的）：0.88rem，无自身背景。',
        'Etiqueta de estado: pílula com cantos arredondados por inteiro, 0,8rem negrito, preenchimento 0,12rem 0,55rem, cores em "cores". Numa linha só; nos pares rótulo/valor (o quadro Agora do painel estreito) e nas marcas da cabeça, a comprida ("Em repouso desde 25/09 20:40") quebra a linha nos espaços (nunca no meio da palavra), com cantos de 0,8rem, e fica dentro do quadro.' => '状态标签：完全圆角的胶囊，0.8rem 粗体，内边距 0.12rem 0.55rem，颜色见“颜色”。单行；在标签/值成对中（窄面板的现在框）以及头部的标记里，较长的（“休息中，自 25/09 20:40”）在空格处换行（绝不在词中间断开），圆角 0.8rem，并留在框内。',
        'Barra de carga: trilho aço com 7px de altura (44px na tabela, 56 a 70px nos quadros), preenchido em safira até a porcentagem (âmbar com carga até 20%), seguido do número em negrito ("68%"; estimado: "~68%") e, menor, de onde a carga vem.' => '电量条：钢灰轨道高 7px（表格中 44px，框中 56 到 70px），按百分比填充蓝宝石色（电量到 20% 为止为琥珀色），随后是粗体数字（“68%”；估计值：“~68%”），以及更小的电量来源。',
        'Janela de data (o "só hoje" / "até sexta, 02/10" do relógio do dia): caixa branca, borda 2px tinta, cantos 3px, negrito, sombra interna fina, como a janela de data de um mostrador.' => '日期窗（当天手表的“只有今天”/“直到周五，02/10”）：白底盒子，边框 2px 墨色，圆角 3px，粗体，细内阴影，像表盘上的日期窗。',
        'Recado (o resultado de uma gravação): um parágrafo âmbar em negrito no topo da área (ou do painel do relógio). Erros de gravação: a caixa vermelha clara com "Não foi salvo:" e um parágrafo por erro, no topo da página.' => '提示（一次保存的结果）：区域内（或手表面板内）顶部的一段琥珀色粗体。保存错误：浅红色盒子，带“未保存：”以及每个错误一段，位于页面顶部。',
        'Abas (Cadastros e Documentos): links lado a lado com borda aço e cantos 0,4rem, preenchimento 0,35rem 0,8rem, texto safira; a ativa com fundo safira e texto branco.' => '标签页（定义和文档）：链接并排，边框钢灰、圆角 0.4rem、内边距 0.35rem 0.8rem、文本蓝宝石色；活动的背景蓝宝石色、文本白色。',
        'Grade de formulário (form-grade): colunas de no mínimo 14rem lado a lado, o rótulo acima de cada campo; textareas, grupos de caixas e botões na linha inteira. Linha de inclusão: campos com o rótulo em cima, lado a lado, separados do resto por uma linha tracejada acima.' => '表单网格（form-grade）：最少 14rem 的列并排，每个字段上方有标签；textarea、复选框组和按钮占整行。添加行：字段标签在上方，并排，与其余部分以上方一条虚线分隔。',
        'Barra de salvar (Configuração): presa no pé da tela enquanto a página rola (sticky), fundo papel quase opaco, borda, cantos 12px, sombra para cima; à esquerda "As mudanças desta página valem depois de salvar.", à direita o botão.' => '保存栏（设置）：页面滚动时固定在屏幕底部（sticky），背景几乎不透明的纸白，有边框，圆角 12px，向上的阴影；左侧“本页的更改在保存后生效。”，右侧是按钮。',
        'Sem foto: quadrado tracejado (2px aço escuro, cantos 14px) com "Sem foto" em cinza no meio. Foto: quadrada (recortada), cantos 14px, borda aço escuro. Miniatura na tabela: 28px (36px no celular), cantos 5px.' => '无照片：虚线方块（2px 深钢灰，圆角 14px），中间灰色“无照片”。照片：正方形（裁切），圆角 14px，边框深钢灰。表格中的缩略图：28px（手机上 36px），圆角 5px。',
        'Ações de uma linha (Editar, ↑, ↓, Excluir): numa linha só, à direita da linha da tabela.' => '一行的操作（编辑、↑、↓、删除）：单行，位于表格行的右侧。',
        'Resumo em números (Execuções e Histórico): uma grade de caixinhas (4 colunas; 2 no celular), cada uma com o número grande (1,4rem) e o que ele é embaixo em cinza; a de erros com fundo vermelho claro.' => '数字摘要（执行和历史）：一格小盒子的网格（4 列；手机上 2 列），每个有大号数字（1.4rem）以及下方灰色的含义；错误的那个背景浅红。',
        'Larguras e tamanhos de tela' => '宽度和屏幕尺寸',
        'Conteúdo centrado com margens de 1,25rem: largura máxima 56rem nas páginas comuns (Plano, Usuários), 72rem na Ficha, 76rem na Configuração, Cadastros, Critérios, Grupos, Execuções e Histórico, 60rem na Ajuda. A página Hoje usa a largura toda.' => '内容居中，边距 1.25rem：普通页面最大宽度 56rem（计划、用户），详情 72rem，设置、定义、标准、分组、执行和历史 76rem，帮助 60rem。今天页面使用全部宽度。',
        'Página Hoje: duas colunas, o meio e o painel do relógio com 22rem à direita, preso ao rolar (sticky) e com rolagem própria; sem relógio aberto, o meio ocupa tudo. Com a Configuração "Numa janela flutuante, grande": o relógio abre no meio da tela, até 78rem ou 94% da largura, de 3% do alto a 3% de baixo, cantos 16px, sombra forte, com o fundo escurecido (rgba(16, 22, 29, .55)) e os quadros lado a lado; fecha no ×, no Esc ou num clique no fundo.' => '今天页面：两列，中间以及右侧 22rem 的手表面板，滚动时固定（sticky）并有自己的滚动；没有打开的手表时，中间占满。设置设为“在大的浮动窗口中”时：手表在屏幕中央打开，最大 78rem 或宽度的 94%，从顶部 3% 到底部 3%，圆角 16px，强阴影，背景变暗（rgba(16, 22, 29, .55)），各框并排；用 ×、Esc 或点击背景关闭。',
        'Até 900px (celular e tablet de pé): o menu recolhido; as tabelas viram fichas (cada célula com o título da coluna ao lado) ou cartões; o painel do relógio cobre a tela inteira, com o botão "× Fechar" preso no alto, e o voltar do aparelho fecha o painel; as grades viram uma coluna. De 901 a 1199px (tablet deitado): o painel "ao lado" desliza por cima, pela direita, com até 30rem, cantos 16px à esquerda e o fundo escurecido. De 1200px em diante: o painel ao lado.' => '到 900px（手机和竖屏平板）：菜单收起；表格变成卡片（每个单元格旁边有列标题）或卡片；手表面板盖住整个屏幕，顶部固定“× 关闭”按钮，设备的返回也会关闭面板；网格变成一列。901 到 1199px（横屏平板）：“在旁边”的面板从右侧滑出盖住，最大 30rem，左侧圆角 16px，背景变暗。1200px 起：面板在旁边。',
        'Nenhuma página rola de lado, em nenhum tamanho. A mesma informação em todos os tamanhos: nada é escondido por falta de espaço (a tabela dos relógios vira cartões com todos os campos quando as 12 colunas não cabem).' => '任何页面在任何尺寸下都不横向滚动。所有尺寸上信息相同：不因空间不足而隐藏任何内容（手表表在 12 列放不下时变成带全部字段的卡片）。',
        'As tabelas de um quadro se arrumam pela largura do quadro (container queries), não pela da tela: o mesmo quadro é estreito no painel ao lado e largo na ficha. Até 40rem, as Medições do gasto viram cartões; até 26rem, as tabelas dos Dados do relógio ficam mais justas e o valor quebra a linha.' => '一个框里的表格按框的宽度排列（container queries），而不是按屏幕宽度：同一个框在旁边的面板里是窄的，在详情里是宽的。到 40rem，消耗测量变成卡片；到 26rem，手表数据的表格更紧凑，值会换行。',
        'Nada sai da caixa em que está, de 320px (celular pequeno) a 1920px: as grades de colunas automáticas encolhem a coluna mínima até a largura da tela; um grupo de campos (fieldset) e os menus dentro dele encolhem com a tela (um menu de nome comprido não vaza); o menu de escolher o relógio da Ficha fica na largura da tela; o código comprido da Ajuda (uma URL de exemplo) quebra a linha. Os botões nunca partem o texto em duas linhas: os da foto (Abrir, Trocar, Remover foto) ficam numa linha, na largura da foto (6,5rem no painel ao lado e no celular); o botão de marcar do quadro Marcar fica numa linha própria, embaixo dos campos. Até 420px, as tabelas do painel e o resumo do Plano ficam mais justas (0,82rem, 0,3rem entre as colunas) e quebram dentro da célula. No Histórico do celular, as colunas são 25%, 25%, 18% e 32% (o Estado, a mais larga).' => '从 320px（小手机）到 1920px，没有任何东西溢出它所在的盒子：自动列网格会把最小列宽缩到屏幕宽度；一组字段（fieldset）以及其中的菜单随屏幕缩小（名称很长的菜单不会溢出）；详情中选择手表的菜单保持在屏幕宽度内；帮助中很长的代码（一条示例 URL）会换行。按钮从不把文本拆成两行：照片的按钮（打开、更换、移除照片）在一行内，宽度为照片的宽度（旁边的面板和手机上为 6.5rem）；标记框的标记按钮单独占一行，在字段下方。到 420px，面板的表格和计划的摘要更紧凑（0.82rem，列间距 0.3rem）并在单元格内换行。在手机的历史中，列宽为 25%、25%、18% 和 32%（状态，最宽的一列）。',
        'Comportamento comum' => '共同行为',
        'Cada página entrega só o esqueleto; o JavaScript dela lê a API e monta a tela. Gravar é um formulário que manda um POST para a API (recurso e acao nos campos); depois a página se remonta com os dados novos, sem recarregar, e mostra a mensagem da API no topo (ou no painel do relógio, se a gravação era dele).' => '每个页面只交付骨架；它的 JavaScript 读取 API 并组装界面。保存是一个向 API 发送 POST 的表单（字段中带 recurso 和 acao）；然后页面用新数据重新组装，不重新加载，并把 API 的消息显示在顶部（若保存属于手表面板，则显示在面板中）。',
        'Antes de toda exclusão e de toda ação que refaz o plano, uma confirmação do navegador com o texto do que vai acontecer (os textos estão em cada página). Durante o envio os botões do formulário ficam desativados; se a conexão falhar: "Não consegui gravar: <motivo>. Confira a conexão e tente de novo."' => '在每次删除以及每次会重做计划的操作之前，浏览器确认框说明将要发生的事（文本在每个页面中）。发送期间表单按钮禁用；若连接失败：“无法保存：<原因>。请检查连接并再试一次。”',
        'Sem login: a página manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e volta. Banco desatualizado (503 com pendentes): a página vai para a Configuração, que mostra só o aviso e o "Aplicar agora". Erro ao ler: "Não consegui ler <o quê>: <motivo>" em âmbar, no lugar da página.' => '未登录：页面转到 api.php?recurso=entrar&volta=<该页面>，浏览器要求输入用户和密码然后返回。数据库过期（503 且有待处理项）：页面转到设置，那里只显示提醒和“立即应用”。读取出错：“无法读取<是什么>：<原因>”，琥珀色，出现在页面的位置。',
        'Fotos reduzidas no navegador antes de enviar: no máximo 1200px no lado maior, JPEG 85%, com a prévia na tela; imagem que não abre: alerta "Não consegui abrir essa imagem. Use JPEG ou PNG.".' => '照片在发送前于浏览器中缩小：长边最大 1200px，JPEG 85%，并在屏幕上预览；打不开的图像：警报“无法打开这张图像。请使用 JPEG 或 PNG。”',
        'A foto do relógio ampliada, só no detalhe do relógio (o painel, ou a ficha): duplo clique na foto (o cursor é a lupa de ampliar) ou o botão "Abrir foto" embaixo dela abre por cima de tudo uma janela flutuante (nas outras fotos, como a do "Hoje é dia de" e as miniaturas da lista, o clique abre o relógio e o duplo clique não faz nada a mais): fundo rgba(10,14,20,.82) na tela inteira, a foto no meio, no tamanho dela (os pixels da imagem em px da página), cantos 6px, fundo branco e sombra; maior que a área que se vê, em escala, sem deformar: a escala é o menor entre 1, (largura − 32px) ÷ a largura da foto e (altura − 72px) ÷ a altura da foto, com a largura e a altura sendo o menor entre o monitor (screen.availWidth/availHeight) e a janela do navegador; refeita quando a janela muda de tamanho ou de monitor. Embaixo, em branco, "<nome> · <largura> × <altura> px" e, em escala, "(mostrada a N%)". Um botão redondo "×" (branco, 2,4rem) no canto de cima, à direita. Fecha com o ×, com um clique fora da foto ou com Esc (o Esc fecha só a foto: o painel por baixo continua aberto); enquanto aberta, a página não rola.' => '手表照片的放大，仅在手表详情中（面板或详情页）：双击照片（光标是放大镜）或它下方的“打开照片”按钮，会在一切之上打开一个浮动窗口（其他照片，如“今天轮到”的照片和列表缩略图，单击打开手表，双击没有额外作用）：整个屏幕背景 rgba(10,14,20,.82)，照片在中间，按其尺寸（图像像素对应页面的 px），圆角 6px，白底和阴影；大于可见区域时按比例缩放、不变形：比例是 1、(宽度 − 32px) ÷ 照片宽度、(高度 − 72px) ÷ 照片高度三者中的最小者，宽度和高度取显示器（screen.availWidth/availHeight）与浏览器窗口中的较小者；窗口改变大小或更换显示器时重算。下方，白色，“<名称> · <宽度> × <高度> px”，以及在缩放时“（显示为 N%）”。一个圆形按钮“×”（白色，2.4rem）在右上角。用 ×、点击照片外部或 Esc 关闭（Esc 只关闭照片：下面的面板保持打开）；打开期间页面不滚动。',
        'O título da aba do navegador é o título da página ("Relógio de hoje", "Plano", "Configuração", "Critérios de escolha", "Grupos de relógios", "Execuções do cron", "Usuários", "Cadastros", "Ajuda", "Ficha do relógio", "Documentos", "Desejos", "Estatísticas", "Hora certa", "Acessórios", "Galeria", "Passaporte do relógio" ("Passaporte — <relógio>" depois de ler); no histórico, "Histórico — <relógio>").' => '浏览器标签的标题是页面标题（“今天的手表”、“计划”、“设置”、“选择标准”、“手表分组”、“cron 执行”、“用户”、“定义”、“帮助”、“手表详情”、“文档”、“心愿单”、“统计”、“准确时间”、“配件”、“图库”、“手表护照”（读取后为“护照 — <手表>”）；在历史中为“历史 — <手表>”）。',
        'O navegador de páginas (Próximos dias, Dia a dia do Plano, Rodízio manual): botões leves pequenos (padding .3rem .65rem, letra .9rem) numa linha que quebra: "<" (dica "Anterior"; desativado na primeira), os números (a 1, a última e até 2 de cada lado da atual, com "…" sem borda nos saltos; dica "Página N"; a atual em safira com letra branca, sem ser botão) e ">" (dica "Próximo"; desativado na última). Uma página só: sem navegador. Cada botão relê a API com a página.' => '页面浏览器（接下来的日子、计划的逐日、手动轮换）：一行可换行的浅色小按钮（padding .3rem .65rem，字号 .9rem）：“<”（提示“上一页”；第一页禁用）、数字（第 1 页、最后一页以及当前页两侧最多 2 页，跳跃处为无边框的“…”；提示“第 N 页”；当前页为蓝宝石色白字，不是按钮）和“>”（提示“下一页”；最后一页禁用）。只有一页：没有浏览器。每个按钮用该页重新读取 API。',
        'Na barra escura do topo, nessa ordem, em todas as páginas; o da página atual em branco e sublinhado. A Ficha, o Histórico e os Documentos não estão no menu: abrem do painel do relógio (o histórico e os documentos numa aba nova). No celular (até 900px): a barra, presa no alto ao rolar, mostra o nome da página atual à esquerda e o botão "☰ Menu" à direita; aberto, ele vira "✕ Menu" e os itens aparecem em duas colunas, cada um num botão escuro (#27323f), o atual em safira. Depois do último item, o seletor do idioma: uma caixa pequena com o código curto de cada idioma (PT, EN, 中文, हिं, ES, FR; o nome inteiro na dica); escolher grava o cookie lingua (um ano, o caminho todo) e abre a página de novo nele. Os rótulos abaixo são os do português: em outro idioma, as traduções do dicionário das telas.' => '在顶部深色栏中，所有页面按此顺序；当前页面的为白色并带下划线。详情、历史和文档不在菜单中：从手表面板打开（历史和文档在新标签页）。在手机上（到 900px）：滚动时固定在顶部的栏，左侧显示当前页面名称，右侧按钮“☰ 菜单”；打开后变成“✕ 菜单”，各项排成两列，每个是深色按钮（#27323f），当前的为蓝宝石色。最后一项之后是语言选择器：一个小盒子，含每种语言的短代码（PT、EN、中文、हिं、ES、FR；提示中为全名）；选择后写入 cookie lingua（一年，整个路径）并重新打开该语言的页面。下面的标签是葡萄牙语的：在其他语言中，使用界面词典的译文。',
        'Estatísticas' => '统计',
        'Hora certa' => '准确时间',
        'Acessórios' => '配件',
        'Configuração' => '设置',
        'Critérios' => '标准',
        'Execuções do cron' => 'cron 运行记录',
        'Usuários' => '用户',
        'Relógio de hoje' => '今日手表',
        'index.php; index.php?r=<id> abre o relógio no painel; index.php?novo=1 abre o cadastro de um novo; index.php#manual abre o quadro Modo de rodízio no Rodízio manual' => 'index.php；index.php?r=<id> 在面板中打开手表；index.php?novo=1 打开新建的档案；index.php#manual 在手动轮换中打开轮换模式框',
        'recurso=hoje (com proximos_pagina)' => 'recurso=hoje（带 proximos_pagina）',
        'recurso=proximos (a troca de página dos Próximos dias)' => 'recurso=proximos（接下来的日子的翻页）',
        'recurso=ficha (o painel)' => 'recurso=ficha（面板）',
        'recurso=rodizio_manual (o Rodízio manual, de 7 em 7 dias)' => 'recurso=rodizio_manual（手动轮换，每 7 天）',
        'lancamento: iniciar, encerrar, lancar, periodo, alterar, excluir' => 'lancamento：iniciar、encerrar、lancar、periodo、alterar、excluir',
        'rodizio: trocar_dia, modo, resortear, resortear_hoje, proxima_semana, usando, sem_relogio, manual, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio：trocar_dia、modo、resortear、resortear_hoje、proxima_semana、usando、sem_relogio、manual、periodo_sortear、periodo_livre、apagar_tudo',
        'relogio: salvar, foto, remover_foto, excluir' => 'relogio：salvar、foto、remover_foto、excluir',
        'O relógio do dia (um cartão grande, no alto do meio)' => '当天的手表（一张大卡片，在中间的顶部）',
        'O relógio do cartão é o de destaque.relogio_id da API (o que tem relogios[].destaque): o relógio do dia, ou, com a Configuração "Destaque no alto da página Hoje" em "O relógio no pulso agora" (destaque_hoje = pulso), o que está no pulso agora. Quando ele não é o do dia (destaque.e = pulso): o nome dele em h1 (link que abre o painel), a janela de data com "no pulso agora" e o tipo dele, e em âmbar "Relógio do dia: <nome, link que abre o painel> (<até>)" (ou "Hoje não tem relógio do dia."), sem o motivo. Com o destaque no pulso e ninguém no pulso, o cartão do dia como sempre e, embaixo do motivo, o destaque.texto em cinza ("Nenhum relógio no pulso agora: aqui, o relógio do dia."). Os pares, o botão Pôs/Tirou do pulso e a foto são do relógio do cartão.' => '卡片上的手表是 API 的 destaque.relogio_id（即带 relogios[].destaque 的那块）：当天的手表，或者，当设置“今天页面顶部的突出显示”为“现在在手腕上的手表”（destaque_hoje = pulso）时，是现在在手腕上的那块。当它不是当天的（destaque.e = pulso）：它的名称作为 h1（打开面板的链接），日期窗写着“现在在手腕上”以及它的类型，琥珀色“当天的手表：<名称，打开面板的链接>（<直到>）”（或“今天没有当天的手表。”），没有事由。突出显示在手腕上但手腕上没有人时，当天的卡片照常，事由下方为灰色的 destaque.texto（“现在手腕上没有手表：这里是当天的手表。”）。成对、手腕的戴上/摘下按钮和照片都属于卡片上的手表。',
        'À esquerda: "<Dia da semana>, DD/MM/AAAA · <nome do modo>" em cinza; o nome do relógio do dia em h1 (link que abre o painel); a janela de data com o "até" ("só hoje", "até sexta, 02/10") e o tipo dele; o lembrete do dia em âmbar ("Pôr no winder: <relógio> (8 h)"); "Por que ele: <motivo>" (o motivo em cinza); embaixo, o botão leve discreto "Sem relógio hoje" (rodizio sem_relogio; confirma "Hoje sem relógio? O dia fica livre: ...").' => '左侧：灰色“<星期几>，DD/MM/AAAA · <模式名称>”；当天手表的名称作为 h1（打开面板的链接）；日期窗带“直到”（“只有今天”、“直到周五，02/10”）以及它的类型；当天的备忘为琥珀色（“放上上链盒：<手表>（8 h）”）；“为什么是它：<事由>”（事由为灰色）；下方，低调的浅色按钮“今天无手表”（rodizio sem_relogio；确认“今天没有手表？该日变为空闲：……”）。',
        'No meio, em pares: Agora (a etiqueta "Em uso desde 07:00", "No sol desde 09:12" ou "Em repouso desde ...", na cor do estado, e o botão leve "Pôs no pulso" / "Tirou do pulso", que manda lancamento iniciar/encerrar do tipo pulso); Carga (a barra, o % e de onde vem, ou só o texto); Última leitura ("89% em 06/10 21:30", se houver); Situação (as linhas da API); Próxima manutenção ("<nome> · <data ou hoje> (<falta>)", a falta em vermelho se atrasada, ou "nenhuma prevista"; o aviso mais perto, sem o Encostado); Encostado (só quando o aviso já venceu: a falta em vermelho); Compra ("R$ valor · loja · data"); Garantia ("até DD/MM/AAAA", "(vencida)" se passou); Código.' => '中间，成对：现在（标签“使用中，自 07:00”、“在晒太阳，自 09:12”或“休息中，自 ……”，按状态的颜色，以及浅色按钮“戴到手腕上”/“从手腕上摘下”，发送 tipo pulso 的 lancamento iniciar/encerrar）；电量（条、% 和来源，或只有文本）；最近一次读数（“89%，于 06/10 21:30”，若有）；情况（API 的各行）；下次保养（“<名称> · <日期或今天>（<还差>）”，若逾期则还差为红色，或“没有预计的”；最近的提醒，不含闲置）；闲置（仅当提醒已经到期：还差为红色）；购买（“R$ 金额 · 商店 · 日期”）；保修（“至 DD/MM/AAAA”，若已过则为“（已到期）”）；编号。',
        'À direita: a foto do relógio (ou o quadrado "Sem foto"), que abre o painel.' => '右侧：手表的照片（或“无照片”方块），它打开面板。',
        'Hoje livre (hoje_livre da API: o Sem relógio hoje, ou um período livre): h1 "Hoje sem relógio", a janela "dia livre", "Nenhum relógio vai ao pulso pelo rodízio hoje. Quer usar um? ..." e o "escolher…" dos dias livres (trocar_dia de hoje: o escolhido vai para o pulso a partir de agora); sem os pares nem a foto (a não ser com o destaque no pulso).' => '今天空闲（API 的 hoje_livre：今天无手表，或一个空闲时段）：h1“今天没有手表”，窗口“空闲日”，“今天没有任何手表会经轮换上手腕。要用一块吗？……”以及空闲日的“选择……”（今天的 trocar_dia：所选的从现在起上手腕）；没有成对也没有照片（除非突出显示在手腕上）。',
        'Sem relógio para hoje: h1 "Nenhum relógio para hoje" e "Nenhum relógio disponível no grupo deste dia. Mude o grupo no modo de rodízio ou marque um relógio como disponível."' => '今天没有手表：h1“今天没有手表”以及“这一天的分组中没有可用的手表。请在轮换模式中更改分组，或把一块手表标为可用。”',
        'Hoje é dia de (só quando há aviso)' => '今天轮到（仅当有提醒时）',
        'Tabela com as colunas "O que fazer" (o nome do aviso; atrasado em vermelho), "Relógio" (link que abre o painel), "Por quê" (o texto do aviso) e, à direita, o botão do lançamento que resolve, com o texto e a ação que a API dá (resolve.botao e resolve.acao): sessão fechada: "Pôs <nome em minúsculas>" (lancamento iniciar); sessão aberta: "Tirou do carregador" (lancamento encerrar); com valor: um campo curto com a unidade de dica ("%") e "Informar <nome>" (lancamento lancar com valor); instantâneo: o nome do tipo (lancamento lancar).' => '表格，列为“要做什么”（提醒的名称；逾期为红色）、“手表”（打开面板的链接）、“为什么”（提醒的文本），右侧是解决它的记录按钮，文本和操作由 API 给出（resolve.botao 和 resolve.acao）：时段已关闭：“已<小写名称>”（lancamento iniciar）；时段已打开：“已从充电器取下”（lancamento encerrar）；带值：一个短字段，提示为单位（“%”），以及“填写<名称>”（lancamento lancar 带值）；瞬时：类型的名称（lancamento lancar）。',
        'Próximos dias' => '接下来的日子',
        'Título "Próximos dias" com o link "ver o plano inteiro →" (plano.php). Tabela: Dia ("DD/MM" e o dia da semana curto, menor), Relógio (o nome; "à mão" pequeno quando escolhido à mão; o motivo embaixo, menor), Lembrete, e o "trocar por…". Fim de semana com fundo #f4f6f8. Sem plano: "Neste modo o sorteio é feito dia a dia." Os dias livres entram no meio, como na página Plano ("livre: escolha à mão", "escolher…"). Os dias vêm da API (hoje.proximos), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 7); passando disso, embaixo o navegador de páginas (recurso=proximos com pagina; só a lista se remonta) e "Página N de M · <total> dias no plano, <n> por página (o "Mostrar até" da Configuração)." (link para configuracao.php). A página à mostra fica a mesma quando a página Hoje se remonta depois de uma gravação.' => '标题“接下来的日子”，带链接“查看整个计划 →”（plano.php）。表格：日（“DD/MM”和更小的星期几短写）、手表（名称；手动选择时有小字“手动”；事由在下方，更小）、备忘，以及“换成……”。周末背景 #f4f6f8。没有计划：“在此模式下抽签是逐日进行的。”空闲日插在中间，与计划页面相同（“空闲：手动选择”、“选择……”）。日子来自 API（hoje.proximos），数量为“显示至”中的“显示至”（设置，默认 7）；超过之后，下方是页面浏览器（recurso=proximos 带 pagina；只重新组装列表）以及“第 N 页，共 M 页 · 计划中 <total> 天，每页 <n> 天（设置中的“显示至”）。”（链接到 configuracao.php）。今天页面在一次保存后重新组装时，当前显示的页保持不变。',
        '"trocar por…": uma lista com os relógios disponíveis (menos o do dia) e, num dia de amanhã em diante escolhido à mão, "↺ voltar a sortear" (valor 0); escolhido um, aparece o botão leve "Trocar" (rodizio trocar_dia com data e relogio_id).' => '“换成……”：一个列表，含可用的手表（不含当天的），以及从明天起手动选择的日子上有“↺ 恢复抽签”（值 0）；选定一块后，出现浅色按钮“更换”（rodizio trocar_dia，带 data 和 relogio_id）。',
        'Modo de rodízio (um quadro que abre e fecha)' => '轮换模式（一个可展开和收起的框）',
        'Fechado: "Modo de rodízio" (cinza) e o nome do modo em negrito, "· <forma de escolha>" (na escala: "pela maior nota") e, à direita, o link "editar".' => '收起时：灰色“轮换模式”以及粗体的模式名称，“· <选择方式>”（在排班表中：“按最高分数”），右侧链接“编辑”。',
        'Aberto, em duas colunas: à esquerda a lista "Modo de rodízio" (os modos), a explicação do modo escolhido (escala: "Monta o plano do período inteiro de uma vez..."; sorteio: "Cada bloco de dias sorteia entre os relógios do grupo escolhido...") e os campos do modo escolhido: na escala, "Período" (Uma semana, Um mês, Dois meses, Meio ano, Um ano, Dois anos = 7, 30, 60, 180, 365, 730); para cada bloco, uma lista com o nome do bloco (grupos "Sortear entre": Todos e cada grupo com recuo pela profundidade; "Relógio fixo": cada relógio disponível) e, fora da escala, a caixa "sortear um por dia".' => '展开时，两列：左侧列表“轮换模式”（各模式）、所选模式的说明（排班表：“一次编排整个时段的计划……”；抽签：“每个日子区块在所选分组的手表之间抽签……”）以及所选模式的字段：在排班表中，“时段”（一周、一个月、两个月、半年、一年、两年 = 7、30、60、180、365、730）；每个区块一个列表，带区块名称（分组“在其中抽签”：全部以及每个分组按深度缩进；“固定手表”：每块可用的手表），不在排班表中时还有复选框“每天抽一块”。',
        'À direita: "Como escolher o relógio" (Inteligente; Inteligente com sorteio; Totalmente aleatório; Fila (FIFO)) com a explicação de cada uma (na escala, "Como escolher o relógio: pela maior nota"); "Garantia de rodízio: dias sem uso, no máximo" (número de 0 a 365; só nas formas inteligente, com sorteio e na escala) com "Quem passa do limite tem prioridade, o mais tempo parado primeiro. 0 desliga. O mesmo valor vale para todos os modos que usam a nota." e "A nota vem dos critérios, que você cadastra."' => '右侧：“如何选择手表”（智能；智能带抽签；完全随机；队列（FIFO））以及各自的说明（在排班表中，“如何选择手表：按最高分数”）；“轮换保障：未使用天数，最多”（0 到 365 的数字；仅智能、带抽签的方式以及排班表）以及“超过上限的优先，停得最久的在前。0 则关闭。同一值适用于所有使用分数的模式。”和“分数来自你登记的标准。”',
        'Botão "Aplicar modo" (rodizio modo), com a confirmação "Trocar o modo apaga o plano atual. Continuar?" (com o dia já começado: "Trocar o modo refaz o plano a partir de amanhã; hoje continua o <relógio>. Continuar?") e a nota sobre o histórico que continua e o link para Cadastros (os modos).' => '按钮“应用模式”（rodizio modo），确认“更换模式会删除当前计划。继续？”（当天已经开始时：“更换模式从明天起重做计划；今天继续是 <手表>。继续？”）以及关于历史会保留的说明和指向定义（各模式）的链接。',
        '"Sortear de novo": uma lista com as ações possíveis agora e o botão leve "Sortear": "a partir de amanhã" (resortear) e "inclusive hoje" (resortear_hoje) com o dia já começado no pulso, ou "a partir de hoje" (resortear); fora da escala, "a próxima semana (DD/MM a DD/MM)" (proxima_semana; só no domingo: nos outros dias a opção vem desativada com "— disponível no domingo"). Embaixo, a explicação da opção escolhida; cada uma tem a sua confirmação.' => '“重新抽签”：一个列表，含现在可以做的操作以及浅色按钮“抽签”：当天已经在手腕上开始时有“从明天起”（resortear）和“包括今天”（resortear_hoje），或“从今天起”（resortear）；不在排班表中时，“下一周（DD/MM 到 DD/MM）”（proxima_semana；仅星期日：其他日子该选项禁用并带“— 星期日可用”）。下方是所选选项的说明；每一个都有自己的确认。',
        'Rodízio manual: a última opção da lista "Modo de rodízio" (não é um modo: o modo de sempre continua valendo fora do período). Escolhida, a explicação diz "Você escolhe o relógio de cada dia de um período. Ponha o começo e o fim e clique em OK: os dias aparecem de 7 em 7, cada um com a lista dos relógios, "Decida por mim" (o sistema escolhe) e "Sem relógio (dia livre)". Fora do período, continua valendo o modo de rodízio de sempre (<modo>)."; somem a coluna da direita, o "Aplicar modo" com a nota e o "Sortear de novo"; aparece, abaixo de uma linha, o formulário do período: "De" (data, de hoje em diante, já com hoje), "Até" (data) e o botão "OK". O endereço index.php#manual abre o quadro já no Rodízio manual (o link da página Plano).' => '手动轮换：列表“轮换模式”的最后一项（它不是一个模式：时段之外仍然是原来的模式）。选中后，说明为“你为一个时段的每一天选择手表。填上开始和结束并点击确定：日子每 7 天出现，每一天带手表列表、“帮我决定”（由系统选择）和“无手表（空闲日）”。时段之外，仍然是原来的轮换模式（<模式>）。”；右侧一列、“应用模式”及其说明和“重新抽签”消失；一条线下方出现时段表单：“从”（日期，从今天起，已填今天）、“到”（日期）和按钮“确定”。地址 index.php#manual 打开已经位于手动轮换的框（计划页面的链接）。',
        'OK lê recurso=rodizio_manual (de, ate, pagina) e mostra a tabela compacta (até 46rem): Dia ("DD/MM" e o dia da semana por extenso, menor, com " · hoje"; o número em safira no fim de semana), No plano agora (o relógio com "à mão" ou "sorteado" pequeno em âmbar, "dia livre" ou "—" em cinza) e Relógio do dia (uma lista: "Decida por mim", o grupo "Relógios" com os disponíveis por nome e, menos hoje, "Sem relógio (dia livre)"; de partida, a escolha que a API manda). Mais de 7 dias: embaixo, os botões leves "‹ Anterior", os números das páginas (a 1, a última e até 2 de cada lado da atual, com "…" nos saltos; a atual em safira) e "Próxima ›"; cada um relê a API. O que se escolhe fica guardado na tela ao trocar de página. Embaixo, "Página N de M · <n> dias, de DD/MM/AAAA a DD/MM/AAAA. O que você escolhe fica guardado enquanto você anda pelas páginas; nada muda antes de gravar.", os botões "Gravar o rodízio manual" (rodizio manual com de, ate e dias[data] dos que você mudou; confirma "Gravar o rodízio manual de DD/MM/AAAA a DD/MM/AAAA? Os dias ficam com os relógios escolhidos; os de "Decida por mim" são decididos agora pelo sistema."); e as notas com o critério do Decida por mim (o texto da API) e "Para apagar o que um período tem (e sortear de novo, ou deixar os dias livres): "Apagar um período", embaixo deste quadro, ou na página Plano." (link). Recusado: o motivo em âmbar acima da tabela, e as escolhas ficam; gravado: o recado no alto da página e a página remontada.' => '确定读取 recurso=rodizio_manual（de、ate、pagina）并显示紧凑表格（最大 46rem）：日（“DD/MM”以及更小的星期几文字，带“ · 今天”；周末数字为蓝宝石色）、计划中现在（手表带琥珀色小字“手动”或“已抽签”，“空闲日”或灰色“—”）和当天的手表（一个列表：“帮我决定”、分组“手表”含按名称的可用手表，以及除今天外的“无手表（空闲日）”；初始为 API 所给的选择）。超过 7 天：下方浅色按钮“‹ 上一页”、页码（第 1 页、最后一页以及当前页两侧最多 2 页，跳跃处为“…”；当前页为蓝宝石色）和“下一页 ›”；每一个都重新读取 API。翻页时屏幕上的选择会保留。下方，“第 N 页，共 M 页 · <n> 天，从 DD/MM/AAAA 到 DD/MM/AAAA。你的选择在翻页期间保留；保存之前什么都不会改变。”，按钮“保存手动轮换”（rodizio manual，带 de、ate 以及你改过的 dias[data]；确认“保存从 DD/MM/AAAA 到 DD/MM/AAAA 的手动轮换？这些日子使用所选的手表；“帮我决定”的由系统现在决定。”）；以及带帮我决定标准的说明（API 的文本）和“要删除一个时段已有的内容（并重新抽签，或让日子空闲）：此框下方的“删除一个时段”，或在计划页面。”（链接）。被拒绝：事由以琥珀色出现在表格上方，选择保留；已保存：提示在页面顶部，页面重新组装。',
        'Abaixo do Sortear de novo, cada um abaixo de uma linha, os mesmos dois formulários da página Plano: "Apagar um período" e "Apagar tudo" (veja a página Plano).' => '在重新抽签的下方，各自在一条线下方，与计划页面相同的两个表单：“删除一个时段”和“全部删除”（见计划页面）。',
        'Relógios (a tabela da coleção)' => '手表（收藏的表格）',
        'Título "Relógios" com "<mostrados> de <total> relógios · <n> em uso" em cinza e, à direita, os botões "Limpar filtros" (leve) e "Novo relógio" (abre o cadastro no painel).' => '标题“手表”，灰色“<所显示的> / <总计> 块手表 · <n> 使用中”，右侧按钮“清除筛选”（浅色）和“新手表”（在面板中打开档案）。',
        '12 colunas, todas ordenáveis clicando no título (▲ ou ▼ ao lado; clicar de novo inverte; vazios sempre por último): Código, Relógio (miniatura e nome em negrito), Tipo, Estado (o estado_texto da API em etiqueta, na cor do estado: Em uso verde, a sessão aberta (No sol, No winder, No carregador) laranja, Em repouso vermelho, Indisponível cinza), Carga (barra e %, ou o texto de por que não tem), Última vez usado, Próxima manutenção (data ou "hoje"), Em (quanto falta; atrasado em vermelho negrito; atualizado a cada minuto), O que fazer (em âmbar negrito; o aviso de manutenção mais perto, sem o Encostado), Encostado (quanto falta para o limite de dias sem ir ao pulso, ou "atrasado …" em vermelho negrito quando já passou; "—" sem data; atualizado a cada minuto), Comprado em, Valor (à direita, "R$ 1.234,56").' => '12 列，点击标题都可排序（旁边 ▲ 或 ▼；再点一次反向；空的始终在最后）：编号、手表（缩略图和粗体名称）、类型、状态（API 的 estado_texto 作为标签，按状态的颜色：使用中绿色，已打开的时段（在晒太阳、在上链盒、在充电器）橙色，休息中红色，不可用灰色）、电量（条和 %，或为什么没有的文本）、最近一次使用、下次保养（日期或“今天”）、还差（还差多少；逾期为红色粗体；每分钟更新）、要做什么（琥珀色粗体；最近的保养提醒，不含闲置）、闲置（距离多少天没上手腕的上限还差多少，或已经过去时红色粗体“逾期 …”；无日期为“—”；每分钟更新）、购买于、金额（靠右，“R$ 1.234,56”）。',
        'Uma linha de filtros embaixo dos títulos: Código ("nº"), Relógio ("buscar" no nome), Tipo (os tipos que existem), Estado (Todos e os estados da API, na ordem: Em uso, cada sessão, Em repouso, Indisponível), Carga (Todas, ≤ 20%, ≤ 50%), Última vez usado (Todos, 7 dias, +7 dias, nunca), Próxima manutenção (Todas, até hoje, 7 dias, 30 dias), O que fazer (os avisos de manutenção, sem o Encostado), Encostado (Todos, Encostados, Dentro do prazo, sem data), Comprado em (Todas, 30 dias, 90 dias, este ano, sem data), Valor (Todos, ≤ 500, 500–1.500, > 1.500, sem valor). A ordem e os filtros ficam guardados na sessão do navegador.' => '标题下方一行筛选：编号（“号”）、手表（在名称中“搜索”）、类型（现有的类型）、状态（全部以及 API 的状态，按顺序：使用中、每个时段、休息中、不可用）、电量（全部、≤ 20%、≤ 50%）、最近一次使用（全部、7 天、+7 天、从未）、下次保养（全部、直到今天、7 天、30 天）、要做什么（保养提醒，不含闲置）、闲置（全部、闲置、期限内、无日期）、购买于（全部、30 天、90 天、今年、无日期）、金额（全部、≤ 500、500–1.500、> 1.500、无金额）。排序和筛选保存在浏览器会话中。',
        'Ordem inicial: os disponíveis primeiro (o de hoje, depois os com aviso), os indisponíveis no fim e em cinza. A linha do relógio de hoje tem a faixa safira à esquerda; a de um com aviso, a âmbar. Clicar numa linha (ou Enter nela) abre o relógio no painel. Rodapé: "Total dos relógios mostrados" e a soma dos valores, à direita. Sem relógios: "Nenhum relógio cadastrado. Use o botão Novo relógio."; com filtros que não deixam nenhum: "Nenhum relógio com esses filtros."' => '初始顺序：可用的在前（今天的，然后有提醒的），不可用的在末尾且为灰色。今天的手表那一行左侧有蓝宝石色条；有提醒的为琥珀色。点击一行（或在其上按 Enter）在面板中打开手表。页脚：“所显示手表的合计”以及金额之和，靠右。没有手表：“没有已登记的手表。请使用新手表按钮。”；筛选后一个都不剩：“没有符合这些筛选的手表。”',
        'Quando as 12 colunas não cabem na largura que a tabela tem: cada relógio vira um cartão, com a foto e o nome na linha de cima e embaixo os mesmos campos com o nome da coluna em cima, em colunas iguais (5; 2 no celular); os títulos viram botões "Ordenar por" e os filtros ficam todos, com o nome em cima.' => '当 12 列在表格现有宽度中放不下时：每块手表变成一张卡片，照片和名称在上面一行，下方是同样的字段，列名在上方，等宽列（5 列；手机上 2 列）；标题变成“排序依据”按钮，筛选全部保留，名称在上方。',
        'O painel do relógio (à direita, flutuante ou em tela cheia)' => '手表面板（在右侧、浮动或全屏）',
        'Um botão redondo "×" no canto (no celular "× Fechar") fecha o painel; Esc também. O endereço vira index.php?r=<id>.' => '角落一个圆形按钮“×”（手机上“× 关闭”）关闭面板；Esc 也可以。地址变为 index.php?r=<id>。',
        'Cabeça: a foto (ou "Sem foto"; com o mouse parado em cima, a dica relogio.dica_foto da API, em linhas: o nome, o grupo e o código; o estado e a carga; a nota e o próximo dia no rodízio; a compra; e "Duplo clique (ou "Abrir foto", embaixo): a foto em tamanho grande.") com os botões leves "Abrir foto" (só com foto: abre a foto ampliada), "Escolher foto" / "Trocar foto" (abre o seletor de arquivo; escolhida, aparece a prévia e o botão "Salvar foto": relogio foto) e, com foto, "Remover foto" (discreto; confirma "Remover a foto?"); ao lado "<tipo> · <caminho no grupo>" em cinza, o nome em h1, a observação, e as etiquetas: em uso/em repouso, "indisponível", "relógio de hoje" e, fora da coleção, a situação (etiqueta lilás: "desejado", "emprestado", "vendido", "arquivado"; no desejado, sem a etiqueta do estado).' => '头部：照片（或“无照片”；鼠标停在上面时，API 的 relogio.dica_foto 提示，分行：名称、分组和编号；状态和电量；分数以及下一次进入轮换的日期；购买；以及“双击（或下方的“打开照片”）：大尺寸照片。”），带浅色按钮“打开照片”（仅有照片时：打开放大的照片）、“选择照片”/“更换照片”（打开文件选择器；选定后出现预览和按钮“保存照片”：relogio foto），有照片时还有“移除照片”（低调；确认“移除照片？”）；旁边灰色“<类型> · <分组中的路径>”，名称作为 h1，备注，以及标签：使用中/休息中、“不可用”、“今天的手表”，以及离开收藏时的情况（淡紫色标签：“心愿中”、“已借出”、“已售出”、“已归档”；在心愿中时，没有状态标签）。',
        'Num relógio desejado, no lugar dos quadros abaixo (Agora, Previsão, Gasto, Autonomia, Rodízio, Compra, Manutenções, Marcar), só o quadro Desejo (pares: Marca, Referência, Preço-alvo "R$ ...", Prioridade, Link "abrir a página" numa aba nova; vazio: "—"; no rodapé "Comprou? Em "Editar cadastro", mude a situação para "Na coleção" e preencha a compra.") e o de Documentos; os quadros largos (Dados, Histórico) e o Editar cadastro continuam.' => '对于心愿中的手表，下面这些框（现在、预测、消耗、续航、轮换、购买、保养、标记）的位置只放心愿框（成对：品牌、型号、目标价格“R$ ...”、优先级、链接“打开页面”于新标签页；空：“—”；页脚“买了？在“编辑档案”中把情况改为“在收藏中”并填写购买。”）和文档框；宽框（数据、历史）和编辑档案仍然保留。',
        'Os quadros, numa grade (lado a lado onde cabem): Agora (pares: Estado ("No carregador desde 06:30", na cor do estado); Carga com a barra e "~68%" e de onde vem; Encostado (a falta, em vermelho negrito se já passou do limite de dias sem ir ao pulso; só quando há data); Situação, uma linha por item; Última leitura); Previsão (só nos que têm leitura: as frases da API, ou "Informe a carga atual para o sistema começar a prever."; embaixo, "De onde vem a conta" (título pequeno em maiúsculas cinza) e a tabela da previsao.conta, uma linha por número: o nome (e, menor, embaixo, o detalhe de como o gasto foi medido), o valor (com a unidade menor embaixo; "—" se vazio, a linha em cinza) e a origem em etiqueta: informado azul, padrão âmbar, medido verde, vazio cinza); Gasto da bateria (No pulso, Fora do pulso: o que vale "% por dia" e embaixo se é medido ou do cadastro; Janela anterior; Medições; no rodapé "Medições mais velhas que a janela saem da conta..."); Autonomia (Cheio, pelo cadastro; Cheio, pela conta; Acaba, seguindo o plano (data e hora, e "em <duração>"); No pulso sem tirar; Guardado; sem dado, o motivo em cinza); Rodízio (Nota com o link "ver a conta" (Critérios, numa aba nova); Critérios de; Próxima vez; no rodapé o botão leve "Usando hoje" (rodizio usando, com confirmação), se ele está disponível e não é o de hoje); Compra (Valor pago, Loja, Comprado em com "há N dias", Garantia "até" ou "vencida em"; sem nada: "Sem dados da compra. Preencha em "Editar cadastro"."); Compra também com "Custo por uso" ("R$ 100,00" em negrito e "3 dias de uso" embaixo; sem: "sem o valor pago" ou "ainda não foi ao pulso" em cinza) e o "há N dias" da compra vindo da API (compra.ha_dias). Documentos (cada categoria com "N arquivos", link para a página Documentos numa aba nova; o botão "Enviar documentos" ou "Abrir os documentos"); Próximas manutenções (data em negrito e o nome; ou "Nada previsto."). Depois de Documentos, Acessórios (pares: o tipo e o nome, com a observação menor embaixo; sem nenhum, "Nenhum: a pulseira extra, a caixa, o estojo, a ferramenta..."; o botão leve "Cadastrar acessórios" ou "Ver os acessórios", que abre acessorios.php?relogio=<id> numa aba nova). No rodapé de Documentos, ao lado do botão dele, o botão leve "Passaporte" (passaporte.php?id=<id> numa aba nova).' => '各框排成网格（能并排就并排）：现在（成对：状态（“在充电器中，自 06:30”，按状态的颜色）；电量带条和“~68%”以及来源；闲置（还差多少，若已超过多少天没上手腕的上限则为红色粗体；仅当有日期时）；情况，每项一行；最近一次读数）；预测（仅带读数的：API 的句子，或“请填写当前电量，系统才能开始预测。”；下方，“计算从何而来”（灰色大写小标题）以及 previsao.conta 的表，每个数字一行：名称（以及更小的、在下方的消耗如何测得的细节）、值（单位更小地在下方；空则为“—”，该行灰色）以及来源标签：已填写蓝色、默认琥珀色、实测绿色、空灰色）；电池消耗（在手腕上、离开手腕：有效的“每天 %”以及下方是实测还是来自档案；前一窗口；测量；页脚“比窗口更旧的测量退出计算……”）；续航（满电量，按档案；满电量，按计算；耗尽，按计划（日期和时间，以及“还有 <时长>”）；戴在手腕上不摘下；静止存放；无数据时，原因用灰色）；轮换（分数带链接“查看计算”（标准，新标签页）；标准来自；下一次；页脚有浅色按钮“今天正在使用”（rodizio usando，带确认），若它可用且不是今天的）；购买（已付金额、商店、购买于带“N 天前”、保修“至”或“已于……到期”；什么都没有：“没有购买数据。请在“编辑档案”中填写。”）；购买还带“每次使用成本”（“R$ 100,00”粗体，下方“3 天使用”；没有时：“没有已付金额”或“还没上过手腕”，灰色）以及购买的“N 天前”来自 API（compra.ha_dias）。文档（每个类别带“N 个文件”，链接到文档页面的新标签页；按钮“上传文档”或“打开文档”）；各项下次保养（日期粗体和名称；或“没有预计的。”）。文档之后，配件（成对：类型和名称，备注更小地在下方；一个都没有，“没有：备用表带、表盒、收纳盒、工具……”；浅色按钮“登记配件”或“查看配件”，在新标签页打开 acessorios.php?relogio=<id>）。在文档的页脚，其按钮旁边，浅色按钮“护照”（在新标签页打开 passaporte.php?id=<id>）。',
        'Marcar (um quadro na largura toda): "O que você quer marcar?" com uma lista em grupos: "Agora, ou numa hora que você disser" (cada sessão como verbo: "Pôr no sol" / "Tirar do sol" conforme está aberta; cada tipo com valor pelo nome; cada instantâneo pelo nome), "Algo que já passou" ("Um período que já passou (<sessões>)") e "Corrigir" ("Corrigir ou excluir uma marcação (últimos 14 dias)"). Escolhido um, aparecem só os campos dele: sessão: o estado aberto e "Pôs às" / "Tirou às" (data e hora, "Anda com o relógio até você mudar (vazio: agora).") e o botão com o verbo; com valor: "Agora em uso/em repouso" e a estimativa, "Leitura" (com a unidade), "Lida às", a caixa "Atualizar o gasto com esta medição" (marcada; só nos tipos que medem o gasto) e "Informar <nome>"; instantâneo: "Quando" e "Marcar <nome>"; período: "Onde" (se houver mais de uma sessão), "De" (uma hora atrás) e "Até" (agora) e "Registrar o período"; corrigir: "Qual marcação" ("DD/MM HH:MM · nome até HH:MM", "(aberta)", ": 68 %", "(rodízio)") e os campos dela com "Salvar" e "Excluir" (confirma). Nada pode ser no futuro. Os campos de data e hora andam com o relógio do navegador: "Pôs às", "Tirou às", "Lida às", "Quando" e o "Até" do período vêm com a hora de agora e acompanham o relógio (a cada 15 s e ao clicar no campo) até a pessoa mexer, e daí ficam no que ela pôs; sem mexer, "Pôs às", "Tirou às", "Lida às" e "Quando" vão vazios (a API usa o agora dela, com os segundos) e o "Até" vai com o minuto de agora; o máximo de todos (nada no futuro) também anda.' => '标记（占整行的一个框）：“你想标记什么？”带一个分组列表：“现在，或你指定的一个时间”（每个时段用动词：“晒太阳”/“结束晒太阳”，视是否已打开；每个带值的类型用名称；每个瞬时的用名称）、“已经过去的事”（“一段已经过去的时段（<各时段>）”）和“更正”（“更正或删除一次标记（最近 14 天）”）。选定一个后，只出现它的字段：时段：已打开的状态以及“戴上于”/“摘下于”（日期和时间，“在你修改之前随手表走（空：现在）。”）和带动词的按钮；带值：“现在使用中/休息中”和估计，“读数”（带单位），“读于”，复选框“用这次测量更新消耗”（已勾选；仅测量消耗的类型）和“填写<名称>”；瞬时：“何时”和“标记<名称>”；时段段：“在哪里”（若有不止一个时段）、“从”（一小时前）和“到”（现在）以及“登记该时段”；更正：“哪一次标记”（“DD/MM HH:MM · 名称直到 HH:MM”、“（已打开）”、“：68 %”、“（轮换）”）以及它的字段，带“保存”和“删除”（确认）。不能是将来。日期和时间字段随浏览器的时钟走：“戴上于”、“摘下于”、“读于”、“何时”和时段的“到”带上现在的时间，并跟随时钟（每 15 秒以及点击字段时），直到人去改，然后停在他所填的值上；不改的话，“戴上于”、“摘下于”、“读于”和“何时”发送为空（API 用它自己的现在，含秒），“到”发送现在的分钟；所有字段的最大值（不能是将来）也跟着走。',
        'Editar cadastro (um quadro que abre e fecha; no relógio novo, já aberto com o título "Novo relógio"): Nome (obrigatório); Grupo ("(na raiz)" e cada grupo pelo caminho, com a nota "os campos, os lançamentos e os critérios de um grupo valem para tudo abaixo dele"); depois os campos do cadastro, só os que valem para o grupo escolhido (mudar o grupo mostra e esconde na hora): sim/não como caixa; lista como menu (com "—"); data como campo de data; texto como campo; número como campo decimal, com o padrão de dica ("vazio: 5"); a Compra num grupo com título (Data da compra, Valor pago, Onde comprou, Garantia até); a Observação; no novo, a Foto; "Situação na coleção" (menu: Na coleção, Desejado, Emprestado, Vendido, Arquivado; no novo, a do endereço, index.php?novo=1&posse=desejado, senão Na coleção; os campos só nos desejados, como o Preço-alvo e a Prioridade, aparecem só com Desejado, e a caixa do disponível só com Na coleção, na hora); "Disponível para o rodízio" (marcada no novo); "Guardar no banco a cópia de todos os documentos dele" (só quando o config.php não decide); botão "Cadastrar relógio" ou "Salvar alterações" (relogio salvar). Embaixo, "Excluir este relógio" (discreto; confirma "Excluir <nome> com todo o histórico e a foto?").' => '编辑档案（一个可展开和收起的框；新手表时已经打开，标题“新手表”）：名称（必填）；分组（“（在根）”以及每个分组的路径，说明“一个分组的字段、记录和标准对其下的全部有效”）；然后是档案字段，只含对所选分组有效的（更换分组会立即显示和隐藏）：是/否为复选框；列表为菜单（带“—”）；日期为日期字段；文本为字段；数字为小数字段，提示中有默认值（“空：5”）；购买在一个带标题的组中（购买日期、已付金额、在哪里购买、保修至）；备注；新建时的照片；“在收藏中的情况”（菜单：在收藏中、心愿中、已借出、已售出、已归档；新建时用地址中的，index.php?novo=1&posse=desejado，否则为在收藏中；仅用于心愿的字段，如目标价格和优先级，只在心愿中时出现，可用复选框只在在收藏中时立即出现）；“可用于轮换”（新建时已勾选）；“在数据库中保存其全部文档的副本”（仅当 config.php 不决定时）；按钮“登记手表”或“保存更改”（relogio salvar）。下方，“删除这块手表”（低调；确认“删除 <名称> 及其全部历史和照片？”）。',
        'Carga ao longo do tempo (largo; nos que têm leitura): um gráfico de linha das leituras (eixo de 0 a 100%, guias em 0, 50 e 100%, pontos verdes em uso e vermelhos em repouso, a linha em safira), com a legenda em pares rótulo/valor, menores (Pontos: as bolinhas "leitura em uso" e "leitura em repouso"; Período: "DD/MM a DD/MM"; Escala: "de 0 a 100%"; A conta: "de onde vem cada número: no quadro Previsão"); com menos de duas leituras, "O gráfico aparece a partir de duas leituras de carga." Embaixo, "Medições do gasto" (no quadro estreito, até 40rem, como no painel ao lado: cada medição vira um cartão, a data em negrito e embaixo cada valor com o nome da coluna em maiúsculas cinza na frente): tabela Quando, Leituras ("89 → 75"), Horas ("14 h no pulso, 2 h fora"), Gasto medido ("% por dia de uso" ou "fora do pulso"), Na conta (sim; não (fora da janela); não (só histórico)), as 10 mais recentes.' => '电量随时间变化（宽；带读数的）：读数的折线图（轴 0 到 100%，参考线在 0、50 和 100%，使用中的点为绿色、休息中的点为红色，线为蓝宝石色），图例为更小的标签/值成对（点：圆点“使用中的读数”和“休息中的读数”；时段：“DD/MM 到 DD/MM”；刻度：“从 0 到 100%”；计算：“每个数字从何而来：在预测框中”）；少于两次读数时，“从两次电量读数起显示图表。”下方，“消耗测量”（在窄框中，到 40rem，如旁边的面板：每次测量变成一张卡片，日期粗体，下方每个值前面是灰色大写的列名）：表格 何时、读数（“89 → 75”）、小时（“14 h 在手腕上，2 h 在外”）、实测消耗（“每个使用日的 %”或“离开手腕”）、计入计算（是；否（在窗口外）；否（只在历史中）），最近 10 次。',
        'Dados do relógio (largo): duas tabelas lado a lado (o valor numérico, a data e o sim/não numa linha só; o valor de texto, como a observação ou uma fórmula que dá texto, quebra a linha dentro da coluna, sem invadir a tabela do lado): Cadastro (Campo, Valor, Origem com a etiqueta informado/padrão/vazio) e Calculado agora (Fórmula com o identificador em código, Valor com a unidade (segundos por extenso), Versão).' => '手表数据（宽）：两张表并排（数字值、日期和是/否占一行；文本值，如备注或给出文本的公式，在列内换行，不侵入旁边的表）：档案（字段、值、来源，标签为已填写/默认/空）和现在算出的（公式，标识符用代码字体，值带单位（秒用文字），版本）。',
        'Histórico (largo): "<n> registros desde DD/MM/AAAA HH:MM. Agora <estado> há <duração>." e a tabela das 5 linhas mais recentes (Quando com "até ..." embaixo, Duração, Estado em etiqueta ou o texto da marcação) e o botão leve "Abrir o histórico completo" (historico.php numa aba nova).' => '历史（宽）：“<n> 条记录，自 DD/MM/AAAA HH:MM。现在 <状态> 已 <时长>。”以及最近 5 行的表（何时，下方“直到 ……”、时长、状态标签或标记的文本）和浅色按钮“打开完整历史”（historico.php，新标签页）。',
        'Depois de gravar no painel, o recado aparece no topo do painel e a página e o painel se remontam sem perder os quadros abertos nem a rolagem; excluir o relógio recarrega a página.' => '在面板中保存之后，提示出现在面板顶部，页面和面板重新组装，不丢失已打开的框也不丢失滚动位置；删除手表会重新加载页面。',
        'Ficha do relógio' => '手表档案',
        'ficha.php?id=<id> (sem id: o primeiro)' => 'ficha.php?id=<id>（无 id：第一块）',
        'recurso=hoje (a lista)' => 'recurso=hoje（列表）',
        'as mesmas do painel do relógio' => '与手表面板相同的那些',
        'Escolha e painel' => '选择和面板',
        'No alto, "Relógio" e uma lista com todos (os disponíveis primeiro, o estado entre parênteses nos outros: "(indisponível)", "(emprestado)"); havendo relógios fora da coleção, a lista vem em dois grupos, "Na coleção" e "Fora da coleção" (cada um com a situação: "(desejado)", "(vendido)", "(arquivado)"); trocar abre o escolhido. Embaixo, o mesmo painel do relógio da página Hoje, numa página própria de até 72rem, com os quadros lado a lado e sem o ×. Sem relógios: "Nenhum relógio cadastrado. Cadastre o primeiro." (link para index.php?novo=1).' => '顶部，“手表”以及包含全部的列表（可用的在前，其他的状态在括号中：“（不可用）”、“（已借出）”）；若有收藏之外的手表，列表分成两组，“在收藏中”和“收藏之外”（各自带情况：“（心愿中）”、“（已售出）”、“（已归档）”）；更换即打开所选的。下方，与今天页面相同的手表面板，在自己的页面上，最大 72rem，各框并排，没有 ×。没有手表：“没有已登记的手表。请登记第一块。”（链接到 index.php?novo=1）。',
        'relogio: salvar (id e posse=colecao: o Comprei e o Voltar para a coleção)' => 'relogio：salvar（id 且 posse=colecao：我买了，以及回到收藏）',
        'Lista de desejos' => '心愿单',
        'h1 "Lista de desejos" com o botão "Novo desejo" à direita (index.php?novo=1&posse=desejado: o cadastro de um relógio novo já como Desejado). A nota: sem desejados, como um relógio entra na lista ("Novo desejo" ou a "Situação na coleção" do cadastro) e que ele não entra no rodízio nem nos avisos; com desejados, "<n> relógios desejados, a prioridade mais alta primeiro. Somando os preços-alvo: R$ <total> (<n> sem preço-alvo). Comprou? ...".' => 'h1“心愿单”，右侧按钮“新心愿”（index.php?novo=1&posse=desejado：新手表的档案，已经是心愿中）。说明：没有心愿时，一块手表如何进入列表（“新心愿”或档案的“在收藏中的情况”），以及它不进入轮换也不进入提醒；有心愿时，“<n> 块心愿中的手表，优先级最高的在前。目标价格合计：R$ <总计>（<n> 块没有目标价格）。买了？……”。',
        'Tabela (vira fichas até 900px) Relógio (a miniatura, o nome com o link da ficha e, embaixo, menor, "marca · referência"), Prioridade, Preço-alvo ("R$ 1.234,56" ou —), Grupo (o caminho; — na raiz), Link ("abrir a página" numa aba nova, só para http:// e https://; outro texto, como está; —) e o botão leve "Comprei" (confirma "Comprou o <nome>? Ele entra na coleção, disponível para o rodízio, e a ficha dele abre para você preencher a compra."; gravado, abre ficha.php?id=<id>).' => '表格（到 900px 变成卡片）手表（缩略图，名称带详情链接，下方更小的“品牌 · 型号”）、优先级、目标价格（“R$ 1.234,56”或 —）、分组（路径；在根为 —）、链接（“打开页面”于新标签页，仅 http:// 和 https://；其他文本原样；—）以及浅色按钮“我买了”（确认“买了 <名称>？它进入收藏，可用于轮换，并打开它的详情供你填写购买。”；保存后打开 ficha.php?id=<id>）。',
        'Fora da coleção' => '收藏之外',
        'h2 "Fora da coleção", a nota (fora do rodízio, do plano e dos avisos; o emprestado continua na tabela da página Hoje e no valor da coleção; a ficha, os documentos e o histórico ficam) e a tabela Relógio (miniatura e nome), Situação (etiqueta lilás: emprestado, vendido, arquivado), Grupo e o botão leve "Voltar para a coleção" (confirma; gravado, abre a ficha).' => 'h2“收藏之外”，说明（在轮换、计划和提醒之外；已借出的仍在今天页面的表格中和收藏金额中；详情、文档和历史保留）以及表格 手表（缩略图和名称）、情况（淡紫色标签：已借出、已售出、已归档）、分组和浅色按钮“回到收藏”（确认；保存后打开详情）。',
        'Na página Hoje, ao lado do "Novo relógio", o botão leve "Desejos (<n>) · Fora da coleção (<n>)" (só as partes que têm algum; sem nenhum, o botão some) leva a esta página.' => '在今天页面，“新手表”旁边，浅色按钮“心愿单（<n>）· 收藏之外（<n>）”（只含有内容的部分；一个都没有则按钮消失）通往此页面。',
        'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD (de=tudo: desde o primeiro uso; sem nada: os últimos 90 dias)' => 'estatisticas.php?de=AAAA-MM-DD&ate=AAAA-MM-DD（de=tudo：从第一次使用起；什么都不传：最近 90 天）',
        'Período e resumo' => '时段和摘要',
        'h1 "Estatísticas" com "de DD/MM/AAAA a DD/MM/AAAA · N dias" em cinza à direita. Filtro num cartão: De, Até (máximo hoje), "Ver" e os atalhos 30 dias, 90 dias, 1 ano, desde o começo.' => 'h1“统计”，右侧灰色“从 DD/MM/AAAA 到 DD/MM/AAAA · N 天”。卡片中的筛选：从、到（最晚今天）、“查看”以及快捷方式 30 天、90 天、1 年、从一开始。',
        'Quatro caixas (duas por linha até 900px): "<n>" dias com relógio no pulso (de <dias>); "<h> h" no pulso · <h> h por dia com relógio; "<usados> de <coleção>" relógios usados · <n> sem uso; "R$ <custo médio>" custo por uso, em média · coleção: R$ <valor>. Embaixo, "Mais usado: <link> (<h> h, <n> dias). Menos usado (dos que foram ao pulso): <link> (<h> h)."' => '四个盒子（到 900px 每行两个）：“<n>”天有手表在手腕上（共 <天数>）；“<h> h”在手腕上 · 有手表的每天 <h> h；“<用过的> / <收藏>”块手表用过 · <n> 未使用；“R$ <平均成本>”平均每次使用成本 · 收藏：R$ <金额>。下方，“使用最多：<链接>（<h> h，<n> 天）。使用最少（上过手腕的之中）：<链接>（<h> h）。”',
        'Cada relógio' => '每块手表',
        'Cartão com a nota do que cada coluna é e a tabela (fichas até 900px) Relógio (o link da ficha e, embaixo, menor, o grupo e a situação fora da coleção), Dias de uso, Horas ("12,5 h"), A parte (a barra horizontal safira com a largura relogios[].barra e "56,8%"), Custo por uso ("R$ 83,30" ou —), Sem uso há ("3 dias", "usado hoje", "nunca usado"), Tendência ("↑ usando mais" em verde, "↓ usando menos" em vermelho, "→ estável", "· poucos dados" em cinza; a dica com as horas de cada metade).' => '卡片，说明每一列是什么，以及表格（到 900px 为卡片）手表（详情链接，下方更小的分组和收藏之外的情况）、使用天数、小时（“12,5 h”）、占比（蓝宝石色水平条，宽度为 relogios[].barra，以及“56,8%”）、每次使用成本（“R$ 83,30”或 —）、多久未使用（“3 天”、“今天用过”、“从未使用”）、趋势（绿色“↑ 用得更多”、红色“↓ 用得更少”、“→ 稳定”、灰色“· 数据很少”；提示中有每一半的小时数）。',
        'Gráficos' => '图表',
        'Dois cartões lado a lado (um embaixo do outro até 900px): Por dia da semana e Por mês, cada um um gráfico de barras verticais em SVG (largura 100%, as barras safira com a altura da barra da API, o valor "14 h" em cima de cada uma quando são até 8, os rótulos embaixo: seg...dom, set/26..., no máximo uns 7 rótulos) e a nota com os números (a média por dia de cada dia da semana; as horas e quantos relógios em cada mês).' => '两张卡片并排（到 900px 上下排列）：按星期几和按月，各自是 SVG 垂直柱状图（宽度 100%，蓝宝石色柱，高度为 API 的柱高，不超过 8 根时每根上方有值“14 h”，下方标签：seg...dom、set/26...，最多大约 7 个标签）以及带数字的说明（每个星期几的日均；每个月的小时数和多少块手表）。',
        'A coleção' => '收藏',
        'Cartão com a nota e as divisões em grade (lado a lado onde cabem, cada uma com pelo menos 22rem): h3 com o título e a tabela nome, "<n> relógios", a barra com a porcentagem e as horas; numa divisão estreita (até 26rem), cada linha em duas: o nome em negrito em cima e os números embaixo.' => '卡片，带说明，以及网格中的划分（能并排就并排，每个至少 22rem）：h3 标题和表格 名称、“<n> 块手表”、带百分比的条和小时数；窄的划分（到 26rem）中，每行分成两行：名称粗体在上，数字在下。',
        'recurso=hora_certa (ao abrir e a cada minuto)' => 'recurso=hora_certa（打开时以及每分钟）',
        'O relógio' => '手表',
        'h1 "Hora certa" com "<fuso> · UTC<deslocamento>" em cinza. Um cartão com o mostrador em SVG (até 15rem: caixa branca de borda escura, 60 marcas, as das horas grossas; ponteiros das horas e dos minutos escuros e arredondados, o dos segundos vermelho fino, o eixo vermelho) e ao lado (embaixo, no celular) a hora digital grande (HH:MM:SS, números de largura fixa), a data por extenso, a hora UTC em cinza e a nota "O relógio deste aparelho está certo (menos de meio segundo de diferença)." ou "... está <n> s adiantado/atrasado." e de onde vem a hora.' => 'h1“准确时间”，灰色“<时区> · UTC<偏移>”。一张卡片，带 SVG 表盘（最大 15rem：白底深色边框的盒子，60 个刻度，整点的较粗；时针和分针深色圆头，秒针细红色，轴红色），旁边（手机上在下方）大号数字时间（HH:MM:SS，等宽数字）、日期的文字、灰色的 UTC 时间，以及说明“这台设备的手表是准的（相差不到半秒）。”或“……快/慢 <n> 秒。”以及时间从何而来。',
        'O relógio da página: a diferença é agora_ms menos o meio do pedido (antes e depois); a cada virada de segundo do relógio acertado, os ponteiros e a hora digital andam (no fuso.segundos da API); a cada minuto, lê a API de novo.' => '页面上的手表：差值是 agora_ms 减去请求的中点（前后）；对好的手表每过一秒，指针和数字时间走动（按 API 的 fuso.segundos）；每分钟重新读取 API。',
        'Os quadros' => '各框',
        'Três cartões lado a lado (um embaixo do outro até 900px), com pares rótulo/valor: Fuso e UTC (Fuso com a abreviação, Deslocamento, UTC (Zulu), Letra militar "P (Papa)", Grupo data-hora local e Zulu em código, ISO 8601), Calendário (Hoje, Dia do ano "286 de 365 · faltam 79", Semana (ISO), Trimestre, Dia juliano, Unix) e Lua (Fase com o símbolo, Idade, Iluminada, Próxima cheia, Próxima nova e a nota do ciclo médio). Embaixo, o cartão Como acertar com o texto da API.' => '三张卡片并排（到 900px 上下排列），标签/值成对：时区和 UTC（时区带缩写、偏移、UTC（Zulu）、军用字母“P（Papa）”、本地和 Zulu 的日期时间组用代码、ISO 8601）、日历（今天、年中第几天“365 天中的第 286 天 · 还差 79”、周（ISO）、季度、儒略日、Unix）和月亮（月相带符号、月龄、被照亮、下次满月、下次新月以及平均周期的说明）。下方，如何对时的卡片，带 API 的文本。',
        'acessorios.php?relogio=<id> (0: os soltos; sem ele: todos)&editar=<id do acessório>' => 'acessorios.php?relogio=<id>（0：未绑定的；不传：全部）&editar=<配件的 id>',
        'recurso=acessorios (com relogio)' => 'recurso=acessorios（带 relogio）',
        'acessorios: salvar, excluir' => 'acessorios：salvar、excluir',
        'Lista e cadastro' => '列表和档案',
        'h1 "Acessórios" com "<n> acessórios [do <relógio> | soltos] · 1 pulseira, 2 caixas..." em cinza. Um cartão com o filtro Relógio (Todos, Soltos (de nenhum relógio) e cada relógio; trocar abre o filtrado).' => 'h1“配件”，灰色“<n> 个配件 [属于 <手表> | 未绑定] · 1 条表带、2 个表盒……”。一张卡片，带手表筛选（全部、未绑定（不属于任何手表）以及每块手表；更换即打开筛选结果）。',
        'Tabela (fichas até 900px) Acessório, Tipo, Relógio (o link da ficha, ou "solto" em cinza), Observação (cinza; —) e as ações Editar (link: editar=<id>#form) e Excluir (botão leve discreto; confirma "Excluir o acessório <nome>?"). Vazia: "Nenhum acessório. Cadastre abaixo."' => '表格（到 900px 为卡片）配件、类型、手表（详情链接，或灰色“未绑定”）、备注（灰色；—）以及操作 编辑（链接：editar=<id>#form）和删除（低调浅色按钮；确认“删除配件 <名称>？”）。空：“没有配件。请在下方登记。”',
        'Cartão Novo acessório (ou "Alterar <nome>", que a página rola até ele), em grade: Nome (obrigatório, até 120, a dica "Pulseira de couro marrom"), Tipo (Pulseira, Caixa, Estojo, Ferramenta, Carregador, Peça, Outro), Relógio ("— solto (serve a vários) —" e cada relógio; no novo, o do filtro), Observação (texto, até 1000) e "Cadastrar" ou "Salvar" e "cancelar". Gravou: volta à lista, com o mesmo filtro; recusou: o alerta com os erros.' => '卡片 新配件（或“修改 <名称>”，页面会滚到它），网格：名称（必填，最多 120，提示“棕色皮革表带”）、类型（表带、表盒、收纳盒、工具、充电器、零件、其他）、手表（“— 未绑定（可供多块使用）—”以及每块手表；新建时用筛选中的）、备注（文本，最多 1000）以及“登记”或“保存”和“取消”。已保存：回到列表，保持同一筛选；被拒绝：带错误的警报。',
        'galeria.php (posse=todos: também os de fora da coleção)' => 'galeria.php（posse=todos：也包括收藏之外的）',
        'Fotos por grupo' => '按分组的照片',
        'Uma barra com o botão "Imprimir" (window.print) e o leve "Também os de fora da coleção" / "Só a coleção". h1 "Galeria" com "<n> relógios · R$ <valor> · <n> com foto" em cinza. Um cartão por grupo (h2 com o caminho) com a grade das fotos (colunas de pelo menos 9rem: duas no celular): a foto quadrada (ou o quadrado "Sem foto"), com o link da ficha, e embaixo o nome em negrito, "marca · referência" e, menor, "ano · R$ valor · <n> dias de uso" em cinza, e a etiqueta lilás da situação fora da coleção. No pé, "Gerado em ... pelo Relojoeiro." No papel (@media print): sem o menu e sem a barra, fundo branco, quatro fotos por linha, nenhuma partida entre páginas.' => '一条栏，带按钮“打印”（window.print）和浅色“也包括收藏之外的”/“只看收藏”。h1“图库”，灰色“<n> 块手表 · R$ <金额> · <n> 块有照片”。每个分组一张卡片（h2 为路径），照片网格（列至少 9rem：手机上两列）：正方形照片（或“无照片”方块），带详情链接，下方粗体名称、“品牌 · 型号”，以及更小的灰色“年份 · R$ 金额 · <n> 天使用”，还有收藏之外情况的淡紫色标签。页脚，“由 Relojoeiro 于 …… 生成。”在纸上（@media print）：没有菜单也没有栏，白底，每行四张照片，不在页面之间被拆开。',
        'Passaporte do relógio' => '手表护照',
        'A ficha para imprimir' => '供打印的详情',
        'Uma barra com "Imprimir", o leve "Voltar para a ficha" e a nota de que no papel saem só os dados. A cabeça: a foto (9rem), "Passaporte do relógio · código N", o nome em h1, "marca · referência · caminho", a situação ("Na coleção · no rodízio · no sistema desde DD/MM/AAAA") e a observação.' => '一条栏，带“打印”、浅色“回到详情”以及说明纸上只输出数据。头部：照片（9rem）、“手表护照 · 编号 N”、名称作为 h1、“品牌 · 型号 · 路径”、情况（“在收藏中 · 在轮换中 · 自 DD/MM/AAAA 进入系统”）和备注。',
        'Cartões (largura até 60rem; os pares lado a lado onde cabem, um embaixo do outro até 700px): Compra e Uso; Cadastro (os valores já em texto); Manutenções (cada tipo: "<n> vezes · a última em DD/MM/AAAA", e a lista das revisões e trocas de pilha); Acessórios e Documentos; Próximos avisos. Vazios: "Sem dados da compra.", "Ainda não foi ao pulso.", "Nada preenchido.", "Nenhuma marcação.", "Nenhum." No pé, "Gerado em ...". No papel: só os cartões, nenhum partido entre páginas.' => '卡片（宽度最大 60rem；成对的能并排就并排，到 700px 则上下排列）：购买和使用；档案（值已经是文本）；保养（每种类型：“<n> 次 · 最近一次于 DD/MM/AAAA”，以及检修和更换电池的列表）；配件和文档；即将到来的提醒。空：“没有购买数据。”、“还没上过手腕。”、“什么都没填。”、“没有任何标记。”、“没有。”页脚，“生成于 ……”。在纸上：只有卡片，不在页面之间被拆开。',
        'recurso=plano (com dias=30, 90, 365, 730 ou todos; pagina e relogio)' => 'recurso=plano（dias=30、90、365、730 或 todos；pagina 与 relogio）',
        'rodizio: trocar_dia, periodo_sortear, periodo_livre, apagar_tudo' => 'rodizio：trocar_dia、periodo_sortear、periodo_livre、apagar_tudo',
        'Cabeça e filtros' => '页眉与筛选',
        'h1 "Plano" e a nota "Modo: <modo> · a escala vai até DD/MM/AAAA · o plano gravado vai até DD/MM/AAAA. Troque o relógio de qualquer dia em "trocar por…": o dia fica escolhido à mão (e a escala é refeita a partir dele)." Filtros lado a lado: Período (Próximos 30 dias, Próximos 90 dias (o padrão), Próximo ano, Próximos 2 anos, Tudo; trocar relê a API) e Relógio (Todos e cada um; filtra o dia a dia na tela).' => 'h1“计划”，以及说明“模式：<modo> · 排班表延伸至 DD/MM/AAAA · 已保存的计划延伸至 DD/MM/AAAA。在“换成……”中更换任意一天的手表：该日即变为手动选定（并从该日起重做排班表）。”并排筛选：时段（接下来 30 天、接下来 90 天（默认）、下一年、接下来 2 年、全部；更换会重新读取 API）和手表（全部以及每一只；在屏幕上筛选逐日列表）。',
        'O período à mão' => '手动时段',
        'Uma nota: "Para escolher os relógios de um período, dia a dia: na página Hoje, no quadro Modo de rodízio, escolha "Rodízio manual". Para apagar a programação, veja o fim desta página." (o link Hoje vai para index.php#manual).' => '一条说明：“要逐日选择某一时段的手表：在今天页面的轮换模式框中，选择“手动轮换”。要清除安排，请看本页末尾。”（“今天”链接指向 index.php#manual）。',
        'Resumo do período (<n> dias)' => '时段摘要（<n> 天）',
        'Tabela Relógio, Dias, %, Próximo dia ("DD/MM/AAAA seg"), À mão; do que tem mais dias ao que tem menos. Embaixo, "Sem nenhum dia no período: <relógios>." Sem dias: "Nenhum dia no plano neste período."' => '表格：手表、天数、%、下一天（“DD/MM/AAAA seg”）、手动；从天数最多排到最少。下方，“本时段没有任何一天：<各手表>。”没有天数时：“本时段的计划中没有任何一天。”',
        'Dia a dia' => '逐日',
        'Os dias livres (livres, da API) entram entre os do plano, na ordem das datas: no lugar do relógio, "livre: escolha à mão" em cinza com a marca "livre", e a lista do dia começa em "escolher…" (com "↺ voltar a sortear"). Um título por mês ("Outubro de 2026") e uma tabela de dias: o dia ("DD/MM" e o dia da semana, "hoje" no de hoje, com a faixa safira), o relógio (com "à mão" e o motivo embaixo), o lembrete e o "trocar por…" (como na página Hoje). Fim de semana com fundo cinza claro. Sem dias: "Neste modo o sorteio é feito semana a semana: o plano tem só a semana atual." ou "Nenhum dia." Os dias vêm da API (plano.dia_a_dia, com pagina e relogio: o filtro de relógio relê a API), de "Mostrar até" em "Mostrar até" (a Configuração, padrão 31); passando disso, o navegador de páginas embaixo (cada página relê a API e rola até o dia a dia) e "Página N de M · <total> dias, <n> por página (o "Mostrar até" da Configuração)."' => '空闲日（livres，来自 API）按日期顺序插入计划日之间：手表的位置是灰色的“空闲：请手动选择”，并带“livre”标记，当天的列表从“选择……”开始（带“↺ 重新抽签”）。每月一个标题（“2026 年 10 月”）和一张日表：日期（“DD/MM”和星期，“今天”标在当天，蓝宝石色色带）、手表（下方带“手动”和事由）、备忘以及“换成……”（与今天页面相同）。周末浅灰底。没有日期时：“此模式下抽签按周进行：计划只有当前这一周。”或“没有任何一天。”日期来自 API（plano.dia_a_dia，带 pagina 与 relogio：手表筛选会重新读取 API），来自“显示至”中的“显示至”（设置，默认 31）；超过之后，下方是翻页（每一页重新读取 API 并滚动到逐日）以及“第 N 页，共 M 页 · <total> 天，每页 <n> 天（设置中的“显示至”）。”',
        'Rodapé: Apagar a programação (um cartão no fim da página, depois do dia a dia, separado por uma margem grande e uma borda de 3px aço escuro em cima)' => '页脚：清除安排（页面末尾一张卡片，在逐日之后，以较大外边距和上方 3px 深钢灰边框分隔）',
        'Título h2 "Apagar a programação". "Apagar um período" (o rótulo em cinza): numa linha que quebra, "De" e "Até" (datas, de hoje em diante, obrigatórias), "Depois" (lista: "e sortear de novo" = rodizio periodo_sortear; "e deixar livre" = periodo_livre) e o botão leve "Apagar". Embaixo, a explicação da opção escolhida ("Tudo o que o período tem, de amanhã em diante (escolhido à mão, sorteado ou livre), sai, e o modo de rodízio sorteia os dias outra vez." / "... sai, e os dias ficam livres: sem relógio e sem sorteio, para você escolher cada um ..."). Confirma "Apagar o que o período tem e sortear de novo? Os dias escolhidos à mão nele também saem." (ou "... e deixar os dias livres, sem relógio? ...").' => 'h2 标题“清除安排”。“清除一个时段”（灰色标签）：在可换行的一行里，“从”和“到”（日期，从今天起，必填）、“之后”（列表：“并重新抽签”= rodizio periodo_sortear；“并留空”= periodo_livre）以及浅色按钮“清除”。下方是所选选项的说明（“该时段从明天起的全部内容（手动选定、抽签或空闲）都会去掉，轮换模式会再次为这些天抽签。”/“……去掉，这些天变为空闲：没有手表、也不抽签，由你逐一选择……”）。确认“清除该时段的内容并重新抽签？其中手动选定的日子也会去掉。”（或“……并让这些天空闲、没有手表？……”）。',
        'Abaixo de uma linha, "Apagar tudo": a caixa "Excluindo hoje (apaga também o dia de hoje)" e o botão leve "Apagar tudo" (rodizio apagar_tudo, com hoje=1 marcada), e a nota "Limpa toda a programação, de amanhã em diante: os dias escolhidos à mão, os sorteados e os livres. Marcando "Excluindo hoje", apaga de hoje em diante (se sair outro relógio para hoje, ele passa a ser o do pulso a partir de agora). Depois, o modo de rodízio monta o plano de novo, do zero." Confirma (com hoje: "Apagar toda a programação, de hoje em diante (escolhidos à mão, sorteados e dias livres)? O modo de rodízio monta o plano de novo, e hoje pode sair outro relógio, que passa a ser o do pulso a partir de agora."; sem: "... de amanhã em diante ...; hoje continua como está.").' => '一条分隔线下方，“全部清除”：复选框“排除今天（也清除今天这一天）”和浅色按钮“全部清除”（rodizio apagar_tudo，勾选时 hoje=1），以及说明“清除从明天起的全部安排：手动选定的日子、抽签的日子和空闲日。勾选“排除今天”则从今天起清除（若今天改派另一只手表，它从现在起成为手腕上的那只）。之后，轮换模式从零重新编制计划。”确认（含今天：“清除全部安排，从今天起（手动选定、抽签和空闲日）？轮换模式会重新编制计划，今天可能改派另一只手表，并从现在起成为手腕上的那只。”；不含：“……从明天起……；今天保持不变。”）。',
        'configuracao.php; ?evento=<id> abre um evento para editar; #personalizados' => 'configuracao.php；?evento=<id> 打开一个事件进行编辑；#personalizados',
        'recurso=migracoes (antes de tudo)' => 'recurso=migracoes（在一切之前）',
        'config: salvar, evento_salvar, evento_excluir, testar_manha, testar_noite, teste_agenda_criar, teste_agenda_remover, sincronizar' => 'config：salvar、evento_salvar、evento_excluir、testar_manha、testar_noite、teste_agenda_criar、teste_agenda_remover、sincronizar',
        'migracoes: aplicar' => 'migracoes：aplicar',
        'backup: fazer, restaurar' => 'backup：fazer、restaurar',
        'Banco desatualizado (só quando há migração pendente)' => '数据库未更新（仅当有待应用的迁移时）',
        'Um cartão só: "O banco está desatualizado", a explicação ("Esta versão do sistema precisa de migrações que ainda não foram aplicadas... as páginas, a API e o cron ficam parados..."), a tabela das pendentes (versão em negrito, o que traz, o arquivo em código), o botão "Aplicar agora" (migracoes aplicar) e a nota de como rodar na mão. Depois de aplicar: "Atualização do banco", o resultado e "Continuar para a Configuração".' => '只有一张卡片：“数据库未更新”，说明（“本版本系统需要尚未应用的迁移……各页面、API 和 cron 都会停住……”），待处理项表格（版本加粗、带来的内容、文件以代码字体显示），按钮“立即应用”（migracoes aplicar）以及如何手动运行的说明。应用之后：“数据库更新”、结果和“继续前往设置”。',
        'Os quadros do alto (uma grade de 3 colunas; um formulário só, salvo pela barra do pé)' => '顶部的框（三列网格；只有一个表单，由页脚栏保存）',
        'Cada opção numa linha: o rótulo à esquerda e o campo à direita, alinhados na mesma coluna em todos os quadros; caixas de marcar no lugar do campo; textos longos com o rótulo em cima e o campo na largura toda. Cada quadro com a explicação embaixo.' => '每个选项占一行：标签在左、字段在右，所有框对齐到同一列；复选框位于字段位置；长文本把标签放在上方、字段占满宽度。每个框下方有说明。',
        'Rotina do dia: Manhã: relógio do dia e avisos (hora); Noite: preparar o de amanhã (hora); No pulso a partir de (hora); Pôr no pulso sozinho (caixa); No pulso até (hora); Tirar do pulso sozinho (caixa); Sessão no sol esquecida fecha às (hora).' => '每日例程：早晨：当天的手表和提醒（时刻）；夜晚：准备明天的（时刻）；从……起上手腕（时刻）；独自上手腕（复选框）；在手腕上直到（时刻）；独自离开手腕（复选框）；忘记的晒太阳时段关闭于（时刻）。',
        'Limites e contas: Carregar quando a carga chegar a (%) (1 a 99, padrão 20); Solar: pôr no sol quando chegar a (%) (1 a 99, padrão 70); Gasto medido: média dos últimos (dias) (1 a 3650, padrão 90); Aviso Encostado: dias sem ir ao pulso (1 a 3650, padrão 30; encostado_dias).' => '限额与计算：电量达到（%）时充电（1 到 99，默认 20）；太阳能：达到（%）时晒太阳（1 到 99，默认 70）；实测消耗：最近（天）的平均（1 到 3650，默认 90）；闲置提醒：多少天没上手腕（1 到 3650，默认 30；encostado_dias）。',
        'Telas: Abrir o relógio na página Hoje (Ao lado da lista; Numa janela flutuante, grande); Destaque no alto da página Hoje (O relógio do dia; O relógio no pulso agora: destaque_hoje dia ou pulso, com a nota "Destaque: ..."); "Próximos dias (página Hoje): mostrar até (dias por página)" e "Plano: mostrar até (dias por página)" (números de 1 a 366, com o valor de mostrar_ate da API: padrão 7 e 31); Endereço do sistema (a âncora {link}); e a nota sobre o Mostrar até (passando disso, as páginas embaixo: <, os números, >).' => '各页面：在今天页面打开手表（在列表旁边；在大的浮动窗口中）；今天页面顶部的突出显示（当天的手表；现在在手腕上的手表：destaque_hoje 为 dia 或 pulso，并带说明“突出显示：……”）；“接下来的日子（今天页面）：显示至（每页天数）”和“计划：显示至（每页天数）”（1 到 366 的数字，带 API 的 mostrar_ate 值：默认 7 和 31）；系统地址（锚点 {link}）；以及关于显示至的说明（超过之后，下方分页：<、数字、>）。',
        'Cron: "Cron rodando: última execução às HH:MM." (nota) ou, em âmbar, "O cron ainda não rodou" / "O cron não roda desde ..." com a linha do crontab em código; o erro guardado numa caixa ("O cron está com erro"); o link "Ver todas as execuções do cron" e o "Registro da última rodada" (abre e fecha).' => 'Cron：“Cron 运行中：最近一次执行于 HH:MM。”（说明）或琥珀色的“cron 尚未运行”/“cron 自……起没有运行”，并附 crontab 行（代码字体）；保存的错误放在一个框里（“cron 出错”）；链接“查看 cron 的全部执行”和“最近一轮的记录”（展开和收起）。',
        'Sorteios (só leitura): "Os números vêm de": "1. RANDOM.ORG (ruído atmosférico) · 2. fora do ar, ANU QRNG (quântico) · 3. sem os dois, o gerador seguro do PHP"; "Último lote": "<fonte> em DD/MM/AAAA HH:MM" (aleatorio.ultimo_lote da API) ou "nenhum ainda"; com os dois fora, "Serviços fora" em âmbar: "os dois sem responder desde DD/MM/AAAA HH:MM; o sistema tenta de novo depois de 10 minutos". A nota: "Todo sorteio do sistema (o rodízio totalmente aleatório, o sorteio pela nota e o desempate de notas iguais na escala) usa estes números. Eles chegam num lote, e cada sorteio usa só o que precisa, sem viés."' => '抽签（只读）：“数字来自”：“1. RANDOM.ORG（大气噪声）· 2. 无法访问时，ANU QRNG（量子）· 3. 两者都没有时，PHP 的安全生成器”；“最近一批”：“<fonte> 于 DD/MM/AAAA HH:MM”（API 的 aleatorio.ultimo_lote）或“还没有”；两者都不可用时，琥珀色“服务不可用”：“自 DD/MM/AAAA HH:MM 起两者都无响应；系统在 10 分钟后再试”。说明：“系统的每一次抽签（完全随机的轮换、按分数抽签以及排班表中分数相同的决胜）都使用这些数字。它们成批到达，每次抽签只用所需的部分，没有偏差。”',
        'Telegram (API de alerta): Enviar alertas (caixa). Google Agenda: Criar eventos na agenda (caixa), Antecedência dos eventos (dias, 1 a 365), ID da agenda, Caminho da chave JSON no servidor; a chave encontrada ("Compartilhe a agenda com <e-mail>") ou não; os botões leves "Criar evento de teste" e "Remover evento de teste".' => 'Telegram（提醒 API）：发送提醒（复选框）。Google 日历：在日历中创建事件（复选框）、事件提前量（天，1 到 365）、日历 ID、服务器上 JSON 密钥的路径；密钥已找到（“把日历共享给 <e-mail>”）或未找到；浅色按钮“创建测试事件”和“移除测试事件”。',
        'Mensagem padrão' => '默认消息',
        'Um cartão por canal (Telegram, Google Agenda), lado a lado: o nome do canal, a lista "Inserir âncora" (põe {ancora} onde está o cursor), o texto (7 linhas) e a ajuda do canal. Embaixo, "O que cada âncora vira" (abre e fecha: a tabela {ancora} → o que é).' => '每个渠道一张卡片（Telegram、Google 日历），并排：渠道名称、“插入锚点”列表（在光标处放入 {ancora}）、文本（7 行）以及该渠道的帮助。下方，“每个锚点会变成什么”（展开和收起：表格 {ancora} → 它是什么）。',
        'O que vai para onde' => '各项发往何处',
        'Tabela: Aviso (o nome; nos eventos personalizados, em negrito, com "editar" e "excluir"), Quando, uma coluna por canal com uma caixa centrada (vai ou não), e Personalizar (uma caixa por canal). Marcar Personalizar abre, na linha de baixo, o texto daquele aviso naquele canal, com "Inserir âncora" e a dica "Vazio usa a mensagem padrão do <canal>".' => '表格：提醒（名称；自定义事件为粗体，带“编辑”和“删除”）、何时、每个渠道一列并居中一个复选框（发或不发），以及自定义（每个渠道一个复选框）。勾选自定义后，在下一行打开该提醒在该渠道的文本，带“插入锚点”和提示“留空则使用 <渠道> 的默认消息”。',
        'A barra de salvar no pé: "As mudanças desta página valem depois de salvar." e o botão "Salvar configuração" (config salvar).' => '页脚保存栏：“本页的更改在保存后生效。”以及按钮“保存设置”（config salvar）。',
        'Eventos personalizados' => '自定义事件',
        'A explicação e um quadro que abre e fecha ("Novo evento" ou "Editar o evento <nome>"): Nome (obrigatório), Relógio (opcional: "Nenhum, é um evento geral" e os relógios), Quando dispara (uma vez, todo dia, toda semana, todo mês, a cada N dias), e só os campos da repetição escolhida: Data / A partir de, Hora (obrigatória), Dia do mês (1 a 31), A cada quantos dias, Dias da semana (caixas seg a dom); Ativo; as próximas vezes (na edição); botão "Criar evento" / "Salvar alterações" e "cancelar".' => '说明以及一个可展开的框（“新事件”或“编辑事件 <nome>”）：名称（必填）、手表（可选：“无，这是一般事件”以及各手表）、何时触发（一次、每天、每周、每月、每 N 天），以及仅所选重复方式的字段：日期 / 从……起、时刻（必填）、月中的日（1 到 31）、每隔多少天、星期几（复选框 seg 到 dom）；启用；接下来的几次（编辑时）；按钮“创建事件”/“保存更改”和“取消”。',
        'Cópia de segurança (no fim da página, depois de Como sai hoje)' => '安全副本（在页面末尾，在“今天如何发出”之后）',
        'Título "Cópia de segurança". Com a pasta: a nota "Uma cópia do banco inteiro por dia, na rodada da noite, guardando as 7 mais novas, sem (ou com) o conteúdo dos documentos... Última: DD/MM/AAAA HH:MM." (ou "Nenhuma feita ainda."); sem a pasta, em âmbar: "A cópia automática está desligada: <motivo>. Ponha no config.php a BACKUP_PASTA, uma pasta do servidor fora da pasta publicada."' => '标题“安全副本”。有文件夹时：说明“每天在夜间一轮做整个数据库的一份副本，保留最新的 7 份，不含（或含）文档内容……最近一次：DD/MM/AAAA HH:MM。”（或“还没有做过。”）；没有文件夹时，琥珀色：“自动副本已关闭：<motivo>。在 config.php 中设置 BACKUP_PASTA，指向已发布文件夹之外的服务器文件夹。”',
        'A tabela compacta das cópias (da mais nova para a mais velha): Cópia (o nome do arquivo em fonte fixa), Feita em, Tamanho ("7 KB"), Documentos (com/sem) e, à direita, "Baixar" (link leve para api.php?recurso=backup&arquivo=<nome>) e "Restaurar" (discreto; confirma "Voltar o banco para a cópia de DD/MM/AAAA HH:MM? Tudo o que foi feito depois some. Antes, o sistema guarda uma cópia do que está agora."; backup restaurar). Embaixo, o botão leve "Fazer uma cópia agora" (backup fazer).' => '副本的紧凑表格（从最新到最旧）：副本（文件名用等宽字体）、完成于、大小（“7 KB”）、文档（有/无），右侧“下载”（指向 api.php?recurso=backup&arquivo=<nome> 的浅色链接）和“恢复”（低调；确认“把数据库恢复到 DD/MM/AAAA HH:MM 的副本？之后所做的一切都会消失。在此之前，系统会保存当前内容的一份副本。”；backup restaurar）。下方浅色按钮“现在做一份副本”（backup fazer）。',
        'Com BACKUP_ATIVO = false no config.php, a seção inteira não aparece (nem o aviso de que falta a pasta).' => '在 config.php 中设置 BACKUP_ATIVO = false 时，整个部分都不显示（也不显示缺少文件夹的警告）。',
        'Como sai hoje' => '今天会发出什么',
        'Três caixas lado a lado: Telegram de manhã e Telegram à noite (o texto como sai, em fonte fixa, ou "(nada a enviar)", e o botão leve "Enviar agora"); Agenda (os próximos eventos com a data, a hora, o título em negrito e a descrição, quantos o sistema já criou, e "Sincronizar agora").' => '三个并排框：早晨的 Telegram 和夜晚的 Telegram（发出的文本，等宽字体，或“（没有要发送的）”，以及浅色按钮“立即发送”）；日历（接下来的事件，含日期、时刻、粗体标题和描述、系统已创建多少，以及“立即同步”）。',
        'Critérios de escolha' => '选择规则',
        'criterios.php?escopo=<"", g:<grupo> ou r:<relógio>>; ?relogio=<id> abre a conta dele' => 'criterios.php?escopo=<""、g:<grupo> 或 r:<手表>>；?relogio=<id> 打开它的计算',
        'criterios: todas as ações' => 'criterios：全部操作',
        'Explicações' => '说明',
        'h1 "Critérios de escolha do relógio". Cartão "Como a nota funciona" (lugar, conjunto, parâmetro, subparâmetro, faixas, peso efetivo e nota final, em negrito os termos). Cartão "Como a nota vira escolha": as quatro formas com a explicação, a tabela Modo de rodízio / Forma de escolha ("(o modo atual)") e a garantia de rodízio.' => 'h1“手表选择标准”。卡片“分数如何运作”（位置、集合、参数、子参数、区间、有效权重和最终分数，术语加粗）。卡片“分数如何变成选择”：四种方式及其说明、表格轮换模式 / 选择方式（“（当前模式）”）以及轮换保障。',
        'Onde há critérios' => '哪里有规则',
        'Tabela Lugar, Parâmetros (quantos), Usado por ("N relógios" e os nomes em cinza) e o link "editar". Em vermelho: "Há relógios sem conjunto nenhum (nota neutra, 50): ..."' => '表格：位置、参数（多少个）、使用者（“N 块手表”以及灰色名称）和链接“编辑”。红色：“有手表没有任何集合（中性分数 50）：……”',
        'O conjunto do lugar escolhido' => '所选位置的集合',
        '"Editar os critérios de" com a lista de todos os lugares ("Todos os relógios", "Grupo: <caminho>", "Relógio: <nome>"; "— com critérios próprios" nos que têm) e "Abrir". Sem critérios próprios: "<Lugar> não tem critérios próprios: usa os de <lugar de cima>." e os botões "Criar critérios próprios, copiando os de <lugar>" e "Criar vazio" (leve).' => '“编辑……的标准”，带全部位置的列表（“全部手表”、“分组：<路径>”、“手表：<名称>”；有自己标准的标“— 有自己的标准”）和“打开”。没有自己的标准：“<位置> 没有自己的标准：使用 <上级位置> 的。”以及按钮“创建自己的标准，复制自 <位置>”和浅色的“创建空白”。',
        'Com critérios: "Critérios de <lugar>", "Usado por N relógios: ..." e a tabela Parâmetro (o nome editável), Peso no conjunto (campo curto e "%"), Subparâmetros (link para a seção; "(fora da conta)" em vermelho se nenhum), e ↑ ↓ Excluir; no rodapé "Soma" com a soma ao vivo e "fecha 100%" ou, em vermelho, "faltam N%" / "passa N%"; botão "Salvar parâmetros". Excluir confirma mostrando como o peso se divide entre os que ficam. Linha de inclusão: Novo parâmetro, Peso (%), "Incluir". Embaixo, "Excluir os critérios próprios de <lugar>" (discreto, confirma).' => '有标准时：“<位置> 的标准”、“由 N 块手表使用：……”以及表格：参数（可编辑的名称）、在集合中的权重（短字段和“%”）、子参数（链到该节；若一个都没有则红色“（不计入）”），以及 ↑ ↓ 删除；页脚“合计”带实时合计，以及“正好 100%”或红色“还差 N%”/“超出 N%”；按钮“保存参数”。删除时确认并显示权重如何分给留下的那些。添加行：新参数、权重（%）、“添加”。下方，“删除 <位置> 的自有标准”（低调，需确认）。',
        'Cada parâmetro' => '每个参数',
        'Um cartão por parâmetro: "<nome> <peso> do conjunto de <lugar>"; a tabela Subparâmetro, Mede, Peso no parâmetro, Peso efetivo no conjunto (atualizado ao digitar), ↑ ↓ Excluir, com a soma no rodapé e "Salvar subparâmetros".' => '每个参数一张卡片：“<名称> 占 <位置> 集合的 <权重>”；表格：子参数、测量、在参数中的权重、在集合中的有效权重（输入时更新）、↑ ↓ 删除，页脚有合计和“保存子参数”。',
        'Para cada subparâmetro, "Faixas de <nome>" (abre e fecha, com quantas faixas e o que mede): numa medida numérica, a tabela De, Até, Nota, Apagar; numa de categoria, Categoria (lista), Nota, Apagar; sempre uma linha em branco para incluir, o botão "+ faixa" (mais uma linha) e "Salvar faixas"; a regra das faixas em nota. Embaixo, "Trocar a medida para" (confirma: as faixas recomeçam) e "Mover para o parâmetro".' => '对每个子参数，“<名称> 的区间”（展开和收起，带区间数量和测量内容）：数值测量时，表格为从、到、分数、删除；类别测量时，类别（列表）、分数、删除；始终有一空白行用于添加，按钮“+ 区间”（再加一行）和“保存区间”；区间规则写在说明里。下方，“把测量改为”（确认：区间重新开始）和“移到参数”。',
        'Linha de inclusão: Novo subparâmetro, Mede (lista das medidas), Peso (%), "Incluir". Sem subparâmetros, em vermelho: "Sem subparâmetros: este parâmetro não entra na conta até ganhar um."' => '添加行：新子参数、测量（测量列表）、权重（%）、“添加”。没有子参数时，红色：“没有子参数：此参数在获得一个之前不计入。”',
        'A nota de cada relógio agora' => '每块手表现在的评分',
        'Um quadro que abre e fecha por relógio disponível, da maior nota para a menor: o nome em negrito, "<grupo> · critérios de <lugar>" e a nota à direita; aberto, a tabela Parâmetro, Subparâmetro, Valor medido, Faixa, Nota, Peso efetivo, Pontos, com a nota final no rodapé, e os links "editar os critérios de <lugar>" e "critérios só deste relógio". Por fim, o cartão "Restaurar os critérios iniciais" com o botão leve "Restaurar" (confirma).' => '每个可用手表一个可展开的框，从分数最高到最低：名称加粗，“<分组> · <位置> 的标准”以及右侧分数；展开后，表格：参数、子参数、测得的值、区间、分数、有效权重、得分，页脚为最终分数，以及链接“编辑 <位置> 的标准”和“仅这块手表的标准”。最后，卡片“恢复初始标准”，带浅色按钮“恢复”（需确认）。',
        'Grupos de relógios' => '手表分组',
        'arvore: novo, renomear, mover, ordem, excluir, relogios' => 'arvore：novo、renomear、mover、ordem、excluir、relogios',
        'Árvore' => '树',
        'A explicação; a árvore como lista com recuo por nível. Cada grupo: o nome num campo com "Renomear" (discreto), "N relógios" ("· critérios próprios" com link), ↑ ↓ e Excluir (confirma dizendo para onde vão os subgrupos, os relógios e o que acontece com os critérios); os relógios dele em cinza embaixo; e "subgrupo e mover" (abre e fecha): Novo subgrupo + "Criar", Mover para dentro de (só onde não forma ciclo) + "Mover". No fim: linha de inclusão "Novo grupo", "dentro de" e "Criar". Sem grupos: "Nenhum grupo ainda."' => '说明；树是按层级缩进的列表。每个分组：名称在一个字段里，带“重命名”（低调）、“N 块手表”（“· 自有标准”带链接）、↑ ↓ 和删除（确认时说明子分组、手表会去哪里，以及标准会怎样）；它的手表以灰色列在下方；以及“子分组和移动”（展开和收起）：新子分组 + “创建”、移入（仅不会形成环的位置）+ “移动”。末尾：添加行“新分组”、“位于……之内”和“创建”。没有分组：“还没有任何分组。”',
        'O grupo de cada relógio' => '每块手表的分组',
        'Tabela Relógio ("(indisponível)" em cinza) e Grupo (lista com "(na raiz)" e os caminhos), e o botão "Salvar grupos" (arvore relogios, todos de uma vez).' => '表格：手表（灰色“（不可用）”）和分组（列表含“（在根）”和各路径），以及按钮“保存分组”（arvore relogios，一次保存全部）。',
        'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina= (os filtros no endereço)' => 'execucoes.php?de=&ate=&situacao=&busca=&por=&pagina=（地址中的筛选）',
        'Título com "Última execução: DD/MM/AAAA HH:MM:SS". Filtros num cartão: De, Até (padrão: os últimos 7 dias), Situação (Com atividade (padrão), Com erro, Sem atividade, Todas), Texto no registro, Por página (25, 50, 100, 200), "Filtrar" e os atalhos hoje, 7 dias, 30 dias, erros do último ano.' => '标题带“最近一次执行：DD/MM/AAAA HH:MM:SS”。筛选在一张卡片中：从、到（默认：最近 7 天）、情况（有活动（默认）、有错误、无活动、全部）、记录中的文本、每页（25、50、100、200）、“筛选”以及快捷方式：今天、7 天、30 天、最近一年的错误。',
        'Resumo em 4 caixas: execuções no período, com atividade, com erro (vermelho se houver), a mais lenta. A nota com quantas e a retenção. Tabela Início (data e a hora em negrito embaixo), Duração ("850 ms" ou "1,5 s"), Situação (etiqueta erro / atividade / sem atividade), Registro (o texto em fonte fixa, ou "nada a fazer neste minuto"); linha com erro em vermelho claro. Paginação: « primeira, ‹ anterior, até 3 números de cada lado, próxima ›, última ».' => '四格摘要：时段内的执行次数、有活动、有错误（若有则为红色）、最慢的一次。说明中有数量和保留期限。表格：开始（日期，下方粗体时刻）、时长（“850 ms”或“1,5 s”）、情况（标签：错误 / 活动 / 无活动）、记录（等宽文本，或“这一分钟无事可做”）；错误行浅红底。分页：« 第一页、‹ 上一页、两侧最多 3 个数字、下一页 ›、最后一页 »。',
        'Histórico — <relógio>' => '历史 — <手表>',
        'Cabeça com a foto, "Histórico · <tipo> · código N", o nome em h1 e "<n> registros desde ...". Filtros num cartão: De, Até, Estado (Todos, Em uso, Fora do rodízio, cada tipo de sessão, Em repouso, Marcações), Por página (25, 50, 100, Todos), "Filtrar" e os atalhos 7 dias, 30 dias, desde o começo.' => '页眉带照片、“历史 · <类型> · 编号 N”、h1 中的名称以及“自……起 <n> 条记录”。筛选在一张卡片中：从、到、状态（全部、使用中、轮换之外、每种时段类型、休息中、标记）、每页（25、50、100、全部）、“筛选”以及快捷方式 7 天、30 天、从一开始。',
        'Resumo em caixas: o tempo em cada estado ("5d 7h" e "em uso · 13%") e a contagem de cada marcação. A nota de quantos e de como ler os trechos. Tabela Início, Fim, Duração, Estado (etiqueta verde para uso, vermelha para repouso, laranja para as outras sessões; marcação em cinza, só o texto; "em andamento: o fim é o momento desta consulta"). Paginação: « mais recentes, ‹ anterior, números, próxima ›, mais antigos » e "ver tudo".' => '方框摘要：每种状态的时间（“5d 7h”和“使用中 · 13%”）以及每种标记的计数。说明有多少条以及如何阅读片段。表格：开始、结束、时长、状态（使用为绿色标签，休息为红色，其他时段为橙色；标记为灰色，只有文本；“进行中：结束时刻是本次查询的时刻”）。分页：« 较新、‹ 上一页、数字、下一页 ›、较旧 » 以及“查看全部”。',
        'documentos.php?relogio=<id>&cat=<categoria> (sem relógio: de todos)' => 'documentos.php?relogio=<id>&cat=<类别>（无手表：全部的）',
        'recurso=documento (cada arquivo)' => 'recurso=documento（每个文件）',
        'documentos: enviar, alterar, excluir' => 'documentos：enviar、alterar、excluir',
        'relogio: salvar (a cópia no banco do relógio)' => 'relogio：salvar（该手表在数据库中的副本）',
        'Cabeça' => '页眉',
        'h1 "Documentos do <relógio>" (ou "de todos os relógios"); a lista "Relógio" (Todos e cada um, com "(N)") e "Abrir a ficha do relógio". A situação da cópia no banco (quem decide: o config.php, o relógio, com o botão "Guardar todos os dele no banco" / "Só os marcados"). Sem a pasta: o motivo em âmbar.' => 'h1“<手表> 的文档”（或“全部手表的”）；列表“手表”（全部以及每一只，带“（N）”）和“打开手表详情”。在数据库中的副本的情况（由谁决定：config.php、手表，带按钮“把他的全部保存在数据库中”/“只保存已标记的”）。没有文件夹：琥珀色的原因。',
        'Enviar arquivos (abre e fecha; aberto quando não há nenhum; só com um relógio escolhido)' => '上传文件（展开和收起；一个都没有时展开；仅在已选择一块手表时）',
        'Categoria (com o que ela aceita), Título ("vazio: o nome do arquivo"), Data, Descrição, Arquivos (vários; o seletor só deixa os tipos da categoria), "Guardar a cópia destes arquivos também no banco" (só quando cabe ao arquivo decidir), o limite de tamanho, "Enviar" e o andamento ("Enviando 2 de 5: foto.jpg — 40%"). Um arquivo por vez, cada foto com a miniatura feita no navegador (480px, JPEG 80%). No fim: "N documentos guardados." e os erros.' => '类别（以及它接受什么）、标题（“空：文件名”）、日期、描述、文件（多个；选择器只允许该类别的类型）、“也把这些文件的副本保存在数据库中”（仅当由文件决定时）、大小限制、“上传”以及进度（“正在上传 5 个中的第 2 个：foto.jpg — 40%”）。一次一个文件，每张照片在浏览器中生成缩略图（480px，JPEG 80%）。结束时：“已保存 N 个文档。”以及错误。',
        'Abas e conteúdo' => '标签页与内容',
        'Abas "Todos (N)" e cada categoria "(N)". Fotos: a galeria (quadrados de 140px, 100px no celular, com o título e a data) e o botão "▶ Apresentação"; tocar numa foto abre o visor em tela cheia (fundo #080b0f): "N de M", "▶ Apresentação" / "❚❚ Parar" (troca a cada 4 s), "Baixar", "×"; ‹ e › nos lados, setas do teclado, deslizar o dedo, Esc fecha, espaço liga a apresentação; a legenda embaixo.' => '标签“全部（N）”以及每个类别“（N）”。照片：图库（140px 方块，手机上 100px，带标题和日期）以及按钮“▶ 放映”；点一张照片打开全屏查看器（背景 #080b0f）：“N / M”、“▶ 放映”/“❚❚ 停止”（每 4 秒切换）、“下载”、“×”；两侧 ‹ 和 ›、键盘方向键、手指滑动、Esc 关闭、空格开关放映；说明在下方。',
        'Vídeos: o player e a lista para marcar e ordenar (↑ ↓), "▶ Assistir os marcados" (tocam em sequência; "‹ Anterior", "Próximo ›", "Fechar"). Arquivos: um cartão por arquivo com o título, a data, a categoria em etiqueta, a descrição, o nome, o tamanho e onde está guardado; PDF: "Ver aqui" (abre embutido), "Abrir noutra aba", "Baixar"; XML de NF-e: a tabela Emitente, Nota, Valor, Produto(s), Chave e "Baixar o XML"; áudio: o player; o resto: "Baixar".' => '视频：播放器以及用于勾选和排序的列表（↑ ↓）、“▶ 播放已勾选的”（按顺序播放；“‹ 上一个”、“下一个 ›”、“关闭”）。文件：每个文件一张卡片，含标题、日期、标签中的类别、描述、名称、大小以及存放位置；PDF：“在此查看”（内嵌打开）、“在另一标签页打开”、“下载”；NF-e 的 XML：表格开票方、发票、金额、产品、密钥以及“下载 XML”；音频：播放器；其余：“下载”。',
        'Em cada arquivo, "editar" (abre e fecha): Título, Data, Categoria, Descrição, a cópia no banco (quando cabe), "Salvar" e "Excluir" (confirma "Excluir <título>? O arquivo sai do servidor."). Fotos e vídeos se editam numa lista à parte, "Editar ou excluir fotos e vídeos".' => '每个文件上，“编辑”（展开和收起）：标题、日期、类别、描述、数据库中的副本（适用时）、“保存”和“删除”（确认“删除 <标题>？文件会从服务器上移除。”）。照片和视频在单独的列表中编辑，“编辑或删除照片和视频”。',
        'recurso=calcular (o testar)' => 'recurso=calcular（测试用）',
        'campos, lancamento_tipos, formulas, avisos, modos, documento_categorias' => 'campos、lancamento_tipos、formulas、avisos、modos、documento_categorias',
        'Em todas as abas' => '在所有标签页中',
        'h1 "Cadastros" e as abas Campos, Tipos de lançamento, Fórmulas, Avisos, Modos de rodízio, Categorias de documentos. Cada aba é um cartão: o título, a explicação, a tabela com "Editar" (link que abre o formulário embaixo com os dados, no #form) e Excluir em cada linha, e o formulário ("Novo ..." ou "Alterar ...", botão "Criar" / "Salvar" e "cancelar"). Gravou: o recado no alto e a edição acaba; recusado: o que foi digitado fica e os erros aparecem no topo.' => 'h1“定义”以及标签：字段、记录类型、公式、提醒、轮换模式、文档类别。每个标签是一张卡片：标题、说明、表格，每行有“编辑”（链接，在下方 #form 处打开已填数据的表单）和删除，以及表单（“新建……”或“修改……”，按钮“创建”/“保存”和“取消”）。保存成功：顶部提示，编辑结束；被拒绝：所输入的内容保留，错误出现在顶部。',
        'Tabela Campo ("(unidade)"), Identificador (fonte fixa), Tipo, Vale para, Padrão, ações (Editar, ↑, ↓, Excluir com confirmação "Excluir o campo <nome> e os valores dele?"). Formulário: Nome (até 120), Identificador (a-z, 0-9 e _; começa com letra; até 40), Tipo (Número inteiro, Número decimal, Sim ou não, Data, Lista de opções, Texto), Unidade (até 20), Valor padrão, Vale para ("todos os relógios" e os grupos), Opções (lista: uma por linha).' => '表格：字段（“（单位）”）、标识符（等宽）、类型、适用于、默认、操作（编辑、↑、↓、删除，确认“删除字段 <名称> 及其值？”）。表单：名称（最多 120）、标识符（a-z、0-9 和 _；以字母开头；最多 40）、类型（整数、小数、是或否、日期、选项列表、文本）、单位（最多 20）、默认值、适用于（“全部手表”以及各分组）、选项（列表：每行一个）。',
        'Tipos de lançamento' => '记录类型',
        'Tabela Tipo, Identificador, Formato (com a unidade), Fecha sozinho às, Exclusiva, Mede o gasto, Vale quando (fonte fixa), Vale para, Lançamentos (quantos), ações. Formulário: Nome, Identificador, Formato (Instantâneo; Instantâneo com valor; Sessão, com início e fim), Unidade (com valor), Fecha sozinho às (hora; vazio: não fecha), Vale para, Vale quando (fórmula), as caixas "sessão exclusiva (o relógio num lugar só)" e "mede o gasto".' => '表格：类型、标识符、格式（带单位）、自动结束于、独占、测量消耗、何时有效（等宽）、适用于、记录（多少条）、操作。表单：名称、标识符、格式（瞬时；带数值的瞬时；时段，有开始和结束）、单位（有数值时）、自动结束于（时刻；空：不结束）、适用于、何时有效（公式）、复选框“独占时段（手表只在一个地方）”和“测量消耗”。',
        'Fórmulas' => '公式',
        'Tabela Fórmula (o nome e o identificador com a unidade), Versão para, Cálculo (fonte fixa), ações. Formulário: Identificador (só na nova), Nome, Unidade, Versão para, Cálculo (textarea, fonte fixa). "Testar uma fórmula (sem gravar)": o texto da fórmula e "Testar em todos os relógios" (recurso=calcular): a tabela Relógio, Resultado, As partes da conta, ou os erros. "As funções do motor" (abre e fecha): cada função em negrito e a explicação.' => '表格：公式（名称和带单位的标识符）、版本适用于、计算（等宽）、操作。表单：标识符（仅新建）、名称、单位、版本适用于、计算（textarea，等宽）。“测试一个公式（不保存）”：公式文本和“在全部手表上测试”（recurso=calcular）：表格手表、结果、计算的各部分，或错误。“引擎的函数”（展开和收起）：每个函数加粗并附说明。',
        'Tabela Aviso, Versão para, Data prevista, Vale quando, Antecedência ("N d"), Resolve, Na escala (com o valor ou as horas simuladas), Na agenda, Na hora (sim/não), Ativo, ações. Formulário: Identificador (na novo), Nome, Antecedência (dias), Resolve (os tipos), Versão para, ativo, "na hora (Telegram no minuto em que vence)" (caixa), Na escala inteligente (não; no relógio do dia; sempre), Escala: valor do lançamento simulado, Escala: horas da sessão simulada, Data na agenda (só dentro da antecedência; qualquer data), Data prevista (fórmula), Vale quando (fórmula), Texto (até 300).' => '表格：提醒、版本适用于、预计日期、何时有效、提前量（“N d”）、解决、在排班表中（带数值或模拟小时）、在日历中、准时（是/否）、启用、操作。表单：标识符（新建时）、名称、提前量（天）、解决（各类型）、版本适用于、启用、“准时（到期的那一分钟发 Telegram）”（复选框）、智能排班表（否；在当天的手表上；始终）、排班表：模拟记录的数值、排班表：模拟时段的小时、日历中的日期（仅在提前量之内；任意日期）、预计日期（公式）、何时有效（公式）、文本（最多 300）。',
        'Modos de rodízio' => '轮换模式',
        'Tabela Modo ("(ativo)"), Forma de escolha ("· com ciclo"), Blocos (nome e dias), ações (Editar; nos outros: Ativar e Excluir). Formulário: Nome, Planejamento (sorteio pelos blocos; escala inteligente de 7 dias, 30 dias, 60 dias, 6 meses, 1 ano, 2 anos), Forma de escolha, a caixa "ciclo", e a tabela dos blocos (os que existem e duas linhas vazias): Bloco (nome), Dias (caixas seg a dom), Sortear de, Um por (um por dia; um por bloco (na semana)), Relógio fixo ("— sorteia —" e os relógios). Bloco sem dia marcado sai.' => '表格：模式（“（启用）”）、选择方式（“· 带循环”）、区块（名称和天数）、操作（编辑；其他的：启用和删除）。表单：名称、规划（按区块抽签；7 天、30 天、60 天、6 个月、1 年、2 年的智能排班表）、选择方式、复选框“循环”，以及区块表格（已有的和两行空白）：区块（名称）、天（复选框 seg 到 dom）、从何处抽签、每个（每天一个；每个区块一个（在一周内））、固定手表（“— 抽签 —”以及各手表）。没有勾选任何一天的区块会被去掉。',
        'Categorias de documentos' => '文档类别',
        'Tabela Categoria, Identificador, Aceita ("qualquer arquivo" ou as famílias), Ordem, Documentos, ações (Excluir só sem documentos). Formulário: Nome, Identificador (na nova), Ordem ("vazio: no fim"), Aceita (caixas imagens, vídeos, áudios, PDF, XML).' => '表格：类别、标识符、接受（“任意文件”或各系列）、顺序、文档、操作（仅在没有文档时才能删除）。表单：名称、标识符（新建时）、顺序（“空：放在末尾”）、接受（复选框：图像、视频、音频、PDF、XML）。',
        'usuarios: salvar, excluir' => 'usuarios：salvar、excluir',
        'h1 "Usuários". Cartão "Quem acessa": tabela Login ("você" em etiqueta azul no próprio), Criado em, e Excluir (menos no próprio; confirma). Cartão "Criar usuário ou trocar senha": Login, Senha (pelo menos 6 caracteres, campo de senha), "Se o login já existir, a senha dele é trocada." e "Salvar usuário". Recusado: o erro no topo.' => 'h1“用户”。卡片“谁可以访问”：表格登录名（自己的那一行有蓝色标签“你”）、创建于、以及删除（自己的那行除外；需确认）。卡片“创建用户或更改密码”：登录名、密码（至少 6 个字符，密码字段）、“如果登录名已存在，则更换其密码。”以及“保存用户”。被拒绝：错误在顶部。',
        'ajuda.php#<âncora>' => 'ajuda.php#<锚点>',
        'recurso=manual (o HTML e o sumário)' => 'recurso=manual（HTML 和目录）',
        'h1 "Ajuda"; "Nesta página": o sumário com os títulos de nível 2 e 3 (recuados), cada um link para a sua âncora; depois o manual em HTML, com as tabelas que rolam de lado no celular, as imagens com borda e cantos, o código em fonte fixa. Abrindo com uma âncora no endereço, a página vai direto para ela.' => 'h1“帮助”；“本页”：目录含 2 级和 3 级标题（缩进），每一个都链接到其锚点；然后是 HTML 手册，表格在手机上可横向滚动，图像有边框和圆角，代码为等宽字体。地址中带锚点打开时，页面直接跳到该处。',
        'a página Hoje no computador, com o painel ao lado' => '电脑上的今天页面，面板在旁边',
        'a tabela dos relógios com as 12 colunas e os filtros' => '带 12 列和筛选的手表表',
        'o histórico de um relógio' => '一块手表的历史',
        'a aba Campos dos Cadastros' => '定义中的字段标签',
        'no celular: a Hoje, os cartões dos relógios e o painel em tela cheia' => '在手机上：今天、手表卡片和全屏面板',
        'a base de todas as páginas: topo() (o head, o menu e o título) e rodape() (os scripts, com a data do arquivo na URL)' => '所有页面的基础：topo()（head、菜单和标题）和 rodape()（脚本，URL 中带文件日期）',
        'o estilo de todas as páginas: as cores, as letras, os controles, os componentes e os tamanhos de tela' => '所有页面的样式：颜色、字体、控件、组件和屏幕尺寸',
        'a base do JavaScript das páginas: os textos no idioma (t(), com o dicionário de recurso=textos), ler e gravar pela API, os formatos do idioma (número, dinheiro, data, hora), o login, os formulários que gravam, as tabelas que viram fichas no celular' => '页面 JavaScript 的基础：语言中的文本（t()，带 recurso=textos 的词典）、通过 API 读取和写入、语言的格式（数字、金钱、日期、时刻）、登录、用于保存的表单、在手机上变成档案卡的表格',
        'os idiomas: a lista (LINGUAS: o nome, o código curto do menu, o locale e os formatos da data e dos números), o idioma do pedido, t() e os formatos no PHP' => '各语言：列表（LINGUAS：名称、菜单短代码、locale 以及日期和数字格式）、请求的语言、t() 以及 PHP 中的格式',
        'o arquivo de um idioma (en, zh-CN, hi, es, fr): o texto em português => a tradução, por parte (telas, api, ajuda, manual, reconstrucao), gerado e conferido por testes/textos.php; o que falta sai em português, ou para com erro no modo estrito (TEXTOS_ESTRITO)' => '一种语言的文件（en、zh-CN、hi、es、fr）：葡萄牙语文本 => 译文，按部分（telas、api、ajuda、manual、reconstrucao），由 testes/textos.php 生成并核对；缺少的以葡萄牙语输出，或在严格模式（TEXTOS_ESTRITO）下因错误停止',
        'o esqueleto da página Hoje (o meio, a tabela dos relógios com os títulos e os filtros, e o painel)' => '今天页面的骨架（中间、带标题和筛选的手表表，以及面板）',
        'a página Hoje: o relógio do dia, os avisos de hoje, os próximos dias, o modo de rodízio e as linhas da tabela dos relógios' => '今天页面：当天的手表、今天的提醒、接下来的日子、轮换模式以及手表表的各行',
        'a tabela dos relógios: ordenar, filtrar e virar cartões quando as 12 colunas não cabem' => '手表表：排序、筛选，以及当 12 列放不下时变成卡片',
        'o painel do relógio (na página Hoje e na Ficha): os quadros, o Marcar, o Editar cadastro, o gráfico da carga, os dados e o histórico' => '手表面板（在今天页面和详情中）：各框、标记、编辑档案、电量图、数据和历史',
        'a foto reduzida no navegador antes de enviar (1200 px, JPEG 85%), com a prévia' => '发送前在浏览器中缩小的照片（1200 px，JPEG 85%），带预览',
        'a página Ficha do relógio: o painel do relógio numa página própria' => '手表详情页：手表面板在单独的页面上',
        'o esqueleto da página Plano' => '计划页面的骨架',
        'a página Plano: o resumo do período e o dia a dia, mês a mês' => '计划页面：时段摘要以及逐日，按月',
        'o esqueleto da página Configuração' => '设置页面的骨架',
        'a página Configuração: o banco desatualizado, os quadros das opções, as mensagens, o que vai para onde, os eventos e como sai hoje' => '设置页面：未更新的数据库、选项框、消息、发往何处、事件以及今天如何发出',
        'o esqueleto da página Critérios' => '标准页面的骨架',
        'a página Critérios: as explicações, os lugares, os parâmetros, os subparâmetros, as faixas e a nota de cada relógio' => '标准页面：说明、位置、参数、子参数、区间以及每块手表的分数',
        'o esqueleto da página Grupos' => '分组页面的骨架',
        'a página Grupos: a árvore e o grupo de cada relógio' => '分组页面：树以及每块手表的分组',
        'o esqueleto da página Execuções do cron' => 'cron 执行页面的骨架',
        'a página Execuções do cron: os filtros, o resumo, a tabela e a paginação' => 'cron 执行页面：筛选、摘要、表格和分页',
        'o esqueleto da página Desejos' => '心愿单页面的骨架',
        'a página Desejos: a lista de desejos (com o Comprei) e os relógios fora da coleção' => '心愿单页面：心愿列表（带我买了）以及收藏之外的手表',
        'o esqueleto da página Estatísticas' => '统计页面的骨架',
        'o esqueleto da página Hora certa' => '准确时间页面的骨架',
        'o esqueleto da página Acessórios' => '配件页面的骨架',
        'o esqueleto da página Galeria' => '图库页面的骨架',
        'a página Galeria: a coleção em fotos, por grupo, para ver e imprimir' => '图库页面：以照片展示收藏，按分组，供查看和打印',
        'o esqueleto da página Passaporte do relógio' => '手表护照页面的骨架',
        'a página Passaporte: a ficha de um relógio para imprimir ou guardar em PDF' => '护照页面：一块手表的档案，供打印或存为 PDF',
        'a página Acessórios: o filtro por relógio, a lista com Editar e Excluir e o cadastro' => '配件页面：按手表筛选、带编辑和删除的列表以及档案',
        'a página Hora certa: o mostrador e a hora digital andando, acertados pela API, e os quadros do fuso, do calendário e da lua' => '准确时间页面：走动的表盘和数字时间，由 API 校准，以及时区、日历和月相的框',
        'a página Estatísticas: o período, o resumo, cada relógio, os gráficos em SVG e a coleção' => '统计页面：时段、摘要、每块手表、SVG 图表以及收藏',
        'o esqueleto da página Histórico' => '历史页面的骨架',
        'a página Histórico de um relógio: os filtros, o resumo do tempo e a linha do tempo' => '一块手表的历史页面：筛选、时间摘要和时间线',
        'o esqueleto da página Documentos' => '文档页面的骨架',
        'a página Documentos: o envio, as abas, a galeria com o visor, os vídeos, os PDFs, as NF-e e a edição' => '文档页面：上传、标签、带查看器的图库、视频、PDF、NF-e 以及编辑',
        'o esqueleto da página Cadastros' => '定义页面的骨架',
        'a página Cadastros: as abas Campos, Tipos de lançamento, Fórmulas, Avisos, Modos de rodízio e Categorias de documentos' => '定义页面：标签字段、记录类型、公式、提醒、轮换模式和文档类别',
        'o esqueleto da página Usuários' => '用户页面的骨架',
        'a página Usuários: quem acessa e criar usuário ou trocar a senha' => '用户页面：谁可以访问，以及创建用户或更换密码',
        'o esqueleto da página Ajuda' => '帮助页面的骨架',
        'a página Ajuda: o sumário e o manual em HTML (recurso=manual)' => '帮助页面：目录以及 HTML 手册（recurso=manual）',
        'a API, a porta única: a autenticação, o formato, a ordem dos recursos (cada um no seu arquivo da pasta api/, ou ali mesmo, os pequenos), os filtros, o JSON e o XML, e no cabeçalho a documentação inteira' => 'API，唯一入口：身份验证、格式、资源顺序（每一个在 api/ 文件夹自己的文件中，小的就在原处）、筛选、JSON 和 XML，以及页眉中的完整文档',
        'as funções que só a API usa (o XML, os textos legíveis do tempo, do plano, dos eventos e da agenda, os filtros das listas e a resposta) e o tratamento dos erros' => '仅 API 使用的函数（XML、时间、计划、事件和日历的可读文本、列表筛选和响应）以及错误处理',
        'api.php sem recurso: tudo o que está guardado' => '不带 recurso 的 api.php：已保存的全部内容',
        'recurso=hoje: tudo o que a página Hoje mostra' => 'recurso=hoje：今天页面显示的全部内容',
        'recurso=ficha: tudo o que o painel de um relógio mostra (ou o cadastro de um novo)' => 'recurso=ficha：一块手表的面板显示的全部内容（或新建的档案）',
        'recurso=config: a Configuração inteira' => 'recurso=config：完整的设置',
        'recurso=desejos: a lista de desejos e os relógios fora da coleção' => 'recurso=desejos：心愿单以及收藏之外的手表',
        'recurso=passaporte: a ficha de um relógio para imprimir, tudo já em texto' => 'recurso=passaporte：一块手表供打印的档案，全部已经是文本',
        'recurso=galeria: a coleção em fotos, por grupo' => 'recurso=galeria：以照片展示的收藏，按分组',
        'recurso=hora_certa: a hora do servidor, o fuso, o UTC, a letra militar, o calendário e a lua (sem banco)' => 'recurso=hora_certa：服务器时间、时区、UTC、军用字母、日历和月相（不用数据库）',
        'recurso=estatisticas: o uso da coleção num período, por relógio, dia da semana e mês, e a distribuição da coleção' => 'recurso=estatisticas：一段时间内收藏的使用情况，按手表、星期几和月份，以及收藏的分布',
        'recurso=historico: a linha do tempo de um relógio, com os filtros e o resumo' => 'recurso=historico：一块手表的时间线，带筛选和摘要',
        'recurso=plano: o plano dia a dia, o resumo por relógio e as páginas' => 'recurso=plano：逐日计划、按手表的摘要以及分页',
        'recurso=cron: as execuções do cron, com os filtros, o resumo e as páginas' => 'recurso=cron：cron 的执行，带筛选、摘要和分页',
        'recurso=arvore: a árvore dos grupos e o grupo de cada relógio' => 'recurso=arvore：分组树以及每块手表的分组',
        'recurso=cadastros: os campos, os tipos de lançamento, as fórmulas, os avisos, os modos e as categorias' => 'recurso=cadastros：字段、记录类型、公式、提醒、模式和类别',
        'recurso=calcular: o resultado de uma fórmula para um relógio (ou para todos)' => 'recurso=calcular：一个公式对一块手表（或全部）的结果',
        'recurso=documentos: os documentos de um relógio (ou de todos), as categorias e o limite' => 'recurso=documentos：一块手表（或全部）的文档、类别和限制',
        'recurso=documento: um arquivo de um documento (o original, a miniatura, a página de um PDF)' => 'recurso=documento：一个文档的一个文件（原件、缩略图、PDF 的一页）',
        'recurso=backup: as cópias de segurança da pasta, e uma cópia para baixar (arquivo=)' => 'recurso=backup：文件夹中的安全副本，以及一份供下载的副本（arquivo=）',
        'recurso=migracoes: as migrações pendentes do banco (a leitura) e aplicar (a escrita)' => 'recurso=migracoes：数据库待应用的迁移（读取）以及应用（写入）',
        'recurso=codigo: o código do sistema como está agora, arquivo por arquivo' => 'recurso=codigo：系统现在的代码，逐个文件',
        'recurso=ajuda: a documentação da API (cada consulta, cada escrita e o dicionário dos campos, a fonte única dele)' => 'recurso=ajuda：API 文档（每一次查询、每一次写入以及字段词典，它的唯一来源）',
        'as escritas (POST): cada recurso e ação vai para a função dele no operacoes.php, que valida, grava e responde' => '写入（POST）：每个资源和操作进入 operacoes.php 中它的函数，该函数校验、写入并响应',
        'o núcleo: o token, o login, a árvore, os campos, os lançamentos, o motor das fórmulas, os avisos, os critérios, o rodízio, a escala e as listas do código' => '核心：令牌、登录、树、字段、记录、公式引擎、提醒、标准、轮换、排班表以及代码中的列表',
        'as escritas: cada ação valida, grava e devolve ok, mensagem e erros (a API chama estas funções)' => '写入：每个操作校验、写入并返回 ok、消息和错误（API 调用这些函数）',
        'o banco: MySQL/MariaDB, PostgreSQL, SQLite ou Firebird, o SQL escrito uma vez só e traduzido para cada um, e o catálogo do modelo' => '数据库：MySQL/MariaDB、PostgreSQL、SQLite 或 Firebird，SQL 只写一次并翻译到每一种，以及模型目录',
        'a reconstrução (recurso=reconstrucao): as regras de cada parte, a especificação das telas e esta lista do código' => '重建（recurso=reconstrucao）：每一部分的规则、各页面的规格以及这份代码清单',
        'o cron, a cada minuto: as mensagens, o pulso sozinho, a agenda, a manutenção dos documentos, sempre mudo e registrado no banco' => 'cron，每分钟：消息、独自上手腕、日历、文档维护，始终沉默并记录在数据库中',
        'a instalação pelo servidor (a mesma do POST recurso=instalacao)' => '通过服务器安装（与 POST recurso=instalacao 相同）',
        'a importação do sistema antigo pelo servidor (a mesma do POST recurso=importacao)' => '通过服务器导入旧系统（与 POST recurso=importacao 相同）',
        'criar um usuário ou trocar a senha pelo servidor (o mesmo do POST recurso=usuarios, acao=salvar)' => '通过服务器创建用户或更换密码（与 POST recurso=usuarios、acao=salvar 相同）',
        'o banco inicial (no dialeto do MySQL, traduzido para os outros) e o cadastro que vem pronto, com os critérios iniciais' => '初始数据库（MySQL 方言，翻译到其他方言）以及预置的档案，含初始标准',
        'o modelo do config.php, com cada constante explicada (o config.php de verdade não sai: veja nao_mostrados)' => 'config.php 的模板，每个常量都有说明（真正的 config.php 不输出：见 nao_mostrados）',
        'o Apache: o que abre pelo navegador e o que fica bloqueado' => 'Apache：浏览器能打开的，以及被阻止的',
        'o nginx: o mesmo bloqueio do .htaccess' => 'nginx：与 .htaccess 相同的阻止',
        'o roteiro de aceitação: faz pela API o que uma pessoa faz e tira a fotografia de tudo o que a API devolve' => '验收脚本：通过 API 做一个人会做的事，并拍摄 API 返回的一切的快照',
        'compara duas fotografias do cenário (os quatro bancos, ou a reescrita com a versão atual)' => '比较场景的两份快照（四个数据库，或用当前版本重写后的）',
        'o teste de paridade com um comando: os quatro bancos ao mesmo tempo, numa pasta temporária, e a comparação' => '用一条命令做的一致性测试：四个数据库同时，在临时文件夹中，并进行比较',
        'o config dos testes (o acesso aos bancos pelo ambiente), apontado por RELOGIOS_CONFIG: o config.php de verdade fica intocado' => '测试用的 config（通过环境访问数据库），由 RELOGIOS_CONFIG 指向：真正的 config.php 保持不动',
        'gera o dicionário dos campos do cabeçalho do api.php a partir do da ajuda (a fonte única), e confere que batem' => '根据帮助中的词典生成 api.php 页眉的字段词典（唯一来源），并核对两者一致',
        'confere que todo campo das respostas da API está explicado no dicionário da ajuda' => '核对 API 响应的每个字段都在帮助的词典中有说明',
        'a conferência do layout: todas as telas num navegador, em 15 tamanhos, com dados de estresse, procurando o que quebra' => '布局核对：在浏览器中以 15 种尺寸查看全部页面，使用压力数据，寻找会坏掉的地方',
        'como rodar o teste de paridade e a conferência do layout' => '如何运行一致性测试和布局核对',
        'o manual inteiro: para quem usa, a instalação, a API e como é por dentro' => '完整手册：给使用者、安装、API 以及内部如何构成',
        'o que o sistema antigo fazia e onde está no novo' => '旧系统做什么，以及在新系统中位于何处',
        'a licença' => '许可证',
        'o que nunca entra no repositório (a configuração, as chaves, os bancos)' => '永不进入仓库的内容（配置、密钥、数据库）',
        'as quebras de linha (LF em tudo) e os binários' => '换行（全部为 LF）以及二进制文件',
        'os testes no GitHub a cada push no main: a paridade nos bancos (com a documentação da API) e o layout das telas' => '每次推送到 main 时在 GitHub 上的测试：各数据库的一致性（含 API 文档）以及页面布局',
        'confere os dicionários dos idiomas com o código (o texto que falta, o que sobra, o parâmetro diferente) e a origem de cada manual traduzido; junta traduções novas (--juntar)' => '把各语言的词典与代码对照（缺少的文本、多余的文本、不同的参数）以及每份翻译手册的来源；合并新的翻译（--juntar）',
        'a conferência da arquitetura: as páginas sem banco, a rede das telas só pela API, o banco só no núcleo, na API e no cron, os scripts de linha de comando como atalhos da API, a guarda do api/, o bloqueio pela web, a API e o config.php documentados, as migrações e o repositório' => '架构检查：页面不碰数据库，界面的网络请求只经过 API，数据库只由核心、API 和 cron 访问，命令行脚本是 API 的快捷方式，api/ 的保护，Web 访问的屏蔽，API 和 config.php 已有文档，迁移以及代码仓库',
        'monta o README de cada idioma (README.<idioma>.md) a partir do manual traduzido e do resto traduzido, e confere que estão em dia (--conferir)' => '根据翻译后的手册和翻译后的其余部分生成每种语言的 README（README.<idioma>.md），并检查它们是否最新（--conferir）',
        'o dicionário do idioma {1}: o texto em português => a tradução, por parte (telas, api, cadastro, ajuda, reconstrucao)' => '语言 {1} 的词典：葡萄牙语文本 => 译文，按部分划分（telas、api、cadastro、ajuda、reconstrucao）',
        'o manual da página Ajuda no idioma {1} (as seções do README para quem usa), com a origem na primeira linha' => '语言 {1} 的帮助页面手册（README 中面向用户的章节），第一行是来源',
        'o resto do README no idioma {1} (o que não está no manual), com a origem na primeira linha' => '语言 {1} 的 README 其余部分（不在手册中的内容），第一行是来源',
        'o README no idioma {1}, montado por testes/readme.php (não editar à mão)' => '语言 {1} 的 README，由 testes/readme.php 生成（不要手动编辑）',
        'tem as senhas do banco e o API_TOKEN' => '含有数据库密码和 API_TOKEN',
        'o config.exemplo.php (o modelo, com cada constante explicada) e listas.config_php no recurso=reconstrucao' => 'config.exemplo.php（模板，每个常量都有说明）以及 recurso=reconstrucao 中的 listas.config_php',
        'a chave JSON do Google (google-conta-servico.json ou o caminho da Configuração)' => 'Google 的 JSON 密钥（google-conta-servico.json 或设置中的路径）',
        'é uma credencial' => '它是一项凭据',
        'a seção mensagens do recurso=reconstrucao e o README (Google Agenda): como criar a conta de serviço e a chave' => 'recurso=reconstrucao 的 mensagens 一节以及 README（Google 日历）：如何创建服务账号和密钥',
        'o banco de dados (o servidor MySQL/PostgreSQL/Firebird, ou o arquivo do SQLite)' => '数据库（MySQL/PostgreSQL/Firebird 服务器，或 SQLite 文件）',
        'são os dados, não o código' => '它们是数据，不是代码',
        'o modelo em modelo_de_dados (recurso=reconstrucao) e os dados pela própria API (api.php sem recurso: tudo o que está guardado)' => 'modelo_de_dados 中的模型（recurso=reconstrucao）以及通过 API 本身取得的数据（不带 recurso 的 api.php：已保存的全部内容）',
        'a pasta dos documentos (DOCUMENTOS_PASTA)' => '文档文件夹（DOCUMENTOS_PASTA）',
        'são os arquivos de cada relógio, não o código' => '它们是每块手表的文件，不是代码',
        'recurso=documentos (a lista) e recurso=documento (cada arquivo)' => 'recurso=documentos（列表）和 recurso=documento（每个文件）',
        'as senhas dos usuários' => '用户密码',
        'não existem no sistema: só o hash' => '系统中不存在：只有哈希',
        'recurso=usuarios (o login e o hash) e senhas na ajuda (como conferir e migrar)' => 'recurso=usuarios（登录名和哈希）以及帮助中的 senhas（如何核对和迁移）',
        'a migração ' => '迁移 ',
        'a captura de tela: ' => '屏幕截图： ',
        'text/plain; charset=utf-8' => 'text/plain; charset=utf-8',
        'O código do sistema como está agora, lido do disco na hora: cada arquivo com a camada, o que ele é, o tamanho e o SHA-256. Um arquivo: arquivo=<nome> (o conteúdo como está, em conteudo; a imagem em conteudo_base64); com cru=1, o arquivo puro, sem JSON (texto como text/plain, para ler no navegador). Numa página, html traz o HTML que o navegador recebe, já montado (html=1 com cru=1: só ele), e usa, os arquivos que ela carrega. Todos de uma vez: conteudo=1 (com os filtros: f[arquivos][camada]=tela traz o HTML, o CSS e o JavaScript das telas). O que fica de fora de propósito está em nao_mostrados, com o que ver no lugar.' => '系统现在的代码，当时从磁盘读取：每个文件带层次、它是什么、大小和 SHA-256。单个文件：arquivo=<名称>（内容原样放在 conteudo 中；图像在 conteudo_base64 中）；cru=1 时为纯文件，无 JSON（文本为 text/plain，供在浏览器中阅读）。在一个页面上，html 带来浏览器收到的、已经组装好的 HTML（html=1 且 cru=1：只有它），usa 为它加载的文件。一次全部：conteudo=1（带筛选：f[arquivos][camada]=tela 带来各页面的 HTML、CSS 和 JavaScript）。有意排除的内容在 nao_mostrados 中，并说明用什么代替查看。',
        'as páginas: o esqueleto em PHP, o estilo e o JavaScript que lê a API e monta a tela' => '各页面：PHP 骨架、样式以及读取 API 并组装页面的 JavaScript',
        'o back-end: a API e o que ela usa (o núcleo, as escritas, o banco, a reconstrução)' => '后端：API 以及它使用的部分（核心、写入、数据库、重建）',
        'o cron e os scripts do servidor' => 'cron 以及服务器脚本',
        'o banco inicial e as migrações' => '初始数据库以及迁移',
        'a configuração do servidor web e o modelo do config.php' => 'Web 服务器的配置以及 config.php 的模板',
        'o roteiro de aceitação e a comparação' => '验收脚本以及比较',
        'o README e os outros textos' => 'README 以及其他文本',
        'os arquivos do git' => 'git 的文件',
        'as capturas das telas' => '各页面的截图',
        ' ou mais' => ' 或更多',
        'O Relojoeiro (Relógios 2) planeja o rodízio de uma coleção de relógios: escolhe o relógio de cada dia pela nota de cada um (critérios com pesos) e pelas regras do modo de rodízio, acompanha a energia de cada um (bateria, reserva de marcha, carga de luz, vida da pilha) pelas fórmulas do cadastro e pelo histórico de lançamentos, avisa o que fazer (carregar, dar corda, pôr no sol, trocar a pilha, revisão) pelo Telegram e pelo Google Agenda, mede o gasto real da bateria pelas leituras e guarda os documentos de cada relógio. Esta resposta é o roteiro para reescrever o sistema inteiro do zero e chegar ao mesmo comportamento.' => 'Relojoeiro（Relógios 2）为一套手表收藏规划轮换：按每一块的分数（带权重的标准）以及轮换模式的规则选择每一天的手表，通过档案中的公式和记录历史跟踪每一块的能量（充电电池、动力储存、光充电量、原电池寿命），通过 Telegram 和 Google 日历告知要做什么（充电、上链、晒太阳、更换电池、检修），根据读数测量电池的实际消耗，并保存每块手表的文档。此响应是从零完整重写整个系统并达到相同行为的路线。',
        'Leia as seções na ordem: os princípios e a arquitetura, a ordem de construção, e cada módulo com as suas regras.' => '按顺序阅读各节：原则与架构、构建顺序，以及每个模块及其规则。',
        'O modelo de dados (modelo_de_dados) é o do banco em uso agora, lido dele: tabelas, colunas, chaves, índices e regras de validação. Os tipos vêm no dialeto desse banco; o dialeto de referência (MySQL) está no schema.sql.' => '数据模型（modelo_de_dados）是现在正在使用的数据库的模型，从它读取：表、列、键、索引和校验规则。类型以该数据库的方言给出；参考方言（MySQL）在 schema.sql 中。',
        'O contrato da API (cada consulta com parâmetros e exemplo, cada escrita com ações e campos, e o significado de cada campo das respostas) está em api.php?recurso=ajuda: a reescrita deve responder igual, para as telas, os scripts e quem integra continuarem funcionando.' => 'API 契约（每一次查询及其参数和示例、每一次写入及其操作和字段，以及响应中每个字段的含义）在 api.php?recurso=ajuda：重写必须同样响应，以便页面、脚本和集成方继续工作。',
        'O conhecimento sobre relógios não está no código: está no cadastro inicial (schema.sql, a partir de "-- critérios iniciais" para os critérios; os campos, os tipos de lançamento, as fórmulas, os avisos e os modos nas migrações). Leia também por recurso=cadastros e recurso=criterios. A reescrita traz esse cadastro como dado, não como código.' => '关于手表的知识不在代码中：它在初始档案中（schema.sql，标准从 "-- critérios iniciais" 起；字段、记录类型、公式、提醒和模式在迁移中）。也请通过 recurso=cadastros 和 recurso=criterios 阅读。重写把这份档案作为数据带来，而不是作为代码。',
        'As telas (telas) são a especificação visual: o visual com os valores exatos, o menu e cada página, parte por parte, com cada tabela, campo, botão e mensagem, palavra por palavra. A reescrita reproduz a mesma interface, não uma parecida: o que está lá existe, e o que não está não existe. As capturas em docs/telas/ mostram o resultado.' => '各页面（telas）是视觉规格：带精确数值的视觉、菜单和每一页，一部分一部分，含每张表、字段、按钮和消息，逐词。重写要再现同一界面，而不是相似的：那里有的就存在，那里没有的就不存在。docs/telas/ 中的截图显示结果。',
        'O código de verdade, como está agora, sai pelo recurso=codigo (a lista em codigo, abaixo): o CSS, o JavaScript, cada página e o HTML que ela entrega ao navegador, a API, o banco e o resto, lido do disco na hora (arquivo=<nome>; cru=1 para o arquivo puro). Cada página em telas diz os arquivos dela (codigo). O que não sai (o config.php, as chaves, os dados) está em codigo.nao_mostrados, com o que ver no lugar.' => '真正的代码，现在的样子，由 recurso=codigo 输出（清单在下面的 codigo 中）：CSS、JavaScript、每一页以及它交给浏览器的 HTML、API、数据库和其余部分，当时从磁盘读取（arquivo=<名称>；cru=1 为纯文件）。telas 中的每一页标明它的文件（codigo）。不输出的内容（config.php、密钥、数据）在 codigo.nao_mostrados 中，并说明用什么代替查看。',
        'O README.md explica cada tela e cada opção para quem usa (as seções para quem usa saem também pela API, em recurso=manual: o texto da página Ajuda); o testes/cenario.php é o roteiro de aceitação (veja a seção testes).' => 'README.md 向使用者说明每一页和每一个选项（给使用者的各节也由 API 输出，在 recurso=manual：帮助页面的文本）；testes/cenario.php 是验收脚本（见 testes 一节）。',
        'Os princípios (não negociáveis)' => '原则（不可协商）',
        'O sistema não sabe nada de relógios: o código tem só mecanismos (árvore, campos, tipos de lançamento, fórmulas, avisos, critérios, modos). Que um automático tem reserva de marcha, ou que um solar carrega no sol, está escrito em fórmulas cadastradas, que o usuário lê, edita e testa pela tela. Mudar uma regra de relógio é mudar cadastro (com uma migração), não código.' => '系统对手表一无所知：代码里只有机制（树、字段、记录类型、公式、提醒、标准、模式）。自动表有动力储存，或太阳能表在太阳下充电，这些写在已登记的公式中，用户通过页面阅读、编辑和测试。改变一条手表规则是改变档案（带一次迁移），不是改变代码。',
        'Tudo pela API: as páginas só desenham; toda leitura e toda gravação passa pela API, a mesma que um script usa. Nenhuma regra de negócio no navegador além de mostrar e esconder campos.' => '一切通过 API：页面只绘制；每一次读取和每一次写入都经过 API，脚本使用的是同一个。除了显示和隐藏字段，浏览器中没有任何业务规则。',
        'Falha segura: sem token válido, com o fuso inválido ou com o banco desatualizado (migração pendente), o sistema para e diz o motivo (a API responde 500 ou 503, o cron registra e não faz nada), em vez de rodar pela metade.' => '故障安全：没有有效令牌、时区无效或数据库未更新（有待应用的迁移）时，系统停止并说明原因（API 响应 500 或 503，cron 记录且什么都不做），而不是做到一半。',
        'O banco se defende: relacional e normalizado, toda ligação é chave estrangeira (obrigatória: some junto, ON DELETE CASCADE; opcional: a ligação se desfaz, SET NULL), nenhuma lista guardada como texto, e regras de validação (CHECK, NOT NULL, UNIQUE) iguais às da tela. Uma gravação errada é recusada pelo banco venha de onde vier (a API responde 409 com a regra quebrada).' => '数据库自我防护：关系型且规范化，每一条关联都是外键（必填：一起消失，ON DELETE CASCADE；可选：关联解除，SET NULL），没有任何列表以文本保存，校验规则（CHECK、NOT NULL、UNIQUE）与页面相同。错误的写入无论来自何处都被数据库拒绝（API 以被打破的规则响应 409）。',
        'Os mesmos resultados em MySQL/MariaDB, PostgreSQL, SQLite e Firebird: o SQL do sistema é escrito uma vez só; o que muda de banco para banco fica numa camada de tradução. Maiúsculas e acentos não contam nos textos curtos ("Relógio" = "RELOGIO"), em todos; no MySQL/MariaDB, toda tabela em utf8mb4_unicode_ci (a utf8mb4_general_ci, padrão do MariaDB, ordena diferente); no Firebird, a collation UNICODE_CI_AI.' => '在 MySQL/MariaDB、PostgreSQL、SQLite 和 Firebird 上结果相同：系统的 SQL 只写一次；随数据库变化的部分放在翻译层。在所有库中，短文本不区分大小写和重音（“Relógio” = “RELOGIO”）；在 MySQL/MariaDB 中，每张表为 utf8mb4_unicode_ci（MariaDB 默认的 utf8mb4_general_ci 排序不同）；在 Firebird 中，collation 为 UNICODE_CI_AI。',
        'Datas e horas no fuso do sistema (FUSO). Nas fórmulas, o tempo é contado em dias no horário local: a meia-noite local de qualquer data é um número inteiro e a fração é a hora do dia; assim uma data e o agora entram na mesma conta sem o fuso aparecer.' => '日期和时刻用系统时区（FUSO）。在公式中，时间按本地时间以天计数：任意日期的本地午夜是一个整数，小数是一天中的时刻；这样日期和现在进入同一计算而时区不出现。',
        'O cron é mudo e rastreável: roda a cada minuto, não escreve na saída, e registra no banco o que fez.' => 'cron 沉默且可追溯：每分钟运行，不向输出写任何内容，并在数据库中记录所做的事。',
        'Mensagens que explicam o que fazer ("Dê um nome ao relógio (até 120 caracteres)."), em seis idiomas: português (o original), inglês, chinês simplificado, hindi, espanhol e francês. Nenhum texto fixo: todo texto que alguém lê passa por t("o texto em português", parâmetros), com o português como chave (como no gettext) e os parâmetros entre chaves ({1}, {nome}) trocados depois da tradução; cada idioma tem o seu dicionário (o texto em português => a tradução), e o que falta sai em português. O idioma de cada pessoa é dela (o seletor do menu, guardado no navegador); quem não escolheu vê o padrão da instalação (config.idioma), senão o do navegador, senão português. As datas e os números seguem o idioma. Os nomes cadastrados ficam como foram escritos.' => '说明要做什么的消息（“给手表起一个名称（最多 120 个字符）。”），六种语言：葡萄牙语（原文）、英语、简体中文、印地语、西班牙语和法语。没有固定文本：任何人阅读的每一段文本都经过 t(“葡萄牙语文本”, 参数)，以葡萄牙语为键（如同 gettext），花括号中的参数（{1}、{nome}）在翻译之后替换；每种语言有自己的词典（葡萄牙语文本 => 译文），缺少的以葡萄牙语输出。每个人的语言是他自己的（菜单中的选择器，保存在浏览器中）；没有选择的人看到安装的默认（config.idioma），否则是浏览器的，否则是葡萄牙语。日期和数字跟随语言。已登记的名称保持原样书写。',
        'A arquitetura' => '架构',
        'Um back-end único, a API (api.php): GET lê (recurso=...), POST grava (recurso=... e acao=...). Responde JSON (ou XML com formato=xml). O api.php faz a porta (a autenticação, o formato, a ordem dos recursos, os filtros e a resposta); cada recurso grande fica num arquivo da pasta api/ (api/hoje.php, api/ficha.php, api/ajuda.php...), que roda dentro dele, com as mesmas variáveis. Autenticação em todo pedido: o token (cabeçalho X-Api-Token ou parâmetro token, igual ao API_TOKEN) ou o login do site (HTTP Basic com usuário e senha da tabela usuario, senha com password_hash).' => '单一后端，即 API（api.php）：GET 读取（recurso=...），POST 写入（recurso=... 和 acao=...）。响应 JSON（或 formato=xml 时为 XML）。api.php 做入口（身份验证、格式、资源顺序、筛选和响应）；每个大资源放在 api/ 文件夹的一个文件中（api/hoje.php、api/ficha.php、api/ajuda.php……），在它内部运行，使用相同的变量。每个请求都要身份验证：令牌（请求头 X-Api-Token 或参数 token，等于 API_TOKEN）或网站登录（HTTP Basic，使用 usuario 表的用户名和密码，密码用 password_hash）。',
        'Um núcleo (lib.php): o motor das fórmulas, as variáveis de cada relógio, os avisos, as notas, o plano, a escala, a previsão, o gasto medido, o pulso sozinho, a linha do tempo, as mensagens, a agenda e os documentos.' => '一个核心（lib.php）：公式引擎、每块手表的变量、提醒、分数、计划、排班表、预测、实测消耗、独自上手腕、时间线、消息、日历和文档。',
        'As gravações (operacoes.php): uma função por recurso (op_relogio, op_lancamento, op_campos...), que valida tudo, grava e devolve {ok, mensagem, erros[], ...}. A tela e a API chamam as mesmas.' => '写入（operacoes.php）：每个资源一个函数（op_relogio、op_lancamento、op_campos……），校验一切、写入并返回 {ok, mensagem, erros[], ...}。页面和 API 调用相同的函数。',
        'O banco (banco.php): a conexão com as extensões do PHP (mysqli, pgsql, sqlite3, pdo_firebird), parâmetros sempre por ? (nunca texto colado no SQL), e a tradução do dialeto do MySQL para os outros: AUTO_INCREMENT, ENUM (vira CHECK ... IN), TINYINT, DATETIME, os INDEX dentro do CREATE TABLE, AFTER, MODIFY COLUMN (o SQLite refaz a tabela), INSERT IGNORE, REPLACE INTO, NOW(), <=>, LIKE sem diferenciar maiúsculas; no Firebird, também LIMIT/OFFSET (OFFSET ... ROWS FETCH NEXT ... ROWS ONLY), DATE(x) (CAST AS DATE), CONCAT (||), LENGTH/LEAST/GREATEST (OCTET_LENGTH/MINVALUE/MAXVALUE), o SELECT sem FROM (FROM RDB$DATABASE), o INSERT de várias linhas (um por linha), a tabela no (palavra reservada: "NO"), nomes de índice e de regra com até 31 letras, o TEXT como VARCHAR(8191) e a chave única de várias colunas com coluna vazia como índice único de uma expressão; e três comandos próprios das migrações: ALTER FOREIGN KEY, DROP COLUMN e ADD CONSTRAINT ... CHECK (trocando a regra sem perder a anterior se os dados não cumprem a nova).' => '数据库（banco.php）：用 PHP 扩展连接（mysqli、pgsql、sqlite3、pdo_firebird），参数始终用 ?（绝不把文本拼进 SQL），并把 MySQL 方言翻译到其他库：AUTO_INCREMENT、ENUM（变成 CHECK ... IN）、TINYINT、DATETIME、CREATE TABLE 内部的 INDEX、AFTER、MODIFY COLUMN（SQLite 重建表）、INSERT IGNORE、REPLACE INTO、NOW()、<=>、不区分大小写的 LIKE；在 Firebird 中，还有 LIMIT/OFFSET（OFFSET ... ROWS FETCH NEXT ... ROWS ONLY）、DATE(x)（CAST AS DATE）、CONCAT（||）、LENGTH/LEAST/GREATEST（OCTET_LENGTH/MINVALUE/MAXVALUE）、没有 FROM 的 SELECT（FROM RDB$DATABASE）、多行 INSERT（一行一条）、表 no（保留字：“NO”）、索引名和规则名最多 31 个字母、TEXT 作为 VARCHAR(8191)，以及含空列的多列唯一键作为表达式的唯一索引；还有迁移专用的三条命令：ALTER FOREIGN KEY、DROP COLUMN 和 ADD CONSTRAINT ... CHECK（若数据不满足新规则，则更换规则而不丢掉旧的）。',
        'As páginas (index.php, plano.php, desejos.php, estatisticas.php, hora.php, acessorios.php, galeria.php, passaporte.php, ficha.php, documentos.php, historico.php, configuracao.php, criterios.php, grupos.php, cadastros.php, execucoes.php, usuarios.php, ajuda.php) só entregam o esqueleto, sem conferir nem o login; o JavaScript de cada uma (hoje.js, painel.js, configuracao.js, ajuda.js...) chama a API e monta a tela, sem fazer conta: resumos, porcentagens e situações (o resumo do plano, a porcentagem de cada estado no histórico, o peso efetivo dos critérios, a situação do cron, o manual em HTML) vêm prontos da API. Formulários com data-recurso gravam pela API e a página se remonta com a resposta.' => '各页面（index.php、plano.php、desejos.php、estatisticas.php、hora.php、acessorios.php、galeria.php、passaporte.php、ficha.php、documentos.php、historico.php、configuracao.php、criterios.php、grupos.php、cadastros.php、execucoes.php、usuarios.php、ajuda.php）只交付骨架，连登录都不核对；每一页的 JavaScript（hoje.js、painel.js、configuracao.js、ajuda.js……）调用 API 并组装页面，不做计算：摘要、百分比和情况（计划摘要、历史中每种状态的百分比、标准的有效权重、cron 的情况、HTML 手册）都由 API 准备好。带 data-recurso 的表单通过 API 写入，页面用响应重新组装。',
        'A API faz tudo, inclusive o que vem antes das telas: a instalação do banco vazio (recurso=instalacao, pelo token), o primeiro usuário (recurso=usuarios pelo token), a importação do sistema anterior (recurso=importacao) e o login das páginas (recurso=entrar: a página sem login recebe 401 da API, o api.js manda para api.php?recurso=entrar&volta=<a página>, o navegador pede o usuário e a senha e a API devolve para a página). Os scripts de linha de comando (instalar.php, criar_usuario.php, importar.php) só chamam as mesmas operações.' => 'API 做一切，包括页面之前的事：空数据库的安装（recurso=instalacao，用令牌）、第一个用户（用令牌的 recurso=usuarios）、从前一个系统导入（recurso=importacao）以及页面登录（recurso=entrar：没有登录的页面从 API 收到 401，api.js 转到 api.php?recurso=entrar&volta=<该页>，浏览器询问用户名和密码，API 再回到该页）。命令行脚本（instalar.php、criar_usuario.php、importar.php）只调用相同的操作。',
        'Fora da API, só o cron (cron.php), a cada minuto pela linha de comando, com as mesmas funções que a API usa; o que ele fez sai em recurso=cron.' => 'API 之外，只有 cron（cron.php），每分钟由命令行运行，使用 API 所用的相同函数；它所做的出现在 recurso=cron 中。',
        'Sem framework e sem dependências: PHP 8.1+ e JavaScript puro. A reescrita pode usar outra pilha, desde que mantenha o contrato da API, o modelo de dados e as regras.' => '没有框架、没有依赖：PHP 8.1+ 和纯 JavaScript。重写可以使用另一套技术栈，只要保持 API 契约、数据模型和规则。',
        'A ordem de construção' => '构建顺序',
        '1. O banco: as tabelas do modelo_de_dados, com as chaves e as regras; a instalação (o schema inteiro num banco vazio) e as migrações (uma lista ordenada; cada uma com o SQL, um passo opcional em programa, e uma marca de aplicada: uma tabela, uma coluna ou uma linha da config; com alguma pendente, o sistema para e a Configuração mostra o botão de aplicar).' => '1. 数据库：modelo_de_dados 的各表，带键和规则；安装（空数据库中的完整 schema）以及迁移（一份有序列表；每一项含 SQL、程序中的一个可选步骤，以及已应用标记：一张表、一列或 config 的一行；有任何待处理项时，系统停止，设置显示应用按钮）。',
        '2. O cadastro inicial (a árvore Smartwatch / Tradicional › Mecânico › Automático e Corda manual / Tradicional › Quartzo › Pilha e Solar, os campos, os tipos de lançamento, as fórmulas, os avisos, os critérios e os modos) como dados.' => '2. 初始档案（树 Smartwatch / 传统 › 机械 › 自动 和 手上链 / 传统 › 石英 › 电池 和 太阳能，字段、记录类型、公式、提醒、标准和模式）作为数据。',
        '3. A autenticação (token e HTTP Basic) e o esqueleto da API: os formatos, os erros (400, 401, 404, 409, 413, 500, 503) e os filtros genéricos de qualquer consulta (incluir, excluir, f[], busca, ordem, limite, pagina, mostrar).' => '3. 身份验证（令牌和 HTTP Basic）以及 API 骨架：格式、错误（400、401、404、409、413、500、503）以及任意查询的通用筛选（incluir、excluir、f[]、busca、ordem、limite、pagina、mostrar）。',
        '4. A árvore, os campos (com a validação do valor pelo tipo), os relógios e as fotos.' => '4. 树、字段（按类型校验值）、手表和照片。',
        '5. Os tipos de lançamento e os lançamentos (instantâneo, com valor, sessão; sessão exclusiva fecha as outras exclusivas no mesmo instante; sem sobreposição de sessões do mesmo tipo), e a linha do tempo.' => '5. 记录类型和记录（瞬时、带数值、时段；独占时段在同一时刻结束其他独占时段；同一类型的时段不重叠），以及时间线。',
        '6. O motor das fórmulas (abaixo), as variáveis de um relógio e o botão Testar.' => '6. 公式引擎（见下）、一块手表的变量以及测试按钮。',
        '7. Os avisos, a visão de cada relógio (agora, carga, situação, próxima manutenção) e a página Hoje.' => '7. 提醒、每块手表的视图（现在、电量、情况、下次保养）以及今天页面。',
        '8. O gasto medido pelas leituras e a previsão da energia (autonomia).' => '8. 由读数得出的实测消耗以及能量预测（续航）。',
        '9. Os critérios e a nota; os modos de rodízio, o plano, a garantia de rodízio, trocar o dia, sortear de novo; a escala inteligente.' => '9. 标准和分数；轮换模式、计划、轮换保障、更换某一天、重新抽签；智能排班表。',
        '10. O pulso sozinho e as sessões esquecidas; o cron.' => '10. 独自上手腕以及被忘记的时段；cron。',
        '11. As mensagens (Telegram), a agenda (Google), os eventos personalizados e a tabela "O que vai para onde".' => '11. 消息（Telegram）、日历（Google）、自定义事件以及表“发往何处”。',
        '12. Os documentos (pasta, cópia no banco em três níveis, galeria, vídeos, PDF, NF-e) e a manutenção deles no cron.' => '12. 文档（文件夹、数据库副本的三级、图库、视频、PDF、NF-e）以及 cron 中对它们的维护。',
        '13. As telas, os usuários, as execuções do cron, a ajuda (o README dentro do sistema: os mesmos trechos que recurso=manual devolve) e a importação do sistema anterior.' => '13. 各页面、用户、cron 执行、帮助（系统内的 README：与 recurso=manual 返回的相同片段）以及从前一个系统导入。',
        '14. A aceitação: o roteiro de testes nos quatro bancos dá as mesmas respostas (seção testes).' => '14. 验收：四个数据库上的测试脚本给出相同响应（testes 一节）。',
        'A árvore, os campos e os relógios' => '树、字段和手表',
        'A árvore de grupos tem quantos níveis o usuário quiser; um relógio fica num grupo só (ou na raiz). Tudo o que se cadastra num grupo (campos, tipos de lançamento, fórmulas, avisos, critérios, a origem de um bloco de modo) vale para ele e para tudo abaixo dele.' => '分组树有用户想要的多少层；一块手表只在一个分组中（或在根）。登记在一个分组上的一切（字段、记录类型、公式、提醒、标准、模式区块的来源）对该分组及其下的一切有效。',
        'O mesmo nome pode se repetir em ramos diferentes, mas não entre irmãos. Mover um grupo para dentro dele mesmo (ou de um de dentro) é recusado. Excluir um grupo pela tela passa antes o que era dele para o grupo de cima (os de dentro, os relógios, os campos, os tipos, as fórmulas, os avisos e os blocos que sorteavam dele); versões de fórmula e de aviso que o grupo de cima já tem saem.' => '同一名称可以在不同分支重复，但不能在兄弟之间重复。把一个分组移入它自己（或它内部的一个）会被拒绝。通过页面删除一个分组时，先把它的内容交给上级分组（内部的、手表、字段、类型、公式、提醒以及从它抽签的区块）；上级分组已经有的公式版本和提醒版本则去掉。',
        'Campos: identificador (minúsculas, números e _, começando por letra, até 40; único entre campos e fórmulas, porque é o nome nas fórmulas; não muda se alguma fórmula usa), nome, tipo (listas.tipos_de_campo), unidade, valor padrão, o grupo, a ordem e a marca só nos desejados (so_desejado). Os campos de um relógio são os de todos e os de cada grupo da cadeia dele (os só nos desejados, só no desejado).' => '字段：标识符（小写、数字和 _，以字母开头，最多 40；在字段和公式之间唯一，因为它是公式中的名称；若有公式使用则不能改）、名称、类型（listas.tipos_de_campo）、单位、默认值、分组、顺序以及仅心愿中的标记（so_desejado）。一块手表的字段是全部的以及它链条上每个分组的（仅心愿中的，只在心愿中）。',
        'O valor de um campo é conferido e normalizado pelo tipo: inteiro; decimal (aceita 1.079,99, 1079,99 e 1079.99, grava com ponto); sim/não (1, sim, s, true; 0, não, nao, n, false); data AAAA-MM-DD; lista (uma das opções); texto (até 1000). Vazio apaga. O valor usado nas contas é o informado, senão o padrão do campo.' => '字段的值按类型核对并规范化：整数；小数（接受 1.079,99、1079,99 和 1079.99，以点保存）；是/否（1、sim、s、true；0、não、nao、n、false）；日期 AAAA-MM-DD；列表（选项之一）；文本（最多 1000）。空则删除。计算中使用的值是已填写的，否则是字段的默认。',
        'A situação na coleção de cada relógio (posse): colecao (o padrão), desejado (a lista de desejos), emprestado, vendido ou arquivado. Só o que está na coleção entra no rodízio: nas outras, o relógio fica indisponível (o banco garante, ck_relogio_posse_disponivel; a gravação força disponivel=0 e diz isso na mensagem), e por isso sai do sorteio, da escala e dos avisos sem regra a mais. Saindo da coleção, as sessões abertas dele fecham agora (com a nota "Fechei agora: ..."), os dias dele no plano de amanhã em diante saem e são sorteados de novo (com escala, gerar_escala de amanhã; sem, garantir_plano); hoje fica, mas a sessão do dia (o pulso sozinho) não abre para um relógio fora da coleção. Voltando para a coleção sem dizer o disponível, ele fica disponível. Da coleção (contam na tabela da página Hoje e no valor): na coleção e emprestado (o estado do emprestado parado é "Emprestado"); desejado, vendido e arquivado vão para fora_da_colecao (recurso=hoje) e para a página Desejos. Um campo com so_desejado=1 (o preço-alvo, a prioridade) vale só no desejado: campos_do_relogio o deixa de fora nos outros, e a gravação dos valores também. A lista de desejos (recurso=desejos) vem da prioridade mais alta para a mais baixa (a ordem das opções do campo prioridade_desejo; sem prioridade, no fim), depois pelo nome, com a soma dos preços-alvo; no painel do desejado, o quadro Desejo e os documentos tomam o lugar dos do dia a dia.' => '每块手表在收藏中的情况（posse）：colecao（默认）、desejado（心愿单）、emprestado、vendido 或 arquivado。只有在收藏中的才进入轮换：在其他情况中，手表变为不可用（数据库保证，ck_relogio_posse_disponivel；写入强制 disponivel=0 并在消息中说明），因此无需额外规则就离开抽签、排班表和提醒。离开收藏时，它已打开的时段现在结束（说明“现在结束了：……”），它在计划中从明天起的日子被去掉并重新抽签（有排班表时，从明天 gerar_escala；没有时，garantir_plano）；今天保留，但当天的时段（独自上手腕）不会为收藏之外的手表打开。回到收藏而未说明可用时，它变为可用。属于收藏（计入今天页面的表格和金额）：在收藏中和已借出（已借出停着的状态是“已借出”）；desejado、vendido 和 arquivado 进入 fora_da_colecao（recurso=hoje）以及心愿单页面。so_desejado=1 的字段（目标价格、优先级）只在心愿中有效：campos_do_relogio 在其他情况中把它排除，值的写入也同样。心愿单（recurso=desejos）从最高优先级到最低（prioridade_desejo 字段选项的顺序；没有优先级的在末尾），然后按名称，并带目标价格合计；在心愿中的面板里，心愿框和文档取代逐日的那些。',
        'Acessórios (tabela acessorio): nome (até 120), tipo (pulseira, caixa, estojo, ferramenta, carregador, peca, outro), o relógio de que ele é (opcional: sem ele, solto; excluir o relógio deixa solto, ON DELETE SET NULL), observação (até 1000) e quando foi cadastrado. A lista vem pelo tipo e pelo nome; a ficha traz os do relógio.' => '配件（表 acessorio）：名称（最多 120）、类型（pulseira（表带）、caixa（表盒）、estojo（收纳盒）、ferramenta（工具）、carregador（充电器）、peca（零件）、outro（其他））、它所属的手表（可选：没有则为未绑定；删除手表则变为未绑定，ON DELETE SET NULL）、备注（最多 1000）以及何时登记。列表按类型和名称；详情带来该手表的那些。',
        'Relógio: nome (até 120), grupo, situação na coleção, disponível (fora do rodízio e dos avisos quando não), a marca da cópia no banco dos documentos, a foto (JPEG, PNG ou WebP até 4 MB; o navegador reduz para 1200 px antes de enviar). Excluir apaga junto os valores, a foto, os documentos (e os arquivos), os lançamentos, o plano e os critérios próprios.' => '手表：名称（最多 120）、分组、在收藏中的情况、可用（否时离开轮换和提醒）、文档在数据库中副本的标记、照片（JPEG、PNG 或 WebP，最多 4 MB；浏览器在发送前缩小到 1200 px）。删除会一并去掉值、照片、文档（及文件）、记录、计划和自有标准。',
        'Os tipos de lançamento, os lançamentos e a linha do tempo' => '记录类型、记录和时间线',
        'Formatos (listas.formatos_de_lancamento): instantâneo (corda, troca de pilha), com valor (a leitura de carga, com unidade) e sessão, com início e fim (no pulso, no winder, no sol). Só a sessão tem "fecha às" (a hora em que a esquecida aberta fecha sozinha) e pode ser exclusiva (abrir uma exclusiva fecha as outras exclusivas abertas no mesmo instante: o relógio fica num lugar só). Só o com valor pode medir o gasto. A condição ("vale quando") é uma fórmula: o tipo só vale para os relógios em que ela dá verdadeiro.' => '格式（listas.formatos_de_lancamento）：瞬时（上链、更换电池）、带数值（电量读数，带单位）和时段，有开始和结束（在手腕上、在上链盒中、在晒太阳中）。只有时段有“结束于”（被忘记的已打开时段自行结束的时刻），并且可以是独占的（打开一个独占时段会在同一时刻结束其他已打开的独占时段：手表只在一个地方）。只有带数值的可以测量消耗。条件（“何时有效”）是一个公式：该类型只对它给出真的手表有效。',
        'Lançar: lancar (instantâneo ou com valor, num instante até agora), iniciar e encerrar (uma sessão; encerrar não antes do início), alternar (a sessão aberta se fecha, a fechada se abre: um botão só num atalho de celular), periodo (uma sessão inteira que já passou, sem sobrepor outra exclusiva), alterar e excluir (corrigir uma marcação). Em todas, relogio_id=hoje é o relógio do dia pelo plano. O formato de um tipo não muda depois de ter lançamentos; um tipo com lançamentos não é excluído.' => '记录：lancar（瞬时或带数值，在直到现在的某一时刻）、iniciar 和 encerrar（一个时段；结束不早于开始）、alternar（已打开的时段关闭，已关闭的打开：手机快捷方式上只有一个按钮）、periodo（一段已经过去的完整时段，不与另一个独占时段重叠）、alterar 和 excluir（改正一条标记）。在全部操作中，relogio_id=hoje 是计划中当天的手表。一个类型在已有记录之后不能改格式；有记录的类型不能删除。',
        'A origem: manual (pela tela ou pela API), rodizio (a sessão no pulso do relógio do dia, aberta pelo sistema ou pelo Pôs no relógio do dia) e importado.' => '来源：manual（通过页面或 API）、rodizio（当天手表在手腕上的时段，由系统或“已戴上当天的手表”打开）和 importado。',
        'A linha do tempo de um relógio divide o histórico em trechos contínuos: em uso pelo rodízio, no pulso fora do rodízio, em cada tipo de sessão (no winder, no sol...) e em repouso (o que sobra); e as marcações (corda, carga, pilha, revisão) como pontos, sem duração. O resumo dá o tempo e a porcentagem em cada estado.' => '一块手表的时间线把历史分成连续片段：轮换中的使用中、轮换之外的手腕上、每种时段类型（在上链盒中、在晒太阳中……）以及休息中（剩余的）；标记（上链、电量、电池、检修）作为点，没有时长。摘要给出每种状态的时间和百分比。',
        'O estado de agora de um relógio: em uso (uma sessão no pulso aberta), numa sessão (outra sessão aberta: o estado é o nome do tipo, "No sol", "No winder", "No carregador"; duas juntas, "No sol · No winder") ou em repouso; na tabela da página Hoje, o indisponível em repouso aparece como indisponível. Com o desde quando: o começo da sessão no pulso, o da sessão mais recente, ou o fim da última no pulso ("Em repouso desde 21:40"). A sessão esquecida aberta conta só até o "fecha às" dela. O pulso é o único tipo que o código conhece pelo identificador; os outros entram pelo nome.' => '一块手表现在的状态：使用中（一个在手腕上的时段已打开）、在一个时段中（另一个时段已打开：状态是类型名称，“晒太阳中”、“上链盒中”、“充电器中”；两个一起，“晒太阳中 · 上链盒中”）或休息中；在今天页面的表格中，休息中的不可用显示为不可用。带从何时起：手腕上时段的开始、最近一个时段的开始，或最后一次在手腕上的结束（“自 21:40 起休息中”）。被忘记的已打开时段只计到它的“结束于”。手腕是代码唯一按标识符认识的类型；其他的按名称进入。',
        'O motor das fórmulas' => '公式引擎',
        'A sintaxe é a de uma planilha: números com vírgula ou ponto, textos entre aspas, ; separando os argumentos, + - * / ^ (a potência associa à direita), as comparações = <> < <= > >= (dão 1 ou 0), o sinal, os parênteses, as variáveis e as funções (listas.funcoes_das_formulas). A precedência, da mais fraca para a mais forte: comparação, soma, produto, potência, sinal.' => '语法如同一张电子表格：数字用逗号或点，文本在引号之间，; 分隔参数，+ - * / ^（幂从右结合），比较 = <> < <= > >=（给出 1 或 0），符号、括号、变量和函数（listas.funcoes_das_formulas）。优先级，从最弱到最强：比较、加法、乘法、幂、符号。',
        'Um valor vazio se propaga pela conta (vazio + 1 = vazio); a divisão por zero dá vazio. MIN e MAX ignoram os vazios. PADRAO(x; outro) troca o vazio. Um erro de escrita diz a posição ("falta fechar as aspas", "\\";\\" sobrando na posição 12").' => '空值在计算中传播（空 + 1 = 空）；除以零得到空。MIN 和 MAX 忽略空值。PADRAO(x; outro) 替换空值。书写错误会指出位置（“引号没有闭合”、“位置 12 多出了“;””）。',
        'As variáveis de um relógio: os campos (o valor usado), as fórmulas (pelo identificador; uma fórmula pode usar outra, sem ciclo) e as que o sistema dá. Cada fórmula pode ter uma versão por grupo; vale a do grupo mais perto do relógio (a dele, senão a de cima, ... senão a de todos). Uma fórmula que não tem versão para o relógio fica vazia nele.' => '一块手表的变量：字段（使用的值）、公式（按标识符；一个公式可以使用另一个，不能成环）以及系统给出的那些。每个公式可以按分组有一个版本；取离手表最近的分组的（它自己的，否则上级的，……否则全部的）。对这块手表没有版本的公式在它那里为空。',
        'As funções de histórico leem os lançamentos do relógio até o instante da conta (o primeiro argumento é o identificador do tipo, entre aspas). ACUMULA percorre o histórico como um saldo: começa no início, perde por hora, ganha por hora em cada sessão da lista, passa a valer o efeito num instantâneo da lista, sempre entre 0 e o máximo. É ela que faz a reserva de marcha e a carga de luz.' => '历史函数读取该手表直到计算时刻的记录（第一个参数是类型的标识符，在引号中）。ACUMULA 把历史当作余额遍历：从起点开始，按小时损失，在列表中每个时段按小时获得，在列表中的一个瞬时变为该效果的值，始终在 0 和最大值之间。动力储存和光充电量就是由它完成的。',
        'Testar: a mesma fórmula calculada em todos os relógios (ou nos escolhidos), sem gravar, com o caminho da conta (rastro). Antes de gravar uma fórmula, o sistema a lê (erro de escrita) e confere as variáveis e os tipos que ela usa. Renomear ou excluir um campo, um tipo ou uma fórmula que outra fórmula usa é recusado, com a lista de quem usa.' => '测试：同一公式在全部手表（或所选的）上计算，不保存，带计算路径（rastro）。保存公式之前，系统读取它（书写错误）并核对其使用的变量和类型。重命名或删除被另一个公式使用的字段、类型或公式会被拒绝，并列出使用者。',
        'O tempo nas contas é em dias: HOJE() é a meia-noite local de hoje, AGORA() o instante, e as datas dos campos viram dias pelo mesmo relógio. As horas viram dias dividindo por 24.' => '计算中的时间以天计：HOJE() 是今天的本地午夜，AGORA() 是此刻，字段的日期按同一时钟变成天。小时除以 24 变成天。',
        'Os avisos e a visão de cada relógio' => '提醒以及每块手表的视图',
        'Um aviso tem uma fórmula que dá a data prevista (expressao, em dias), uma condição (vale quando), a antecedência (0 a 3650 dias), o texto (até 300, com {relogio}, {data}, {quando} e {limite}), o tipo de lançamento que resolve (o botão na tela Hoje), se está ativo, uma versão por grupo (como as fórmulas), e como a escala simula a solução (escala: nao, uso ou sempre; o valor ou as horas simuladas) e se entra na agenda só dentro da janela de antecedência ou sempre.' => '一个提醒有一个给出预计日期的公式（expressao，以天计）、一个条件（何时有效）、提前量（0 到 3650 天）、文本（最多 300，带 {relogio}、{data}、{quando} 和 {limite}）、用来解决的记录类型（今天页面上的按钮）、是否启用、按分组的一个版本（如同公式），以及排班表如何模拟解决方案（escala：nao、uso 或 sempre；模拟的数值或小时）以及是只在提前量窗口内进入日历还是始终进入。',
        'Um relógio fora da coleção (desejado, vendido, arquivado) não tem aviso nenhum (o emprestado tem). O aviso vale para um relógio disponível quando a condição dá verdadeiro e a data prevista existe; sai hoje quando a data menos a antecedência já chegou. Estado: atrasado (a data passou) ou em breve. O aviso de um relógio com uma sessão aberta à mão (carregando, no sol) não vai para a agenda enquanto ela estiver aberta: a data andaria a cada conta.' => '收藏之外的手表（心愿中、已售出、已归档）没有任何提醒（已借出的有）。当条件为真且预计日期存在时，提醒对一块可用手表有效；日期减去提前量已经到达时，今天发出。状态：atrasado（日期已过，即逾期）或即将。一块手表有手动打开的时段（正在充电、在晒太阳）时，它的提醒在该时段打开期间不进入日历：日期会在每次计算时变动。',
        'Os avisos de carga usam o limite de carga: o do relógio (campo carga_minima), senão o geral da Configuração (carga_limiar); o solar usa sol_limiar. A data do Carregar é pelo gasto do estado de agora (no pulso, o de uso; guardado, o de guardado); no carregador, o Carregar some e vale o Tirar do carregador (carregado: vence quando a bateria enche no carregador).' => '电量提醒使用电量下限：手表自己的（字段 carga_minima），否则是设置中的一般值（carga_limiar）；太阳能使用 sol_limiar。充电的日期按现在状态的消耗（在手腕上，用使用中的；存放着，用存放的）；在充电器中，充电消失，改为离开充电器有效（已充满：在充电器中电池充满时到期）。',
        'Um aviso pode ser "na hora" (na_hora): além do alerta da manhã, o cron manda pelo Telegram no minuto em que ele vence, uma vez, e guarda quais já foram (config.na_hora_enviados, relogio_id:identificador); um aviso sai da lista quando deixa de vencer. O botão do aviso na página Hoje vem da API (resolve.acao e resolve.botao): a sessão que resolve, aberta, se encerra ("Tirou do carregador"); fechada, se inicia ("Pôs no sol"); a leitura se informa.' => '提醒可以是“准时”（na_hora）：除了早晨的提醒，cron 在它到期的那一分钟通过 Telegram 发送一次，并记住哪些已经发过（config.na_hora_enviados，relogio_id:identificador）；一个提醒不再到期时就离开列表。今天页面上提醒的按钮来自 API（resolve.acao 和 resolve.botao）：用来解决的时段，若已打开则结束（“已离开充电器”）；若已关闭则开始（“已去晒太阳”）；读数则填写。',
        'O aviso Encostado (encostado, de todos os relógios, resolve com o pulso) é só cadastro: a data prevista é PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias") (a Configuração, padrão 30), antecedência 0; sem nunca ter ido ao pulso nem data da compra, não avisa. Não entra na próxima manutenção nem no "O que fazer": a tabela da coleção tem a coluna Encostado, o cartão do dia mostra a falta quando já venceu, e o quadro Agora do painel também.' => '闲置提醒（encostado，全部手表，用手腕解决）只是档案：预计日期是 PADRAO(ULTIMA_DATA("pulso"); data_compra) + CONFIG("encostado_dias")（设置，默认 30），提前量 0；从未上手腕也没有购买日期时，不提醒。它不进入下次保养，也不进入“要做什么”：收藏表格有闲置列，当天的卡片在已经到期时显示缺失，面板的现在框也显示。',
        'A visão de cada relógio (a tabela da página Hoje e o painel): em uso ou em repouso desde quando, a carga estimada agora e de onde vem (a fórmula energia e a origem), a situação (frases curtas: autonomia restante, reserva...), a próxima manutenção (o aviso mais perto, sem o Encostado), o que fazer e a coluna Encostado.' => '每块手表的视图（今天页面的表格和面板）：使用中或休息中从何时起、现在估计的电量以及来自何处（公式 energia 和来源）、情况（短句：剩余续航、储能……）、下次保养（最近的提醒，不含闲置）、要做什么以及闲置列。',
        'O gasto medido pelas leituras e a autonomia' => '由读数得出的实测消耗以及续航',
        'Cada leitura de carga de um tipo que mede o gasto é comparada com a anterior do mesmo relógio: o intervalo vira uma medição, com a queda, as horas no pulso e as horas fora do pulso no intervalo (o horário de uso conta como pulso sozinho quando o pulso sozinho está ligado; as marcações Pôs e Tirou mandam). Uma subida é recarga: novo ponto de partida, sem medir. Só entram intervalos de 1 hora ou mais; o curto entra com peso pequeno. Um intervalo com outra sessão no meio (o carregador) não mede: a medição só separa pulso e guardado.' => '测量消耗的类型的每一次电量读数与同一手表的前一次比较：间隔变成一次测量，含下降、该间隔内在手腕上的小时和离开手腕的小时（当独自上手腕开启时，使用时段按独自上手腕计；戴上和摘下的标记为准）。上升是再充电：新的起点，不测量。只计入 1 小时或更长的间隔；短的以小权重计入。中间有另一个时段（充电器）的间隔不测量：测量只区分手腕和存放。',
        'Cada medição é uma conta com dois desconhecidos: queda = dias de uso × gasto em uso + dias fora × gasto fora. Com as medições da janela (medicao_janela_dias, padrão 90), os dois gastos saem juntos por mínimos quadrados, cada medição pesando as horas que cobriu. Quando elas não separam os dois (só leituras guardado, por exemplo), vale a média das medições de cada um; sem nenhuma na janela, as de antes; sem nenhuma, o do cadastro. O resultado também é dado na janela anterior, para comparar (a bateria envelhecendo).' => '每次测量是一个有两个未知数的式子：下降 = 使用天数 × 使用中消耗 + 离开天数 × 离开时消耗。用窗口内的测量（medicao_janela_dias，默认 90），两个消耗由最小二乘一起得出，每次测量按其覆盖的小时加权。当它们分不开两者时（例如只有存放时的读数），取各自测量的平均；窗口内一个都没有时，用更早的；一个都没有时，用档案中的。结果也给出前一个窗口的，以便比较（电池在老化）。',
        'MEDIDO("uso") e MEDIDO("repouso") dão esses gastos às fórmulas; corrigir uma marcação de pulso recalcula as horas das medições que cobrem aquele trecho.' => 'MEDIDO("uso") 和 MEDIDO("repouso") 把这些消耗交给公式；改正一条手腕标记会重算覆盖该片段的测量的小时。',
        'A autonomia: cheio pelo cadastro e pela conta (com o gasto medido), quando acaba seguindo o plano (simulando os dias do plano), quanto dura no pulso sem tirar e guardado; e a previsão do smartwatch (a carga dia a dia, até o limite).' => '续航：按档案和按计算充满（用实测消耗）、按计划走到何时结束（模拟计划中的日子）、不摘下时在手腕上能持续多久以及存放时；以及智能手表的预测（逐日电量，直到下限）。',
        'Os critérios e a nota' => '标准与分数',
        'Um conjunto de critérios por lugar: todos os relógios, um grupo ou um relógio. O relógio usa o conjunto mais perto dele, inteiro (o dele, senão o do grupo, senão o de cima, ..., senão o de todos).' => '每个位置一套标准：全部手表、一个分组或一块手表。手表使用离它最近的整套（它自己的，否则分组的，否则上级的，……否则全部的）。',
        'O conjunto tem parâmetros com peso (somam 100%); cada parâmetro tem subparâmetros com peso (somam 100% dentro dele); cada subparâmetro lê uma variável (um campo ou uma fórmula) e transforma o valor em nota (0 a 100) pelas faixas: de um número até outro (a primeira começa em 0, sem buracos nem sobreposição, só a última sem limite) ou por categoria (campo de lista ou texto).' => '集合有带权重的参数（合计 100%）；每个参数有带权重的子参数（在它内部合计 100%）；每个子参数读取一个变量（一个字段或一个公式）并按区间把值变成分数（0 到 100）：从一个数到另一个数（第一个从 0 开始，没有空洞也没有重叠，只有最后一个没有上限）或按类别（列表字段或文本）。',
        'A nota do parâmetro é a média das notas dos subparâmetros, pelo peso; a nota do relógio, a média dos parâmetros, pelo peso. Um subparâmetro sem valor (campo vazio, valor fora de toda faixa) sai da conta e os outros dividem o peso dele. A conta inteira de cada nota é mostrada (cada faixa, cada peso, cada ponto).' => '参数的分数是子参数分数按权重的平均；手表的分数是参数按权重的平均。没有值的子参数（空字段、值落在所有区间之外）离开计算，其他的分掉它的权重。每一个分数的完整计算都会显示（每一个区间、每一个权重、每一个得分）。',
        'Restaurar os critérios iniciais apaga os de todos os lugares e volta aos do cadastro inicial.' => '恢复初始标准会删除所有位置的标准并回到初始档案中的那些。',
        'Os modos de rodízio, o plano e a escala inteligente' => '轮换模式、计划与智能排班表',
        'Hoje sem relógio (rodizio sem_relogio): o plano de hoje sai e hoje vira um dia livre; a sessão do rodízio de hoje que já começou fecha agora (o tempo dela conta como uso), a que ainda não começou sai; a sessão do dia (o pulso sozinho) não abre num dia sem plano, e o garantir_plano não põe de volta como plano de hoje o relógio que esteve no pulso pelo rodízio num dia livre. Os outros dias não mudam. Desfaz: trocar_dia (ou usando) de hoje, ou resortear_hoje.' => '今天没有手表（rodizio sem_relogio）：今天的计划去掉，今天变成空闲日；今天已经开始的轮换时段现在结束（它的时间计为使用），尚未开始的去掉；当天的时段（独自上手腕）在没有计划的一天不打开，并且 garantir_plano 不会把曾因轮换在空闲日上手腕的手表放回为今天的计划。其他日子不变。撤销：今天的 trocar_dia（或 usando），或 resortear_hoje。',
        'Um modo é feito de blocos de dias da semana (cada dia em um bloco só). Cada bloco diz de onde escolher (um grupo, a coleção toda ou um relógio fixo) e se é um relógio por dia ou um para o bloco inteiro. A forma de escolha do modo: inteligente (a maior nota), ponderado (sorteio com a nota como chance), aleatório ou fifo (quem espera há mais tempo). Com o ciclo ligado, um relógio só volta depois que todos os disponíveis do bloco passaram. No máximo um modo em uso.' => '一个模式由星期几的区块组成（每一天只在一个区块中）。每个区块说明从何处选择（一个分组、整个收藏或一块固定手表）以及是每天一块还是整个区块一块。模式的选择方式：inteligente（最高分数）、ponderado（以分数为机会的抽签）、aleatorio 或 fifo（等得最久的）。循环开启时，一块手表要等该区块全部可用的都过了一遍才回来。最多一个模式在使用中。',
        'A garantia de rodízio (max_sem_uso, padrão 21) vale antes da nota: candidato além desse limite de dias sem uso ganha direto, o mais parado primeiro. Os dias sem uso de um relógio nunca usado contam desde a compra (sem data de compra: 9999).' => '轮换保障（max_sem_uso，默认 21）先于分数：候选人超过这个未使用天数上限就直接获得，停得最久的优先。从未使用的手表的未使用天数从购买起算（没有购买日期：9999）。',
        'O plano guarda o relógio de cada dia, o bloco, a origem (sorteio ou manual), a ação do dia e o motivo, numa frase ("Garantia de rodízio: ...", "Sorteio pela nota, entre 5 candidatos: nota 70,2, 16,4% de chance", "Escolhido à mão"). O cron monta o dia que falta (à 0h da segunda, a semana nova); trocar o relógio de um dia o marca como manual; sortear de novo refaz o período; usando hoje põe outro relógio no período atual e refaz o plano.' => '计划保存每一天的手表、区块、来源（抽签或手动）、当天的操作和事由，成一句（“轮换保障：……”、“按分数抽签，在 5 个候选人中：分数 70,2，16,4% 的机会”、“手动选定”）。cron 编制缺少的那一天（星期一 0 点，新的一周）；更换某一天的手表把它标为手动；重新抽签重做该时段；今天正在使用则在当前时段放入另一块手表并重做计划。',
        'Um período escolhido à mão (rodizio, acao=periodo): de, até (de hoje até 2 anos), os relógios na ordem e quantos dias seguidos cada (dias_cada): cada dia do período fica manual, com o relógio da vez (depois do último, volta ao primeiro; hoje, ele passa a ser o do pulso a partir de agora); na escala, ela é refeita a partir do começo do período. De amanhã em diante: periodo_sortear apaga o que o período tem (à mão, sorteado ou livre) e sorteia de novo; periodo_livre apaga e deixa os dias livres (a tabela plano_livre: sem relógio e sem sorteio; o sorteio e a escala pulam esses dias, e a escala não estica um bloco sobre eles). Escolher um relógio para um dia livre (trocar_dia, periodo, usando) o tira de plano_livre; trocar_dia 0 também (volta ao sorteio). Os dias manuais e os livres de amanhã em diante ficam quando se sorteia de novo ou se monta a próxima semana (hoje, o sortear de novo sorteia); trocar de modo refaz os sorteados. A API dá os dias livres em plano.livres e hoje.livres (as telas os põem entre os dias do plano, como "livre: escolha à mão").' => '手动选择的时段（rodizio，acao=periodo）：从、到（从今天直到 2 年）、手表按顺序以及每一块连续多少天（dias_cada）：该时段的每一天变为手动，用轮到的手表（最后一块之后回到第一块；今天，它从现在起成为手腕上的那只）；在排班表中，从该时段的起点重做。从明天起：periodo_sortear 去掉该时段已有的（手动、抽签或空闲）并重新抽签；periodo_livre 去掉并让这些天空闲（表 plano_livre：无手表且无抽签；抽签和排班表跳过这些天，排班表也不把一个区块拉过它们）。为空闲日选择一块手表（trocar_dia、periodo、usando）会把它从 plano_livre 去掉；trocar_dia 0 也同样（回到抽签）。重新抽签或编制下一周时，从明天起的手动日和空闲日保留（今天，重新抽签会抽签）；更换模式会重做已抽签的。API 在 plano.livres 和 hoje.livres 中给出空闲日（页面把它们放在计划日之间，如“空闲：请手动选择”）。',
        'O Rodízio manual (a última opção da lista Modo de rodízio da página Hoje; não é um modo: fora do período vale o modo ativo): de e até (de hoje até 2 anos); recurso=rodizio_manual dá os dias de 7 em 7 (pagina), cada um com o que o plano tem e a escolha de partida do seletor: o relógio escolhido à mão, livre (dia livre) ou auto (Decida por mim: o dia sorteado ou sem relógio). rodizio acao=manual grava o período inteiro: dias[data] = o id, auto ou livre (hoje não); o dia que não vem fica com a escolha de partida. Os dias com relógio ficam manual ("Escolhido à mão no rodízio manual de DD/MM a DD/MM."); os livres vão para plano_livre; hoje com outro relógio passa a ser o do pulso a partir de agora (hoje em auto continua o que está); na escala, ela é refeita a partir do começo. O Decida por mim decide ao gravar e grava manual, com o motivo ("Decida por mim: a maior nota (62,9), entre 4 candidatos. O de ontem (X) ficou de fora." ou "Decida por mim, pela garantia de rodízio: parado há 33 dias, além do limite de 15 dias sem uso, ..."): de hoje até o fim do período, dia a dia, cada dia vira uma sessão simulada no pulso (os do plano antes do período, os escolhidos e os decididos), e no dia auto: os disponíveis, menos o de ontem e o escolhido para amanhã (se sobrar outro); a garantia de rodízio na frente (o mais tempo parado além de max_sem_uso); senão a maior nota no começo do uso do dia; empate: o menor id. A resposta diz quantos dias foram escolhidos, decididos, livres e quantos ficaram como já estavam.' => '手动轮换（今天页面轮换模式列表的最后一项；它不是一个模式：时段之外仍是启用的模式）：从和到（从今天直到 2 年）；recurso=rodizio_manual 每 7 天给出日子（pagina），每一天带计划中已有的以及选择器的起始选择：手动选定的手表、livre（空闲日）或 auto（帮我决定：抽签的那一天或没有手表）。rodizio acao=manual 写入整个时段：dias[data] = id、auto 或 livre（不含今天）；没有传来的那一天保留起始选择。有手表的日子变为手动（“在 DD/MM 至 DD/MM 的手动轮换中手动选定。”）；空闲的进入 plano_livre；今天若是另一块手表，则从现在起成为手腕上的那只（今天为 auto 则继续当前的）；在排班表中，从起点重做。帮我决定在写入时决定并记为手动，带事由（“帮我决定：最高分数（62,9），在 4 个候选人中。昨天的（X）被排除。”或“帮我决定，按轮换保障：已停 33 天，超过 15 天未使用的上限，……”）：从今天到时段结束，逐日，每一天变成手腕上的一个模拟时段（时段之前计划中的、已选择的和已决定的），在 auto 的那一天：可用的，减去昨天的以及为明天选定的（若还剩另一块）；轮换保障在前（超过 max_sem_uso、停得最久的）；否则取当天使用开始时的最高分数；平局：最小的 id。响应说明多少天被选择、被决定、空闲以及多少天保持原样。',
        'Apagar a programação (página Plano e quadro Modo de rodízio): apagar um período (periodo_sortear: sai tudo o que ele tem, de amanhã em diante, e o modo sorteia de novo; periodo_livre: sai tudo e os dias ficam livres) e apagar tudo (rodizio apagar_tudo: sai toda a programação de amanhã em diante, à mão, sorteada e livre; com hoje=1, "Excluindo hoje", de hoje em diante; depois o modo ativo monta o plano de novo, gerar_escala na escala e garantir_plano até domingo no sorteio; hoje, se mudar, o novo vai para o pulso a partir de agora, como no resortear_hoje).' => '清除安排（计划页面和轮换模式框）：清除一个时段（periodo_sortear：去掉它从明天起的全部内容，模式重新抽签；periodo_livre：去掉全部，这些天变为空闲）以及全部清除（rodizio apagar_tudo：去掉从明天起的全部安排，手动、抽签和空闲；hoje=1 时，“排除今天”，从今天起；之后启用的模式重新编制计划，排班表中 gerar_escala，抽签中 garantir_plano 直到星期日；今天若改变，新的从现在起上手腕，如同 resortear_hoje）。',
        'As listas longas de dias vêm da API uma página por vez (plano_pagina): os Próximos dias (hoje.proximos e recurso=proximos, de hoje até o fim do plano) e o dia a dia da página Plano (plano.dia_a_dia, com o filtro relogio), com os dias livres no meio (origem livre; sem eles no filtro de relógio), cada dia com o dia da semana (dia_semana 1 a 7, dia_semana_curto); o tamanho da página é o Mostrar até da Configuração (config proximos_por_pagina, padrão 7; plano_por_pagina, padrão 31; 1 a 366; por_pagina no pedido vale por cima), e o recurso=config devolve os dois já com o padrão (mostrar_ate).' => '长日子列表由 API 一次一页给出（plano_pagina）：接下来的日子（hoje.proximos 和 recurso=proximos，从今天到计划结束）以及计划页面的逐日（plano.dia_a_dia，带 relogio 筛选），空闲日在中间（来源 livre；手表筛选中没有它们），每一天带星期几（dia_semana 1 到 7，dia_semana_curto）；页大小是设置中的显示至（config proximos_por_pagina，默认 7；plano_por_pagina，默认 31；1 到 366；请求中的 por_pagina 优先），recurso=config 返回两者且已带默认（mostrar_ate）。',
        'A escala inteligente (um modo com escala_dias de 7 a 730) planeja tudo de uma vez simulando dia a dia: a nota de cada relógio com o estado simulado daquele dia; a escolha (o smartwatch fica os dias que a bateria aguenta, até 7); a sessão no pulso no horário de uso e o efeito dela em todos; os avisos (se o escolhido vai precisar de carga ou corda, anota a ação no dia e simula o lançamento que resolve). Toda manhã o cron refaz a escala a partir do estado real. Notas iguais na maior (o empate exato) se desempatam por sorteio, e o motivo diz "Empatado na nota com N outros: saiu no sorteio (<fonte>)."' => '智能排班表（escala_dias 为 7 到 730 的模式）一次规划全部，逐日模拟：每块手表以该日模拟状态得出的分数；选择（智能手表停留电池能撑住的天数，最多 7）；在使用时段内手腕上的时段及其对全部的效果；提醒（若被选中的将需要电量或上链，在当天记下操作并模拟用来解决的记录）。每天早晨 cron 从真实状态重做排班表。最高分相同（精确平局）由抽签决出，事由写“与另外 N 块分数相同：抽签得出（<fonte>）。”',
        'O sorteio (sorteio(min, max): o modo aleatório, o sorteio pela nota e o desempate da escala) usa números aleatórios de fora, nesta ordem: RANDOM.ORG (www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new: ruído atmosférico); senão o ANU QRNG (qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16, o endereço antigo, sem chave: {"success": true, "data": [...]}; quântico); senão o gerador seguro do PHP (random_int). Um lote de 64 números de 16 bits por pedido, na memória do pedido; cada sorteio junta quantos pedaços de 16 bits precisar e descarta o valor que passa do último múltiplo inteiro da faixa (sem viés). Cada serviço tem 4 segundos; a resposta tem de vir completa e dentro da faixa, senão vale como falha. Se os dois falham, a config aleatorio_fora guarda quando, e por 10 minutos o sistema nem tenta (usa o do PHP); a config aleatorio_ultima guarda a fonte do último lote e quando (recurso=config: aleatorio.ultimo_lote, aleatorio.fora_desde; a Configuração mostra no quadro Sorteios). O motivo de cada dia sorteado termina com a fonte entre parênteses ("... todos com a mesma chance (RANDOM.ORG)."). Com RELOGIOS_SEMENTE (os testes), mt_rand com a semente, sem rede (a fonte: "semente de teste"). O que é segredo (o sal das senhas, os nomes dos arquivos dos documentos) fica no gerador do PHP: número que viaja pela internet não serve para segredo.' => '抽签（sorteio(min, max)：随机模式、按分数抽签以及排班表的决胜）按此顺序使用外部随机数：RANDOM.ORG（www.random.org/integers/?num=64&min=0&max=65535&col=1&base=10&format=plain&rnd=new：大气噪声）；否则 ANU QRNG（qrng.anu.edu.au/API/jsonI.php?length=64&type=uint16，旧地址，无密钥：{"success": true, "data": [...]}；量子）；否则 PHP 的安全生成器（random_int）。每次请求一批 64 个 16 位数字，放在该请求的内存中；每次抽签拼接所需数量的 16 位片段，并丢弃超过该区间最后一个整数倍的值（无偏差）。每个服务 4 秒；响应必须完整且在区间内，否则算失败。若两者都失败，config aleatorio_fora 记录时间，此后 10 分钟系统甚至不再尝试（使用 PHP 的）；config aleatorio_ultima 记录最近一批的来源和时间（recurso=config：aleatorio.ultimo_lote、aleatorio.fora_desde；设置在抽签框中显示）。每一个被抽签的日子的事由以括号中的来源结束（“……机会全部相同（RANDOM.ORG）。”）。有 RELOGIOS_SEMENTE（测试）时，用该种子的 mt_rand，无网络（来源：“测试种子”）。属于秘密的（密码的盐、文档文件的名称）留在 PHP 的生成器中：经互联网传输的数字不能用于秘密。',
        'O pulso sozinho e as sessões esquecidas' => '独自上手腕以及被忘记的时段',
        'O horário de uso (uso_inicio e uso_fim) diz quando o relógio do dia está no pulso. Pôr sozinho (pulso_auto_inicio): no início do horário, o cron abre a sessão no pulso do relógio do dia (origem rodizio). Tirar sozinho (pulso_auto_fim): o "fecha às" do tipo No pulso segue o fim do horário. Desligados, só as marcações Pôs e Tirou contam; o que foi marcado sempre vale. Com o relógio do dia noutra sessão exclusiva aberta (no carregador, no sol, no winder), o pôr sozinho espera; se ele saiu de uma depois do início do horário, a sessão no pulso começa quando ele saiu.' => '使用时段（uso_inicio 和 uso_fim）说明当天的手表何时在手腕上。自动戴上（pulso_auto_inicio）：在时段开始时，cron 打开当天手表在手腕上的时段（来源 rodizio）。自动摘下（pulso_auto_fim）：类型“在手腕上”的“结束于”跟随使用时段的结束。关闭时，只有戴上和摘下的标记算数；已经标记的始终有效。当天的手表在另一个已打开的独占时段中（在充电器中、在晒太阳中、在上链盒中）时，自动戴上等待；若它在使用时段开始之后离开了其中一个，手腕上的时段从它离开时开始。',
        'Toda sessão esquecida aberta fecha sozinha no "fecha às" do tipo dela (a do sol, em sol_fim).' => '每一个被忘记的已打开时段在它类型的“结束于”自行结束（晒太阳的，在 sol_fim）。',
        'O cron' => 'cron',
        'A cada minuto: confere o token, o fuso e as migrações (pendente: registra e para); apaga execuções antigas (sem atividade, 7 dias; com atividade ou erro, 1 ano); monta o dia do plano que falta; fecha as sessões esquecidas; abre a sessão no pulso do dia; dispara os eventos personalizados no minuto marcado (depois de uma parada de até 7 dias, sai uma vez só, sem repetir); a manutenção dos documentos.' => '每分钟：核对令牌、时区和迁移（待处理：记录并停止）；删除旧的执行（无活动，7 天；有活动或错误，1 年）；编制计划中缺少的那一天；结束被忘记的时段；打开当天在手腕上的时段；在标记的分钟触发自定义事件（停机最多 7 天之后，只发出一次，不重复）；文档维护。',
        'Na hora da manhã (horario_manha), uma vez por dia: refaz a escala a partir do estado real, manda o Telegram do dia (o relógio de hoje e os avisos) e sincroniza a agenda. Na hora da noite (horario_noite): o Telegram da véspera (o relógio de amanhã e o que preparar) e a sincronização; conta os documentos perdidos; e, com a BACKUP_PASTA no config.php, faz a cópia de segurança do banco.' => '在早晨的时刻（horario_manha），每天一次：从真实状态重做排班表，发送当天的 Telegram（今天的手表和提醒）并同步日历。在夜晚的时刻（horario_noite）：前夕的 Telegram（明天的手表以及要准备的）和同步；清点丢失的文档；并且，若 config.php 中有 BACKUP_PASTA，则做数据库的安全副本。',
        'Os avisos na hora, a cada minuto: os vencidos agora (de todos os relógios) que ainda não foram vão pelo Telegram.' => '准时的提醒，每分钟：现在到期的（全部手表）、尚未发送的，通过 Telegram 发出。',
        'A cópia de segurança: um arquivo relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz na BACKUP_PASTA (fora da pasta publicada: dentro dela, recusada), JSON Lines comprimido, o mesmo nos quatro bancos: a primeira linha é o cabeçalho (relojoeiro_copia 1, criada, banco, versao: a última migração, documentos, tabelas); depois, para cada tabela, uma linha {tabela, colunas, binarias} e uma linha por registro com a lista dos valores (binários em base64). As tabelas vêm na ordem em que voltam (a citada antes da que cita; a que cita a si mesma, a árvore, volta em rodadas). Ficam as BACKUP_MANTER mais novas (padrão 7). O conteúdo dos documentos (documento_parte) só com BACKUP_DOCUMENTOS = true. Restaurar: só da mesma versão; antes, uma cópia do que está agora; depois, numa transação, apaga tudo (na ordem inversa) e grava a cópia; sem o conteúdo dos documentos, documento.no_banco volta a 0.' => '安全副本：BACKUP_PASTA 中一个文件 relojoeiro-AAAA-MM-DD-HHMMSS.jsonl.gz（在已发布文件夹之外：在其中则拒绝），压缩的 JSON Lines，四个数据库相同：第一行是页眉（relojoeiro_copia 1、criada、banco、versao：最近一次迁移、documentos、tabelas）；然后，对每张表，一行 {tabela, colunas, binarias} 以及每个记录一行，带值的列表（二进制为 base64）。表按恢复时的顺序（被引用的在引用它的之前；引用自身的，即树，分轮恢复）。保留最新的 BACKUP_MANTER 份（默认 7）。文档内容（documento_parte）仅在 BACKUP_DOCUMENTOS = true 时。恢复：仅同一版本；之前，先做当前内容的一份副本；然后，在一个事务中，删除一切（逆序）并写入副本；没有文档内容时，documento.no_banco 回到 0。',
        'Com BACKUP_ATIVO = false no config.php, o cron não faz a cópia de segurança e a escrita fazer é recusada.' => '在 config.php 中设置 BACKUP_ATIVO = false 时，cron 不做备份，写入操作 fazer 被拒绝。',
        'Mudo: avisos do PHP e erros entram no registro, nunca na saída. Grava em cron_execucao o que fez (só quando fez algo, ou deu erro), o último erro em config.cron_erro (sai na primeira execução sem erro) e a última rodada com atividade em config.cron_registro. Erro fatal sem banco vai para um arquivo na pasta temporária. Opções: --forcar (manhã e noite agora) e -v (mostra o registro).' => '沉默：PHP 警告和错误进入记录，从不进入输出。在 cron_execucao 中写入所做的（仅当做了某事或出错），最近的错误在 config.cron_erro（在第一次无错误的执行中消失），最近一轮有活动的在 config.cron_registro。没有数据库的致命错误进入临时文件夹中的一个文件。选项：--forcar（现在执行早晨和夜晚）和 -v（显示记录）。',
        'As mensagens, a agenda e os eventos personalizados' => '消息、日历和自定义事件',
        'Dois canais (listas.canais): Telegram (tg) e Google Agenda (ag). Cada tipo de aviso (dia, vespera, o identificador de cada aviso e ev<id> de cada evento personalizado) é marcado ou não para cada canal, e pode ter mensagem própria no canal; sem ela, vale a mensagem padrão do canal (tg_padrao, ag_padrao). As mensagens têm âncoras entre chaves (listas.ancoras), trocadas pelos valores na hora.' => '两个渠道（listas.canais）：Telegram（tg）和 Google 日历（ag）。每种提醒类型（dia、vespera、每个提醒的标识符以及每个自定义事件的 ev<id>）对每个渠道标记或不标记，并且可以在渠道上有自己的消息；没有时，使用该渠道的默认消息（tg_padrao、ag_padrao）。消息含花括号中的锚点（listas.ancoras），在当时替换为值。',
        'O Telegram vai por uma API de mensagem (MSG_ENDPOINT): GET com destinatario, titulo e mensagem; partes de até 3000 caracteres (as mensagens do mesmo horário vão juntas, separadas por uma linha em branco).' => 'Telegram 通过一个消息 API（MSG_ENDPOINT）发出：GET，带 destinatario、titulo 和 mensagem；每段最多 3000 个字符（同一时刻的消息放在一起，以一个空行分隔）。',
        'A agenda: uma conta de serviço do Google (a chave JSON no servidor; token por JWT RS256, escopo do Calendar). O sistema calcula o que tem de estar na agenda (de hoje até agenda_antecedencia dias: os avisos marcados para a agenda, no horário da manhã do dia previsto; o relógio do dia e a véspera, pelo plano; as ocorrências dos eventos), cada item com uma chave estável; cria o que falta, atualiza o que mudou (pela assinatura), apaga o que deixou de valer; o que já passou fica. Na agenda, a primeira linha do modelo é o título e o resto a descrição.' => '日历：一个 Google 服务账号（服务器上的 JSON 密钥；JWT RS256 令牌，Calendar 范围）。系统计算日历中应该有的（从今天直到 agenda_antecedencia 天：标记给日历的提醒，在预计日的早晨时刻；当天的手表和前夕，按计划；事件的各次发生），每一项有一个稳定键；创建缺少的，更新已改变的（按签名），删除不再有效的；已经过去的保留。在日历中，模板的第一行是标题，其余是描述。',
        'Evento personalizado: nome, ativo, repetição (listas.repeticoes), data (uma vez; a cada N dias: a partir dela), hora, dias da semana, dia do mês (1 a 31; mês sem o dia, o último), intervalo (1 a 3650), relógio opcional (com ele, as âncoras do relógio funcionam). Só o que a repetição usa fica gravado. Novo, já vai pelo Telegram.' => '自定义事件：名称、启用、重复（listas.repeticoes）、日期（一次；每 N 天：从该日期起）、时刻、星期几、月中的日（1 到 31；该月没有这一天则为最后一天）、间隔（1 到 3650）、可选手表（有它时，手表的锚点有效）。只保存重复方式使用的内容。新建后，已经通过 Telegram 发出。',
        'Os documentos de cada relógio' => '每块手表的文档',
        'Qualquer arquivo, cada um numa categoria (as que aceitam só algumas famílias recusam as outras), com título, data e descrição. O tipo vem do conteúdo do arquivo; quando o conteúdo diz pouco (texto, binário genérico, zip), da extensão. A família decide como abre: imagem (galeria com visor em tela cheia e apresentação, com a miniatura feita no navegador), vídeo (player, em sequência na ordem escolhida), PDF (visualizador), XML (o resumo da NF-e: emitente, número, série, data, valor, chave e produtos; lido sem baixar nada de fora), o resto para baixar. Inline só o que o navegador mostra sem rodar nada (HTML, SVG e XML sempre como download); atende pedido de pedaço (Range).' => '任意文件，每一个属于一个类别（只接受某些系列的会拒绝其他的），带标题、日期和描述。类型来自文件内容；当内容说明很少时（文本、通用二进制、zip），来自扩展名。系列决定如何打开：图像（带全屏查看器和放映的图库，缩略图在浏览器中生成）、视频（播放器，按所选顺序连续播放）、PDF（查看器）、XML（NF-e 摘要：开票方、号码、系列、日期、金额、密钥和产品；读取时不从外部下载任何东西）、其余供下载。Inline 只用于浏览器显示时不运行任何东西的（HTML、SVG 和 XML 始终作为下载）；响应分段请求（Range）。',
        'Os arquivos ficam numa pasta fora da publicada (DOCUMENTOS_PASTA), em r<id do relógio>/ com nome aleatório. Limite por arquivo: DOCUMENTOS_LIMITE (padrão 100 MB) e os do PHP e do servidor web.' => '文件放在已发布文件夹之外的一个文件夹中（DOCUMENTOS_PASTA），在 r<手表 id>/ 中，名称为随机。每个文件的限制：DOCUMENTOS_LIMITE（默认 100 MB）以及 PHP 和 Web 服务器的限制。',
        'A cópia no banco (documento_parte, pedaços de 4 MB, com o SHA-256): três níveis, e o de cima vale sobre os de baixo. O sistema (DOCUMENTOS_COPIA_BANCO: true todos; false nenhum; ausente, decidem os de baixo), o relógio (copia_banco: todos os dele) e o arquivo (copia_banco: só ele). A tela só mostra a escolha de quem decide. A cópia entra na hora no envio e em editar; pelo relógio, o cron copia aos poucos; quando ninguém mais pede, sai, mas só se o arquivo da pasta confere com ela (o documento nunca fica sem as duas).' => '数据库中的副本（documento_parte，4 MB 的块，带 SHA-256）：三级，上一级优先于下一级。系统（DOCUMENTOS_COPIA_BANCO：true 全部；false 一个都没有；缺省时由下一级决定）、手表（copia_banco：它的全部）和文件（copia_banco：只有它）。页面只显示由谁决定的那一个选择。副本在上传时和编辑时立即进入；按手表时，cron 逐步复制；当不再有人要求时去掉，但仅当文件夹中的文件与它一致（文档永远不会两者都没有）。',
        'A manutenção (o cron, a cada minuto, até 256 MB por rodada): o arquivo que sumiu da pasta volta da cópia (conferindo o SHA-256); a cópia pedida que falta é feita; a que ninguém pede sai; a pasta de um relógio que não existe mais sai inteira; o arquivo que não é de nenhum documento sai (só depois de 10 minutos: um envio pode estar no meio). Os perdidos (sem arquivo e sem cópia) são contados à noite.' => '维护（cron，每分钟，每一轮最多 256 MB）：从文件夹消失的文件从副本恢复（核对 SHA-256）；被要求但缺少的副本被做出；不再有人要求的去掉；不再存在的手表的文件夹整份去掉；不属于任何文档的文件去掉（仅在 10 分钟之后：一次上传可能正在进行）。丢失的（没有文件也没有副本）在夜晚清点。',
        'As estatísticas' => '统计',
        'recurso=estatisticas conta o tempo no pulso de cada relógio em cada dia do período (as sessões do tipo pulso partidas na meia-noite, a aberta até agora; as marcações antigas no pulso contam o dia, sem horas). Dela saem: os dias de uso e as horas de cada relógio, a parte de cada um, a barra (comparada com o mais usado), a tendência (a segunda metade do período contra a primeira: até 20% ou menos de 1 h de diferença é estável; menos de 1 h no total ou período de menos de 14 dias, poucos dados), o uso por dia da semana e por mês (com a média por dia e a barra comparada com o maior) e o resumo. O custo por uso e os dias de uso desde sempre são as fórmulas custo_por_uso e dias_de_uso. A coleção (na coleção e emprestados) é dividida por grupo, marca, ano da compra, situação e cada campo de lista (menos os só dos desejados). Período padrão: os últimos 90 dias; até hoje; no máximo 3661 dias; de=tudo: desde o primeiro uso.' => 'recurso=estatisticas 计算时段内每一天每块手表在手腕上的时间（类型 pulso 的时段在午夜切开，已打开的直到现在；旧的手腕标记只计天数，不计小时）。由此得出：每块手表的使用天数和小时、每一块的份额、条形（与用得最多的比较）、趋势（时段的后半相对前半：相差在 20% 以内或少于 1 h 为稳定；合计少于 1 h 或时段少于 14 天，数据不足）、按星期几和按月份的使用（带每天平均以及与最大者比较的条形）和摘要。每次使用成本和有史以来的使用天数是公式 custo_por_uso 和 dias_de_uso。收藏（在收藏中和已借出）按分组、品牌、购买年份、情况和每个列表字段划分（仅心愿的除外）。默认时段：最近 90 天；直到今天；最多 3661 天；de=tudo：从第一次使用起。',
        'A hora certa' => '准确时间',
        'recurso=hora_certa não usa o banco: a hora do servidor (microtime) no fuso do sistema e em UTC; a letra militar do fuso pelo deslocamento em horas cheias (A a M sem J a leste, N a Y a oeste, Z no UTC; fora da hora cheia, nenhuma); o grupo data-hora DDHHMM + letra + mês em inglês + ano com dois dígitos; o calendário pelo formato de datas (z, L, W, o); o dia juliano = segundos / 86400 + 2440587,5; a lua pela idade no ciclo sinódico médio de 29,530588853 dias a partir da lua nova de 06/01/2000 18:14 UTC (dia juliano 2451550,1), a parte iluminada (1 - cos(2π idade/ciclo)) / 2 e a fase pelos oitavos do ciclo (os limites 1,85; 5,54; 9,23; 12,92; 16,61; 20,30; 23,99; 27,68 dias).' => 'recurso=hora_certa 不使用数据库：服务器时间（microtime）在系统时区和 UTC；时区的军用字母按整小时偏移（东向 A 到 M，不含 J，西向 N 到 Y，UTC 为 Z；不是整小时则没有）；日期时间组（DTG）DDHHMM + 字母 + 英语月份 + 两位年份；日历按日期格式（z、L、W、o）；儒略日 = 秒 / 86400 + 2440587,5；月相按从 2000-01-06 18:14 UTC 新月（儒略日 2451550,1）起、平均朔望周期 29,530588853 天的月龄，被照亮部分 (1 - cos(2π 月龄/周期)) / 2，以及按周期八分之一的相位（界限 1,85；5,54；9,23；12,92；16,61；20,30；23,99；27,68 天）。',
        'As telas' => '各页面',
        'A especificação completa, tela por tela, está em telas (abaixo): o visual com os valores exatos (cores, letras, controles, componentes, larguras), o menu, e cada página com o endereço, o que ela lê e grava na API, e as partes em ordem com cada tabela, campo, botão e mensagem. Aqui, o resumo.' => '完整规格，逐页，在下面的 telas 中：带精确数值的视觉（颜色、字体、控件、组件、宽度）、菜单，以及每一页的地址、它在 API 中读取和写入的内容，以及按顺序的各部分，含每张表、字段、按钮和消息。这里是摘要。',
        'Hoje: no alto, o destaque: o relógio do dia ou, com destaque_hoje = pulso, o que está no pulso agora (a API escolhe: destaque.relogio_id) (com o Pôs e o Tirou), "Hoje é dia de" (os avisos com o botão que resolve), os próximos dias com o motivo e o trocar por…, o modo de rodízio (troca ali mesmo), e a tabela da coleção com filtros e ordenação; clicar num relógio abre o painel dele, ao lado da lista ou numa janela flutuante (painel_modo).' => '今天：顶部是突出显示：当天的手表，或当 destaque_hoje = pulso 时现在在手腕上的那块（API 选择：destaque.relogio_id）（带戴上和摘下），“今天是……的日子”（带用来解决的按钮的提醒），接下来的日子带事由和换成……，轮换模式（就在那里更换），以及带筛选和排序的收藏表格；点击一块手表打开它的面板，在列表旁边或浮动窗口中（painel_modo）。',
        'O painel (e a ficha, a mesma coisa numa página): a cabeça (foto, grupo, nome, marcas), quadros alinhados numa grade (Agora, Previsão, Gasto da bateria, Autonomia, Rodízio, Compra, Documentos, Próximas manutenções), cada um com rótulo e valor em duas colunas; o quadro Marcar (um menu só, "O que você quer marcar?", e embaixo só os campos daquilo); Editar cadastro; o gráfico da carga com as medições; os dados do relógio (o cadastro com a origem de cada valor e o resultado de cada fórmula com a versão); o histórico recente.' => '面板（以及详情，同一事物在一个页面上）：页眉（照片、分组、名称、标记），在网格中对齐的框（现在、预测、电池消耗、续航、轮换、购买、文档、接下来的保养），每一个以两列显示标签和值；标记框（只有一个菜单，“你想标记什么？”，下方只有那一项的字段）；编辑档案；带测量的电量图；手表的数据（档案，带每个值的来源，以及每个公式的结果和版本）；最近的历史。',
        'Plano, Histórico, Documentos, Configuração (quadros com uma opção por linha e a barra de salvar presa no pé), Critérios, Grupos, Cadastros, Execuções do cron, Usuários e Ajuda (as seções do README).' => '计划、历史、文档、设置（每行一个选项的框以及固定在页脚的保存栏）、标准、分组、定义、cron 执行、用户和帮助（README 的各节）。',
        'Três tamanhos com o mesmo sistema visual: até 900 px (celular e tablet de pé) o menu fica recolhido, as tabelas viram cartões e o relógio abre em tela cheia (o voltar do aparelho fecha); de 901 a 1199 px o painel ao lado desliza por cima, pela direita. A mesma informação em todos os tamanhos: nenhuma coluna, filtro ou dia é escondido por falta de espaço. A tabela dos relógios tem sempre as 12 colunas; quando a tabela inteira não cabe na largura que tem (medida com os dados, com ou sem o painel aberto), cada relógio vira um cartão com os mesmos 12 campos na mesma ordem, cada um com o nome da coluna em cima (2 colunas no celular, 5 no tablet), os títulos viram botões de ordenar e os 11 filtros ficam todos. Campos com letra de 16 px no celular (o iPhone não aproxima a tela).' => '同一视觉系统的三种尺寸：直到 900 px（手机和竖放平板）菜单收起，表格变成卡片，手表全屏打开（设备的返回关闭它）；从 901 到 1199 px，旁边的面板从右侧滑到上面。所有尺寸上信息相同：没有任何一列、筛选或日子因空间不足被隐藏。手表表始终有 12 列；当整张表在现有宽度中放不下时（用数据测量，面板打开或未打开），每块手表变成一张卡片，同样的 12 个字段按同样顺序，每一个上方是列名（手机上 2 列，平板上 5 列），标题变成排序按钮，11 个筛选全部保留。手机上字段字号 16 px（iPhone 不会放大页面）。',
        'Segurança' => '安全',
        'Todo pedido da API exige autenticação (o token ou o login do site); as páginas são só o esqueleto, sem dado nenhum, e quem chega sem login vai para o login da API. O cron e os scripts só pela linha de comando. Os arquivos internos (núcleo, banco, configuração, scripts, testes, dados, os que começam com ponto) ficam bloqueados no servidor web (.htaccess e nginx-relogios.conf).' => 'API 的每一个请求都要求身份验证（令牌或网站登录）；页面只是骨架，没有任何数据，没有登录就来的人前往 API 的登录。cron 和脚本只能由命令行。内部文件（核心、数据库、配置、脚本、测试、数据、以点开头的）在 Web 服务器上被阻止（.htaccess 和 nginx-relogios.conf）。',
        'SQL sempre com parâmetros; textos escapados no HTML; XML da NF-e lido sem entidades nem rede; arquivos servidos inline só dos tipos seguros; senhas com password_hash; o token comparado em tempo constante.' => 'SQL 始终带参数；文本在 HTML 中转义；NF-e 的 XML 读取时无实体也无网络；文件 inline 提供时只限于安全类型；密码用 password_hash；令牌以常数时间比较。',
        'Senhas: só o hash, pelo password_hash do PHP (bcrypt, $2y$<custo>$<sal de 22><resultado de 31>); o login confere com o password_verify (o bcrypt da senha digitada com o sal e o custo do hash). A API entrega o login e o hash de cada usuário (recurso=usuarios: senha_hash, senha_algoritmo, senha_custo) e aceita criar um usuário pelo hash de outro sistema (usuarios/salvar com senha_hash; bcrypt $2y$, $2b$ ou $2a$, ou argon2; o $2b$ guardado como $2y$, o mesmo cálculo). A reescrita tem de conferir pelo mesmo bcrypt, para os usuários migrarem com a mesma senha. Os arquivos dos documentos só pelo recurso=documento.' => '密码：只有哈希，用 PHP 的 password_hash（bcrypt，$2y$<成本>$<22 的盐><31 的结果>）；登录用 password_verify 核对（用哈希的盐和成本对所输入的密码做 bcrypt）。API 给出每个用户的登录名和哈希（recurso=usuarios：senha_hash、senha_algoritmo、senha_custo）并接受用来自另一个系统的哈希创建用户（usuarios/salvar 带 senha_hash；bcrypt $2y$、$2b$ 或 $2a$，或 argon2；$2b$ 存为 $2y$，同一计算）。重写必须用同一个 bcrypt 核对，以便用户以同一密码迁移。文档的文件只能通过 recurso=documento。',
        'Os testes e a aceitação' => '测试与验收',
        'testes/cenario.php faz pela API o que uma pessoa faz (cadastra relógios de cada tipo, lança cordas, cargas, sol, winder e pilha, monta a escala, mexe nos critérios, nos eventos e nas fotos, roda o cron) e tira a fotografia de tudo o que a API devolve; testes/comparar.php compara duas fotografias. Com RELOGIOS_SEMENTE (o sorteio fica previsível), o roteiro rodado em MySQL, PostgreSQL, SQLite e Firebird, num banco recém-instalado, tem de dar as mesmas respostas; e a reescrita, as mesmas da versão atual. testes/paridade.sh faz tudo com um comando (os bancos recriados, a instalação, o usuário, os servidores, o roteiro e a comparação), com o config de teste apontado pela variável de ambiente RELOGIOS_CONFIG (o núcleo carrega o arquivo que ela diz; sem ela, o config.php).' => 'testes/cenario.php 通过 API 做一个人会做的事（登记每种类型的手表，记录上链、电量、晒太阳、上链盒和电池，编制排班表，改动标准、事件和照片，运行 cron）并拍摄 API 返回的一切的快照；testes/comparar.php 比较两份快照。有 RELOGIOS_SEMENTE（抽签变为可预测）时，脚本在 MySQL、PostgreSQL、SQLite 和 Firebird 上、在刚安装的数据库中运行，必须给出相同响应；重写也必须与当前版本相同。testes/paridade.sh 用一条命令做完全部（重建数据库、安装、用户、服务器、脚本和比较），测试 config 由环境变量 RELOGIOS_CONFIG 指向（核心加载它所指的文件；没有它则用 config.php）。',
        'Além disso: nenhuma escrita do roteiro recusada; o dicionário da ajuda explica todos os campos das respostas; as telas sem erro de JavaScript e sem rolagem lateral no celular, no tablet e no computador.' => '此外：脚本的任何写入都没有被拒绝；帮助的词典说明了响应的全部字段；页面在手机、平板和电脑上没有 JavaScript 错误，也没有横向滚动。',
        'A documentação da API tem uma fonte só: o dicionário dos campos da ajuda (recurso=ajuda, campos); o do cabeçalho do api.php é gerado dele (testes/dicionario.php --gravar; sem o --gravar, confere). testes/campos.php confere que todo campo das respostas está explicado. Os dois rodam no testes/paridade.sh.' => 'API 文档只有一个来源：帮助的字段词典（recurso=ajuda，campos）；api.php 页眉中的由它生成（testes/dicionario.php --gravar；没有 --gravar 则核对）。testes/campos.php 核对响应的每个字段都有说明。两者都在 testes/paridade.sh 中运行。',
        'testes/layout.cjs abre todas as telas (com os quadros recolhidos abertos e cada opção dos menus que mostram partes) num navegador, em 15 tamanhos de 320 a 1920px, e mede o que quebra: a página que rola de lado, o elemento que sai da caixa em que está, a etiqueta partida, o texto cortado, o botão com o texto em duas linhas e o que fica por cima de outro. O esperado: 0 problemas.' => 'testes/layout.cjs 在浏览器中打开全部页面（收起的框被打开，以及显示各部分的菜单的每一个选项），尺寸从 320 到 1920px 共 15 种，并测量会坏掉的：页面横向滚动、元素越出它所在的框、标签被拆开、文本被截断、按钮上的文本变成两行、以及叠在另一个之上的。预期：0 个问题。',
        'Cada tabela com as colunas (nome, tipo no dialeto do banco em uso, se aceita vazio, o padrão), a chave primária, as chaves estrangeiras (a coluna, a tabela.coluna de referência e o que acontece ao apagar a linha de cima: CASCADE some junto, SET NULL desfaz a ligação), as chaves únicas, os índices e as regras de validação (CHECK). As colunas de texto curto não diferenciam maiúsculas nem acentos. Três referências ficam pelo nome, de propósito: as fórmulas e os critérios citam campos e fórmulas pelo identificador, e canal_aviso.tipo cita o aviso pelo identificador (vale para todas as versões dele).' => '每张表带列（名称、正在使用的数据库方言中的类型、是否接受空、默认）、主键、外键（列、引用的表.列以及删除上方一行时发生什么：CASCADE 一起消失，SET NULL 解除关联）、唯一键、索引和校验规则（CHECK）。短文本列不区分大小写也不区分重音。三处引用有意按名称保留：公式和标准按标识符引用字段和公式，canal_aviso.tipo 按标识符引用提醒（对其全部版本有效）。',
    ],
];
